#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_0 0x4000      // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0040 // +/- 4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115(int i2c_handle)
{
    char buf[2];
    int16_t value;

    // Read the conversion register (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion register\n");
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    value = (buf[0] << 8) | buf[1];

    return value;
}

// Function to convert the raw ADC value to amperes
float convert_to_amperes(int16_t raw_value)
{
    // Full-scale range is +/- 4.096V, which corresponds to 40A (assuming 1A/V)
    // The ADC has a resolution of 16 bits, so the value ranges from -32768 to 32767
    // The voltage range is +/- 4.096V, so each bit represents 4.096V / 32768 = 0.000125V
    // 1A = 1V, so each bit represents 0.000125V * 1A/V = 0.000125A
    // To convert to amperes, multiply the raw value by 0.000125A
    return (float)raw_value * 0.000125;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for single-ended input on AIN0, +/- 4.096V range, and 128 SPS
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    // Write the configuration register
    if (i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing to configuration register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Wait for conversion to complete (at least 8ms for 128 SPS)
        gpioDelay(10); // Wait 10ms

        // Read the conversion result
        int16_t raw_value = read_ads1115(i2c_handle);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert the raw value to amperes
        float current = convert_to_amperes(raw_value);

        // Log the current value to the console
        printf("Current: %.6f A\n", current);

        // Wait 500ms
        gpioDelay(500);
    }

    // The program should never reach here due to the infinite loop, but include cleanup for safety
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

