#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096
#define TEMPERATURE_THRESHOLD 60.0
#define DEBOUNCE_DELAY_MS 50
#define BUZZER_DURATION_SEC 2

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int initialize();
int read_flame_sensor();
float read_temperature_sensor();
void activate_buzzer(int duration_ms);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    unsigned char config_reg;
    unsigned char conversion_reg;
} ads1115_config_t;

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion
    ads1115_config_t config = {
        .config_reg = 0x43, // 0b01000011: Single-shot mode, AIN0, +/-4.096V, 128 SPS
        .conversion_reg = ADS1115_CONVERSION_REG
    };

    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = config.config_reg;
    buf[2] = 0x83; // 128 SPS, Single-shot mode

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
