    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return -1000.0; // Indicate error
    }

    raw_value = (read_buf[0] << 8) | read_buf[1];

    // Convert raw value to voltage
    voltage = (float)raw_value * ADS1115_FULL_SCALE_VOLTAGE / 32768.0;

    // Convert voltage to temperature (Celsius) using LM393 characteristics
    temperature = voltage * 100.0; // Example conversion, adjust as needed

    return temperature;
