#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 5.0 // Amperes
#define LOG_FILE "current_log.txt"
#define SENSOR_ABSENT_VALUE 0x3FF // All bits set (0b111111111)

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int read_adc(int channel);
float convert_to_current(int adc_value);
void control_fan(float current);
void log_current(float current);
void signal_handler(int sig);
int gpio_init(int pin);
void gpio_set_output(int pin, int value);

// SPI Initialization
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read ADC value
int read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to current (Amperes)
float convert_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and that the ADC value ranges from 0 to 1023 (10-bit ADC)
    // and the current ranges from 0 to 10 Amperes
    float current = (float)adc_value * 10.0 / 1023.0;
    return current;
}

// Control the cooling fan
void control_fan(float current) {
    if (current > CURRENT_THRESHOLD) {
        gpio_set_output(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpio_set_output(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Log current reading to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// GPIO Initialization
int gpio_init(int pin) {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return -1;
    }

    pinMode(pin, OUTPUT);
    return 0;
}

// GPIO Set Output
void gpio_set_output(int pin, int value) {
    digitalWrite(pin, value);
}

int main() {
    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(FAN_GPIO) == -1) {
        fprintf(stderr, "GPIO initialization failed.\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Check for sensor absence
        if (adc_value == SENSOR_ABSENT_VALUE) {
            fprintf(stderr, "Sensor absent.\n");
            log_current(-1.0); // Log a special value to indicate sensor absence
        } else {
            // Convert ADC value to current
            float current = convert_to_current(adc_value);

            // Control the fan
            control_fan(current);

            // Log the current reading
            log_current(current);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpio_set_output(FAN_GPIO, 0); // Turn fan OFF

    printf("Exiting.\n");
    return 0;
}

