// Define GPIO pins for I2C emulation
#define I2C_DATA_PIN 2
#define I2C_CLOCK_PIN 3

// Define I2C address for the microphone
#define I2C_ADDRESS 0x48

// Define the log file name
#define LOG_FILE "audio_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    float microphone1;
    float microphone2;
} MicrophoneData;

// Function prototypes
int initialize_i2c();
int read_microphone_data(float *microphone1, float *microphone2);
float calculate_average_level(float microphone1, float microphone2);
int log_data(float average_level);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(I2C_DATA_PIN, PI_INPUT);
    gpioSetMode(I2C_CLOCK_PIN, PI_OUTPUT);

    // Open I2C device
    i2c_handle = i2cOpen(1, I2C_ADDRESS, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read microphone data
int read_microphone_data(float *microphone1, float *microphone2) {
    int data;
    int clock_cycles;

    // Read data from microphone 1
    data = 0;
    for (int i = 0; i < 16; i++) {
        gpioWrite(I2C_CLOCK_PIN, 1);
        gpioDelay(1); // Short delay for clock high
        data = data << 1;
        if (gpioRead(I2C_DATA_PIN)) {
            data++;
        }
        gpioWrite(I2C_CLOCK_PIN, 0);
        gpioDelay(1); // Short delay for clock low
    }

    // Read data from microphone 2
    data = 0;
    for (int i = 0; i < 16; i++) {
        gpioWrite(I2C_CLOCK_PIN, 1);
        gpioDelay(1); // Short delay for clock high
        data = data << 1;
        if (gpioRead(I2C_DATA_PIN)) {
            data++;
        }
        gpioWrite(I2C_CLOCK_PIN, 0);
        gpioDelay(1); // Short delay for clock low
    }

    // Convert to signed 16-bit integer
    short signed_data1 = (short)data;
    short signed_data2 = (short)data;

    // Convert to dB
    *microphone1 = 20 * log10f((float)abs(signed_data1) / 32768.0f);
    *microphone2 = 20 * log10f((float)abs(signed_data2) / 32768.0f);

    return 0;
}

// Function to calculate the average level
float calculate_average_level(float microphone1, float microphone2) {
    return (microphone1 + microphone2) / 2.0f;
}

// Function to log data to file
int log_data(float average_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, average_level);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file!\n");
        cleanup();
        return 1;
    }

    float microphone1, microphone2, average_level;

    // Main loop
    while (!terminate) {
        // Read microphone data
        if (read_microphone_data(&microphone1, &microphone2) != 0) {
            microphone1 = -999.0f;
            microphone2 = -999.0f;
        }

        // Calculate average level
        average_level = calculate_average_level(microphone1, microphone2);

        // Log data
        if (log_data(average_level) != 0) {
            fprintf(stderr, "Failed to log data!\n");
        }

        // Wait 100ms
        gpioDelay(100); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

