#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC1_CS 8
#define MIC2_CS 9
#define MOSI 10
#define MISO 9
#define SCLK 11
#define LED 27

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define high-level threshold
#define HIGH_THRESHOLD 500

// Define sampling window duration (in milliseconds)
#define SAMPLING_WINDOW 100

// Define number of samples per channel
#define NUM_SAMPLES (SAMPLING_WINDOW / 1) // 100ms window, 1ms sampling rate

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(int state);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate RMS level
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control LED
void control_led(int state) {
    gpioWrite(LED, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC1_CS, PI_OUTPUT);
    gpioSetMode(MIC2_CS, PI_OUTPUT);
    gpioSetMode(MOSI, PI_OUTPUT);
    gpioSetMode(MISO, PI_INPUT);
    gpioSetMode(SCLK, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Allocate memory for audio samples
    int *mic1_samples = malloc(NUM_SAMPLES * sizeof(int));
    int *mic2_samples = malloc(NUM_SAMPLES * sizeof(int));

    if (mic1_samples == NULL || mic2_samples == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Sample audio from both microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            // Read sample from microphone 1
            mic1_samples[i] = read_mcp3008(0);
            if (mic1_samples[i] < 0) {
                fprintf(stderr, "Error reading mic1 sample, exiting.\n");
                program_running = 0;
                break;
            }

            // Read sample from microphone 2
            mic2_samples[i] = read_mcp3008(1);
            if (mic2_samples[i] < 0) {
                fprintf(stderr, "Error reading mic2 sample, exiting.\n");
                program_running = 0;
                break;
            }

            // Delay for 1ms
            gpioDelay(1); // Delay in microseconds
        }

        // Calculate RMS levels
        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Check for high-level threshold
        if (mic1_rms > HIGH_THRESHOLD || mic2_rms > HIGH_THRESHOLD) {
            control_led(1); // Turn LED on
            gpioDelay(500);  // Wait for 500ms
            control_led(0); // Turn LED off
        }

        // Reset sample buffers
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = 0;
            mic2_samples[i] = 0;
        }
    }

    // Clean up
    free(mic1_samples);
    free(mic2_samples);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Audio monitoring stopped.\n");

    return 0;
}

