#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0
#define SAMPLE_RATE 10 // Hz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_ads1115(int i2c_handle, int channel);
float convert_to_current(int raw_value);
void buffer_add(CircularBuffer *cb, float value);
float buffer_get_average(CircularBuffer *cb);
void control_led(int gpio, int state);
void signal_handler(int signal);
void cleanup();

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read from ADS1115
int read_ads1115(int i2c_handle, int channel) {
    uint8_t config[3];
    int16_t raw_value;

    // Configure ADS1115 for single-ended read on channel A0
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // 4.096V, 128 SPS, Single-ended A0
    config[2] = 0x83; // Start single conversion

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    config[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, (char *)config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char buffer[2];
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];

    return raw_value;
}

// Convert raw value to current
float convert_to_current(int raw_value) {
    // Assuming a full-scale range of 4.096V and a sensitivity of 40mV/A
    return (float)raw_value * 0.0004; // 4.096V / 2^15 * 40mV/A
}

// Add value to circular buffer
void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get average of circular buffer
float buffer_get_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    control_led(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize circular buffer
    CircularBuffer current_buffer = {{0.0}, 0, 0};

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        int raw_value = read_ads1115(i2c_handle, 0);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADS1115, retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert raw value to current
        float current = convert_to_current(raw_value);

        // Add current to circular buffer
        buffer_add(&current_buffer, current);

        // Calculate average current
        float average_current = buffer_get_average(&current_buffer);

        // Check if average current exceeds threshold
        if (average_current > CURRENT_THRESHOLD) {
            control_led(LED_GPIO, 1); // Turn on LED
        } else {
            control_led(LED_GPIO, 0); // Turn off LED
        }

        // Delay to achieve 10 Hz sampling rate
        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

