#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_WTIME           (0x03)
#define TCS34725_AILTL           (0x04)
#define TCS34725_AILTH           (0x05)
#define TCS34725_AIHTL           (0x06)
#define TCS34725_AIHTH           (0x07)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_ENABLE_AIEN     (0x10)  // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN      (0x08)  // Wait Enable - Writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN      (0x02)  // ALS Enable - Writing 1 activates the ALS
#define TCS34725_ENABLE_PON      (0x01)  // Power on

// Configuration Values
#define TCS34725_INTEGRATIONTIME_2_4MS  0xFF   //  2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_GAIN_1X             0x00   //  1x

// Global Variables
static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_sensor();
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_color_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize the TCS34725 sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    // Enable power and ALS
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON);
        if (status >= 0) break;
        fprintf(stderr, "Warning: Failed to enable PON (attempt %d): %s\n", 4 - retries, strerror(errno));
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN);
        if (status >= 0) break;
        fprintf(stderr, "Warning: Failed to enable AEN (attempt %d): %s\n", 4 - retries, strerror(errno));
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) return -1;

    // Set integration time
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_2_4MS);
        if (status >= 0) break;
        fprintf(stderr, "Warning: Failed to set integration time (attempt %d): %s\n", 4 - retries, strerror(errno));
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) return -1;

    // Set gain
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN | (TCS34725_GAIN_1X << 4));
        if (status >= 0) break;
        fprintf(stderr, "Warning: Failed to set gain (attempt %d): %s\n", 4 - retries, strerror(errno));
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) return -1;

    return 0;
}

// Read color data from the sensor
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
        if (status >= 0) {
            *clear = (uint16_t)status;
            break;
        } else {
            fprintf(stderr, "Warning: Failed to read clear data (attempt %d): %s\n", 4 - retries, strerror(errno));
            gpioDelay(1000); // Wait 1ms
            retries--;
        }
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
        if (status >= 0) {
            *red = (uint16_t)status;
            break;
        } else {
            fprintf(stderr, "Warning: Failed to read red data (attempt %d): %s\n", 4 - retries, strerror(errno));
            gpioDelay(1000); // Wait 1ms
            retries--;
        }
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
        if (status >= 0) {
            *green = (uint16_t)status;
            break;
        } else {
            fprintf(stderr, "Warning: Failed to read green data (attempt %d): %s\n", 4 - retries, strerror(errno));
            gpioDelay(1000); // Wait 1ms
            retries--;
        }
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
        if (status >= 0) {
            *blue = (uint16_t)status;
            break;
        } else {
            fprintf(stderr, "Warning: Failed to read blue data (attempt %d): %s\n", 4 - retries, strerror(errno));
            gpioDelay(1000); // Wait 1ms
            retries--;
        }
    }
    if (retries == 0) return -1;

    return 0;
}

// Log color data to a CSV file
int log_color_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    uint16_t clear, red, green, blue;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (status < 0) {
        fprintf(stderr, "Error: Could not read sensor ID: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (status != 0x44) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            log_color_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error: Failed to read color data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

