#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_PIN 17
#define SPI_CE0 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define over-current threshold
#define OVER_CURRENT_THRESHOLD 10.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_amperes(int adc_value);
void log_current(float current);
void control_motor(float current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold configuration data
typedef struct {
    int motor_pin;
    int spi_ce0;
    int spi_channel;
    int spi_speed;
    float over_current_threshold;
    char *log_file_name;
} Config;

Config config = {
    MOTOR_PIN, SPI_CE0, SPI_CHANNEL, SPI_SPEED, OVER_CURRENT_THRESHOLD, "current_log.csv"
};

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI read failed, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: SPI read failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to convert ADC value to amperes
float convert_to_amperes(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and that the ADC value ranges from 0 to 1023 (10-bit ADC)
    // and the current ranges from 0 to 20A (example)
    float current = (float)adc_value / 1023.0 * 20.0;
    return current;
}

// Function to log current to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control motor based on current
void control_motor(float current) {
    if (current > config.over_current_threshold) {
        gpioWrite(config.motor_pin, 0); // Disable motor
        fprintf(log_file, "Over-current event detected! Current: %.2f A\n", current);
        fflush(log_file);
        gpioDelay(1000); // Wait 1 second
        gpioWrite(config.motor_pin, 1); // Re-enable motor
    }
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO17 as output
    gpioSetMode(config.motor_pin, PI_OUTPUT);
    gpioWrite(config.motor_pin, 1); // Initially enable the motor

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Check if the file is empty and add a header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    return 0;
}

// Cleanup function
void cleanup() {
    // Disable motor
    gpioWrite(config.motor_pin, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert to amperes
        float current = convert_to_amperes(adc_value);

        // Log current
        log_current(current);

        // Control motor
        control_motor(current);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

