void log_data(float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to check for alarm condition
void check_alarm(float ppm) {
    if (ppm > ALARM_THRESHOLD) {
        fprintf(stderr, "ALARM: Methane concentration exceeds threshold (%.2f ppm > %.2f ppm)!\n", ppm, ALARM_THRESHOLD);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Configure CS_GPIO as output
    gpioSetMode(CS_GPIO, PI_OUTPUT);
    gpioWrite(CS_GPIO, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    fprintf(stderr, "Methane monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Calculate methane concentration
        float ppm = calculate_ppm(adc_value);

        // Log data
        log_data(ppm);

        // Check for alarm condition
        check_alarm(ppm);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    cleanup();
    fprintf(stderr, "Methane monitoring stopped.\n");
    return 0;
}

