#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define MAX_PRESSURE 100.0 // kPa
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for ADS1115 configuration
typedef struct {
    uint16_t config_reg;
} ads1115_config_t;

// Function prototypes
int init_i2c();
int init_ads1115();
int16_t read_adc();
float convert_to_pressure(int16_t adc_value);
int validate_pressure(float pressure);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize ADS1115
int init_ads1115() {
    // Configure ADS1115 for single-ended AIN0, 4.096V, 128 SPS, single-shot mode
    ads1115_config_t config = {
        .config_reg = 0x4003 // 0b0100000000000011
    };

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config.config_reg >> 8) & 0xFF;
    buf[2] = config.config_reg & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register: %d\n", result);
        return -1;
    }

    return 0;
}

