    if (init_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Starting pressure monitoring...\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Convert to pressure
        float pressure = convert_to_pressure(adc_value);

        // Validate pressure
        if (validate_pressure(pressure) == 0) {
            // Log pressure
            log_pressure(pressure);
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 ms = 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

