#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email
#define EMAIL_SENDER "sender@example.com" // Replace with actual email
#define EMAIL_SUBJECT "Humidity Exceeds Threshold"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float convert_adc_to_humidity(int adc_value);
float convert_adc_to_temperature(int adc_value);
int log_data(float humidity, float temperature);
int send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from specified channel
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3208 single-ended read)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to humidity (HIH-4602-A datasheet)
float convert_adc_to_humidity(int adc_value) {
    // Datasheet formula (simplified for 12-bit ADC)
    float humidity = ((float)adc_value / 4095.0) * 100.0; // Assuming 0-100% range
    return humidity;
}

// Convert ADC value to temperature (HIH-4602-A datasheet)
float convert_adc_to_temperature(int adc_value) {
    // Datasheet formula (simplified for 12-bit ADC)
    float temperature = ((float)adc_value / 4095.0) * 125.0 - 40.0; // Assuming -40 to 125 degrees C
    return temperature;
}

// Log data to file
int log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Send email alert using ssmtp
int send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "ssmtp %s", EMAIL_RECIPIENT);

    FILE *email_pipe = popen(command, "w");
    if (email_pipe == NULL) {
        fprintf(stderr, "Error opening email pipe\n");
        return -1;
    }

    fprintf(email_pipe, "To: %s\n", EMAIL_RECIPIENT);
    fprintf(email_pipe, "From: %s\n", EMAIL_SENDER);
    fprintf(email_pipe, "Subject: %s\n\n", EMAIL_SUBJECT);
    fprintf(email_pipe, "Humidity exceeds threshold: %.2f%%\n", humidity);

    int status = pclose(email_pipe);
    if (status != 0) {
        fprintf(stderr, "Error sending email (exit status %d)\n", status);
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Convert ADC value to humidity and temperature
        float humidity = convert_adc_to_humidity(adc_value);
        float temperature = convert_adc_to_temperature(adc_value);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity exceeds threshold: %.2f%%\n", humidity);
            send_email_alert(humidity);
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

