    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(pin, PI_OUTPUT);
    return 0;
}

// GPIO set mode function
int gpio_set_mode(int pin, int mode) {
    gpioSetMode(pin, mode);
    return 0;
}

// GPIO write function
int gpio_write(int pin, int value) {
    gpioWrite(pin, value);
    return 0;
}

