    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CE) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3208(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to Celsius
        float temperature_celsius = convert_to_celsius(adc_value);

        // Validate temperature
        if (validate_temperature(temperature_celsius) != 0) {
            fprintf(stderr, "Invalid temperature reading\n");
            continue; // Skip to the next iteration
        }

        // Log temperature
        if (log_temperature(temperature_celsius) != 0) {
