int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float flow_rate_min;
    float flow_rate_max;
    char *log_file;
} Config;

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI device
int open_spi_device(int spi_channel, int spi_speed) {
    int handle = spiOpen(spi_channel, spi_speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read ADC value from MCP3008
int read_adc(int spi_handle, int adc_channel) {
    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", adc_channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | adc_channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to flow rate (L/min)
float convert_adc_to_flow_rate(int adc_value) {
    // Assuming a linear relationship between ADC value and flow rate
    // and that the ADC value ranges from 0 to 1023 (10-bit ADC)
    // and the flow rate ranges from 0.0 to 5.0 L/min
    float flow_rate = (float)adc_value / 1023.0 * 5.0;
    return flow_rate;
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
        fprintf(stderr, "Flow rate out of range: %.2f L/min\n", flow_rate);
        return -1;
    }
    return 0;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 7, ".%06ld", ts.tv_nsec / 1000);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Configuration
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .adc_channel = ADC_CHANNEL,
        .flow_rate_min = FLOW_RATE_MIN,
        .flow_rate_max = FLOW_RATE_MAX,
        .log_file = LOG_FILE
    };

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI device
    spi_handle = open_spi_device(config.spi_channel, config.spi_speed);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(spi_handle, config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Convert ADC value to flow rate
        float flow_rate = convert_adc_to_flow_rate(adc_value);

        // Validate flow rate
        if (validate_flow_rate(flow_rate) != 0) {
            continue; // Continue to the next iteration
        }

        // Log flow rate
        if (log_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Failed to log flow rate\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

