#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x68
#define MEASURE_COMMAND 0x07
#define RETRY_COUNT 3
#define RETRY_DELAY 5 // seconds
#define SAMPLE_INTERVAL 5 // seconds
#define CSV_FILENAME "environmental_data.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration parameters
typedef struct {
    double T_cal[8];
    double P_cal[8];
} calibration_params_t;

calibration_params_t cal_params;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int write_command(uint8_t command);
double calculate_temperature(uint32_t raw_temp, calibration_params_t cal_params);
double calculate_pressure(uint32_t raw_pressure, calibration_params_t cal_params);
int log_data(double temperature, double pressure);
void display_data(double temperature, double pressure);
void signal_handler(int signal);
int read_calibration_data(calibration_params_t *cal_params);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to write a command to the sensor
int write_command(uint8_t command) {
    int result = i2cWriteByteData(i2c_handle, 0x00, command); // Register address is 0x00 for ICP-10125
    if (result < 0) {
        fprintf(stderr, "Error writing command 0x%02X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6); // Read 6 bytes
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(uint32_t raw_temp, calibration_params_t cal_params) {
    double temp = raw_temp;
    double T_cal[8] = cal_params.T_cal;

    temp = (temp - T_cal[4]) * T_cal[0] + T_cal[1];
    temp = (temp - T_cal[3]) * T_cal[2] + T_cal[3];
    temp = (temp - T_cal[6]) * T_cal[5] + T_cal[6];
    temp = (temp - T_cal[7]) * T_cal[7] + T_cal[7];

    return temp;
}

// Function to calculate pressure in Pascals
double calculate_pressure(uint32_t raw_pressure, calibration_params_t cal_params) {
    double pressure = raw_pressure;
    double P_cal[8] = cal_params.P_cal;

    pressure = (pressure - P_cal[4]) * P_cal[0] + P_cal[1];
    pressure = (pressure - P_cal[3]) * P_cal[2] + P_cal[3];
    pressure = (pressure - P_cal[6]) * P_cal[5] + P_cal[6];
    pressure = (pressure - P_cal[7]) * P_cal[7] + P_cal[7];

    return pressure;
}

// Function to log data to a CSV file
int log_data(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to display data on the console
void display_data(double temperature, double pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Function to read calibration data from the sensor
int read_calibration_data(calibration_params_t *cal_params) {
    uint8_t data[32]; // Calibration data is 32 bytes
    int result = i2cReadI2CBlockData(i2c_handle, 0x31, (char *)data, 32); // Read calibration data starting from register 0x31
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    // Extract calibration parameters from the data buffer
    for (int i = 0; i < 8; i++) {
        cal_params->T_cal[i] = (double)((int16_t)(data[2 * i] << 8 | data[2 * i + 1]));
        cal_params->P_cal[i] = (double)((int16_t)(data[2 * i + 2] << 8 | data[2 * i + 3]));
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CSV_FILENAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
    }
    rewind(log_file);

    // Read calibration data
    if (read_calibration_data(&cal_params) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[6];
        int retry = 0;

        // Retry loop for I2C communication
        while (retry < RETRY_COUNT) {
            if (write_command(MEASURE_COMMAND) == 0) {
                gpioDelay(10); // Wait for conversion (adjust as needed)
                if (read_sensor_data(sensor_data) == 0) {
                    // Success, break out of retry loop
                    break;
                } else {
                    fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                    retry++;
                    sleep(RETRY_DELAY);
                }
            } else {
                fprintf(stderr, "I2C write failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                retry++;
                sleep(RETRY_DELAY);
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries. Skipping.\n", RETRY_COUNT);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Extract raw data
        uint32_t raw_pressure = ((uint32_t)sensor_data[0] << 16) | ((uint32_t)sensor_data[1] << 8) | (uint32_t)sensor_data[2];
        uint32_t raw_temperature = ((uint32_t)sensor_data[3] << 16) | ((uint32_t)sensor_data[4] << 8) | (uint32_t)sensor_data[5];

        // Calculate temperature and pressure
        double temperature = calculate_temperature(raw_temperature, cal_params);
        double pressure = calculate_pressure(raw_pressure, cal_params);

        // Log data
        log_data(temperature, pressure);

        // Display data
        display_data(temperature, pressure);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

