// Define MCP3008 channel assignments
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Define gain control parameters
#define GAIN_MIN 0
#define GAIN_MAX 100

// Global variables for SPI handle and program termination flag
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t mic1;
    int16_t mic2;
} MicrophoneData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
MicrophoneData read_microphone_data(int spi_handle);
int16_t apply_gain(int16_t sample, int gain);
int16_t noise_cancellation(int16_t mic1_sample, int16_t mic2_sample);
void print_audio_sample(int16_t sample);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read microphone data from MCP3008
MicrophoneData read_microphone_data(int spi_handle) {
    MicrophoneData data;
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | MIC1_CHANNEL) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    data.mic1 = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | MIC2_CHANNEL) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    data.mic2 = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return data;
}

// Apply gain to audio sample
int16_t apply_gain(int16_t sample, int gain) {
    return (int16_t)((sample * gain) / 100.0); // Scale gain from 0-100 to 0-1
}

// Apply noise cancellation algorithm
int16_t noise_cancellation(int16_t mic1_sample, int16_t mic2_sample) {
    // Simple averaging noise cancellation
    return (mic1_sample + mic2_sample) / 2;
}

// Print audio sample to terminal in CSV format
void print_audio_sample(int16_t sample) {
    printf("%d\n", sample);
}

int main(int argc, char *argv[]) {
    int mic1_gain = GAIN_MIN;
    int mic2_gain = GAIN_MIN;

    // Parse command-line arguments
    if (argc == 3) {
        mic1_gain = atoi(argv[1]);
        mic2_gain = atoi(argv[2]);

        if (mic1_gain < GAIN_MIN || mic1_gain > GAIN_MAX || mic2_gain < GAIN_MIN || mic2_gain > GAIN_MAX) {
            fprintf(stderr, "Error: Gain values must be between %d and %d\n", GAIN_MIN, GAIN_MAX);
            return 1;
        }
    } else {
        fprintf(stderr, "Usage: %s <mic1_gain> <mic2_gain>\n", argv[0]);
        fprintf(stderr, "Using default gain values: Mic1 = %d%%, Mic2 = %d%%\n", GAIN_MIN, GAIN_MIN);
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read microphone data
        MicrophoneData data = read_microphone_data(spi_handle);

        // Apply gain and noise cancellation
        int16_t processed_sample = noise_cancellation(apply_gain(data.mic1, mic1_gain), apply_gain(data.mic2, mic2_gain));

        // Print audio sample
        print_audio_sample(processed_sample);

        // Delay to control sampling rate (adjust as needed)
        gpioDelay(1000); // 1 ms delay
    }

    // Clean up and exit
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

