int read_mcp3008(int channel);
int validate_adc_value(int adc_value);
int log_data(int adc_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to validate ADC value
int validate_adc_value(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format timestamp as ISO 8601 UTC
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", LOG_FILE);
        return -1;
    }

    // Write data to log file
    fprintf(log_file, "%s,%d\n", timestamp, adc_value);

    // Close log file
    fclose(log_file);

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture sensor data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Validate ADC value
        if (validate_adc_value(adc_value) != 0) {
            fprintf(stderr, "Error: Failed to validate ADC value\n");
            continue; // Skip to the next iteration
        }

        // Log data
        if (log_data(adc_value) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Wait for 60 seconds
        gpioSleep(PI_TIME_RELATIVE, 60, 0);
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture sensor data logger stopped.\n");

    return 0;
}

