#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define FLAME_THRESHOLD 0.5 // Adjust as needed

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float temperature_compensation(int raw_adc, float ambient_temp);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);
int read_ambient_temperature(float *temperature);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to read ambient temperature from file
int read_ambient_temperature(float *temperature) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open ambient temperature file. Using default temperature of 25.0°C.\n");
        *temperature = 25.0;
        return -1; // Indicate file read failure
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Warning: Could not read ambient temperature from file. Using default temperature of 25.0°C.\n");
        fclose(fp);
        *temperature = 25.0;
        return -1; // Indicate file read failure
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL) {
        fprintf(stderr, "Warning: Invalid ambient temperature format. Using default temperature of 25.0°C.\n");
        *temperature = 25.0;
        return -1; // Indicate invalid format
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Warning: Invalid ambient temperature format. Using default temperature of 25.0°C.\n");
        *temperature = 25.0;
        return -1; // Indicate invalid format
    }

    char *endptr;
    *temperature = strtof(token, &endptr);
    if (*endptr != '\0') {
        fprintf(stderr, "Warning: Invalid ambient temperature format. Using default temperature of 25.0°C.\n");
        *temperature = 25.0;
        return -1; // Indicate invalid format
    }

    return 0;
}

// Function to perform temperature compensation
float temperature_compensation(int raw_adc, float ambient_temp) {
    // Simple linear compensation (replace with a more accurate model if needed)
    float voltage = (float)raw_adc / 1023.0 * 3.3; // Assuming 3.3V reference
    float compensated_voltage = voltage * (1.0 + ambient_temp * 0.1); // Example: 10% increase per degree Celsius

    return compensated_voltage;
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
