#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE SPI_MODE_0

// SPI bits per word
#define SPI_BITS_PER_WORD 8

// SPI max speed Hz
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to initialize the SPI interface
int spi_init() {
    int fd;
    int mode = SPI_MODE;
    int bits = SPI_BITS_PER_WORD;
    int speed = SPI_MAX_SPEED_HZ;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_MAX_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the received data
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// Function to calculate the moisture percentage
float calculate_moisture(int adc_value) {
    return (100.0 * adc_value) / 1023.0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the SPI interface
    spi_fd = spi_init();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (1) {
        int adc_value;
        float moisture_percentage;

        // Read the ADC value from channel 0
        adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate the moisture percentage
        moisture_percentage = calculate_moisture(adc_value);

        // Log the raw ADC reading and moisture percentage to the console
        printf("Raw ADC Value: %d, Moisture Percentage: %.2f%%\n", adc_value, moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    // The program should never reach here due to the infinite loop
    close(spi_fd);
    return 0;
}

