// Function to log data to CSV file
void log_data(float voltages[NUM_SENSORS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(fp, ",%.2f", voltages[i]);
    }
    fprintf(fp, "\n");
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("environmental_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Sensor1,Sensor2,Sensor3,Sensor4\n");
    }
    fflush(fp);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float voltages[NUM_SENSORS];

    // Main loop
    while (!terminate) {
        // Read ADC values from each sensor
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
                continue; // Skip to the next sensor
            }
            voltages[i] = convert_to_voltage(adc_value);
        }

        // Log the data
        log_data(voltages);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close SPI device and CSV file
    spiClose(spi_handle);
    fclose(fp);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

