#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define CIRCULAR_BUFFER_SIZE 20

// Data Structures
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

typedef struct {
    LogEntry buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global Variables
int spi_handle;
CircularBuffer log_buffer;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void add_log_entry(int moisture_level, int pump_state);
void print_log_buffer();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function Implementations

// Reads the analog value from the specified MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform the SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Controls the water pump by setting the specified GPIO pin
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Adds a new log entry to the circular buffer
void add_log_entry(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    LogEntry entry;
    entry.timestamp = now;
    entry.moisture_level = moisture_level;
    entry.pump_state = pump_state;

    log_buffer.buffer[log_buffer.head] = entry;
    log_buffer.head = (log_buffer.head + 1) % CIRCULAR_BUFFER_SIZE;
    if (log_buffer.count < CIRCULAR_BUFFER_SIZE) {
        log_buffer.count++;
    }
}

// Prints the contents of the circular buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    int start = (log_buffer.head - log_buffer.count + CIRCULAR_BUFFER_SIZE) % CIRCULAR_BUFFER_SIZE;
    for (int i = 0; i < log_buffer.count; i++) {
        int index = (start + i) % CIRCULAR_BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer.buffer[index].timestamp));
        printf("[%s] Moisture: %d, Pump: %s\n", time_str, log_buffer.buffer[index].moisture_level, log_buffer.buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initializes the pigpio library and SPI interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Initialize circular buffer
    log_buffer.head = 0;
    log_buffer.count = 0;

    return 0;
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Soil Moisture Monitoring and Irrigation System\n");

    while (!terminate) {
        // Read moisture level from MCP3008 channel 0
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            continue; // Skip to the next iteration
        }

        // Control the water pump based on moisture level
        int pump_state = 0; // Default to off
        if (moisture_level < MOISTURE_LOW_THRESHOLD) {
            control_pump(1); // Turn pump on
            pump_state = 1;
        } else if (moisture_level > MOISTURE_HIGH_THRESHOLD) {
            control_pump(0); // Turn pump off
            pump_state = 0;
        }

        // Add log entry
        add_log_entry(moisture_level, pump_state);

        // Print log buffer
        print_log_buffer();

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    cleanup();
    return 0;
}

