#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <math.h>

// Configuration
#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define DISTANCE_THRESHOLD 20.0 // cm
#define RELAY_PULSE_DURATION 3000 // ms
#define SAMPLE_INTERVAL 200      // ms
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY 50     // ms

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Structure to hold calibration data
typedef struct {
    double baseline;
    double slope;
} calibration_data_t;

static calibration_data_t calibration_data = {0.0, 0.0};

// Function prototypes
int i2c_write_reg(int fd, unsigned char reg, unsigned short value);
int i2c_read_reg(int fd, unsigned char reg, unsigned short *value);
int read_adc(int fd);
double adc_to_distance(int adc_value, double baseline, double slope);
void control_relay(int gpio_pin, int state);
void log_event(const char *event);
void signal_handler(int sig);
int setup_gpio(int gpio_pin, int direction);
int read_door_sensor(int gpio_pin);

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned short value) {
    unsigned char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, unsigned char reg, unsigned short *value) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (register select) failed: %s", strerror(errno));
        return -1;
    }

    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Read ADC value from ADS1115
int read_adc(int fd) {
    unsigned short config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    unsigned short adc_value;

    if (i2c_write_reg(fd, ADS1115_REG_CONFIG, config) < 0) {
        syslog(LOG_ERR, "Failed to write config register");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    if (i2c_read_reg(fd, ADS1115_REG_CONVERT, &adc_value) < 0) {
        syslog(LOG_ERR, "Failed to read conversion register");
        return -1;
    }

    // Sign extend 16-bit value to 32-bit
    long signed_adc_value = (long)adc_value << 16;

    return (int)signed_adc_value;
}

// Convert ADC value to distance (cm) using calibration data
double adc_to_distance(int adc_value, double baseline, double slope) {
    return slope * (adc_value - baseline) + 5.0; // Assuming a linear relationship
}

// Control relay (active-high)
void control_relay(int gpio_pin, int state) {
    int fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO value file: %s", strerror(errno));
        return;
    }

    if (write(fd, state ? "1" : "0", 1) != 1) {
        syslog(LOG_ERR, "Failed to write to GPIO value file: %s", strerror(errno));
    }

    close(fd);
}

// Log event to file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    if (log_file != NULL) {
        fprintf(log_file, "%ld.%03ld: %s\n", now, milliseconds, event);
        fflush(log_file);
    } else {
        syslog(LOG_ERR, "Log file is not open");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    keep_running = 0;
}

// Setup GPIO pin as input or output
int setup_gpio(int gpio_pin, int direction) {
    char buffer[64];
    int fd;

    // Export GPIO pin
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/export");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        if (errno == EBUSY) {
            // GPIO already exported, continue
        } else {
            syslog(LOG_ERR, "Failed to open GPIO export file: %s", strerror(errno));
            return -1;
        }
    } else {
        snprintf(buffer, sizeof(buffer), "%d", gpio_pin);
        write(fd, buffer, strlen(buffer));
        close(fd);
    }

    // Set GPIO direction
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", gpio_pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO direction file: %s", strerror(errno));
        return -1;
    }

    if (direction == 0) { // Input
        write(fd, "in", 2);
    } else { // Output
        write(fd, "out", 3);
    }

    close(fd);
    return 0;
}

// Read door sensor state
int read_door_sensor(int gpio_pin) {
    char buffer[64];
    int fd;
    char value;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", gpio_pin);
    fd = open(buffer, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO value file: %s", strerror(errno));
        return -1;
    }

    if (read(fd, &value, 1) != 1) {
        syslog(LOG_ERR, "Failed to read GPIO value file: %s", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);

    return (value == '0') ? 1 : 0; // Active-low
}

int main() {
    // Initialize syslog
    openlog("door_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("/var/log/door_events.log", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        fclose(log_file);
        return 1;
    }

