// Global variables
int spi_fd = -1; // SPI file descriptor
FILE *fp = NULL; // File pointer for CSV file
volatile sig_atomic_t program_running = 1; // Flag to control program execution

// Function prototypes
int spi_init(int speed, int mode);
int read_mcp3008(int spi_fd, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void cleanup(int spi_fd, FILE *fp);
void signal_handler(int signum);

// Function to initialize the SPI interface
int spi_init(int speed, int mode) {
    int fd;
    unsigned int mode_flags;

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    mode_flags = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_flags) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    // Perform SPI transaction
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error performing SPI transaction");
        return -1;
    }

    // Extract ADC value
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current timestamp
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to file
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }

    return 0;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signum);
}

// Function to cleanup resources
void cleanup(int spi_fd, FILE *fp) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    // Release GPIO resources (not directly possible with standard C, but can be done with wiringPi or similar)
    // For example, using wiringPi:
    // wiringPiSetup();
    // pinMode(CS0_GPIO, OUTPUT);
    // digitalWrite(CS0_GPIO, HIGH);
    // pinMode(CS1_GPIO, OUTPUT);
    // digitalWrite(CS1_GPIO, HIGH);
    // pinMode(CS2_GPIO, OUTPUT);
    // digitalWrite(CS2_GPIO, HIGH);
}

int main() {
    int sensor1_value, sensor2_value, sensor3_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        cleanup(spi_fd, fp);
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(fp);

    // Main loop
    while (program_running) {
        // Read sensor values
        sensor1_value = read_mcp3008(spi_fd, 0);
        sensor2_value = read_mcp3008(spi_fd, 0);
        sensor3_value = read_mcp3008(spi_fd, 0);

        // Log data to CSV file
        if (log_data(fp, sensor1_value, sensor2_value, sensor3_value) != 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup resources
    cleanup(spi_fd, fp);

    return 0;
}

