        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Detect peak above threshold
int detect_peak(int adc_value, int threshold) {
    return (adc_value > threshold) ? 1 : 0;
}

// Log event to file
void log_event(int adc_value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    fprintf(log_file, "%s, ADC Value: %d\n", buf, adc_value);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Sound event detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (detect_peak(adc_value, THRESHOLD)) {
            log_event(adc_value);
            printf("Peak detected! ADC Value: %d\n", adc_value);
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 10ms
    }

    cleanup();
    printf("Sound event detection stopped.\n");
    return 0;
}

