#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// PCF8591 I2C address
#define PCF8591_ADDR 0x48

// I2C bus
#define I2C_BUS 1

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Dummy read to discard previous conversion
        if (i2cWriteByte(i2c_fd, 0x40) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
        if (i2cReadByte(i2c_fd) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Read ADC value from AIN0
        if (i2cWriteByte(i2c_fd, 0x40) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
        int adc_value = i2cReadByte(i2c_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Print ADC value
        printf("ADC Value: %d\n", adc_value);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // This point will not be reached due to the infinite loop
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

