    config[1] = CONFIG_OS_SINGLE | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DIS;
    config[2] = 0x00; // Dummy byte

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        return -1;
    }

