    gpioDelay(10000); // 10ms

    // Read the conversion register
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from I2C device");
        return -1;
    }

    adc_value = (data[0] << 8) | data[1];
    return adc_value;
