#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define LOG_FILE "watering_events.txt"
#define MAX_ADC_VALUE 1023 // 10-bit ADC

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int is_moisture_low(int adc_value, int threshold);
void control_pump(int gpio_pin, int state);
void log_event(int adc_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to check if moisture is low
int is_moisture_low(int adc_value, int threshold) {
    return adc_value < threshold;
}

// Function to control the water pump
void control_pump(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log watering events
void log_event(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - ADC Value: %d\n", timestamp, adc_value);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Soil moisture monitoring and watering system started.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > MAX_ADC_VALUE) {
            fprintf(stderr, "Warning: Invalid ADC value: %d\n", adc_value);
            fprintf(log_file, "Warning: Invalid ADC value: %d\n", adc_value);
            fflush(log_file);
        }

        // Check moisture level
        if (is_moisture_low(adc_value, MOISTURE_THRESHOLD)) {
            fprintf(stderr, "Moisture level low, activating pump.\n");
            control_pump(PUMP_GPIO, 1); // Turn pump on
            log_event(adc_value);
            gpioDelay(WATERING_DURATION * 1000000); // Wait for watering duration (microseconds)
            control_pump(PUMP_GPIO, 0); // Turn pump off
            fprintf(stderr, "Pump deactivated.\n");
        }

        gpioDelay(60000); // Wait 60 seconds (microseconds)
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    control_pump(PUMP_GPIO, 0); // Ensure pump is off
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Soil moisture monitoring and watering system stopped.\n");

    return 0;
}

