#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define BLINK_DURATION 1000 // milliseconds
#define SAMPLE_INTERVAL 100 // milliseconds

// Global variables
static int i2c_handle;
static double threshold = 100.0; // Default threshold
static volatile int running = 1;

// Function prototypes
int init_i2c();
int16_t read_adc();
double calculate_magnetic_field(int16_t adc_value);
void blink_led();
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    double threshold;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value
int16_t read_adc() {
    char config[3];
    char buf[2];
    int16_t adc_value;

    // Configure ADS1115 for single-ended AIN0, PGA=4.096V, continuous conversion
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // 0b11000010: Single-ended AIN0, PGA=4.096V, Continuous conversion
    config[2] = 0x83; // 0b10000011: 128 SPS, Traditional comparator

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    adc_value = (buf[0] << 8) | buf[1];
    adc_value = adc_value >> 4; // Right align 12-bit value

    return adc_value;
}

// Calculate magnetic field strength in Gauss
double calculate_magnetic_field(int16_t adc_value) {
    // Sensitivity: 0.0001 Gauss/LSB (example value, check datasheet)
    return (double)adc_value * 0.0001;
}

// Blink LED
void blink_led() {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(50);          // Wait 50ms
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(50);          // Wait 50ms
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring magnetic field... Threshold: %.2f Gauss\n", threshold);

    // Main loop
    while (running) {
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        double magnetic_field = calculate_magnetic_field(adc_value);
        printf("Magnetic Field: %.2f Gauss\n", magnetic_field);

        if (magnetic_field > threshold) {
            printf("Threshold exceeded! Blinking LED...\n");
            blink_led();
            gpioDelay(BLINK_DURATION);
        }

        gpioDelay(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

