#include <wiringPiSPI.h>
#include <mosquitto.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER_ADDRESS "localhost" // Change this to your MQTT broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC_PUBLISH "soil_moisture"
#define MQTT_TOPIC_SUBSCRIBE "pump_control"
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_KEEPALIVE 60

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static int pump_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int moisture_percentage);
void publish_moisture_data(float moisture_percentage);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void signal_handler(int sig);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        syslog(LOG_ERR, "SPI read failed: %s", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

