#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// SPI device file descriptor
int spi_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nClosing SPI device and exiting...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(0);
}

// Function to initialize the SPI device
int spi_init(int fd) {
    uint8_t mode = 0; // SPI mode 0
    uint8_t bits = 8; // 8 bits per word
    uint32_t speed = 1000000; // 1 MHz

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Can't set SPI mode");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Can't set bits per word");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Can't set max speed hz");
        return -1;
    }

    return 0;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// Function to calculate the voltage from the ADC value
float calculate_voltage(int adc_value, float vdd, float vref) {
    return ((float)adc_value / 1023.0) * (vdd - vref) + vref;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the SPI device file
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open /dev/spidev0.0");
        return 1;
    }

    // Initialize the SPI device
    if (spi_init(spi_fd) < 0) {
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        float voltage = calculate_voltage(adc_value, 3.3, 3.3);

        printf("Raw ADC Value: %d, Voltage: %.2f V\n", adc_value, voltage);

        usleep(500000); // 500 ms delay
    }

    // Close the SPI device file descriptor
    close(spi_fd);

    return 0;
}

