#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_GPIO_1 17
#define MOTOR_GPIO_2 27
#define PWM_RANGE 1000
#define PWM_CLOCK_DIVISOR 16
#define NOISE_THRESHOLD 500
#define VIBRATION_LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_MS 10

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(const char *device);
int read_mcp3008(int channel);
void set_motor_pwm(int gpio, int duty_cycle);
void log_vibration_event(int gpio);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd;
    int mode = SPI_MODE;
    int bits = SPI_BITS_PER_WORD;
    int speed = SPI_SPEED;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// Set Motor PWM Duty Cycle
void set_motor_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    pwmWrite(gpio, duty_cycle);
}

// Log Vibration Event
void log_vibration_event(int gpio) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Vibration detected on GPIO %d\n", timestamp, gpio);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    keep_running = 0;
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");

    // Stop motors
    set_motor_pwm(MOTOR_GPIO_1, 0);
    set_motor_pwm(MOTOR_GPIO_2, 0);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate wiringPi
    wiringPiSetupGpio(); // Reinitialize to ensure GPIO cleanup
    pinMode(MOTOR_GPIO_1, INPUT); // Set GPIO to input to avoid short circuits
    pinMode(MOTOR_GPIO_2, INPUT);

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    int adc_value;
    int motor1_duty_cycle, motor2_duty_cycle;
    double rms_noise_level;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd == -1) {
        fprintf(stderr, "Error initializing SPI.\n");
        return 1;
    }

    // Configure GPIO pins for PWM
    pinMode(MOTOR_GPIO_1, PWM_OUTPUT);
    pinMode(MOTOR_GPIO_2, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(PWM_CLOCK_DIVISOR);

    // Open log file
    log_file = fopen(VIBRATION_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value. Skipping iteration.\n");
            delay(SAMPLE_INTERVAL_MS);
            continue;
        }

        // Calculate RMS noise level
        rms_noise_level = sqrt(adc_value * (double)adc_value / 1024.0); // Scale ADC value to 0-1 range

        // Control motors
        if (rms_noise_level > NOISE_THRESHOLD) {
            motor1_duty_cycle = (int)(rms_noise_level * 1000); // Scale RMS to PWM range
            motor2_duty_cycle = (int)(rms_noise_level * 1000);
            set_motor_pwm(MOTOR_GPIO_1, motor1_duty_cycle);
            set_motor_pwm(MOTOR_GPIO_2, motor2_duty_cycle);
        } else {
            set_motor_pwm(MOTOR_GPIO_1, 0);
            set_motor_pwm(MOTOR_GPIO_2, 0);
        }

        // Check for vibration events
        if (rms_noise_level > NOISE_THRESHOLD) {
            // Simulate vibration detection (replace with actual sensor data)
            if (rand() % 100 < 5) { // 5% chance of a "vibration event"
                log_vibration_event(MOTOR_GPIO_1);
                log_vibration_event(MOTOR_GPIO_2);
            }
        }

        delay(SAMPLE_INTERVAL_MS);
    }

    cleanup();
    return 0;
}

