#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_BUS 1
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX9814_CHANNEL 0
#define ADC_MAX_VALUE 1023.0
#define LOG_FILE "tamper_log.csv"

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float adc_to_db(int adc_value);
int read_bh1750();
void log_data(float sound_level_db, int light_level_lux, int error_code);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to dB
float adc_to_db(int adc_value) {
    return 20 * log10(adc_value / ADC_MAX_VALUE + 1);
}

// Function to read light level from BH1750 sensor
int read_bh1750() {
    // Write measurement mode command
    if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) != 0) {
        fprintf(stderr, "Error: Failed to set BH1750 measurement mode\n");
        return -1;
    }

    // Wait for measurement to complete (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read 2 bytes of data
    int light_level = i2cReadWordData(i2c_handle, 0x00);
    if (light_level < 0) {
        fprintf(stderr, "Error: Failed to read light level from BH1750\n");
        return -1;
    }

    // Convert to lux (MSB first)
    light_level = ((light_level & 0xFF00) >> 8) | ((light_level & 0x00FF) << 8);

    return light_level;
}

// Function to log data to CSV file
void log_data(float sound_level_db, int light_level_lux, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, 0x23, 0); // Bus 1, Address 0x23, Flags 0
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sound Level (dB),Light Level (Lux),Error Code\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(MAX9814_CHANNEL);
        int light_level_lux = read_bh1750();
        float sound_level_db = 0.0;
        int error_code = 0;

        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed\n");
            error_code = 1;
        } else {
            sound_level_db = adc_to_db(adc_value);
        }

        if (light_level_lux < 0) {
            fprintf(stderr, "Error: BH1750 read failed\n");
            error_code = 2;
        }

        log_data(sound_level_db, light_level_lux, error_code);

        sleep(5);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

