        // Retry loop for reading ADC value
        do {
            adc_value = read_mcp3008(0); // Read from channel 0
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read ADC value (attempt %d)\n", retries + 1);
                retries++;
                gpioDelay(100); // Wait 100ms before retrying
            } else {
                break; // Exit retry loop if read is successful
            }
        } while (retries < MAX_RETRIES);

        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);

            log_data(adc_value, moisture_percentage);

            // Control pump based on moisture level
            if (moisture_percentage < MOISTURE_THRESHOLD) {
                control_pump(1); // Turn pump ON
                printf("Moisture level low, turning pump ON\n");
            } else {
                control_pump(0); // Turn pump OFF
                printf("Moisture level OK, turning pump OFF\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup
    control_pump(0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

