    // Main loop
    while (!terminate) {
        // Read ADC value from MQ-135 sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Log the error to the file
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,Error reading ADC\n", timestamp);
            fflush(log_file);
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Convert ADC value to CO2 concentration
        float co2_ppm = adc_to_co2(adc_value);
        if (co2_ppm < 0) {
            fprintf(stderr, "Error: Failed to convert ADC to CO2\n");
            // Log the error to the file
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,Error converting ADC to CO2\n", timestamp);
            fflush(log_file);
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Control the ventilation fan
        control_fan((int)co2_ppm);

        // Log the data
        int fan_state = gpioRead(FAN_GPIO);
        log_data(co2_ppm, fan_state);

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    fprintf(stdout, "Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Air quality monitoring stopped.\n");
    return 0;
}

