#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 100
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"
#define RETRY_COUNT 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int *values, int num_values);
void set_valve_position(int average);
void log_data(int *adc_values);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transaction with retry
    int retry = 0;
    while (retry < RETRY_COUNT) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (channel %d), retrying (%d/%d)\n", channel, retry + 1, RETRY_COUNT);
            gpioDelay(1000); // Wait 1 ms before retrying
            retry++;
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries (channel %d)\n", RETRY_COUNT, channel);
    return -1; // Indicate failure
}

// Function to calculate the average of ADC values
float calculate_average(int *values, int num_values) {
    if (num_values == 0) return 0.0;

    long sum = 0;
    for (int i = 0; i < num_values; i++) {
        sum += values[i];
    }
    return (float)sum / num_values;
}

// Function to set the valve position using PWM
void set_valve_position(int average) {
    // Map average to PWM duty cycle (0-100)
    int duty_cycle = (int)(((float)average / 1023.0) * PWM_RANGE);

    // Ensure duty cycle is within valid range
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(VALVE_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(int *adc_values) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(log_file, "ADC%d: %d, ", i, adc_values[i]);
    }
    fprintf(log_file, "Average: %.2f, Valve Position: %d\n", calculate_average(adc_values, NUM_SENSORS), gpioGetPWMdutycycle(VALVE_GPIO));
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int adc_values[NUM_SENSORS];
    int valid_readings = 0;

    // Main loop
    while (!terminate) {
        // Read ADC values from sensors
        for (int i = 0; i < NUM_SENSORS; i++) {
            int result = read_mcp3008(i);
            if (result >= 0) {
                adc_values[i] = result;
                valid_readings++;
            } else {
                adc_values[i] = 0; // Store 0 for invalid readings
            }
        }

        // Calculate average
        float average = 0.0;
        if (valid_readings > 0) {
            average = calculate_average(adc_values, valid_readings);
        }

        // Set valve position
        set_valve_position((int)(average * 1023.0 / 100.0)); // Scale average to 0-1023

        // Log data
        log_data(adc_values);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioPWM(VALVE_GPIO, 0); // Set valve to 0
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

