// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define NUM_RETRIES 5
#define RETRY_DELAY_BASE_MS 10
#define RETRY_DELAY_MAX_MS 100
#define MOISTURE_MIN 0.0
#define MOISTURE_MAX 100.0
#define ADC_MIN 0
#define ADC_MAX 1023

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void log_data(float moisture);
void signal_handler(int signal);
int setup();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int num_retries;
    int retry_delay_base_ms;
    int retry_delay_max_ms;
    float moisture_min;
    float moisture_max;
    int adc_min;
    int adc_max;
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_SPEED,
    SPI_MODE,
    NUM_RETRIES,
    RETRY_DELAY_BASE_MS,
    RETRY_DELAY_MAX_MS,
    MOISTURE_MIN,
    MOISTURE_MAX,
    ADC_MIN,
    ADC_MAX
};

int main() {
    if (setup() != 0) {
        fprintf(stderr, "Setup failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture = calculate_moisture(adc_value);
            log_data(moisture);
        } else {
            // Log error if ADC read fails
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            fprintf(log_file, "%s,ERROR,Failed to read ADC value\n", buf);
            fflush(log_file);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

