#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel for LDR
#define LDR_CHANNEL 0

// Define frequency range
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000

// Define volume range
#define MIN_VOLUME 0.5
#define MAX_VOLUME 1.0

// Define error value for distance
#define ERROR_DISTANCE -1.0

// Define error value for volume
#define ERROR_VOLUME -1.0

// Define timeout duration (in microseconds)
#define TIMEOUT 50000

// Define the number of readings for LDR averaging
#define LDR_READINGS 5

// Global variables
static volatile int running = 1;
static float last_distance = ERROR_DISTANCE;
static float last_volume = ERROR_VOLUME;
static int spi_handle;
static FILE *log_file;

// Structure to hold calibration data
typedef struct {
    float frequency_offset;
    float volume_offset;
} CalibrationData;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_spi();
int read_ldr();
float read_distance();
float map_distance_to_frequency(float distance);
float map_ldr_to_volume(int ldr_value);
void generate_tone(float frequency, float volume);
void log_data(float distance, float frequency, float volume);
void load_calibration_data(CalibrationData *calibration);
void save_calibration_data(CalibrationData *calibration);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_PIN, 4000); // Set PWM frequency to 4 kHz
    gpioSetPWMrange(PWM_PIN, 1000); // Set PWM range to 1000

    return 0;
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Read LDR value from MCP3008
int read_ldr() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // MCP3008 command to read channel 0 (single-ended)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | LDR_CHANNEL) << 4; // Single-ended, channel selection
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Read distance from HC-SR04 sensor
float read_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIG_PIN, 0); // Ensure TRIG is low
    gpioDelay(2); // Wait 2 us

    gpioWrite(TRIG_PIN, 1); // Send a 10 us pulse
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    // Wait for echo to start (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        start_tick = gpioTick();
        if (count++ > 100) return ERROR_DISTANCE; // Timeout
    }

    // Wait for echo to end (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (count++ > 100) return ERROR_DISTANCE; // Timeout
    }

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (float)diff_tick / 1000000.0 * 34300.0 / 2.0; // cm

    return distance;
}

// Map distance to frequency
float map_distance_to_frequency(float distance) {
    // Linear mapping from 2cm to 50cm to 200Hz to 2000Hz
    if (distance < 2.0) return MAX_FREQUENCY;
    if (distance > 50.0) return MIN_FREQUENCY;

    return MIN_FREQUENCY + (distance - 2.0) * (MAX_FREQUENCY - MIN_FREQUENCY) / (50.0 - 2.0);
}

// Map LDR value to volume
float map_ldr_to_volume(int ldr_value) {
    // Linear mapping from 0 to 1023 to 0.5 to 1.0
    return MIN_VOLUME + (float)ldr_value / 1023.0 * (MAX_VOLUME - MIN_VOLUME);
}

// Generate tone on PWM pin
void generate_tone(float frequency, float volume) {
    int duty_cycle = (int)(volume * 1000.0); // Scale volume to duty cycle (0-1000)
    gpioPWM(PWM_PIN, duty_cycle);
    gpioSetPWMfrequency(PWM_PIN, (int)frequency); // Set PWM frequency
}

// Log data to file
void log_data(float distance, float frequency, float volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Frequency: %.2f Hz, Volume: %.2f\n", timestamp, distance, frequency, volume);
    fflush(log_file); // Ensure data is written to file immediately
}

// Load calibration data from file
void load_calibration_data(CalibrationData *calibration) {
    FILE *fp = fopen("theremin_config.txt", "r");
    if (fp == NULL) {
        // Use default values if file doesn't exist
        calibration->frequency_offset = 0.0;
        calibration->volume_offset = 0.0;
        printf("Calibration file not found, using default values.\n");
        return;
    }

    if (fscanf(fp, "%f %f", &calibration->frequency_offset, &calibration->volume_offset) != 2) {
        // Use default values if reading fails
        calibration->frequency_offset = 0.0;
        calibration->volume_offset = 0.0;
        fprintf(stderr, "Error reading calibration data, using default values.\n");
    }

    fclose(fp);
}

// Save calibration data to file
void save_calibration_data(CalibrationData *calibration) {
    FILE *fp = fopen("theremin_config.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing.\n");
        return;
    }

    fprintf(fp, "%f %f", calibration->frequency_offset, calibration->volume_offset);
    fclose(fp);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(PWM_PIN, 0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("theremin_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
    }

    // Load calibration data
    CalibrationData calibration;
    load_calibration_data(&calibration);

    printf("Theremin instrument started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read distance
        float distance = read_distance();

        // Read LDR value
        int ldr_value = read_ldr();

        if (ldr_value == -1) {
            ldr_value = last_volume; // Use last valid value
        }

        // Map distance to frequency
        float frequency = map_distance_to_frequency(distance);

        // Apply frequency offset from calibration
        frequency += calibration.frequency_offset;

        // Map LDR value to volume
        float volume = map_ldr_to_volume(ldr_value);

        // Apply volume offset from calibration
        volume += calibration.volume_offset;

        // Ensure volume is within valid range
        if (volume < MIN_VOLUME) volume = MIN_VOLUME;
        if (volume > MAX_VOLUME) volume = MAX_VOLUME;

        // Generate tone
        generate_tone(frequency, volume);

        // Log data
        if (log_file != NULL) {
            log_data(distance, frequency, volume);
        }

        // Update last valid values
        last_distance = distance;
        last_volume = volume;

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

