// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define FAN_GPIO 18
#define NUM_SENSORS 3
#define MAX_RETRIES 3
#define RETRY_DELAY 1 // seconds
#define LOG_FILE "air_quality.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_aqi(int adc_value);
void log_aqi(float aqi_values[], int num_sensors);
void control_fan(float aqi);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate AQI
float calculate_aqi(int adc_value) {
    // Simple linear mapping for demonstration purposes.
    // Replace with actual calibration data and AQI calculation formula.
    // This is a placeholder and needs to be calibrated for your specific sensors.
    float aqi = (float)adc_value * 0.5; // Example: 0-1023 -> 0-511.5
    return aqi;
}

// Function to log AQI values to a file
void log_aqi(float aqi_values[], int num_sensors) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ", timestamp);
    for (int i = 0; i < num_sensors; i++) {
        fprintf(log_file, "Sensor %d: %.2f, ", i + 1, aqi_values[i]);
    }
