    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan OFF

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn fan OFF
    gpioWrite(FAN_GPIO, 0);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    float aqi_values[NUM_SENSORS];

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = -1;
            int retries = 0;

            while (adc_value == -1 && retries < MAX_RETRIES) {
                adc_value = read_mcp3008(i);
                if (adc_value == -1) {
                    fprintf(stderr, "Error: Failed to read sensor %d, retrying...\n", i + 1);
                    retries++;
                    gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
                }
            }

            if (adc_value != -1) {
                aqi_values[i] = calculate_aqi(adc_value);
                printf("Sensor %d: ADC = %d, AQI = %.2f\n", i + 1, adc_value, aqi_values[i]);
            } else {
                fprintf(stderr, "Error: Failed to read sensor %d after multiple retries\n", i + 1);
                aqi_values[i] = -1.0; // Indicate error
            }
        }

        control_fan(aqi_values[0]); // Control fan based on the first sensor's AQI

        log_aqi(aqi_values, NUM_SENSORS);

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

