// Motor GPIOs
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// PWM Configuration
#define PWM_FREQUENCY 1000 // 1 kHz

// Potentiometer Mapping
#define POT1_MIN 0
#define POT1_MAX 1023
#define POT2_MIN 0
#define POT2_MAX 1023

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_mcp3008(int channel);
int map_pot_to_speed(int pot_value);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void accelerate(int motor, int target_speed);
void decelerate(int motor, int target_speed);
void pause(int duration_ms);
void reverse_direction(int motor);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map potentiometer reading to speed value
int map_pot_to_speed(int pot_value) {
    if (pot_value < POT1_MIN) pot_value = POT1_MIN;
    if (pot_value > POT1_MAX) pot_value = POT1_MAX;

    int speed = (int)(((float)(pot_value - POT1_MIN) / (POT1_MAX - POT1_MIN)) * 255.0);

    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    return speed;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor != 1 && motor != 2) {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    int gpio_pin;
    int direction_gpio;

    if (motor == 1) {
        gpio_pin = MOTOR1_ENABLE;
        direction_gpio = MOTOR1_DIRECTION;
    } else {
        gpio_pin = MOTOR2_ENABLE;
        direction_gpio = MOTOR2_DIRECTION;
    }

    gpioPWM(gpio_pin, speed);
    gpioWrite(direction_gpio, 1); // Assuming forward direction is high
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    if (motor != 1 && motor != 2) {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    int direction_gpio;

    if (motor == 1) {
        direction_gpio = MOTOR1_DIRECTION;
    } else {
        direction_gpio = MOTOR2_DIRECTION;
    }

    gpioWrite(direction_gpio, direction);
}

// Function to accelerate motor to target speed
void accelerate(int motor, int target_speed) {
    int current_speed = 0;
    int increment = 5; // Adjust for smooth acceleration

    while (current_speed < target_speed) {
        current_speed += increment;
        if (current_speed > target_speed) current_speed = target_speed;
        set_motor_speed(motor, current_speed);
        gpioDelay(1000); // 1ms delay
    }
}

// Function to decelerate motor to target speed
void decelerate(int motor, int target_speed) {
    int current_speed = 255; // Assuming initial speed is 255
    int decrement = 5; // Adjust for smooth deceleration

    while (current_speed > target_speed) {
        current_speed -= decrement;
        if (current_speed < target_speed) current_speed = target_speed;
        set_motor_speed(motor, current_speed);
        gpioDelay(1000); // 1ms delay
    }
}

// Function to pause for a specified duration
void pause(int duration_ms) {
    gpioDelay(duration_ms * 1000); // Convert ms to us
}

// Function to reverse motor direction
void reverse_direction(int motor) {
    int direction_gpio;

    if (motor == 1) {
        direction_gpio = MOTOR1_DIRECTION;
    } else {
        direction_gpio = MOTOR2_DIRECTION;
    }

    gpioWrite(direction_gpio, 0); // Change direction
    gpioDelay(100000); // 100ms delay
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIOs
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Configure PWM
    gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(0);
        int pot2_value = read_mcp3008(1);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer value\n");
            // Consider adding retry logic here
            pause(500000); // Wait before retrying
            continue;
        }

        // Map potentiometer values to speed
        int speed1 = map_pot_to_speed(pot1_value);
        int speed2 = map_pot_to_speed(pot2_value);

        // Accelerate, hold speed, decelerate
        accelerate(1, speed1);
        pause(2000000); // 2 seconds
        decelerate(1, 0);

        accelerate(2, speed2);
        pause(2000000); // 2 seconds
        decelerate(2, 0);

        // Pause
        pause(5000000); // 5 seconds

        // Reverse direction
        reverse_direction(1);
        pause(100000); // 100ms
        reverse_direction(2);
        pause(100000); // 100ms

        // Repeat
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

