#define SPI_CS_PIN 8

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 10

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int calibrate_noise_level();
void control_led(int state);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int led_pin;
    int spi_cs_pin;
    int spi_channel;
    int spi_baud;
    int debounce_time;
} config_t;

config_t config = {
    LED_PIN,
    SPI_CS_PIN,
    SPI_CHANNEL,
    SPI_BAUD,
    DEBOUNCE_TIME
};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI interface
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int noise_threshold = calibrate_noise_level();

    // Main loop
    while (!terminate) {
        // Read sound level from MCP3008 channel 0
        int sound_level = read_mcp3008(0);

        // Check if sound level exceeds threshold
        if (sound_level > noise_threshold) {
            // Turn on LED
            control_led(1);

            // Debounce
            gpioDelay(config.debounce_time * 1000); // Convert ms to us

            // Check if sound level is still above threshold after debounce
            if (read_mcp3008(0) > noise_threshold) {
                // Keep LED on
            } else {
                // Turn off LED
                control_led(0);
            }
        } else {
            // Turn off LED
            control_led(0);
        }

        // Delay for a short period
        gpioDelay(10000); // 10ms
    }

    // Cleanup
    control_led(0);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

