int initialize_gpio() {
    // Set LED pin as output
    gpioSetMode(config.led_pin, PI_OUTPUT);
    return 0;
}

// Function to initialize SPI interface
int initialize_spi() {
    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

