    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_MAX_SPEED_HZ;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Manually toggle CS pin
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO init failed during ADC read\n");
        return -1;
    }

    if (write(gpio_fd, "0", 1) != 1) {
        perror("Error writing to GPIO");
        return -1;
    }
    usleep(1); // Small delay

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    if (write(gpio_fd, "1", 1) != 1) {
        perror("Error writing to GPIO");
        return -1;
    }
    usleep(1); // Small delay

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log data to file
int log_data(long long timestamp_ns, int adc_value) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%lld|%d\n", timestamp_ns, adc_value);
    fflush(log_file);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_fd != -1) {
        if (munmap(gpio_map.map, gpio_map.size) == -1) {
            perror("Error unmapping GPIO memory");
        }
        close(gpio_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        // Get timestamp
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Error getting timestamp");
            break;
        }
        long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

        // Log data
        if (log_data(timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Data logging failed\n");
            break;
        }

        // Sleep for 1 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 1000000; // 1 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

