#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define MCP3008 channel assignments
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

// Define ADXL335 sensitivity (300mV/g) and VREF (3.3V)
#define SENSITIVITY 0.3
#define VREF 3.3

// Define Kalman filter parameters
#define Q 0.01
#define R 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold Kalman filter state
typedef struct {
    float x;
    float P;
} KalmanState;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_g(int adc_value);
KalmanState kalman_filter(KalmanState state, float measurement);
void print_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read analog value from MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to g-force units
float convert_to_g(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    return voltage / SENSITIVITY;
}

// Kalman filter implementation
KalmanState kalman_filter(KalmanState state, float measurement) {
    float K = state.P / (state.P + R);
    float x = state.x + K * (measurement - state.x);
    float P = (1 - K) * state.P;
    return (KalmanState){x, P};
}

// Print acceleration values to console
void print_acceleration(float x, float y, float z) {
    printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x, y, z);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI interface
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman filter state
    KalmanState x_state = {0.0, 1.0};
    KalmanState y_state = {0.0, 1.0};
    KalmanState z_state = {0.0, 1.0};

    // Main loop
    while (!terminate) {
        // Read ADC values from each channel
        int x_adc = read_mcp3008(X_CHANNEL);
        int y_adc = read_mcp3008(Y_CHANNEL);
        int z_adc = read_mcp3008(Z_CHANNEL);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to g-force units
        float x_g = convert_to_g(x_adc);
        float y_g = convert_to_g(y_adc);
        float z_g = convert_to_g(z_adc);

        // Apply Kalman filter
        x_state = kalman_filter(x_state, x_g);
        y_state = kalman_filter(y_state, y_g);
        z_state = kalman_filter(z_state, z_g);

        // Print filtered acceleration values
        print_acceleration(x_state.x, y_state.x, z_state.x);

        // Delay to achieve 10 Hz sampling rate
        gpioDelay(100000); // 100 ms = 10 Hz
    }

    // Close SPI interface and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

