#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the number of sensors
#define NUM_SENSORS 3

// Define the sensitivity of the DRV5055VA sensor (mT/V)
#define SENSITIVITY 0.002 // 2 mT/V

// Define the voltage range (V)
#define VOLTAGE_RANGE 3.3

// Define the magnetic field range (mT)
#define MAGNETIC_FIELD_RANGE 100.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to read the digital state of a GPIO pin
int read_gpio(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert a digital state to a voltage
float convert_to_voltage(int digital_state) {
    if (digital_state == 1) {
        return VOLTAGE_RANGE;
    } else {
        return 0.0;
    }
}

// Function to convert a voltage to a magnetic field strength
float convert_to_magnetic_field(float voltage) {
    return voltage * SENSITIVITY;
}

// Function to log the magnetic field strengths to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for logging!\n");
        return -1; // Indicate an error
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Check for out-of-range values and print warnings
    if (sensor1_mT < -MAGNETIC_FIELD_RANGE || sensor1_mT > MAGNETIC_FIELD_RANGE) {
        fprintf(stderr, "%s: WARNING: Sensor 1 magnetic field strength out of range: %.3f mT\n", timestamp, sensor1_mT);
    }
    if (sensor2_mT < -MAGNETIC_FIELD_RANGE || sensor2_mT > MAGNETIC_FIELD_RANGE) {
        fprintf(stderr, "%s: WARNING: Sensor 2 magnetic field strength out of range: %.3f mT\n", timestamp, sensor2_mT);
    }
    if (sensor3_mT < -MAGNETIC_FIELD_RANGE || sensor3_mT > MAGNETIC_FIELD_RANGE) {
        fprintf(stderr, "%s: WARNING: Sensor 3 magnetic field strength out of range: %.3f mT\n", timestamp, sensor3_mT);
    }

    // Write the data to the file
    fprintf(fp, "%.3f,%.3f,%.3f\n", sensor1_mT, sensor2_mT, sensor3_mT);

    // Flush the buffer to ensure data is written to the file immediately
    fflush(fp);

    fclose(fp);
    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
