#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE SPI_MODE_0

// SPI bits per word
#define SPI_BITS_PER_WORD 8

// SPI max speed Hz
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz

// Global variable for SPI file descriptor
int spi_fd = -1;

// Global variable for CSV file pointer
FILE *csv_file = NULL;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
int log_data(int channel0_value, int channel1_value, int channel2_value);
void signal_handler(int signal);

// Structure to hold SPI configuration
struct spi_config {
    int mode;
    int bits_per_word;
    int max_speed_hz;
};

// SPI configuration
struct spi_config spi_config = {
    SPI_MODE,
    SPI_BITS_PER_WORD,
    SPI_MAX_SPEED_HZ
};

// Function to initialize the SPI interface
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_config.mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_config.bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed Hz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_config.max_speed_hz) == -1) {
        perror("Error setting max speed Hz");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read data from MCP3008 channel
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode + channel number
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_MAX_SPEED_HZ;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(int channel0_value, int channel1_value, int channel2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (csv_file == NULL) {
        csv_file = fopen("sensor_data.csv", "a");
        if (csv_file == NULL) {
            perror("Error opening CSV file");
            return -1;
        }
        fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n");
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, channel0_value, channel1_value, channel2_value);
    fflush(csv_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    if (csv_file != NULL) {
        fclose(csv_file);
    }

    if (spi_fd != -1) {
        close(spi_fd);
    }

    exit(0);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (1) {
        // Read sensor data
        int channel0_value = read_mcp3008(0);
        int channel1_value = read_mcp3008(1);
        int channel2_value = read_mcp3008(2);

        if (channel0_value == -1 || channel1_value == -1 || channel2_value == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Log data to CSV file
        if (log_data(channel0_value, channel1_value, channel2_value) != 0) {
            fprintf(stderr, "Error logging data. Retrying.\n");
        }

        sleep(1); // Wait for 1 second
    }

    return 0;
}

