#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

// Configuration
#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static int reconnect_delay = 1;

// Function prototypes
void signal_handler(int sig);
int connect_mqtt(void);
void disconnect_mqtt(void);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json(const char *payload, int *led_state);
void set_led_state(int led_state);
void log_message(const char *message);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        running = 0;
        log_message("Received signal, shutting down...");
    }
}

// MQTT connection function
int connect_mqtt(void) {
    int rc;

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message("Error: Out of memory.");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_disconnect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, message_callback);

    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("Error: Connection failed.");
        mosquitto_destroy(mosq);
        mosq = NULL;
        return 1;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("Error: Subscription failed.");
        mosquitto_destroy(mosq);
        mosq = NULL;
        return 1;
    }

    log_message("Connected to MQTT broker.");
    return 0;
}

// MQTT disconnection function
void disconnect_mqtt(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        log_message("Disconnected from MQTT broker.");
    }
}

// MQTT message callback
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json(message->payload, &led_state) == 0) {
            set_led_state(led_state);
        } else {
            log_message("Error: Failed to parse JSON payload.");
        }
    } else {
        log_message("Error: Empty message received.");
    }
}

// JSON parsing function
int parse_json(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        fprintf(stderr, "Error: JSON parse error: %s\n", error.text);
        return 1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json || !json_is_boolean(led_state_json)) {
        fprintf(stderr, "Error: 'led_state' is not a boolean or missing.\n");
        json_decref(root);
        return 1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

// LED control function
void set_led_state(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "LED set to %s", led_state ? "ON" : "OFF");
    log_message(log_message_buffer);
}

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn LED off at startup

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (!mosq) {
            if (connect_mqtt() != 0) {
                // Exponential backoff
                sleep(reconnect_delay);
                reconnect_delay *= 2;
                if (reconnect_delay > MAX_RECONNECT_DELAY) {
                    reconnect_delay = MAX_RECONNECT_DELAY;
                }
            }
        } else {
            mosquitto_loop(mosq, -1, 1); // Non-blocking loop
        }
    }

    // Cleanup
    disconnect_mqtt();
    gpioWrite(GPIO_PIN, 0); // Turn LED off
    gpioTerminate();

    log_message("Exiting.");
    return 0;
}

