#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the digital output of the sound sensor
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        // Check for errors during GPIO read
        if (sound_level < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", SOUND_SENSOR_PIN);
            break; // Exit loop on error
        }

        // Print the sound level to the console
        printf("Sound level: %d\n", sound_level);

        // Check if a sound event is detected (LOW signal)
        if (sound_level == 0) {
            printf("Sound event detected!\n");

            // Activate the alarm LED for 1 second
            if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
                fprintf(stderr, "Error writing to GPIO%d\n", ALARM_LED_PIN);
                break; // Exit loop on error
            }
            gpioDelay(1000); // Delay for 1 second (1000 ms)
            if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
                fprintf(stderr, "Error writing to GPIO%d\n", ALARM_LED_PIN);
                break; // Exit loop on error
            }
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("GPIO resources released.\n");

    return 0;
}

