#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_CHIP 0
#define GPIO_PIN 17
#define GPIO_CONSUMER "vibration-monitor"
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define SHUTDOWN_COMMAND "sudo shutdown -h now"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int open_gpio_chip(int chip, const char *consumer) {
    int fd = open("/sys/class/gpio/gpiochip%d", chip);
    if (fd < 0) {
        perror("Error opening GPIO chip");
        return -1;
    }
    char line[64];
    snprintf(line, sizeof(line), "/sys/class/gpio/gpiochip%d/lines", chip);
    FILE *fp = fopen(line, "r");
    if (fp == NULL) {
        perror("Error opening GPIO lines file");
        close(fd);
        return -1;
    }
    char *token;
    char *line_buffer = NULL;
    size_t line_capacity = 0;
    ssize_t line_length;

    // Read the lines file line by line
    while ((line_length = getline(&line_buffer, &line_capacity, fp)) != -1) {
        // Tokenize the line
        token = strtok(line, ",");
        while (token != NULL) {
            if (strstr(token, consumer) != NULL) {
                int line_num = atoi(strtok(token, "="));
                if (line_num > 0) {
                    return line_num;
                }
            }
            token = strtok(NULL, ",");
        }
    }

    fclose(fp);
    if (line_buffer) free(line_buffer);
    close(fd);
    return -1; // Line not found
}

int request_gpio_line(int chip, int line, const char *consumer) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", line);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }
    if (write(fd, "in", 2) != 2) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return -1;
    }
    close(fd);

    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }
    if (write(fd, "falling", 7) != 7) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

int read_gpio_event(int chip, int line) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", line);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }
    char value[2];
    if (read(fd, value, 1) != 1) {
        perror("Error reading GPIO value file");
        close(fd);
        return -1;
    }
    close(fd);
    return (value[0] == '0') ? 1 : 0;
}

int log_event(const char *message) {
    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        perror("Error opening log file");
        return -1;
    }

    // Check if the file is newly created and truncate it if needed
    struct stat st;
    if (fstat(fd, &st) == 0) {
        if (st.st_size == 0) {
            // Truncate the file if it's empty
            if (ftruncate(fd, 0) != 0) {
                perror("Error truncating log file");
                close(fd);
                return -1;
            }
        }
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s\n", timestamp, message);

    if (write(fd, log_message, strlen(log_message)) != strlen(log_message)) {
        perror("Error writing to log file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int gpio_line = open_gpio_chip(GPIO_CHIP, GPIO_CONSUMER);
    if (gpio_line < 0) {
        gpioTerminate();
        return 1;
    }

    if (request_gpio_line(GPIO_CHIP, gpio_line, GPIO_CONSUMER) < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Vibration monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_gpio_event(GPIO_CHIP, gpio_line) == 1) {
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

            char message[256];
            snprintf(message, sizeof(message), "Vibration detected at %s. Initiating shutdown.", timestamp);

            if (log_event(message) == 0) {
                printf("%s\n", message);
            } else {
                fprintf(stderr, "Failed to log event.\n");
            }

            if (system(SHUTDOWN_COMMAND) != 0) {
                fprintf(stderr, "Failed to execute shutdown command.\n");
            }
            break; // Exit the loop after shutdown is initiated
        }
        usleep(100000); // Check every 100ms
    }

    // Cleanup
    gpioTerminate();
    printf("Vibration monitor stopped.\n");
    return 0;
}

