#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to log the event to a CSV file
int log_event(time_t timestamp, int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    struct tm *timeinfo = localtime(&timestamp);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d\n", timestamp_str, pin, state);
    fclose(fp);

    return 0;
}

// Function to handle the alarm
void handle_alarm(int state) {
    if (state == 1) {
        printf("ALARM: Flame detected!\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

