#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define I2C_BUS 1
#define MCP4725_ADDRESS 0x60
#define VREF 3.3 // Reference voltage for DAC
#define TEMP_SCALE 0.01 // 10mV/°C
#define TEMP_OFFSET 0.5 // 0.5V offset

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int set_dac_voltage(int i2c_handle, float voltage);
int log_temperature(float celsius, int adc_value, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0;
    float temperature = (voltage - TEMP_OFFSET) / TEMP_SCALE;
    return temperature;
}

// Function to set DAC voltage
int set_dac_voltage(int i2c_handle, float voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Error: Invalid DAC voltage: %.2f\n", voltage);
        return -1;
    }

    // Calculate DAC value (12-bit resolution)
    int dac_value = (int)((voltage / VREF) * 4095.0);
    if (dac_value < 0) dac_value = 0;
    if (dac_value > 4095) dac_value = 4095;

    // Construct I2C message
    char tx_buffer[3];
    tx_buffer[0] = 0x40; // Write command
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // Upper nibble
    tx_buffer[2] = (dac_value << 4) & 0xF0; // Lower nibble

    // Transfer I2C data
    int result = i2cWriteDevice(i2c_handle, tx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to log temperature data
int log_temperature(float celsius, int adc_value, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, celsius, voltage);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, celsius, voltage);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MCP4725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert to Celsius
        float celsius = convert_to_celsius(adc_value);

        // Set DAC voltage
        if (set_dac_voltage(i2c_handle, celsius) != 0) {
            fprintf(stderr, "Error: Failed to set DAC voltage\n");
            continue; // Retry
        }

        // Log temperature data
        log_temperature(celsius, adc_value, celsius * TEMP_SCALE + TEMP_OFFSET);

        // Wait 0.5 seconds
        gpioDelay(500000); // 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

