// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 16
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "sound_events.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int is_sound_detected(int adc_value, int threshold);
void control_led(int state);
void log_event(int adc_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close SPI interface
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to detect sound
int is_sound_detected(int adc_value, int threshold) {
    return adc_value > threshold;
}

