    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    int threshold = 500; // Adjust this threshold based on your sensor and environment
    int last_trigger_time = 0;

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        if (is_sound_detected(adc_value, threshold)) {
            int current_time = gpioTick();
            if (current_time - last_trigger_time > DEBOUNCE_DELAY_MS * 1000) {
                control_led(1); // Turn on LED
                log_event(adc_value); // Log the event
                gpioDelay(500); // Wait for 500ms
                control_led(0); // Turn off LED
                last_trigger_time = current_time;
            }
        }

        gpioDelay(10); // Sample every 10ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

