void control_motor(int direction, int duration) {
    if (direction != 0 && direction != 1) {
        fprintf(stderr, "Error: Invalid motor direction: %d\n", direction);
        return;
    }

    // Set motor direction pins
    if (direction == 0) { // Forward
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
    } else { // Reverse
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
    }

    // Set PWM duty cycle
    gpioPWM(MOTOR_ENA, PWM_DUTY);

    // Wait for specified duration
    gpioDelay(duration * 1000000); // Convert seconds to microseconds

