    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read rain sensor value
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor value\n");
            continue; // Skip to the next iteration
        }

        // Log data
        log_data(rain_level);

        // Control motor based on rain level
        if (rain_level > RAIN_THRESHOLD) {
            printf("Rain detected! Closing window.\n");
            control_motor(0, 3); // Close window
        } else {
            printf("No rain detected. Opening window.\n");
            control_motor(1, 3); // Open window
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

