#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define ADC_PIN 26
#define LED_PIN 16

// Define clap detection parameters
#define CLAP_THRESHOLD 500
#define DEBOUNCE_DELAY 50 // milliseconds

// Global variables
static volatile int running = 1;
static int clap_count = 0;
static unsigned long last_clap_time = 0;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int adc_value);
void control_led(int state);
void print_timestamped_message(const char *message);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
} program_state_t;

program_state_t state = {0};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    state.gpio_initialized = 1;

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_adc();

        // Detect clap event
        if (detect_clap(adc_value)) {
            clap_count++;
            unsigned long current_time = gpioTick();

            // Debounce mechanism
            if (clap_count == 1) {
                last_clap_time = current_time;
            } else if (clap_count >= 2) {
                if ((current_time - last_clap_time) > (DEBOUNCE_DELAY * 1000)) { // Convert ms to microseconds
                    // Valid clap detected
                    printf("Clap detected!\n");
                    print_timestamped_message("Clap detected!");

                    // Turn on LED
                    control_led(1);

                    // Wait for 500ms
                    gpioDelay(500);

                    // Turn off LED
                    control_led(0);

                    // Reset clap count
                    clap_count = 0;
                }
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10);
    }

    // Clean up GPIO
