#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "soil_moisture.log"
#define MAX_ADC_VALUE 1023.0
#define MIN_ADC_VALUE 0.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_moisture_percentage(int adc_value);
void control_pump(int pump_state);
void log_data(float moisture_percentage, int pump_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > MAX_ADC_VALUE) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    float moisture_percentage = ((float)adc_value / MAX_ADC_VALUE) * 100.0;
    return moisture_percentage;
}

// Control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
}

// Log data to file
void log_data(float moisture_percentage, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f, %s\n", timestamp, moisture_percentage, pump_state == 1 ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in 60 seconds...\n");
            time_sleep(60.0);
            continue;
        }

        // Convert to moisture percentage
        float moisture_percentage = convert_to_moisture_percentage(adc_value);
        if (moisture_percentage < 0) {
            fprintf(stderr, "Error converting ADC value to moisture percentage, retrying in 60 seconds...\n");
            time_sleep(60.0);
            continue;
        }

        // Control pump
        int pump_state = 0;
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            control_pump(1); // Turn pump ON
            pump_state = 1;
        } else {
            control_pump(0); // Turn pump OFF
            pump_state = 0;
        }

        // Log data
        log_data(moisture_percentage, pump_state);

        // Wait 60 seconds
        time_sleep(60.0);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn pump OFF
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

