#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LED_PIN 21 // BCM GPIO 21
#define MAGNETIC_FIELD_THRESHOLD 10.0 // mT
#define ADC_MAX_VALUE 1023.0 // 10-bit ADC

// Global variables
FILE *log_file = NULL;
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init();
int read_mcp3008(int channel);
float adc_to_magnetic_field(int adc_value);
int log_data(float magnetic_field);
void control_led(float magnetic_field);
void signal_handler(int signal);

// SPI Initialization
int spi_init() {
    if ((spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "SPI setup failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Convert ADC value to magnetic field strength (mT)
float adc_to_magnetic_field(int adc_value) {
    return (adc_value / ADC_MAX_VALUE) * 20.0; // Assuming 0-20mT range
}

// Log data to file
int log_data(float magnetic_field) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f mT\n", timestamp, magnetic_field);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Control LED based on magnetic field strength
void control_led(float magnetic_field) {
    if (magnetic_field > MAGNETIC_FIELD_THRESHOLD) {
        digitalWrite(LED_PIN, HIGH); // Turn LED on
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
    if (log_file != NULL) {
        fclose(log_file);
    }
    digitalWrite(LED_PIN, LOW); // Turn off LED
    exit(0);
}

int main() {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (spi_init() == -1) {
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Initially turn off the LED

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Magnetic sensor data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value.\n");
            continue; // Skip to the next iteration
        }

        float magnetic_field = adc_to_magnetic_field(adc_value);

        if (log_data(magnetic_field) == -1) {
            fprintf(stderr, "Failed to log data.\n");
        }

        control_led(magnetic_field);

        delay(100); // Sample every 100 ms
    }

    return 0;
}

