            fprintf(log_file, "%s -1\n", timestamp);
            fflush(log_file);
            fprintf(stderr, "Error: Failed to read from MCP3008.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, config.read_interval, 0); // Sleep for 60 seconds
    }

