// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 2000 // 2ms

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to read the sensor value with debouncing
int read_sensor_debounced(int gpio) {
    int readings[DEBOUNCE_READINGS];
    int i;

    // Read the sensor multiple times and store the values
    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(gpio);
        gpioDelay(DEBOUNCE_DELAY_US);
    }

    // Determine the majority value
    int majority = 0;
