// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for SPI configuration
typedef struct {
    int channel;
    int baud;
} spi_config_t;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture level
double calculate_moisture_level(int adc_value) {
    double moisture_level = ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture_level < 0.0) {
        moisture_level = 0.0;
    } else if (moisture_level > 100.0) {
        moisture_level = 100.0;
    }
    return moisture_level;
}

// Function to log data to file
void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_entry, sizeof(log_entry), "%s,%.2f\n", timestamp, moisture_level);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    if (fprintf(fp, "%s", log_entry) < 0) {
        fprintf(stderr, "Error writing to log file!\n");
    }

    fclose(fp);
    printf("%s", log_entry);
}

// Function to initialize SPI
int spi_setup(spi_config_t config) {
    int handle = spiOpen(config.channel, config.baud, 0); // SPI channel 0, 1MHz, no flags
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return -1;
    }
    return handle;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD};
    spi_handle = spi_setup(spi_config);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        // Calculate moisture level
        double moisture_level = calculate_moisture_level(adc_value);

        // Log data
        log_data(moisture_level);

        // Wait for the next reading
        sleep(READ_DELAY);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

