#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <stdbool.h>

// Configuration
#define PIR_GPIO 17
#define DHT22_GPIO 4
#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_CALIB_DATA_ADDR 0x88
#define BMP280_CALIB_DATA_LEN 26

#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DELAY_S 5

// Global variables
static volatile int running = 1;
static int i2c_fd;
static int bmp280_calib_data[26];

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_i2c();
int read_dht22(float *temperature, float *humidity);
int read_bmp280(float *temperature, float *pressure);
int capture_image(const char *filename);
void log_event(int priority, const char *message);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    log_event(LOG_INFO, "Received signal, shutting down...");
    running = 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    return 0;
}

// Initialize I2C
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-1"); // Standard I2C bus on Raspberry Pi

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        log_event(LOG_ERR, "Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        log_event(LOG_ERR, "Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    // Check BMP280 chip ID
    unsigned char chip_id;
    if (read(i2c_fd, &chip_id, 1) != 1) {
        log_event(LOG_ERR, "Failed to read BMP280 chip ID");
        close(i2c_fd);
        return -1;
    }

    if (chip_id != BMP280_CHIP_ID) {
        log_event(LOG_ERR, "Incorrect BMP280 chip ID");
        close(i2c_fd);
        return -1;
    }

    // Set BMP280 to forced mode and configure oversampling
    unsigned char ctrl_meas = (0x03 << 5) | (0x05 << 2) | 0x03; // Temperature x8, Pressure x16, Normal mode
    unsigned char config = (0x02 << 5) | (0x04 << 2); // t_sb = 0.5ms, filter = x16

    unsigned char buf[2];
    buf[0] = BMP280_CTRL_MEAS_REG;
    buf[1] = ctrl_meas;
    if (write(i2c_fd, buf, 2) != 2) {
        log_event(LOG_ERR, "Failed to write to BMP280 control register");
        close(i2c_fd);
        return -1;
    }

    buf[0] = BMP280_CONFIG_REG;
    buf[1] = config;
    if (write(i2c_fd, buf, 2) != 2) {
        log_event(LOG_ERR, "Failed to write to BMP280 config register");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read DHT22 sensor
int read_dht22(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_LOW);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(30);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read data
    for (int i = 0; i < 85; i++) {
        int counter = 0;
        while (gpioRead(DHT22_GPIO) == laststate) {
            counter++;
            gpioDelay(1);
            if (counter == 255) {
                log_event(LOG_ERR, "DHT22 timeout error");
                return -1;
            }
        }
        laststate = gpioRead(DHT22_GPIO);

        if (counter > 3) {
            data[j / 8] <<= 1;
            if (counter > 16)
                data[j / 8] |= 1;
            j++;
        }
    }

    // Check checksum
    if (j < 40 || data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        log_event(LOG_ERR, "DHT22 checksum error");
        return -1;
    }

    // Convert data
    *humidity = (float)(((data[0] << 8) + data[1]) / 10.0);
    *temperature = (float)(((data[2] << 8) + data[3]) / 10.0);

    return 0;
}

// Read BMP280 sensor
int read_bmp280(float *temperature, float *pressure) {
    unsigned char data[6];
    int32_t raw_temp, raw_press;
    int32_t var1, var2, T, p;

    // Read temperature and pressure data
    unsigned char reg = BMP280_TEMP_MSB_REG;
    if (write(i2c_fd, &reg, 1) != 1) {
        log_event(LOG_ERR, "Failed to write to BMP280 data register");
        return -1;
    }
    if (read(i2c_fd, data, 6) != 6) {
        log_event(LOG_ERR, "Failed to read BMP280 data");
        return -1;
    }

    raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    // Temperature compensation
    var1 = ((((raw_temp >> 3) - ((int32_t)bmp280_calib_data[5] << 1))) * ((int32_t)bmp280_calib_data[6])) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)bmp280_calib_data[2] << 1))) * ((raw_temp >> 4) - ((int32_t)bmp280_calib_data[2] << 1))) >> 12) * ((int32_t)bmp280_calib_data[1]) >> 14;
    T = var1 + var2;
    *temperature = (float)((T * 5 + 128) >> 8) / 100.0;

    // Pressure compensation
    var1 = (((int32_t)bmp280_calib_data[0] << 12) + (raw_press * ((int32_t)bmp280_calib_data[3])) >> 11) * ((int32_t)bmp280_calib_data[6]) >> 14;
    var2 = (((((raw_press >> 8) - ((int32_t)bmp280_calib_data[4] << 1))) * (((raw_press >> 8) - ((int32_t)bmp280_calib_data[4] << 1))) >> 12) * ((int32_t)bmp280_calib_data[1])) >> 14;
    p = var1 + var2;
    *pressure = (float)((p * 5 + 128) >> 8) / 100.0;

    return 0;
}

// Capture image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 --nopreview", filename);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        if (execvp(command, NULL) == -1) {
            log_event(LOG_ERR, "Failed to execute libcamera-still");
            perror("execvp");
            exit(EXIT_FAILURE);
        }
    } else if (pid < 0) {
        log_event(LOG_ERR, "Failed to fork process");
        perror("fork");
        return -1;
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            log_event(LOG_ERR, "libcamera-still exited with error");
            return -1;
        }
    }

    return 0;
}

// Log events to syslog
void log_event(int priority, const char *message) {
    syslog(priority, message);
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

int main() {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        closelog();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Read BMP280 calibration data
    unsigned char calib_data[BMP280_CALIB_DATA_LEN];
    unsigned char reg = BMP280_CALIB_DATA_ADDR;
    if (write(i2c_fd, &reg, 1) != 1) {
        log_event(LOG_ERR, "Failed to write to BMP280 calibration register");
        close(i2c_fd);
        gpioTerminate();
        closelog();
        return 1;
    }
    if (read(i2c_fd, calib_data, BMP280_CALIB_DATA_LEN) != BMP280_CALIB_DATA_LEN) {
        log_event(LOG_ERR, "Failed to read BMP280 calibration data");
        close(i2c_fd);
        gpioTerminate();
        closelog();
        return 1;
    }

    for (int i = 0; i < 26; i++) {
        bmp280_calib_data[i] = (int16_t)((calib_data[2 * i] << 8) | calib_data[2 * i + 1]);
    }

    log_event(LOG_INFO, "Security camera started");

    while (running) {
        // Read PIR sensor
        int pir_value = gpioRead(PIR_GPIO);

        // Debounce and read DHT22 sensor
        static int last_pir_value = 0;
        if (pir_value != last_pir_value) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
            float temperature, humidity;
            if (read_dht22(&temperature, &humidity) == 0) {
                char message[256];
                snprintf(message, sizeof(message), "Motion detected, DHT22: Temp=%.2fC, Hum=%.2f%%", temperature, humidity);
                log_event(LOG_INFO, message);
            } else {
                log_event(LOG_ERR, "Failed to read DHT22 sensor");
            }
            last_pir_value = pir_value;
        }

        // Read BMP280 sensor
