#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define FRAME_RATE 30
#define FRAME_DURATION_US (1000000 / FRAME_RATE)
#define BUFFER_COUNT 1
#define MAX_FILENAME_LENGTH 256

typedef struct {
    void *start;
    size_t length;
} buffer_t;

buffer_t *buffers;
int fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int init_mmap(int fd, buffer_t *buffers, int buffer_count) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = buffer_count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < buffer_count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    return 0;
}

int start_capturing(int fd) {
    for (int i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int dequeue_buffer(int fd, int *buffer_index) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for buffer\n");
        return -1; // EAGAIN
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *buffer_index = buf.index;
    return 0;
}

int save_image(const char *filename, const buffer_t *buffer) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t bytes_written = fwrite(buffer->start, 1, buffer->length, fp);
    if (bytes_written != buffer->length) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    fclose(fp);
    return 0;
}

int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int uninit_mmap(int fd, buffer_t *buffers, int buffer_count) {
    for (int i = 0; i < buffer_count; i++) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            fprintf(stderr, "Error unmapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

int close_device(int fd) {
    if (close(fd) == -1) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("capture.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int buffer_index = 0;
    int frame_count = 0;

    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (init_device(fd) == -1) {
        close_device(fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (init_mmap(fd, buffers, BUFFER_COUNT) == -1) {
        close_device(fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (start_capturing(fd) == -1) {
        uninit_mmap(fd, buffers, BUFFER_COUNT);
        close_device(fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        if (dequeue_buffer(fd, &buffer_index) == 0) {
            char filename[MAX_FILENAME_LENGTH];
            snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_count++);
            if (save_image(filename, &buffers[buffer_index]) != 0) {
                fprintf(stderr, "Error saving image %s\n", filename);
            }
        } else {
            // EAGAIN, continue capturing
            continue;
        }
    }

    if (stop_capturing(fd) == -1) {
        uninit_mmap(fd, buffers, BUFFER_COUNT);
        close_device(fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (uninit_mmap(fd, buffers, BUFFER_COUNT) == -1) {
        close_device(fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (close_device(fd) == -1) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (fclose(log_file) == -1) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Capture session finished.\n");
    return EXIT_SUCCESS;
}

