// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize the video device
int initialize_video_device(video_device_t *device) {
    device->fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK);
    if (device->fd == -1) {
        perror("Error opening video device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(device->fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(device->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        close(device->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        close(device->fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Set desired width
    fmt.fmt.pix.height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Request MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(device->fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(device->fd);
        return -1;
    }

    device->width = fmt.fmt.pix.width;
    device->height = fmt.fmt.pix.height;
    device->format = fmt.fmt.pix.pixelformat;

    return 0;
}

// Function to allocate memory and map the video buffer
int map_video_buffer(video_device_t *device) {
    device->buffer = mmap(NULL, MJPEG_BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, device->fd, 0);
    if (device->buffer == MAP_FAILED) {
        perror("Error mapping video buffer");
        close(device->fd);
        return -1;
    }
    device->buffer_size = MJPEG_BUFFER_SIZE;
    return 0;
}

// Function to unmap the video buffer
void unmap_video_buffer(video_device_t *device) {
    if (device->buffer != MAP_FAILED) {
        if (munmap(device->buffer, device->buffer_size) == -1) {
            perror("Error unmapping video buffer");
        }
        device->buffer = MAP_FAILED; // Mark as unmapped
    }
}

// Function to capture a frame from the video device
int capture_frame(video_device_t *device) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.length = MJPEG_BUFFER_SIZE; // Set length to buffer size

    if (ioctl(device->fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return buf.bytesused;
}

// Function to log the timestamp of a frame to a file
int log_frame_time(const char *filename, struct timeval tv) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%ld.%06ld\n", tv.tv_sec, tv.tv_usec);
    fclose(fp);
    return 0;
}

int main() {
    video_device_t device;
    struct timeval tv;
    fd_set readfds;
    int retval;

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the video device
    if (initialize_video_device(&device) == -1) {
        return EXIT_FAILURE;
    }

    // Map the video buffer
    if (map_video_buffer(&device) == -1) {
        close(device.fd);
        return EXIT_FAILURE;
    }

    // Main loop to capture frames and log timestamps
    while (program_running) {
        FD_ZERO(&readfds);
        FD_SET(device.fd, &readfds);

        retval = select(device.fd + 1, &readfds, NULL, NULL, NULL);
        if (retval == -1) {
            perror("Error in select");
            break;
        } else if (retval) {
            // Frame is ready
            int frame_size = capture_frame(&device);
            if (frame_size > 0) {
                gettimeofday(&tv, NULL);
                if (log_frame_time(FRAME_LOG_FILE, tv) == -1) {
                    fprintf(stderr, "Error logging frame time\n");
                }
            } else {
                fprintf(stderr, "Error capturing frame\n");
                break;
            }
        } else {
            // Timeout occurred, but we continue
            //printf("Timeout occurred, continuing...\n");
        }
    }

    // Clean up resources before exiting
    unmap_video_buffer(&device);
    close(device.fd);

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

