#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define NUM_BUFFERS 4
#define WIDTH 192
#define HEIGHT 128
#define FRAME_RATE 30
#define FILENAME "image.jpg"

struct buffer {
    void   *start;
    size_t  length;
};

static volatile int keep_running = 1;
static int fd = -1;
static struct buffer *buffers = NULL;
static FILE *file = NULL;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    keep_running = 0;
}

int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    return 0;
}

int request_buffers(int fd, int num_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < num_buffers) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    return 0;
}

int map_buffer(int fd, int buffer_index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        return -1;
    }

    buffers[buffer_index].length = buf.length;
    buffers[buffer_index].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

    if (buffers[buffer_index].start == MAP_FAILED) {
        perror("Error mapping buffer");
        return -1;
    }

    return 0;
}

int start_capturing(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

int dequeue_frame(int fd, int buffer_index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return buf.bytesused;
}

int write_to_file(const void *data, size_t size, const char *filename) {
    file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    if (fwrite(data, 1, size, file) != size) {
        perror("Error writing to file");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int uninit_device(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
        return -1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    return 0;
}

int close_device(int fd) {
    if (close(fd) == -1) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (request_buffers(fd, NUM_BUFFERS) == -1) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(NUM_BUFFERS, sizeof(struct buffer));
    if (buffers == NULL) {
        perror("Error allocating buffer array");
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (map_buffer(fd, i) == -1) {
            free(buffers);
            uninit_device(fd);
            close_device(fd);
            return EXIT_FAILURE;
        }
    }

    if (start_capturing(fd) == -1) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    int bytes_used = dequeue_frame(fd, 0);
    if (bytes_used <= 0) {
        fprintf(stderr, "No data received\n");
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (write_to_file(buffers[0].start, bytes_used, FILENAME) == -1) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    printf("Frame saved to %s\n", FILENAME);

    for (int i = 0; i < NUM_BUFFERS; i++) {
        munmap(buffers[i].start, buffers[i].length);
    }
    free(buffers);

    if (uninit_device(fd) == -1) {
        return EXIT_FAILURE;
    }

    if (close_device(fd) == -1) {
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

