        return -1;
    }

    return buf.bytesused;
}

int write_to_file(const void *data, size_t size, const char *filename) {
    file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    if (fwrite(data, 1, size, file) != size) {
        perror("Error writing to file");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int uninit_device(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
        return -1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    return 0;
}

int close_device(int fd) {
    if (close(fd) == -1) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (request_buffers(fd, NUM_BUFFERS) == -1) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(NUM_BUFFERS, sizeof(struct buffer));
    if (buffers == NULL) {
        perror("Error allocating buffer array");
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (map_buffer(fd, i) == -1) {
            free(buffers);
            uninit_device(fd);
            close_device(fd);
            return EXIT_FAILURE;
        }
    }

    if (start_capturing(fd) == -1) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    int bytes_used = dequeue_frame(fd, 0);
    if (bytes_used <= 0) {
        fprintf(stderr, "No data received\n");
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (write_to_file(buffers[0].start, bytes_used, FILENAME) == -1) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    printf("Frame saved to %s\n", FILENAME);

    for (int i = 0; i < NUM_BUFFERS; i++) {
        munmap(buffers[i].start, buffers[i].length);
    }
    free(buffers);

    if (uninit_device(fd) == -1) {
        return EXIT_FAILURE;
    }

    if (close_device(fd) == -1) {
        return EXIT_FAILURE;
    }

