#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <math.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

typedef struct {
    void   *start;
    size_t  length;
} buffer;

static int fd = -1;
static buffer *buffers = NULL;
static unsigned int n_buffers = 0;
static int running = 1;

static void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

static int xioctl(int fh, int request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static int read_frame(int fd, buffer *buffers, unsigned int n_buffers) {
    fd_set rfds;
    struct timeval tv;
    int r;

    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &rfds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    } else {
        return 0; // Frame is ready
    }
}

static int init_device(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    *fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (*fd == -1) {
        perror("Cannot open '/dev/video0'");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", "/dev/video0");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", "/dev/video0");
        close(*fd);
        return -1;
    }

    CLEAR(fmt);

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }

    CLEAR(req);

    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        close(*fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", "/dev/video0");
        close(*fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(buffer));
    if (!buffers) {
        perror("Out of memory");
        close(*fd);
        return -1;
    }

    for (i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;

        CLEAR(buf);

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            close(*fd);
            free(buffers);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL /* start anywhere */,
                                buf.length,
                                PROT_READ | PROT_WRITE /* required */,
                                MAP_SHARED /* recommended */,
                                *fd, buf.m.offset);

        if (MAP_FAILED == buffers[i].start) {
            perror("mmap");
            close(*fd);
            free(buffers);
            return -1;
        }
    }

    return 0;
}

static int start_capturing(int fd) {
    unsigned int i;
    enum v4l2_buf_type type;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        CLEAR(buf);

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

static int stop_capturing(int fd) {
    enum v4l2_buf_type type;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }

    return 0;
}

static int uninit_device(int fd) {
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("munmap");
            return -1;
        }
    }

    free(buffers);

    if (close(fd) == -1) {
        perror("close");
        return -1;
    }

    return 0;
}

static int encode_jpeg(unsigned char *yuyv, int width, int height, int quality, unsigned char **jpeg_data, unsigned long *jpeg_size) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    unsigned char *row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    jpeg_mem_dest(&cinfo, jpeg_data, jpeg_size);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3; // RGB

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &yuyv[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

static int convert_yuyv_to_rgb(unsigned char *yuyv, int width, int height, unsigned char *rgb) {
    int i, j;
    unsigned char *y, *u, *v, *r, *g, *b;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            y = yuyv + (i * width * 2) + (j * 2);
            u = y + 1;
            v = y + 3;

            r = y + 0;
            g = y + 1;
            b = y + 2;

            // YUV to RGB conversion (simplified)
            r = y + 0;
            g = y + 1;
            b = y + 2;

            *r = *y + 1.370705 * (*v - 128);
            *g = *y - 0.698001 * (*v - 128) - 0.336331 * (*u - 128);
            *b = *y + 1.732446 * (*u - 128);

            // Clamp RGB values to 0-255
            if (*r < 0) *r = 0;
            if (*r > 255) *r = 255;
            if (*g < 0) *g = 0;
            if (*g > 255) *g = 255;
            if (*b < 0) *b = 0;
            if (*b > 255) *b = 255;

            yuyv += 4; // Move to the next YUYV pair
            rgb += 3;  // Move to the next RGB pixel
        }
    }

    return 0;
}

static int apply_gaussian_blur(unsigned char *rgb, int width, int height, unsigned char *blurred_rgb) {
    int i, j;
    int kernel_size = 5; // Define the size of the Gaussian blur kernel
    float kernel[5][5] = {
        {0.0113, 0.0780, 0.1840, 0.0780, 0.0113},
        {0.0780, 0.5556, 1.0000, 0.5556, 0.0780},
        {0.1840, 1.0000, 1.8367, 1.0000, 0.1840},
        {0.0780, 0.5556, 1.0000, 0.5556, 0.0780},
        {0.0113, 0.0780, 0.1840, 0.0780, 0.0113}
    };

    for (i = 1; i < height - 1; i++) {
        for (j = 1; j < width - 1; j++) {
            int r_sum = 0, g_sum = 0, b_sum = 0;
            int r_count = 0, g_count = 0, b_count = 0;

            // Apply the Gaussian blur kernel
            for (int x = -2; x <= 2; x++) {
                for (int y = -2; y <= 2; y++) {
                    int index = (i + y) * width + (j + x);
                    r_sum += rgb[index * 3 + 0] * kernel[2 + y][2 + x];
                    g_sum += rgb[index * 3 + 1] * kernel[2 + y][2 + x];
