            blurred_rgb[(i * width) + j * 3 + 1] = (unsigned char)(g_sum / g_count);
            blurred_rgb[(i * width) + j * 3 + 2] = (unsigned char)(b_sum / b_count);
        }
    }

    return 0;
}

