#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define MAX_RESOLUTIONS 10

// Structure to hold frame size information
typedef struct {
    unsigned int width;
    unsigned int height;
} frame_size_t;

// Structure to hold frame interval information
typedef struct {
    unsigned int interval;
} frame_interval_t;

// Function to check if a file exists
int file_exists(const char *filename) {
    if (access(filename, F_OK) == 0) {
        return 1;
    } else {
        return 0;
    }
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to query the device capabilities
int query_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to enumerate supported frame sizes
int enumerate_frame_sizes(int fd, frame_size_t *frame_sizes, int max_sizes) {
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsizeenum;
    int i = 0;

    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmtdesc.flags = 0;

    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0 && i < max_sizes) {
        frmsizeenum.index = 0;
        frmsizeenum.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        frmsizeenum.pixel_format = fmtdesc.pixelformat;

        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsizeenum) < 0) {
            fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
            break;
        }

        if (frmsizeenum.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            frame_sizes[i].width = frmsizeenum.discrete.width;
            frame_sizes[i].height = frmsizeenum.discrete.height;
            i++;
        }

        fmtdesc.index++;
    }

    return i;
}

// Function to enumerate supported frame intervals
int enumerate_frame_intervals(int fd, frame_interval_t *frame_intervals, int max_intervals) {
    struct v4l2_frmivalenum frmivalenum;
    int i = 0;

    frmivalenum.index = 0;
    frmivalenum.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    frmivalenum.pixel_format = V4L2_PIX_FMT_YUYV; // Example pixel format

    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmivalenum) == 0 && i < max_intervals) {
        frame_intervals[i].interval = frmivalenum.interval;
        i++;
        frmivalenum.index++;
    }

    return i;
}

// Function to query the focus control
int query_focus_control(int fd) {
    struct v4l2_control control;

    control.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &control) < 0) {
        fprintf(stderr, "Error querying focus control: %s\n", strerror(errno));
        return -1;
    }

    if (control.type != V4L2_CTRL_TYPE_BOOLEAN) {
        fprintf(stderr, "Focus control is not a boolean type\n");
        return -1;
    }

    return control.value;
}

// Function to print the summary
void print_summary(frame_size_t *frame_sizes, int num_sizes, frame_interval_t *frame_intervals, int num_intervals, int autofocus_supported) {
    printf("Summary:\n");
    printf("---------\n");

    for (int i = 0; i < num_sizes; i++) {
        printf("  %ux%u: ", frame_sizes[i].width, frame_sizes[i].height);
        printf("Intervals: ");
        for (int j = 0; j < num_intervals; j++) {
            printf("%u ", frame_intervals[j].interval);
        }
        printf("\n");
    }

    if (autofocus_supported) {
        printf("  Autofocus: Supported\n");
    } else {
        printf("  Autofocus: Not Supported\n");
    }
}

int main() {
    int fd;
    frame_size_t frame_sizes[MAX_RESOLUTIONS];
    frame_interval_t frame_intervals[MAX_RESOLUTIONS];
    int num_frame_sizes, num_frame_intervals;
    int autofocus_supported;

    // Check if the device exists
    if (!file_exists(DEVICE_NAME)) {
        fprintf(stderr, "Device %s does not exist\n", DEVICE_NAME);
        return 1;
    }

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    // Query the device capabilities
    if (query_capabilities(fd, &((struct v4l2_capability){})) < 0) {
        close(fd);
        return 1;
    }

    // Enumerate supported frame sizes
    num_frame_sizes = enumerate_frame_sizes(fd, frame_sizes, MAX_RESOLUTIONS);
    if (num_frame_sizes < 0) {
        close(fd);
        return 1;
    }

    // Enumerate supported frame intervals
    num_frame_intervals = enumerate_frame_intervals(fd, frame_intervals, MAX_RESOLUTIONS);
    if (num_frame_intervals < 0) {
        close(fd);
        return 1;
    }

    // Query the focus control
    autofocus_supported = query_focus_control(fd);
    if (autofocus_supported < 0) {
        close(fd);
        return 1;
    }

    // Print the summary
    print_summary(frame_sizes, num_frame_sizes, frame_intervals, num_frame_intervals, autofocus_supported);

    // Close the device
    close(fd);

    return 0;
}

