#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <curl/curl.h>
#include <jansson.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_TIME_MS 2000
#define POLLING_INTERVAL_MS 100
#define IMAGE_QUALITY 85
#define HTTP_ENDPOINT "http://<IP>:<port>/upload" // Replace with actual endpoint
#define LOG_FILE "motion_logger.log"

// Global variables
static volatile int running = 1;
static int last_motion_time = 0;
static char *ip_address = NULL;
static char *port = NULL;
static FILE *log_file = NULL;

// Structure to hold the response from the HTTP POST request
typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

// Callback function to write the HTTP response to memory
static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if (ptr == NULL) {
        fprintf(stderr, "realloc() failed\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

// Function to read the PIR sensor value
int read_pir_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to capture a JPEG image using raspistill
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s -q %d", filename, IMAGE_QUALITY);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspistill: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspistill exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Function to generate a JSON payload
json_t *generate_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    json_t *root = json_object();
    json_object_set_new(root, "filename", json_string(filename));
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "motion_status", json_integer(motion_status));
    json_object_set_new(root, "gpio_pin", json_integer(gpio_pin));
    return root;
}

// Function to POST the JSON payload and image to the HTTP endpoint
int post_data(const char *filename, const char *json_payload, const char *image_data) {
    CURL *curl;
    CURLcode res;
    long response_code = 0;
    MemoryStruct chunk;

    chunk.memory = malloc(1);
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, HTTP_ENDPOINT);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));

        // Set the image data as a multipart/form-data field
        struct curl_httppost *formpost = NULL;
        struct curl_httppost *lastptr = NULL;
        curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "image", CURLFORM_COPYCONTENTS, image_data, CURLFORM_END);

        curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            printf("HTTP response code: %ld\n", response_code);
        }

        curl_formfree(formpost);
        curl_easy_cleanup(curl);
    }
    free(chunk.memory);
    curl_global_cleanup();
    return (int)response_code;
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP address> <port>\n", argv[0]);
        return 1;
    }

    ip_address = argv[1];
    port = argv[2];

    // Replace HTTP_ENDPOINT with the correct URL
    char endpoint[256];
    snprintf(endpoint, sizeof(endpoint), "http://%s:%s/upload", ip_address, port);
    strcpy(HTTP_ENDPOINT, endpoint);

    // Initialize logging
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed");
        fclose(log_file);
        return 1;
    }
    log_event("GPIO initialized successfully");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            int current_time = time(NULL) * 1000; // Get current time in milliseconds
            if (current_time - last_motion_time > DEBOUNCE_TIME_MS) {
                last_motion_time = current_time;

                // Generate filename
                time_t rawtime;
                struct tm *timeinfo;
                char filename[64];
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(filename, sizeof(filename), "motion_capture_%Y%m%d_%H%M%S.jpg", timeinfo);

                // Capture image
                if (capture_image(filename) == 0) {
                    log_event("Motion detected, capturing image");

                    // Generate JSON payload
                    json_t *payload = generate_json_payload(filename, ctime(&rawtime), 1, GPIO_PIN);
                    char *json_string = json_dumps(payload, JSON_REAL_PRECISION(5));
                    if (!json_string) {
                        log_event("Failed to generate JSON payload");
                        json_decref(payload);
                        continue;
                    }

                    // Post data
                    int response_code = post_data(filename, json_string, filename); // Use filename as image data
                    if (response_code >= 200 && response_code < 300) {
                        log_event("Data posted successfully");
                    } else {
                        log_event("Failed to post data");
                    }

                    json_decref(payload);
                    free(json_string);
                } else {
                    log_event("Failed to capture image");
                }
            }
        }

        gpioDelay(POLLING_INTERVAL_MS);
    }

    // Cleanup
    gpioTerminate();
    log_event("GPIO terminated");
    fclose(log_file);
    log_event("Log file closed");

    return 0;
}

