    if (status == -1) {
        log_message("Error executing raspistill command.");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "raspistill command failed with exit status %d", WEXITSTATUS(status));
        log_message(error_message);
        return -1;
    }

    return 0;
}

