void generate_filename(char *filename, size_t filename_size) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &tm);

    snprintf(filename, filename_size, "%s_%c.jpg", timestamp, 'm');
}

// Callback function for GPIO interrupt
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) { // Falling edge
        if (current_tick - last_tick > DEBOUNCE_DELAY_MS * 1000) { // Debounce
            char filename[64];
            generate_filename(filename, sizeof(filename));

            if (capture_image(filename) == 0) {
                char log_message_buffer[128];
                snprintf(log_message_buffer, sizeof(log_message_buffer), "Motion detected, image captured: %s", filename);
                log_message(log_message_buffer);
            } else {
                log_message("Failed to capture image.");
            }

            last_tick = current_tick;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set interrupt callback function
    gpioSetAlertFuncEx(GPIO_PIN, motion_detected_callback, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Motion detection started");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Clean up
    gpioTerminate();
    log_message("pigpio terminated");

    return 0;
}

