#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <sys/select.h>

#define VIDEO_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 1
#define CROPPED_WIDTH 200
#define CROPPED_HEIGHT 150
#define FILENAME "cropped.yuv"

struct buffer {
    void   *start;
    size_t  length;
};

static volatile int keep_running = 1;
static int fd = -1;
static struct buffer *buffers = NULL;
static FILE *output_file = NULL;

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal, exiting...\n");
        keep_running = 0;
    }
}

int xioctl(int fd, int request, void *arg) {
    int r;

    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *yuyv;
    unsigned char *cropped_yuyv;
    int i;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Cannot open device");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", VIDEO_DEVICE);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", VIDEO_DEVICE);
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return EXIT_FAILURE;
    }

    for (i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[i].start) {
            perror("mmap");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            close(fd);
            for (int j = 0; j < i; ++j) {
                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        close(fd);
        for (int j = 0; j < req.count; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (-1 == r) {
        perror("select");
        close(fd);
        for (int j = 0; j < req.count; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    if (0 == r) {
        fprintf(stderr, "select timeout\n");
        close(fd);
        for (int j = 0; j < req.count; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        close(fd);
        for (int j = 0; j < req.count; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    yuyv = (unsigned char *)buffers[buf.index].start;

    // Check format
    struct v4l2_format check_fmt;
    memset(&check_fmt, 0, sizeof(check_fmt));
    check_fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    check_fmt.fmt.pix.width = WIDTH;
    check_fmt.fmt.pix.height = HEIGHT;
    check_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    check_fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &check_fmt) == -1) {
        perror("VIDIOC_S_FMT (check format)");
        close(fd);
        for (int j = 0; j < req.count; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    // Allocate memory for cropped image
    cropped_yuyv = (unsigned char *)malloc(CROPPED_WIDTH * CROPPED_HEIGHT * 2);
    if (!cropped_yuyv) {
        perror("Out of memory for cropped image");
        close(fd);
        for (int j = 0; j < req.count; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    // Copy YUYV macroblocks to avoid color corruption
    for (int row = 0; row < HEIGHT; row += 2) {
        for (int col = 0; col < WIDTH; col += 2) {
            memcpy(cropped_yuyv + ((row / 2) * CROPPED_WIDTH + (col / 2)) * 2, yuyv + (row * WIDTH + col) * 2, 4);
        }
    }

    // Crop the image
    for (int row = 0; row < CROPPED_HEIGHT; ++row) {
        for (int col = 0; col < CROPPED_WIDTH; ++col) {
            memcpy(cropped_yuyv + (row * CROPPED_WIDTH + col) * 2, cropped_yuyv + ((row * 2) * WIDTH + (col * 2)) * 2, 2);
        }
    }

    // Write to file
    output_file = fopen(FILENAME, "wb");
    if (!output_file) {
        perror("Cannot open output file");
        close(fd);
        for (int j = 0; j < req.count; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        free(cropped_yuyv);
        return EXIT_FAILURE;
    }

    size_t bytes_written = fwrite(cropped_yuyv, 1, CROPPED_WIDTH * CROPPED_HEIGHT * 2, output_file);
    if (bytes_written != CROPPED_WIDTH * CROPPED_HEIGHT * 2) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %d\n", bytes_written, CROPPED_WIDTH * CROPPED_HEIGHT * 2);
        fclose(output_file);
        close(fd);
        for (int j = 0; j < req.count; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        free(cropped_yuyv);
        return EXIT_FAILURE;
    }

    printf("Wrote %zu bytes to %s\n", bytes_written, FILENAME);

    // Cleanup
    fclose(output_file);
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
    }

    for (i = 0; i < req.count; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("munmap");
        }
    }

    free(buffers);

    close(fd);

    free(cropped_yuyv);

    return EXIT_SUCCESS;
}

