#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define neutral servo position (90 degrees)
#define NEUTRAL_ANGLE 90

// Define angle increment/decrement
#define ANGLE_INCREMENT 5

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Global variables for servo angles
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
int set_servo_angle(int gpio_pin, int angle);
int move_servo(int current_angle, int direction);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Set servos to neutral position
    if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        fprintf(stderr, "Error setting pan servo to neutral.\n");
    }
    if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        fprintf(stderr, "Error setting tilt servo to neutral.\n");
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

// Function to set servo angle
int set_servo_angle(int gpio_pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    // Calculate pulse width (SG90 servo: 500us - 2500us for 0-180 degrees)
    int pulse_width = 500 + (angle * 2000 / 180);

    // Set PWM duty cycle
    if (gpioServo(gpio_pin, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d.\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to move servo in a given direction
int move_servo(int current_angle, int direction) {
    int new_angle = current_angle + direction;

    if (new_angle < MIN_ANGLE) {
        new_angle = MIN_ANGLE;
        fprintf(stderr, "Warning: Angle reached minimum limit (%d).\n", MIN_ANGLE);
    } else if (new_angle > MAX_ANGLE) {
        new_angle = MAX_ANGLE;
        fprintf(stderr, "Warning: Angle reached maximum limit (%d).\n", MAX_ANGLE);
    }

    if (set_servo_angle((direction == 1) ? PAN_SERVO_PIN : TILT_SERVO_PIN, new_angle) != 0) {
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Set PWM frequency for both servos
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (SG90 servo: 500us - 2500us)
    gpioSetPWMrange(PAN_SERVO_PIN, 20000); // 20ms period
    gpioSetPWMrange(TILT_SERVO_PIN, 20000); // 20ms period

    // Main loop
    while (1) {
        int input;

        // Read input from stdin
        input = getchar();

        // Handle arrow key presses
        if (input == 'a') {
            if (move_servo(pan_angle, -1) != 0) {
                fprintf(stderr, "Error moving pan servo.\n");
            }
        } else if (input == 'd') {
            if (move_servo(pan_angle, 1) != 0) {
                fprintf(stderr, "Error moving pan servo.\n");
            }
        } else if (input == 'w') {
            if (move_servo(tilt_angle, -1) != 0) {
                fprintf(stderr, "Error moving tilt servo.\n");
            }
        } else if (input == 's') {
            if (move_servo(tilt_angle, 1) != 0) {
                fprintf(stderr, "Error moving tilt servo.\n");
            }
        } else if (input == 'q') {
            // Exit program
            cleanup(0);
        } else {
            // Discard other characters
            while ((input = getchar()) != '\n' && input != EOF);
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms
    }

    return 0;
}

