    if (oled_command(i2c_fd, 0x00) < 0) return -1; // --no offset
    if (oled_command(i2c_fd, 0x40) < 0) return -1; // Set start line address
    if (oled_command(i2c_fd, 0x8D) < 0) return -1; // Charge pump setting
    if (oled_command(i2c_fd, 0x14) < 0) return -1; // --enable charge pump
    if (oled_command(i2c_fd, 0x20) < 0) return -1; // Set memory addressing mode
    if (oled_command(i2c_fd, 0x00) < 0) return -1; // --horizontal addressing mode
    if (oled_command(i2c_fd, 0xA1) < 0) return -1; // Set segment re-map
    if (oled_command(i2c_fd, 0xC8) < 0) return -1; // Set COM output scan direction
    if (oled_command(i2c_fd, 0xDA) < 0) return -1; // Set COM pins hardware configuration
    if (oled_command(i2c_fd, 0x12) < 0) return -1; // --alternative COM pin configuration
    if (oled_command(i2c_fd, 0x81) < 0) return -1; // Set contrast control
    if (oled_command(i2c_fd, 0xCF) < 0) return -1; // --contrast
    if (oled_command(i2c_fd, 0xD9) < 0) return -1; // Set pre-charge period
    if (oled_command(i2c_fd, 0xF1) < 0) return -1; // --discharge pre-charge
    if (oled_command(i2c_fd, 0xDB) < 0) return -1; // Set VCOM deselect level
    if (oled_command(i2c_fd, 0x40) < 0) return -1; // --VCOM deselect level
    if (oled_command(i2c_fd, 0xA4) < 0) return -1; // Entire display ON/OFF
    if (oled_command(i2c_fd, 0xA6) < 0) return -1; // Set normal display
    if (oled_command(i2c_fd, 0xAF) < 0) return -1; // Display on

    return 0;
}

// Function to clear the OLED display
int oled_clear() {
    unsigned char buffer[OLED_WIDTH * OLED_HEIGHT / 8];
    memset(buffer, 0x00, sizeof(buffer));
    return oled_data(i2c_fd, buffer, sizeof(buffer));
}

// Function to write a string to the OLED display
int oled_write_string(int x, int y, const char *str) {
    int i, j;
    for (i = 0; str[i] != '\0'; i++) {
        char c = str[i];
        if (c >= ' ' && c <= '~') {
            for (j = 0; j < 5; j++) {
                unsigned char pixel = font[c - ' '][j];
                for (int col = 0; col < 8; col++) {
                    if ((pixel >> col) & 0x01) {
                        // Calculate the index in the buffer
                        int index = (x + j) + ((x + j + 1) / 8) * (OLED_WIDTH + 1);
                        index += (y + col) * OLED_WIDTH;

                        // Set the pixel in the buffer
                        unsigned char buffer[OLED_WIDTH * OLED_HEIGHT / 8];
                        memset(buffer, 0x00, sizeof(buffer));
                        buffer[index / 8] |= (1 << (index % 8));

                        // Write the data to the OLED
                        if (oled_data(i2c_fd, (unsigned char *)buffer, sizeof(buffer)) < 0) {
                            return -1;
                        }
                    }
                }
                x += 6; // Advance to the next character position
            }
        } else {
            // Handle out-of-range characters (e.g., newline)
            x += 6; // Advance to the next character position
        }
    }
    return 0;
}

// Function to read the CPU temperature from the file
int read_temperature() {
    FILE *fp;
    int temp;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        log_error("Failed to open temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        log_error("Failed to read temperature from file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to read the CPU usage percentage from /proc/stat
int read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    int usage;

    fp = fopen(CPU_STAT_FILE, "r");
    if (fp == NULL) {
        log_error("Failed to open CPU stat file");
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        log_error("Failed to read CPU stat from file");
        fclose(fp);
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        log_error("Failed to read CPU stat from file");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    unsigned long long total_cpu_time = user + nice + system + idle + iowait + irq + softirq + steal;
    unsigned long long total_cpu_time_prev = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal;

    unsigned long long idle_time = idle + iowait;
    unsigned long long idle_time_prev = prev_idle + prev_iowait;

    unsigned long long idle_time_delta = idle_time - idle_time_prev;
    unsigned long long total_cpu_time_delta = total_cpu_time - total_cpu_time_prev;

    usage = (int)(((float)(total_cpu_time_delta - idle_time_delta)) / (float)total_cpu_time_delta * 100);

    return usage;
}

// Function to display the temperature on the OLED
void oled_display_temperature(int temp) {
    char temp_str[20];
    snprintf(temp_str, sizeof(temp_str), "Temp: %d m°C", temp);
    oled_write_string(0, 0, temp_str);
}

// Function to display the CPU usage on the OLED
void oled_display_cpu_usage(int usage) {
    char usage_str[20];
    snprintf(usage_str, sizeof(usage_str), "CPU: %d%%", usage);
    oled_write_string(0, 16, usage_str);
}

// Function to log errors to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int temp, usage;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize OLED display
    if (oled_init() < 0) {
        log_error("OLED initialization failed");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read temperature and CPU usage
        temp = read_temperature();
        usage = read_cpu_usage();

        // Display on OLED
        if (temp != -1 && usage != -1) {
            oled_clear();
            oled_display_temperature(temp);
            oled_display_cpu_usage(usage);
        } else {
            oled_clear();
            oled_write_string(0, 0, "Temp Err");
            oled_write_string(0, 16, "CPU Err");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    oled_clear(); // Clear the display before exiting
    return 0;
}

