#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// Configuration
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x27 // HD44780 I2C address
#define PULSES_PER_LITER 450.0
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_fd = -1;
bool running = true;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
void log_data(double flow_rate, double total_volume);
void update_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_print(int row, int col, const char *text);

// LCD commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20

// LCD flags
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

#define LCD_DISPLAYON 0x04
#define LCD_DISPLAYOFF 0x00
#define LCD_CURSORON 0x02
#define LCD_CURSOROFF 0x00
#define LCD_BLINKON 0x01
#define LCD_BLINKOFF 0x00

#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// LCD constants
#define LCD_BACKLIGHT 0x08
#define En 0b00000100  // Enable bit
#define Rw 0b00000010  // Read/Write bit (not used in this example)
#define Rs 0b00000001  // Register select bit

// Helper function to send a command to the LCD
void lcd_send_command(unsigned char cmd) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];

    data_u = (cmd & 0xF0);
    data_l = ((cmd << 4) & 0xF0);

    data_t[0] = data_u | LCD_BACKLIGHT;
    data_t[1] = data_u | En | LCD_BACKLIGHT;
    data_t[2] = data_u | LCD_BACKLIGHT;
    data_t[3] = data_l | LCD_BACKLIGHT;

    for (int i = 0; i < 4; i++) {
        if (i2c_smbus_write_byte_data(i2c_fd, 0, data_t[i]) < 0) {
            fprintf(stderr, "Error writing to LCD (command): %d\n", data_t[i]);
        }
        usleep(1000); // Delay for 1ms
    }
}

// Helper function to send data to the LCD
void lcd_send_data(unsigned char data) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];

    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    data_t[0] = data_u | Rs | LCD_BACKLIGHT;
    data_t[1] = data_u | Rs | En | LCD_BACKLIGHT;
    data_t[2] = data_u | Rs | LCD_BACKLIGHT;
    data_t[3] = data_l | Rs | LCD_BACKLIGHT;

    for (int i = 0; i < 4; i++) {
        if (i2c_smbus_write_byte_data(i2c_fd, 0, data_t[i]) < 0) {
            fprintf(stderr, "Error writing to LCD (data): %d\n", data_t[i]);
        }
        usleep(1000); // Delay for 1ms
    }
}

// Helper function to print a string to the LCD
void lcd_print(int row, int col, const char *text) {
    // Move cursor to the specified position
    unsigned char address;
    if (row == 0) {
        address = 0x80 + col;
    } else {
        address = 0xC0 + col;
    }
    lcd_send_command(address);

    // Print the string
    for (int i = 0; text[i] != '\0'; i++) {
        lcd_send_data(text[i]);
    }
}

int lcd_init() {
    // Initialize LCD
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
    lcd_send_command(LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF);
    lcd_send_command(LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT);
    lcd_clear();
    return 0;
}

void lcd_clear() {
    lcd_send_command(LCD_CLEARDISPLAY);
    usleep(2000); // Delay for 2ms
}

// Interrupt handler for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate and update total volume
void update_flow_rate() {
    static double last_flow_rate = 0.0;
    static time_t last_time = 0;
    time_t current_time = time(NULL);
    double flow_rate;

    if (last_time != 0) {
        flow_rate = (double)pulse_count / PULSES_PER_LITER / ((double)(current_time - last_time) / 60.0); // Liters per minute
        total_volume += (double)pulse_count / PULSES_PER_LITER;
        pulse_count = 0; // Reset pulse count after processing

        // Log data every second
        if (current_time % 60 == 0) {
            log_data(flow_rate, total_volume);
            update_lcd(flow_rate, total_volume);
        }

        last_flow_rate = flow_rate;
        last_time = current_time;
    }
}

// Function to log data to the console
void log_data(double flow_rate, double total_volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Flow Rate: %.2f L/min, Total Volume: %.2f L\n", timestamp, flow_rate, total_volume);
}

// Function to update the LCD with the current flow rate and total volume
void update_lcd(double flow_rate, double total_volume) {
    char flow_rate_str[17];
    char total_volume_str[17];

    snprintf(flow_rate_str, sizeof(flow_rate_str), "Flow: %.2f L/min", flow_rate);
    snprintf(total_volume_str, sizeof(total_volume_str), "Total: %.2f L", total_volume);

    lcd_clear();
    lcd_print(0, 0, flow_rate_str);
    lcd_print(1, 0, total_volume_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt handler for rising edge detection
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        update_flow_rate();
        sleep(1); // Check every second
    }

    // Cleanup
    close(i2c_fd);
    gpioTerminate();
    lcd_clear();
    lcd_send_command(0x08); // Turn off display
    lcd_send_command(0x00); // Disable display
    lcd_clear();

    return 0;
}

