    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        update_flow_rate();
        sleep(1); // Check every second
    }

    // Cleanup
    close(i2c_fd);
    gpioTerminate();
    lcd_clear();
    lcd_send_command(0x08); // Turn off display
    lcd_send_command(0x00); // Disable display
    lcd_clear();

    return 0;
}

