#include <wiringPiSPI.h>
#include <wiringPiI2C.h>

// Constants
#define ANEMOMETER_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LCD_I2C_ADDR 0x27 // PCF8574 I2C address
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define PULSES_PER_SECOND 1.0 // Example value, calibrate for your anemometer
#define WIND_SPEED_MAX 50.0   // Maximum wind speed (m/s)

// Global variables
volatile unsigned int pulse_count = 0;
unsigned long last_interrupt_time = 0;
int spi_fd;
int lcd_fd;
bool running = true;

// Function prototypes
void anemometer_interrupt(void);
float calculate_wind_speed(unsigned int pulses);
int read_wind_direction(void);
void update_lcd(float wind_speed, int wind_direction);
void signal_handler(int signal);
void lcd_init(void);
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear(void);
void lcd_set_cursor(int col, int row);

// Anemometer interrupt handler
void anemometer_interrupt(void) {
    unsigned long current_time = millis();
    if (current_time - last_interrupt_time > 1) {
        pulse_count++;
        last_interrupt_time = current_time;
    }
}

// Calculate wind speed
float calculate_wind_speed(unsigned int pulses) {
    float time_seconds = (float)SAMPLE_WINDOW_MS / 1000.0;
    float speed = (float)pulses / PULSES_PER_SECOND * time_seconds;
    return speed;
}

// Read wind direction from MCP3008
int read_wind_direction(void) {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Update LCD with wind speed and direction
void update_lcd(float wind_speed, int wind_direction) {
    char speed_str[20];
    char direction_str[20];

    snprintf(speed_str, sizeof(speed_str), "Speed: %.2f m/s", wind_speed);
    snprintf(direction_str, sizeof(direction_str), "Dir: %d deg", wind_direction);

    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_string(speed_str);
    lcd_set_cursor(0, 1);
    lcd_string(direction_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
}

// LCD initialization
void lcd_init(void) {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        exit(1);
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        exit(1);
    }

    // Initialize I2C
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        exit(1);
    }

    // Initialize LCD
    delay(50); // Wait for LCD to power up
    lcd_byte(0x33, 0); // Initialize
    lcd_byte(0x32, 0); // Initialize
    lcd_byte(0x06, 0); // Cursor move direction
    lcd_byte(0x0C, 0); // Display On,Cursor Off, Blink Off
    lcd_byte(0x28, 0); // Data length, number of lines, font size
    lcd_byte(0x01, 0); // Clear display
    delay(2);
}

// Send byte to LCD
void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | 0x08;  // Enable bit high
    int bits_low = mode | ((bits << 4) & 0xF0) | 0x08; // Enable bit low

    // High bits
    wiringPiI2CWrite(lcd_fd, bits_high);
    wiringPiI2CWrite(lcd_fd, bits_high | 0x04); // Enable pulse
    delayMicroseconds(1); // Delay
    wiringPiI2CWrite(lcd_fd, bits_high & ~0x04); // Disable pulse
    delayMicroseconds(1); // Delay

    // Low bits
    wiringPiI2CWrite(lcd_fd, bits_low);
    wiringPiI2CWrite(lcd_fd, bits_low | 0x04); // Enable pulse
    delayMicroseconds(1); // Delay
    wiringPiI2CWrite(lcd_fd, bits_low & ~0x04); // Disable pulse
    delayMicroseconds(1); // Delay
}

// Send string to LCD
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, 0);
    }
}

// Clear LCD
void lcd_clear(void) {
    lcd_byte(0x01, 0);
    delay(2);
}

// Set cursor position
void lcd_set_cursor(int col, int row) {
    int row_offsets[] = {0x00, 0x40};
    lcd_byte(0x80 | (col + row_offsets[row]), 0);
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize LCD
    lcd_init();

    // Set up anemometer interrupt
    pinMode(ANEMOMETER_PIN, INPUT);
    pullUpDnControl(ANEMOMETER_PIN, PUD_UP); // Enable pull-up resistor
    wiringPiISR(ANEMOMETER_PIN, INT_EDGE_RISING, anemometer_interrupt);

    printf("Wind sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read wind direction
        int wind_direction = read_wind_direction();

        // Check for sensor errors
        if (wind_direction == 0) {
            fprintf(stderr, "Error: ADC reading stuck at 0.\n");
        } else if (wind_direction == 1023) {
            fprintf(stderr, "Error: ADC reading stuck at 1023.\n");
        }

        // Calculate wind speed
        unsigned int pulses = pulse_count;
        pulse_count = 0; // Reset pulse count for the next sample window
        float wind_speed = calculate_wind_speed(pulses);

        // Update LCD
        update_lcd(wind_speed, wind_direction);

        // Wait for the next sample window
        delay(SAMPLE_WINDOW_MS);
    }

    // Cleanup
    lcd_clear();
    close(spi_fd);
    close(lcd_fd);

    printf("Wind sensor program stopped.\n");
    return 0;
}

