#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define PULSES_PER_LITER 450.0
#define FLOW_RATE_INTERVAL 1.0 // seconds
#define SENSOR_TIMEOUT 5.0      // seconds
#define LCD_WIDTH 16

// Global variables
volatile int pulse_count = 0;
int i2c_handle;
double flow_rate = 0.0;
time_t last_pulse_time;
int lcd_initialized = 0;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulses);
int lcd_init();
int lcd_write_string(int row, int col, const char *str);
void lcd_clear();
void lcd_display_flow_rate(double flow_rate);
void signal_handler(int signal);
void sensor_timeout_handler();

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) { // Rising edge
        pulse_count++;
    }
}

// Calculate flow rate in L/min
double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

// LCD initialization function
int lcd_init() {
    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Initialize LCD (example initialization sequence - adjust as needed)
    char init_sequence[] = {0x33, 0x32, 0x28, 0x0C, 0x06, 0x01, 0x02, 0x08, 0x14, 0x15, 0x12, 0x08, 0x07, 0x08, 0x04, 0x02, 0x0C};
    for (int i = 0; i < sizeof(init_sequence); i++) {
        char buf[2];
        buf[0] = 0x80; // Control byte for command
        buf[1] = init_sequence[i];
        if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
            fprintf(stderr, "Error writing to LCD during initialization\n");
            i2cClose(i2c_handle);
            return -1;
        }
        gpioDelay(5000); // Delay 5ms
    }

    lcd_clear();
    lcd_write_string(0, 0, "Flow Rate:");
    lcd_initialized = 1;
    return 0;
}

// LCD write string function
int lcd_write_string(int row, int col, const char *str) {
    if (!lcd_initialized) {
        fprintf(stderr, "LCD not initialized\n");
        return -1;
    }

    // Calculate the column and row address
    int addr = (row == 0) ? (0x80 + col) : (0xC0 + col);

    // Send the column address command
    char buf[2];
    buf[0] = 0x80; // Control byte for command
    buf[1] = (char)addr;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing column address to LCD\n");
        return -1;
    }
    gpioDelay(5000); // Delay 5ms

    // Send the string data
    for (int i = 0; str[i] != '\0'; i++) {
        buf[0] = 0x40; // Control byte for data
        buf[1] = str[i];
        if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
            fprintf(stderr, "Error writing data to LCD\n");
            return -1;
        }
        gpioDelay(5000); // Delay 5ms
    }

    return 0;
}

// LCD clear function
void lcd_clear() {
    if (!lcd_initialized) {
        fprintf(stderr, "LCD not initialized\n");
        return;
    }

    char buf[2];
    buf[0] = 0x80; // Control byte for command
    buf[1] = 0x01; // Clear display command
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing clear command to LCD\n");
        return;
    }
    gpioDelay(2000); // Delay 2ms
}

// Display flow rate on LCD
void lcd_display_flow_rate(double flow_rate) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    lcd_write_string(1, 0, buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Sensor timeout handler
void sensor_timeout_handler() {
    time_t now = time(NULL);
    if (difftime(now, last_pulse_time) > SENSOR_TIMEOUT) {
        fprintf(stderr, "Sensor timeout: No pulses detected for %f seconds\n", SENSOR_TIMEOUT);
        flow_rate = 0.0; // Set flow rate to 0
        lcd_clear();
        lcd_write_string(0, 0, "Sensor Error");
        lcd_write_string(1, 0, "Check Connection");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt callback for rising edge detection
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt callback\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Reset pulse count
        pulse_count = 0;

        // Measure flow rate over 1-second interval
        time_t start_time = time(NULL);
        while (time(NULL) - start_time < FLOW_RATE_INTERVAL) {
            // Check for sensor timeout
            sensor_timeout_handler();

            // Small delay to avoid busy-waiting
            gpioDelay(1000); // 1ms
        }

        // Calculate flow rate
        flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate on LCD
        lcd_display_flow_rate(flow_rate);

        // Reset last pulse time
        last_pulse_time = time(NULL);

        // Wait for the next interval
        sleep(FLOW_RATE_INTERVAL);
    }

    return 0;
}

