    for (int col = 1; col <= NUM_COLS; col++) {
        set_led(left_to_right_frame, col, 1);
    }

    // Right-to-left wave
    for (int col = NUM_COLS; col >= 1; col--) {
        set_led(right_to_left_frame, col, 1);
    }

    gpioDelay(DELAY_US);
}

