            gpioDelay(DELAY_MS * 1000); // Delay in microseconds
        }
    }

    // Clean up GPIO on exit
    clear_matrix();
    gpioTerminate();

    fprintf(stderr, "LED wave animation stopped.\n");

    return 0;
}

