#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75031_ADDR 0x4A

// Define the register addresses for the MLX75031 (replace with actual values from datasheet)
#define MLX75031_REG_DISTANCE_HIGH 0x00
#define MLX75031_REG_DISTANCE_LOW 0x01
#define MLX75031_REG_CONFIG 0x02

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
int write_config_register(int reg, int value);
int log_data(int distance);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int integration_time;
    int modulation_frequency;
} sensor_config_t;

// Global sensor configuration
sensor_config_t sensor_config = {100, 1000}; // Example values

// Function to initialize the sensor
int initialize_sensor() {
    // Example: Write configuration to the sensor (replace with actual values)
    if (write_config_register(MLX75031_REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error writing to config register.\n");
        return -1;
    }
    return 0;
}

// Function to write to a configuration register
int write_config_register(int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read distance data from the sensor
int read_distance(int *distance) {
    char buf[1];
    char data[2];

    // Read high byte
    buf[0] = MLX75031_REG_DISTANCE_HIGH;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for high byte.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 1) != 1) {
        fprintf(stderr, "Error reading high byte.\n");
        return -1;
    }

    // Read low byte
    buf[0] = MLX75031_REG_DISTANCE_LOW;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for low byte.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data + 1, 1) != 1) {
        fprintf(stderr, "Error reading low byte.\n");
        return -1;
    }

    // Combine the bytes into a 16-bit value
    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Function to log data to a file
int log_data(int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (distance == -1) {
        fprintf(log_file, "%s,Error during I2C read\n", timestamp);
    } else {
        fprintf(log_file, "%s,%d\n", timestamp, distance);
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("depth_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    rewind(log_file);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int distance;
    while (1) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance, attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                log_data(-1); // Log the error
            } else {
                if (initialize_sensor() != 0) {
                    fprintf(stderr, "Sensor re-initialization failed.\n");
                    log_data(-1); // Log the error
                }
            }
        }

        gpioDelay(100); // Sample every 100 ms
    }

    return 0;
}

