#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_REVID 0x01
#define SI1145_REG_SEQID 0x02

#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_PS1_DATA1 0x25

#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_HW_KEY 0x07

#define SI1145_HW_KEY_VAL 0x17

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t ambient_light;
    uint16_t proximity;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
char* get_iso8601_timestamp();
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    // Enable ALS and PS1
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error writing command: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint8_t buffer[4];

    // Read ambient light data
    if (i2cReadI2CBlockData(i2c_handle, SI1145_REG_ALS_VIS_DATA0, (char*)buffer, 4) < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        data.ambient_light = 0; // Set default value in case of error
