#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "proximity.log"

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set GPIO pin mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", pin);
        return -1;
    }
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(100);       // Wait for 100ms
    gpioWrite(LED_PIN, 0); // Turn LED off
}

// Function to log the event to a file
int log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    FILE *fp;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s Object detected\n", timestamp);
    fclose(fp);

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO pin modes
    if (set_gpio_mode(SENSOR_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_gpio_mode(LED_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Object detected (LOW signal)
            if (log_event() != 0) {
                fprintf(stderr, "Error logging event\n");
            }
            blink_led();
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    printf("Program terminated gracefully.\n");
    return 0;
}

