#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24

// I2C handle
int i2c_handle;

// Log file pointer
FILE *log_file;

// Function prototypes
int init_si1145();
int read_si1145_data(int *proximity, int *ambient_light);
int log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C handle
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Call sensor's API call() function for proper cleanup (if available)
    // This might require including the Si1145 library headers and linking against it
    // For this example, we'll just print a message indicating that cleanup is needed
    printf("Note: Si1145 sensor requires explicit cleanup using its API.\n");

    exit(0);
}

// Initialize Si1145 sensor
int init_si1145() {
    // Verify PART_ID
    int part_id = i2cReadByteData(i2c_handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Reset the sensor (example initialization sequence)
    if (i2cWriteByteData(i2c_handle, 0x07, 0x01) < 0) return -1; // Reset
    gpioDelay(10); // Wait for reset
    if (i2cWriteByteData(i2c_handle, 0x18, 0x7B) < 0) return -1; // PS1_ADCMUX
    if (i2cWriteByteData(i2c_handle, 0x19, 0x6B) < 0) return -1; // PS1_ADC_GAIN
    if (i2cWriteByteData(i2c_handle, 0x1A, 0x01) < 0) return -1; // PS1_LED12_SELECT
    if (i2cWriteByteData(i2c_handle, 0x1B, 0x00) < 0) return -1; // PS1_ADC_MISC
    if (i2cWriteByteData(i2c_handle, 0x08, 0x03) < 0) return -1; // MEAS_RATE
    if (i2cWriteByteData(i2c_handle, 0x09, 0x00) < 0) return -1; // ALS_RATE
    if (i2cWriteByteData(i2c_handle, 0x0A, 0x00) < 0) return -1; // PS_RATE
    if (i2cWriteByteData(i2c_handle, 0x0F, 0x00) < 0) return -1; // ALS_IR_ADCMUX
    if (i2cWriteByteData(i2c_handle, 0x10, 0x00) < 0) return -1; // ALS_VIS_ADCMUX
    if (i2cWriteByteData(i2c_handle, 0x11, 0x00) < 0) return -1; // ALS_PS_ADCMUX
    if (i2cWriteByteData(i2c_handle, 0x12, 0x00) < 0) return -1; // ALS_IR_ADC_GAIN
    if (i2cWriteByteData(i2c_handle, 0x13, 0x00) < 0) return -1; // ALS_VIS_ADC_GAIN
    if (i2cWriteByteData(i2c_handle, 0x14, 0x00) < 0) return -1; // ALS_PS_ADC_GAIN
    if (i2cWriteByteData(i2c_handle, 0x15, 0x00) < 0) return -1; // ALS_IR_ADC_MISC
    if (i2cWriteByteData(i2c_handle, 0x16, 0x00) < 0) return -1; // ALS_VIS_ADC_MISC
    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) return -1; // ALS_PS_ADC_MISC
    if (i2cWriteByteData(i2c_handle, 0x1C, 0x00) < 0) return -1; // PS_LED12_SELECT
    if (i2cWriteByteData(i2c_handle, 0x1D, 0x00) < 0) return -1; // PS_LED3_SELECT
    if (i2cWriteByteData(i2c_handle, 0x1E, 0x00) < 0) return -1; // PS_LED1_SELECT
    if (i2cWriteByteData(i2c_handle, 0x1F, 0x00) < 0) return -1; // PS_LED2_SELECT
    if (i2cWriteByteData(i2c_handle, 0x20, 0x00) < 0) return -1; // PS_ADC_MISC
    if (i2cWriteByteData(i2c_handle, 0x21, 0x00) < 0) return -1; // PS_ADC_GAIN
    if (i2cWriteByteData(i2c_handle, 0x07, 0x00) < 0) return -1; // Enable measurements

    return 0;
}

// Read proximity and ambient light data from Si1145 sensor
int read_si1145_data(int *proximity, int *ambient_light) {
    int prox_low, prox_high, amb_low, amb_high;

    prox_low = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
    if (prox_low < 0) return -1;
    prox_high = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0 + 1);
    if (prox_high < 0) return -1;

    amb_low = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (amb_low < 0) return -1;
    amb_high = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0 + 1);
    if (amb_high < 0) return -1;

    *proximity = (prox_high << 8) | prox_low;
    *ambient_light = (amb_high << 8) | amb_low;

    return 0;
}

// Log data to file
int log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int proximity, ambient_light;
    while (1) {
        if (read_si1145_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(1);
    }

    return 0;
}

