#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0     // cm
#define TRIGGER_PULSE_DURATION 10 // us
#define TIMEOUT_RISING 30000     // us (30 ms)
#define TIMEOUT_FALLING 30000    // us (30 ms)
#define LOG_INTERVAL 60000       // ms (60 seconds)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void log_distance(float distance);
void check_watering_distance(float distance);
char* iso8601_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width on the ECHO pin
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_RISING) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_RISING) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_FALLING) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_FALLING) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        // Handle tick rollover
        pulse_width += 0xFFFFFFFF; // Add maximum value to get correct pulse width
    }

    return pulse_width;
}

// Calculate distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Log the distance to a file
void log_distance(float distance) {
    char* timestamp = iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to generate timestamp\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
    free(timestamp);
}

// Check if watering is needed
void check_watering_distance(float distance) {
    if (distance < 15.0) {
        char* timestamp = iso8601_timestamp();
        if (timestamp != NULL) {
            if (log_file != NULL) {
                fprintf(log_file, "%s,Time to water the plant!\n", timestamp);
                fflush(log_file);
            } else {
                fprintf(stderr, "Log file is not open\n");
            }
            free(timestamp);
        }
    }
}

// Generate ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return buffer;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
                check_watering_distance(distance);
            } else {
                char* timestamp = iso8601_timestamp();
                if (timestamp != NULL) {
                    fprintf(log_file, "%s,Invalid distance: %.2f cm\n", timestamp, distance);
                    fflush(log_file);
                    free(timestamp);
                }
            }
        } else {
            char* timestamp = iso8601_timestamp();
            if (timestamp != NULL) {
                fprintf(log_file, "%s,Timeout or error\n", timestamp);
                fflush(log_file);
                free(timestamp);
            }
        }

        gpioDelay(LOG_INTERVAL); // Wait for the next measurement
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

