#define APDS9960_AILT 0x84
#define APDS9960_AIHT 0x86
#define APDS9960_PILT 0x88
#define APDS9960_PIHT 0x8A
#define APDS9960_PERS 0x8C
#define APDS9960_CONFIG1 0x8D
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Enable register values
#define APDS9960_PON 0b00000001
#define APDS9960_AEN 0b00000010
#define APDS9960_PEN 0b00000100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    uint16_t proximity;
} sensor_data_t;

// Function prototypes
int init_apds9960();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
int i2c_read_byte(int handle, uint8_t reg);
int i2c_write_byte(int handle, uint8_t reg, uint8_t value);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C read byte function
int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// I2C write byte function
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Initialize APDS-9960 sensor
int init_apds9960() {
    // Enable power and proximity sensor
    if (i2c_write_byte(i2c_handle, APDS9960_ENABLE, APDS9960_PON) < 0) return -1;
    if (i2c_write_byte(i2c_handle, APDS9960_ENABLE, APDS9960_PON | APDS9960_AEN) < 0) return -1;
    if (i2c_write_byte(i2c_handle, APDS9960_ENABLE, APDS9960_PON | APDS9960_AEN | APDS9960_PEN) < 0) return -1;

    // Set proximity gain to 4x
    if (i2c_write_byte(i2c_handle, APDS9960_CONTROL, 0x03) < 0) return -1; // 4x gain

    // Set LED pulse length to 8 us
    if (i2c_write_byte(i2c_handle, APDS9960_PPULSE, 0x87) < 0) return -1; // 8 us pulse length

    // Set proximity threshold
    if (i2c_write_byte(i2c_handle, APDS9960_PERS, 0x0A) < 0) return -1; // Proximity threshold

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    int c, r, g, b, p;

    c = i2c_read_byte(i2c_handle, APDS9960_CDATAL);
    r = i2c_read_byte(i2c_handle, APDS9960_RDATAL);
    g = i2c_read_byte(i2c_handle, APDS9960_GDATAL);
    b = i2c_read_byte(i2c_handle, APDS9960_BDATAL);
    p = i2c_read_byte(i2c_handle, APDS9960_PDATA);

    if (c < 0 || r < 0 || g < 0 || b < 0 || p < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    data->red = (uint16_t)r;
    data->green = (uint16_t)g;
    data->blue = (uint16_t)b;
    data->proximity = (uint16_t)p;

    return 0;
}

// Log data to CSV file
int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data->red, data->green, data->blue, data->proximity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (init_apds9960() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("APDS9960 proximity sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (sensor_data.proximity > 200) {
                log_data(&sensor_data);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            sleep(1);

            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip the rest of the loop iteration
            }

            if (init_apds9960() < 0) {
                fprintf(stderr, "APDS9960 re-initialisation failed\n");
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip the rest of the loop iteration
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

