#define I2C_ADDRESS 0x60
#define HEART_RATE_REG 0x24 // Example register, adjust as needed
#define SAMPLE_INTERVAL_MS 100
#define MAX_BPM 200
#define MIN_BPM 30

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Function prototypes
int initialize_i2c();
int read_proximity_data(int *proximity);
