    // Simple linear mapping (replace with actual sensor calibration)
    // Assuming proximity value ranges from 0 to 65535
    float bpm = (float)proximity / 65535.0 * MAX_BPM; // Scale to MAX_BPM
    if (bpm > MAX_BPM) bpm = MAX_BPM;
    if (bpm < MIN_BPM) bpm = MIN_BPM;
    return bpm;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

