int write_to_csv(const char *timestamp, float bpm) {
    FILE *fp = fopen("heartrate.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, bpm);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int proximity;
        if (read_proximity_data(&proximity) == 0) {
            float bpm = calculate_bpm(proximity);
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (write_to_csv(timestamp, bpm) != 0) {
                    fprintf(stderr, "Error writing to CSV file.\n");
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
        } else {
            fprintf(stderr, "Error reading proximity data, skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

