#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17
#define PULLUP_RESISTOR 1
#define TIMEOUT_MS 100
#define LOG_FILE "distance_log.txt"

// VL53L0X Registers
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L0X_REG_SYSRANGE_START 0x0040
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0083
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0086
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l0x();
int read_distance();
void log_distance(time_t timestamp, int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x() {
    // Check sensor presence
    int model_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "VL53L0X not found! Model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance() {
    int status = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading interrupt status: %d\n", status);
        return -1;
    }

    if ((status & 0x07) != 0) {
        fprintf(stderr, "Timeout or error occurred\n");
        return -1;
    }

    // Read range status
    int range_status = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", range_status);
        return -1;
    }

    if (range_status != 0) {
        fprintf(stderr, "Range status error: 0x%02X\n", range_status);
        return -1;
    }

    // Read distance
    int distance = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }

    return distance;
}

// Function to log the distance to a file
void log_distance(time_t timestamp, int distance) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp_str, distance);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x() < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PULLUP_RESISTOR);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Monitoring distance... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Wait for falling edge
        while (gpioRead(GPIO_PIN) == 1 && program_running) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (!program_running) break;

        // Trigger distance measurement
        if (i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
            fprintf(stderr, "Error triggering measurement\n");
            continue; // Continue to the next iteration
        }

        // Poll for result with timeout
        int timeout_counter = 0;
        while ((i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS) & 0x07) == 0 && timeout_counter < TIMEOUT_MS) {
            gpioDelay(1); // Small delay
            timeout_counter++;
        }

        if (timeout_counter >= TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for result\n");
            continue; // Continue to the next iteration
        }

        // Read distance
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            continue; // Continue to the next iteration
        }

        // Get timestamp
        time_t now = time(NULL);

        // Log distance
        log_distance(now, distance);

        printf("Distance: %d mm\n", distance);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

