#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x68
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "distance_log.txt"

// ICU-20201 Register Addresses (Example - Refer to datasheet for actual values)
#define ICU20201_REG_WHO_AM_I 0x00
#define ICU20201_REG_CONFIG 0x01
#define ICU20201_REG_DISTANCE_MSB 0x02
#define ICU20201_REG_DISTANCE_LSB 0x03

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_sensor();
int read_distance(float *distance);
int log_distance(float distance);
void control_led(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize the ICU-20201 sensor
int init_sensor() {
    // Example initialization sequence (refer to datasheet)
    if (i2cWriteByteData(i2c_handle, ICU20201_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    uint8_t data[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ICU20201_REG_DISTANCE_MSB, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Combine MSB and LSB to get the distance
    int16_t raw_distance = (data[0] << 8) | data[1];

    // Convert raw distance to centimeters (example conversion, adjust as needed)
    *distance = (float)raw_distance / 10.0; // Example: 1 unit = 0.1 cm

    return 0;
}

// Log distance to file
int log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fclose(log_file);

    return 0;
}

// Control LED based on distance
void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Release GPIO
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            control_led(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpio uses microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

