#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define WHO_AM_I_VALUE 0x41
#define DISTANCE_REG 0x00 // Example register, adjust as needed
#define DISTANCE_DATA_LEN 2 // Example length, adjust as needed
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100 // mm
#define LOG_FILE "tof_log.txt"

// Global variables
int i2c_handle;
int distance_threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor_id();
int read_distance(int *distance);
void control_led(int distance);
void log_data(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor ID
int verify_sensor_id() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }
    printf("WHO_AM_I value: 0x%02X (OK)\n", who_am_i);
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char data[DISTANCE_DATA_LEN];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, data, DISTANCE_DATA_LEN);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", bytes_read);
        return -1;
    } else if (bytes_read != DISTANCE_DATA_LEN) {
        fprintf(stderr, "Warning: Incomplete distance data read (%d bytes, expected %d)\n", bytes_read, DISTANCE_DATA_LEN);
        return -1; // Indicate incomplete data
    }

    // Convert the data to distance (example: assuming little-endian and 16-bit integer)
    int16_t raw_distance = (int16_t)((data[1] << 8) | data[0]);
    *distance = raw_distance; // Assign the raw distance value

    return 0;
}

// Control the LED based on distance
void control_led(int distance) {
    if (distance < distance_threshold) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Log data to file
void log_data(int distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Reset GPIO mode
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        distance_threshold = atoi(argv[1]);
        printf("Using distance threshold: %d mm\n", distance_threshold);
    } else {
        printf("Using default distance threshold: %d mm\n", distance_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            control_led(distance);
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }
        gpioDelay(50); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

