// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define MEASUREMENT_COMMAND_SIZE 4
#define RESPONSE_SIZE 15
#define HEADER_VALUE 0x01
#define DISTANCE_OFFSET 11
#define DISTANCE_SIZE 2
#define SAMPLES 10
#define DELAY_MS 100
#define INTRUSION_THRESHOLD 1000 // mm
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int distance;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measurement_command(const unsigned char *command);
int read_sensor_data(unsigned char *data);
int verify_header(const unsigned char *data);
int extract_distance(const unsigned char *data, int *distance);
float calculate_average_distance(const sensor_data_t *data, int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sends the measurement command to the sensor
int send_measurement_command(const unsigned char *command) {
    int result = i2cWriteDevice(i2c_handle, (char *)command, MEASUREMENT_COMMAND_SIZE);
    if (result != MEASUREMENT_COMMAND_SIZE) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads data from the sensor
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, RESPONSE_SIZE);
    if (result != RESPONSE_SIZE) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Verifies the header byte
int verify_header(const unsigned char *data) {
    if (data[0] != HEADER_VALUE) {
        fprintf(stderr, "Error: Invalid header value: 0x%02x\n", data[0]);
        return -1;
    }
    return 0;
}

// Extracts the 16-bit distance from the response data
int extract_distance(const unsigned char *data, int *distance) {
    *distance = (data[DISTANCE_OFFSET] << 8) | data[DISTANCE_OFFSET + 1];
    return 0;
}

// Calculates the average distance from the sensor data
float calculate_average_distance(const sensor_data_t *data, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += data[i].distance;
    }
    return sum / num_samples;
}

