            break;
        }

        // Wait for measurement
        gpioDelay(10); // 10 ms

        // Read sensor data
        unsigned char response_data[RESPONSE_SIZE];
        if (read_sensor_data(response_data) != 0) {
            fprintf(stderr, "Error reading sensor data, exiting...\n");
            break;
        }

        // Verify header
        if (verify_header(response_data) != 0) {
            fprintf(stderr, "Error verifying header, exiting...\n");
            break;
        }

        // Extract distance
        int distance;
        if (extract_distance(response_data, &distance) != 0) {
            fprintf(stderr, "Error extracting distance, exiting...\n");
            break;
        }

        // Store distance in sensor data array
        sensor_data[0].distance = distance;

        // Repeat for multiple samples
        for (int i = 1; i < SAMPLES; i++) {
            // Send measurement command again (assuming it's a streaming sensor)
            if (send_measurement_command(measurement_command) != 0) {
                fprintf(stderr, "Error sending measurement command, exiting...\n");
                break;
            }

            // Wait for measurement
            gpioDelay(10); // 10 ms

