            if (read_sensor_data(response_data) != 0) {
                fprintf(stderr, "Error reading sensor data, exiting...\n");
                break;
            }

            // Verify header again
            if (verify_header(response_data) != 0) {
                fprintf(stderr, "Error verifying header, exiting...\n");
                break;
            }

            // Extract distance again
            if (extract_distance(response_data, &distance) != 0) {
                fprintf(stderr, "Error extracting distance, exiting...\n");
                break;
            }

            // Store distance in sensor data array
            sensor_data[i].distance = distance;
        }

        // Calculate average distance
        float average_distance = calculate_average_distance(sensor_data, SAMPLES);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD) {
            printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
            log_intrusion(average_distance);
        } else {
            printf("Average distance: %.2f mm\n", average_distance);
        }

        // Delay between cycles
        gpioDelay(DELAY_MS);
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

