// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0014
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Expected VL53L0X model ID
#define VL53L0X_MODEL_ID 0xEE

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read a register from the VL53L0X
int read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    if (i2cReadI2CBlockData(handle, reg, (char *)data, len) != len) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a register to the VL53L0X
int write_register(int handle, uint8_t reg, uint8_t data) {
    if (i2cWriteByteData(handle, reg, data) != 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

