#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A

// Define the register to read from (example, adjust based on datasheet)
#define DISTANCE_REG 0x00

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C connection
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }
    // Combine the two bytes into a single distance value
    int distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Function to print the distance to stdout
void print_distance(int distance) {
    printf("Distance: %d mm\n", distance);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance >= 0) {
            print_distance(distance);
        }
        gpioDelay(500000); // 500ms
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

