#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // Timeout in microseconds (200ms)
#define MIN_PULSE_DURATION 0.000038 // 38ms in seconds
#define MAX_PULSE_DURATION 0.0002  // 200ms in seconds

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse duration on the echo pin
long measurePulse() {
    long start_tick, end_tick, pulse_duration;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;
    if (pulse_duration < 0) {
        pulse_duration += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_duration;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration <= 0) {
        return -1.0; // Invalid pulse duration
    }

    if (pulse_duration > MAX_PULSE_DURATION * 1000000 || pulse_duration < MIN_PULSE_DURATION * 1000000) {
        return -1.0; // Invalid pulse duration
    }

    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log the distance with a timestamp
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance >= 0) {
        printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    } else {
        printf("[%s] Error: Invalid distance measurement\n", timestamp);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_duration = measurePulse();
        float distance = calculateDistance(pulse_duration);
        logDistance(distance);
        gpioDelay(1000000); // 1 second delay
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    return 0;
}

