#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define DISTANCE_BINS 64
#define DISTANCE_THRESHOLD 1.0 // meters
#define LED_GPIO 17
#define ALERT_DURATION 2 // seconds
#define ISO_8601_FORMAT "%Y-%m-%dT%H:%M:%SZ"

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for configuration (optional)
typedef struct {
    char uart_device[64];
    int baud_rate;
    int led_gpio;
    double distance_threshold;
} Config;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int size);
int verify_magic_word(const unsigned char *buffer, int size);
int decode_range_profile(const unsigned char *buffer, int size, short *range_profile);
int check_distance_threshold(const short *range_profile, int num_bins, double threshold);
int log_intrusion(const char *timestamp, double distance);
int activate_alert_led(int gpio, int duration);
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// UART initialization function
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CSIZE;             /* mask the character size bits */
    tty.c_cflag |= CS8;                /* 8-bit data */
    tty.c_cflag &= ~(PARENB | PARODD); /* no parity */
    tty.c_cflag &= ~CSTOPB;            /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;           /* no hardware flowcontrol */

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;  // read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from UART
int read_uart_data(int fd, unsigned char *buffer, int size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        fprintf(stderr, "No data received from UART\n");
        return 0; // Indicate no data
    }
    return (int)bytes_read;
}

// Function to verify the magic word
int verify_magic_word(const unsigned char *buffer, int size) {
    const unsigned char magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (size != MAGIC_WORD_SIZE) {
        return 0; // Incorrect size
    }
    for (int i = 0; i < MAGIC_WORD_SIZE; i++) {
        if (buffer[i] != magic_word[i]) {
            return 0; // Mismatch
        }
    }
    return 1; // Match
}

// Function to decode the range profile
int decode_range_profile(const unsigned char *buffer, int size, short *range_profile) {
    if (size != RANGE_PROFILE_SIZE) {
        fprintf(stderr, "Error: Range profile size mismatch. Expected %d, got %d\n", RANGE_PROFILE_SIZE, size);
        return -1;
    }

    for (int i = 0; i < DISTANCE_BINS; i++) {
        range_profile[i] = (buffer[i * 2] << 8) | buffer[i * 2 + 1];
    }
    return 0;
}

// Function to check the distance threshold
int check_distance_threshold(const short *range_profile, int num_bins, double threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (range_profile[i] < (short)(threshold * 1000)) { // Convert meters to millimeters
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

// Function to log an intrusion
int log_intrusion(const char *timestamp, double distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to activate the alert LED
int activate_alert_led(int gpio, int duration) {
    gpioWrite(gpio, 1); // Turn LED on
    gpioDelay(duration * 1000000); // Delay for duration seconds
    gpioWrite(gpio, 0); // Turn LED off
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = gmtime(&timer);

    strftime(timestamp_buffer, buffer_size, ISO_8601_FORMAT, tm_info);
    return timestamp_buffer;
}

int main() {
    // Configuration
    Config config = {
        .uart_device = UART_DEVICE,
        .baud_rate = BAUD_RATE,
        .led_gpio = LED_GPIO,
        .distance_threshold = DISTANCE_THRESHOLD
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Initialize UART
    uart_fd = initialize_uart(config.uart_device, config.baud_rate);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    unsigned char buffer[RANGE_PROFILE_SIZE];
    short range_profile[DISTANCE_BINS];
    char timestamp_buffer[32];

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd, buffer, RANGE_PROFILE_SIZE);
        if (bytes_read > 0) {
            if (verify_magic_word(buffer, bytes_read)) {
                if (decode_range_profile(buffer, bytes_read, range_profile) == 0) {
                    if (check_distance_threshold(range_profile, DISTANCE_BINS, config.distance_threshold)) {
                        get_iso8601_timestamp(timestamp_buffer, sizeof(timestamp_buffer));
                        if (log_intrusion(timestamp_buffer, config.distance_threshold) == 0) {
                            printf("Intrusion detected at %s, distance: %.2f meters\n", timestamp_buffer, config.distance_threshold);
                            activate_alert_led(config.led_gpio, ALERT_DURATION);
                        } else {
                            fprintf(stderr, "Error logging intrusion.\n");
                        }
                    }
                } else {
                    fprintf(stderr, "Error decoding range profile.\n");
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }
    }

    // Cleanup
    close(uart_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

