    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int previous_sensor_value = -1; // Initialize to an invalid value
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break; // Exit loop on sensor read error
        }

        if (sensor_value != previous_sensor_value) {
            if (sensor_value == 0) {
                activate_buzzer();
                log_event("Obstacle detected");
            } else {
                deactivate_buzzer();
                log_event("Obstacle removed");
            }
            previous_sensor_value = sensor_value;
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    deactivate_buzzer(); // Ensure buzzer is off before exiting
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

