#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define LOG_FILE "distance_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_distance(float *distance);
int log_distance(float distance);
int check_distance_threshold(float distance);
int set_gpio_alert(int alert);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor configuration (example)
typedef struct {
    int i2c_address;
    int alert_pin;
    float threshold;
} sensor_config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Assuming distance is a 16-bit value (adjust if needed)
            *distance = (float)((buf[0] << 8) | buf[1]) / 10.0; // Example conversion
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to log distance to file
int log_distance(float distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fclose(log_file);

    return 0;
}

// Function to check distance threshold and set GPIO alert
int check_distance_threshold(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        return set_gpio_alert(1); // Set alert
    } else {
        return set_gpio_alert(0); // Clear alert
    }
}

// Function to set GPIO alert
int set_gpio_alert(int alert) {
    gpioWrite(GPIO_PIN, alert);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is low on exit
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set GPIO back to input
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    float distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance monitoring...\n");

    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);
            check_distance_threshold(distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    cleanup();
    return 0;
}

