#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void log_data(time_t timestamp, int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID (example)
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEACC) { // Expected value for VL53L1X
        fprintf(stderr, "Incorrect model ID: 0x%X\n", model_id);
        return -1;
    }

    // Start continuous ranging (example)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }
    return distance;
}

// Log data to file
void log_data(time_t timestamp, int distance) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp_str, distance);
    fflush(log_file); // Ensure data is written immediately
}

// Print parking guidance message
void print_guidance(int distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

