#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define LED_GPIO 18
#define MAX_DISTANCE 200.0 // Maximum measurable distance in cm
#define MIN_FREQUENCY 0.5  // Minimum blinking frequency in Hz
#define MAX_FREQUENCY 5.0  // Maximum blinking frequency in Hz
#define BLINK_DELAY_US 50000 // Half-cycle delay in microseconds (50ms)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
void set_led_frequency(float distance);
void log_data(float distance, float frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the CH201 sensor
int read_distance(float *distance) {
    char buf[2];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Success
            uint16_t raw_distance = (buf[0] << 8) | buf[1];
            *distance = (float)raw_distance * 0.1; // Convert to cm
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 3 - retries + 1, result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Function to set the LED blinking frequency based on distance
void set_led_frequency(float distance) {
    float frequency;

    if (distance <= 0.0) {
        frequency = MIN_FREQUENCY;
    } else if (distance >= MAX_DISTANCE) {
        frequency = MAX_FREQUENCY;
    } else {
        frequency = MIN_FREQUENCY + (distance / MAX_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY);
    }

    gpioSetPWMfrequency(LED_GPIO, (int)frequency);
}

// Function to log the data to stdout
void log_data(float distance, float frequency) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Distance: %.2f cm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    float distance;
    float frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            set_led_frequency(distance);
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        gpioDelay(BLINK_DELAY_US); // Half-cycle delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

