#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A

// Define the measurement command (replace with actual command from datasheet)
#define MEASURE_COMMAND 0x01

// Define the delay after sending the measurement command (in microseconds)
#define MEASURE_DELAY 10000 // 10ms

// Define the delay before reading the distance data (in microseconds)
#define READ_DELAY 50000  // 50ms

// Define the retry count for I2C operations
#define MAX_RETRIES 3

// Global variables for I2C handle and program termination
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration parameters
typedef struct {
    int i2c_bus;
    int mlx_address;
    int measure_command;
    int measure_delay;
    int read_delay;
    int max_retries;
    const char* log_file;
} config_t;

// Signal handler for graceful termination
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library and I2C
int initialize_i2c(config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(config->i2c_bus, config->mlx_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to write a command to the MLX75030
int write_command(int handle, uint8_t command) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, 0x00, command); // Assuming register 0x00 is the command register
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    fprintf(stderr, "I2C write failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read the distance data from the MLX75030
int read_distance(int handle, uint16_t *distance) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(handle, 0x00); // Assuming register 0x00 contains the distance data
        if (result >= 0) {
            *distance = (uint16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to log the distance data to a file
int log_data(const char *filename, time_t timestamp, uint16_t distance) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%ld,%u\n", timestamp, distance);
    fclose(fp);
    return 0;
}

int main() {
    config_t config = {
        .i2c_bus = I2C_BUS,
        .mlx_address = MLX75030_ADDR,
        .measure_command = MEASURE_COMMAND,
        .measure_delay = MEASURE_DELAY,
        .read_delay = READ_DELAY,
        .max_retries = MAX_RETRIES,
        .log_file = "distance_log.csv"
    };

    // Register signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c(&config) != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t distance;
        time_t timestamp = time(NULL);

        // Trigger measurement
        if (write_command(i2c_handle, config.measure_command) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue; // Skip to the next iteration
        }

        gpioDelay(config.measure_delay);

        // Read distance
        if (read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue; // Skip to the next iteration
        }

        // Log data
        if (log_data(config.log_file, timestamp, distance) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay before next measurement
        gpioDelay(100000); // 100ms
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

