#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define CH101_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01
#define MEASURE_REG 0x0F
#define MEASURE_CMD 0x01
#define CSV_FILE "distance_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int write_read_i2c(int reg, int *value);
int read_distance(int *distance);
int log_data(const char *timestamp, int distance);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Helper function to write to and read from I2C
int write_read_i2c(int reg, int *value) {
    char buf[2];
    int result;

    buf[0] = reg;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *value = buf[0];
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    int status;
    int retries = 3;

    while (retries > 0) {
        if (write_read_i2c(MEAS_STATUS_REG, &status) == 0) {
            if (status == 0) {
                // Start measurement
                if (write_read_i2c(MEASURE_REG, NULL) != 0) {
                    fprintf(stderr, "Error starting measurement\n");
                    return -1;
                }
                gpioDelay(5000); // Wait for measurement (5ms)

                // Read distance
                if (write_read_i2c(DISTANCE_REG, distance) == 0) {
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error reading distance\n");
                }
            } else {
                fprintf(stderr, "Measurement not ready\n");
            }
        } else {
            fprintf(stderr, "Error polling MEAS_STATUS_REG\n");
        }

        retries--;
        gpioDelay(50000); // Wait 50ms before retrying
    }

    fprintf(stderr, "Failed to read distance after multiple retries\n");
    return -1; // Failure
}

// Log data to CSV file
int log_data(const char *timestamp, int distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

int main() {
    int distance;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(timestamp, distance) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error reading distance, skipping logging\n");
        }

        gpioDelay(500000); // Wait 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

