#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A

// Define the register address for distance data (example)
#define DISTANCE_REG 0x00

// Define the number of bytes to read from the sensor
#define DATA_LENGTH 2

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int i2c_handle, uint16_t *distance) {
    char buf[DATA_LENGTH];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, DATA_LENGTH);
        if (result == DATA_LENGTH) {
            // Combine the two bytes into a 16-bit value
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to get the current timestamp in milliseconds
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long ms = ts.tv_nsec / 1000000;
    sprintf(timestamp, "%ld.%03ld", ts.tv_sec, ms);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        uint16_t distance;
        char timestamp[30];

        // Read distance from the sensor
        if (read_distance(i2c_handle, &distance) == 0) {
            // Get timestamp
            get_timestamp(timestamp);

            // Log the distance and timestamp to the console
            printf("%s Distance: %u mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        // Wait for 100ms
        gpioDelay(100000);
    }

    // The following lines will never be reached in normal execution
    // because the program runs in an infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

