#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 400.0     // Maximum distance in cm
#define MIN_ANGLE -90.0        // Minimum angle in degrees
#define MAX_ANGLE 90.0         // Maximum angle in degrees
#define TIMEOUT_MS 50          // Timeout in milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void trigger_pulse();
long measure_pulse_width();
float calculate_distance(long pulse_width);
int map_distance_to_angle(float distance);
void set_servo_angle(int angle);
void log_data(float distance, int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping...\n", signal);
    running = 0;
    set_servo_angle(0); // Stop the servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width on the echo pin
long measure_pulse_width() {
    long start_time = 0, end_time = 0;

    // Wait for the echo pin to go high
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_MS) {
        if (start_time == 0) {
            start_time = gpioTick();
        }
        gpioDelay(1); // Check every 1 ms
        timeout++;
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    // Wait for the echo pin to go low
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_MS) {
        if (end_time == 0) {
            end_time = gpioTick();
        }
        gpioDelay(1); // Check every 1 ms
        timeout++;
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    if (start_time > end_time) {
        fprintf(stderr, "Pulse width is negative, likely a timeout error\n");
        return -1; // Handle wrap-around
    }

    return end_time - start_time;
}

// Calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate an error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Map the distance to a servo angle
int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return (int)(MIN_ANGLE * (distance - MIN_DISTANCE) / (MIN_DISTANCE - 0) + 90); // Ensure angle is within bounds
    } else if (distance > MAX_DISTANCE) {
        return (int)(MAX_ANGLE * (distance - MAX_DISTANCE) / (400 - MAX_DISTANCE) + 90); // Ensure angle is within bounds
    } else {
        return (int)(MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE));
    }
}

// Set the servo angle
void set_servo_angle(int angle) {
    // Map angle to pulse width (500us - 2500us)
    int pulse_width = (int)(500 + (angle + 90) * 1000 / 90); // Ensure pulse width is within bounds
    gpioServo(SERVO_PIN, pulse_width);
}

// Log the data to a file
void log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);
        int angle = 0;

        if (distance > 0) {
            angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(200); // Wait 200ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_servo_angle(0); // Stop the servo
    fclose(log_file);
    gpioTerminate();

    return 0;
}

