    gpioWrite(BUZZER_GPIO, 0); // Set GPIO low
}

// Log distance to message queue
void log_distance(int distance) {
    message_t msg;
    msg.mtype = 1; // Message type (must be > 0)
    msg.distance = distance;

    if (msgsnd(msg_queue_id, &msg, sizeof(msg), 0) == -1) {
