int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *message);
void signal_handler(int signal);
int setup_socket();
void handle_client(int client_socket);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        return -1;
    }
    return 0;
}

// Function to write a word (2 bytes) to a VL53L1X register
int write_register_word(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int read_register_word(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_event("I2C initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_event("VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup socket
    int server_socket = setup_socket();
    if (server_socket < 0) {
        log_event("Socket setup failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Gate control system started. Listening on port %d\n", PORT);

    // Main loop
    while (!terminate) {
        // Check for incoming connections
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        handle_client(client_socket);

        close(client_socket);
    }

    // Cleanup
    close(server_socket);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Gate control system stopped\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Software reset
    if (write_register(i2c_handle, 0x0000, 0x00) != 0) return -1;
    gpioDelay(10000); // 10ms

    // Check sensor ID (example)
    uint8_t sensor_id;
    if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id) != 0) return -1;
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Start ranging (example)
    if (write_register(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) return -1;

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    uint16_t distance;
    if (read_register_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        return -1;
    }
    return distance;
}

// Open the gate
void open_gate() {
    gpioServo(SERVO_PIN, OPEN_ANGLE);
    log_event("Gate opened");
}

// Close the gate
void close_gate() {
    gpioServo(SERVO_PIN, CLOSE_ANGLE);
    log_event("Gate closed");
}

// Log an event to the log file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Setup socket
int setup_socket() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Socket creation failed");
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_socket);
        return -1;
    }

    if (listen(server_socket, 5) < 0) {
        perror("Listen failed");
        close(server_socket);
        return -1;
    }

    return server_socket;
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        return;
    }
    buffer[bytes_received] = '\0';

    printf("Received: %s\n", buffer);

    if (strcmp(buffer, "open") == 0) {
        open_gate();
    } else if (strcmp(buffer, "close") == 0) {
        close_gate();
    } else if (strcmp(buffer, "status") == 0) {
        int distance = read_distance();
        if (distance > 0) {
            char response[50];
            snprintf(response, sizeof(response), "Distance: %d mm", distance);
            send(client_socket, response, strlen(response), 0);
        } else {
            send(client_socket, "Error reading distance", strlen("Error reading distance"), 0);
        }
    } else {
        send(client_socket, "Invalid command", strlen("Invalid command"), 0);
    }
}

