#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define TRIGGER_PULSE_DURATION 10  // microseconds
#define SAMPLING_PERIOD 200       // milliseconds
#define SPEED_OF_SOUND 34300      // cm/s
#define MIN_PULSE_WIDTH 100       // microseconds
#define MAX_PULSE_WIDTH 30000     // microseconds
#define TIMEOUT_THRESHOLD 60000   // microseconds (60ms)

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int valid_pulse = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t rising_tick, uint32_t falling_tick);
void log_distance(double distance);
void signal_handler(int signal);
int initialize_gpio();

// Structure to hold callback data
typedef struct {
    uint32_t rising_tick;
    uint32_t falling_tick;
} callback_data_t;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for rising and falling edges
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_tick = tick;
        valid_pulse = 0; // Reset valid_pulse on rising edge
    } else if (level == 0) {
        falling_tick = tick;
        valid_pulse = 1; // Set valid_pulse on falling edge
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t rising_tick, uint32_t falling_tick) {
