// VL53L1X register write function with retry and exponential backoff
int vl53l1x_write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 3;
    int delay_ms = 1;
    int result;

    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error: %s (reg 0x%02X, value 0x%02X, error %d)\n", strerror(errno), reg, value, result);
            log_message("I2C write error");
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }
    return -1; // Failure after retries
}

// VL53L1X register read function with retry and exponential backoff
int vl53l1x_read_register(int handle, uint8_t reg, uint8_t *value) {
    int retries = 3;
    int delay_ms = 1;
    int result;

    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %s (reg 0x%02X, error %d)\n", strerror(errno), reg, result);
            log_message("I2C read error");
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }
    return -1; // Failure after retries
}

// VL53L1X soft reset
int vl53l1x_soft_reset(int handle) {
    if (vl53l1x_write_register(handle, 0x0000, 0x01) != 0) {
        fprintf(stderr, "VL53L1X soft reset failed\n");
        log_message("VL53L1X soft reset failed");
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    return 0;
}

// VL53L1X start measurement
int vl53l1x_start_measurement(int handle) {
    if (vl53l1x_write_register(handle, 0x001E, 0x01) != 0) {
        fprintf(stderr, "VL53L1X start measurement failed\n");
        log_message("VL53L1X start measurement failed");
        return -1;
    }
    return 0;
}

// VL53L1X read distance
int vl53l1x_read_distance(int handle, int *distance) {
    uint8_t range_status;

    if (vl53l1x_read_register(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "VL53L1X read range status failed\n");
        log_message("VL53L1X read range status failed");
        return -1;
    }

    if (range_status & 0x01) {
        uint8_t msb, lsb;
        if (vl53l1x_read_register(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &msb) != 0) {
            fprintf(stderr, "VL53L1X read MSB failed\n");
            log_message("VL53L1X read MSB failed");
            return -1;
        }
        if (vl53l1x_read_register(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &lsb) != 0) {
            fprintf(stderr, "VL53L1X read LSB failed\n");
            log_message("VL53L1X read LSB failed");
            return -1;
        }

        *distance = (msb << 8) | lsb;
        return 0;
    } else {
        fprintf(stderr, "VL53L1X data not ready\n");
        log_message("VL53L1X data not ready");
        return -1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        log_message("I2C open failed");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        log_message("VL53L1X initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for trigger pin
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        log_message("Failed to set ISR function");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int distance;
    while (running) {
        gpioDelay(100000); // 100ms delay
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Example initialization sequence (adjust based on datasheet)
    if (vl53l1x_soft_reset(i2c_handle) != 0) return -1;

    // Configure sensor parameters (example values)
    if (vl53l1x_write_register(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x00) != 0) return -1;
    if (vl53l1x_write_register(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT, 0x00) != 0) return -1;
    if (vl53l1x_write_register(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x00) != 0) return -1;

    // Start continuous ranging
    if (vl53l1x_start_measurement(i2c_handle) != 0) return -1;

    return 0;
}

// Motor control functions
void motor_forward() {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    log_message("Motor forward");
}

void motor_backward() {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    log_message("Motor backward");
}

void motor_stop() {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    log_message("Motor stop");
}

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Interrupt handler function
void trigger_callback(int gpio, int level, uint32_t tick, void *user) {
    int distance;
    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
        printf("Distance: %d mm\n", distance);

        if (distance < FORWARD_THRESHOLD) {
            motor_forward();
        } else if (distance > BACKWARD_THRESHOLD) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "Failed to read distance\n");
        log_message("Failed to read distance");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

