#include <wiringPiI2C.h>

// Define GPIO pins for LEDs
#define LED0_PIN 17
#define LED1_PIN 18
#define LED2_PIN 27
#define LED3_PIN 22

// Define MPR121 I2C address
#define MPR121_ADDRESS 0x5A

// Define MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_mpr121();
int read_touch_status(uint16_t *touch_status);
void set_led_pattern(uint16_t touch_status);
void log_event(uint16_t electrode);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPR121 sensor
int init_mpr121() {
    // Soft reset
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG2, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121. Error code: %d\n", errno);
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Verify sensor presence by reading a register
    int test_read = wiringPiI2CReadReg8(i2c_fd, MPR121_ECR);
    if (test_read < 0) {
        fprintf(stderr, "Error: Failed to read MPR121 ECR register. Error code: %d\n", errno);
        return -1;
    }

    // Configure MPR121 (example configuration)
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x00) < 0) { // Exit Electrode Configure mode
        fprintf(stderr, "Error: Failed to write to MPR121 ECR register. Error code: %d\n", errno);
        return -1;
    }
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG1, 0x20) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error: Failed to write to MPR121 CONFIG1 register. Error code: %d\n", errno);
        return -1;
    }
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG2, 0x01) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error: Failed to write to MPR121 CONFIG2 register. Error code: %d\n", errno);
        return -1;
    }
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x8F) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Failed to write to MPR121 ECR register. Error code: %d\n", errno);
        return -1;
    }

    return 0;
}

// Read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    int low_byte, high_byte;

    low_byte = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_L);
    if (low_byte < 0) {
        fprintf(stderr, "Error: Failed to read MPR121 TOUCHSTATUS_L register. Error code: %d\n", errno);
        return -1;
    }

    high_byte = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_H);
    if (high_byte < 0) {
        fprintf(stderr, "Error: Failed to read MPR121 TOUCHSTATUS_H register. Error code: %d\n", errno);
        return -1;
    }

    *touch_status = (high_byte << 8) | low_byte;
    return 0;
}

// Set LED pattern based on touch status
void set_led_pattern(uint16_t touch_status) {
    // Calculate the 4-bit pattern from the touch status
    uint16_t pattern = 0;
    if (touch_status & (1 << 0)) pattern |= (1 << 0); // ELE0
    if (touch_status & (1 << 1)) pattern |= (1 << 1); // ELE1
    if (touch_status & (1 << 2)) pattern |= (1 << 2); // ELE2
    if (touch_status & (1 << 3)) pattern |= (1 << 3); // ELE3
    if (touch_status & (1 << 4)) pattern |= (1 << 4); // ELE4
    if (touch_status & (1 << 5)) pattern |= (1 << 5); // ELE5
    if (touch_status & (1 << 6)) pattern |= (1 << 6); // ELE6
    if (touch_status & (1 << 7)) pattern |= (1 << 7); // ELE7
    if (touch_status & (1 << 8)) pattern |= (1 << 8); // ELE8
    if (touch_status & (1 << 9)) pattern |= (1 << 9); // ELE9
    if (touch_status & (1 << 10)) pattern |= (1 << 10); // ELE10
    if (touch_status & (1 << 11)) pattern |= (1 << 11); // ELE11

    // Set GPIO pins based on the pattern
    digitalWrite(LED0_PIN, (pattern >> 0) & 1);
    digitalWrite(LED1_PIN, (pattern >> 1) & 1);
    digitalWrite(LED2_PIN, (pattern >> 2) & 1);
    digitalWrite(LED3_PIN, (pattern >> 3) & 1);
}

// Log event to console
void log_event(uint16_t electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Electrode %d touched\n", timestamp, electrode);
}

int main() {
    uint16_t touch_status;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi. Error code: %d\n", errno);
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C. Error code: %d\n", errno);
        return 1;
    }

    // Initialize MPR121 sensor
    if (init_mpr121() == -1) {
        fprintf(stderr, "Error: Failed to initialize MPR121 sensor.\n");
        return 1;
    }

    // Set GPIO pins as output
    pinMode(LED0_PIN, OUTPUT);
    pinMode(LED1_PIN, OUTPUT);
    pinMode(LED2_PIN, OUTPUT);
    pinMode(LED3_PIN, OUTPUT);

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file. Error code: %d\n", errno);
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity-based interactive art installation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read touch status
        if (read_touch_status(&touch_status) == 0) {
            // Set LED pattern
            set_led_pattern(touch_status);

            // Log events
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    log_event(i);
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status.\n");
        }

        delay(50); // Poll every 50ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    digitalWrite(LED0_PIN, LOW);
    digitalWrite(LED1_PIN, LOW);
    digitalWrite(LED2_PIN, LOW);
    digitalWrite(LED3_PIN, LOW);

    return 0;
}

