#define LED_ON_DURATION_MS 1000

// MPR121 Registers
#define MPR121_REG_PARTID 0x00
#define MPR121_REG_ELECTRODE_CONFIG 0x5E
#define MPR121_REG_FFE 0x1D
#define MPR121_REG_SFE 0x1E
#define MPR121_REG_ELE0_FILTER_CONFIG 0x2B
