#define MPR121_REG_ELE5_FILTER_CONFIG 0x30
#define MPR121_REG_ELE6_FILTER_CONFIG 0x31
#define MPR121_REG_ELE7_FILTER_CONFIG 0x32
#define MPR121_REG_ELE8_FILTER_CONFIG 0x33
#define MPR121_REG_ELE9_FILTER_CONFIG 0x34
#define MPR121_REG_ELE10_FILTER_CONFIG 0x35
#define MPR121_REG_ELE11_FILTER_CONFIG 0x36
#define MPR121_REG_TOUCHTH_0 0x41
#define MPR121_REG_RELEASETH_0 0x42
#define MPR121_REG_ECR 0x5E
#define MPR121_REG_CONFIG1 0x5B
