#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 400.0     // Maximum distance in cm
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define ECHO_TIMEOUT 30000       // Echo timeout in microseconds (30ms)
#define LOG_FILE "distance_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void triggerSensor();
long measurePulseWidth();
double calculateDistance(long pulseWidth);
void logDistance(double distance);
void signalHandler(int signal);
int initialize();
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Structure to hold sensor data
typedef struct {
    long pulse_width;
    double distance;
} sensor_data_t;

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(TRIGGER_PULSE_DURATION); // Wait for pulse duration
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the pulse width of the echo signal
long measurePulseWidth() {
    long startTime = 0, endTime = 0;
    long pulseWidth = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < ECHO_TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= ECHO_TIMEOUT) {
        fprintf(stderr, "Error: Echo signal never rose (timeout).\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < ECHO_TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= ECHO_TIMEOUT) {
        fprintf(stderr, "Error: Echo signal never fell (timeout).\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    pulseWidth = endTime - startTime;
    return pulseWidth;
}

// Function to calculate the distance from the pulse width
double calculateDistance(long pulseWidth) {
    return (double)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Convert pulseWidth to seconds and divide by 2
}

// Function to log the distance to a file
void logDistance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Flush the buffer to ensure data is written to the file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate(); // Clean up pigpio before exiting
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signalHandler);

    // Initialize
    if (initialize() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseWidth = measurePulseWidth();

        if (pulseWidth > 0) {
            double distance = calculateDistance(pulseWidth);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
