#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 400.0     // Maximum distance in cm
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define ECHO_TIMEOUT 30000       // Echo timeout in microseconds (30ms)
#define LOG_FILE "distance_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void triggerSensor();
long measurePulseWidth();
double calculateDistance(long pulseWidth);
void logDistance(double distance);
void signalHandler(int signal);
int initialize();
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Structure to hold sensor data
typedef struct {
    long pulse_width;
    double distance;
} sensor_data_t;

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(TRIGGER_PULSE_DURATION); // Wait for pulse duration
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the pulse width of the echo signal
long measurePulseWidth() {
    long startTime = 0, endTime = 0;
    long pulseWidth = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < ECHO_TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= ECHO_TIMEOUT) {
        fprintf(stderr, "Error: Echo signal never rose (timeout).\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < ECHO_TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= ECHO_TIMEOUT) {
        fprintf(stderr, "Error: Echo signal never fell (timeout).\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    pulseWidth = endTime - startTime;
    return pulseWidth;
}

// Function to calculate the distance from the pulse width
double calculateDistance(long pulseWidth) {
    return (double)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Convert pulseWidth to seconds and divide by 2
}

