        trigger_pulse();
        gpioDelay(1000000); // 1 second delay

        // Calculate pulse width
        int pulse_width = pulse_end - pulse_start;

        // Validate pulse width
        if (pulse_width > 0 && pulse_width < 25000) { // 58us - 25ms (in microseconds)
            // Calculate distance
            double distance = calculate_distance(pulse_width);

