#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 30000       // Timeout in microseconds (30ms)
#define NUM_SAMPLES 5          // Number of samples for moving average filter
#define SERVO_MIN_PULSE_WIDTH 500 // Minimum pulse width for servo (us)
#define SERVO_MAX_PULSE_WIDTH 2500 // Maximum pulse width for servo (us)
#define SERVO_RANGE 180.0       // Servo range in degrees

// Global variables
volatile int pulse_width = 0;
volatile int new_pulse = 0;
FILE *log_file = NULL;
int running = 1; // Flag to control the main loop

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
float moving_average(float new_value, float *history, int *index, int history_size);
void set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int pulse_start = 0; // Flag to indicate if we are waiting for the start of the pulse

    if (level == 1) {
        // Rising edge: record start time
        if (!pulse_start) {
            start_tick = tick;
            pulse_start = 1;
        }
    } else if (level == 0) {
        // Falling edge: calculate pulse width
        if (pulse_start) {
            uint32_t end_tick = tick;
            pulse_width = end_tick - start_tick;
            new_pulse = 1; // Signal main loop that new pulse width is available
            pulse_start = 0; // Reset flag
        }
    } else {
        // Timeout: reset pulse width and flag
        pulse_width = 0;
        new_pulse = 0;
        pulse_start = 0;
    }
}

// Function to calculate distance in centimeters
float calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Invalid pulse width
    }
    return (float)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Function to calculate moving average
float moving_average(float new_value, float *history, int *index, int history_size) {
    history[*index] = new_value;
    *index = (*index + 1) % history_size;

    float sum = 0.0;
    for (int i = 0; i < history_size; i++) {
        sum += history[i];
    }
    return sum / history_size;
}

// Function to set servo angle using API call
void set_servo_angle(float angle) {
    if (angle < 0.0) angle = 0.0;
    if (angle > SERVO_RANGE) angle = SERVO_RANGE;

    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (angle / SERVO_RANGE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log data to CSV file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop

    // Stop the servo
    set_servo_angle(0.0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN to avoid floating values
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
        fflush(log_file);
    }

    // Initialize moving average filter
    float distance_history[NUM_SAMPLES] = {0.0};
    int history_index = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for a short period
        gpioDelay(100); // 100ms delay

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Filter the distance reading
        float filtered_distance = moving_average(distance, distance_history, &history_index, NUM_SAMPLES);

        // Set servo angle based on filtered distance
        if (filtered_distance > 2.0 && filtered_distance < 400.0) {
            set_servo_angle(filtered_distance);
            log_data(filtered_distance, filtered_distance); // Log distance as angle
        } else {
            set_servo_angle(0.0);
            log_data(-1.0, 0.0); // Log invalid distance and 0 angle
        }

        // Check if new pulse width is available
        if (new_pulse) {
            new_pulse = 0; // Clear the flag
        }

        // Small delay to avoid overwhelming the CPU
        gpioDelay(10); // 10ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_servo_angle(0.0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

