#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0    // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0   // Maximum frequency in Hz
#define TIMEOUT_US 200000       // Timeout in microseconds (200ms)
#define PWM_RANGE 1000          // PWM range

// Global variables
volatile sig_atomic_t terminate = 0;
double previous_frequency = 440.0; // Initial frequency

// Function prototypes
void trigger_sensor();
long read_pulse_width();
double calculate_distance(long pulse_width);
double map_distance_to_frequency(double distance);
void set_pwm_frequency(double frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to read the pulse width from the echo pin
long read_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a frequency
double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return previous_frequency; // Preserve previous frequency
    }

    // Logarithmic mapping
    double frequency = MIN_FREQUENCY + (log10(distance / MIN_DISTANCE) / log10(MAX_DISTANCE / MIN_DISTANCE)) * (MAX_FREQUENCY - MIN_FREQUENCY);
    return frequency;
}

// Function to set the PWM frequency
void set_pwm_frequency(double frequency) {
    int pwm_range = PWM_RANGE;
    int dutycycle = pwm_range / 2; // 50% duty cycle

    // Calculate the period of the PWM signal
    double period = 1.0 / frequency;

    // Calculate the on-time and off-time in microseconds
    double on_time = period / 2.0;
    double off_time = period / 2.0;

    // Convert on-time and off-time to microseconds
    int on_us = (int)(on_time * 1000);
    int off_us = (int)(off_time * 1000);

    // Set the PWM duty cycle
    gpioPWM(PWM_PIN, dutycycle); // Set duty cycle (0-1000)
    gpioDelay(on_us);           // On time
    gpioDelay(off_us);          // Off time
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    gpioSetPWMfrequency(PWM_PIN, 0); // Initialize PWM frequency to 0

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        trigger_sensor();

        // Read the pulse width
        long pulse_width = read_pulse_width();

        // Calculate the distance
        double distance = calculate_distance(pulse_width);

        // Map the distance to a frequency
        double frequency = map_distance_to_frequency(distance);

        // Set the PWM frequency
        set_pwm_frequency(frequency);

        // Update the previous frequency
        previous_frequency = frequency;

        // Delay to avoid overwhelming the sensor and CPU
        gpioDelay(10000); // 10 ms delay
    }

    // Clean up and terminate
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();
    fprintf(stderr, "Theremin-like instrument stopped.\n");
    return 0;
}

