#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 5.0      // Minimum distance in cm
#define MAX_DISTANCE 50.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT_US 100000      // Timeout in microseconds (100ms)
#define TIMEOUT_NS 100000000   // Timeout in nanoseconds (100ms)
#define TRIGGER_PULSE_US 10    // Trigger pulse duration in microseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
float calculate_distance(long pulse_width);
float map_distance_to_frequency(float distance);
void generate_tone(float frequency);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping program...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop the buzzer
    gpioTerminate();       // Terminate the pigpio library
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    return 0; // Indicate success
}

