void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high (start of pulse)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_NS) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_NS) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1; // Indicate timeout
    }

    start_tick = gpioTick();

