#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define GPIO pin for chip select
#define CS_PIN 8

// Define distance range for validation
#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000

// Define log file name
#define LOG_FILE "distance_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    unsigned int status;
    unsigned int distance;
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_sensor_data(sensor_data_t *data);
int validate_distance(unsigned int raw_distance);
int log_data(time_t timestamp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from ICU-20201
int read_sensor_data(sensor_data_t *data) {
    char tx_buf[4] = {0x00, 0x00, 0x00, 0x00}; // Example transmit buffer
    char rx_buf[4];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "Error reading SPI data\n");
        return -1;
    }

    // Parse the received data (adjust according to the sensor's datasheet)
    data->status = (rx_buf[0] << 8) | rx_buf[1];
    data->distance = (rx_buf[2] << 8) | rx_buf[3];

    return 0;
}

// Validate distance data
int validate_distance(unsigned int raw_distance) {
    if (raw_distance >= MIN_DISTANCE && raw_distance <= MAX_DISTANCE) {
        return 1; // Valid distance
    } else {
        fprintf(stderr, "Invalid distance: %u mm\n", raw_distance);
        return 0; // Invalid distance
    }
}

// Log data to CSV file
int log_data(time_t timestamp, int distance) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp_str, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate CS initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    time_t current_time;

    // Main loop
    while (!terminate) {
        // Activate CS
        gpioWrite(CS_PIN, 0);

        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate distance
            if (validate_distance(sensor_data.distance)) {
                // Get current timestamp
                current_time = time(NULL);

                // Log data
                log_data(current_time, sensor_data.distance);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Deactivate CS
        gpioWrite(CS_PIN, 1);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

