#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_DATA 0x22
#define SI1120_REG_PS_DATA 0x24
#define SI1120_REG_RESET 0x07

// Reset value
#define SI1120_RESET_VALUE 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1120();
int read_si1120_data(uint16_t *als, uint16_t *prox);
int log_data(uint16_t als, uint16_t prox);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Initialize the Si1120 sensor
int init_si1120() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, SI1120_RESET_VALUE);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error resetting Si1120: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }

    gpioDelay(20); // Wait for reset to complete

    // Verify Part ID
    int part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x40) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    fprintf(stderr, "Si1120 initialized successfully.\n");
    return 0;
}

// Read ALS and proximity data from the Si1120 sensor
int read_si1120_data(uint16_t *als, uint16_t *prox) {
    int retries = 3;
    int result;

    // Read ALS data
    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, SI1120_REG_ALS_DATA);
        if (result >= 0) {
            *als = (uint16_t)result; // pigpio returns big-endian, cast to uint16_t to force little-endian
            break;
        } else {
            fprintf(stderr, "Error reading ALS data: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
        return -1;
    }

    // Read proximity data
    retries = 3;
    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, SI1120_REG_PS_DATA);
        if (result >= 0) {
            *prox = (uint16_t)result; // pigpio returns big-endian, cast to uint16_t to force little-endian
            break;
        } else {
            fprintf(stderr, "Error reading proximity data: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(uint16_t als, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als, prox);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1120() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t als, prox;

    // Main loop
    while (!terminate) {
        if (read_si1120_data(&als, &prox) == 0) {
            log_data(als, prox);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(500); // 500ms delay
    }

    // Close resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

