#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define LUX_REG 0x22
#define PROX_REG 0x24
#define LUX_SCALE 0.0 // Placeholder, replace with actual value from datasheet
#define PROX_SCALE 1.0 // Placeholder, replace with actual value from datasheet

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int verify_sensor(int fd);
int configure_sensor(int fd);
int read_sensor_data(int fd, float *lux, int *prox);
int log_data(FILE *fp, float lux, int prox);
void signal_handler(int signum);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    int result;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, &result, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return result;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Sensor verification function
int verify_sensor(int fd) {
    int part_id = i2c_read_reg(fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading part ID\n");
        return -1;
    }
    printf("Part ID: 0x%02X\n", part_id);
    if (part_id != 0x52) { // Expected part ID for Si1182-A-GM
        fprintf(stderr, "Incorrect part ID. Sensor not found.\n");
        return -1;
    }
    printf("Sensor verified!\n");
    return 0;
}

// Sensor configuration function
int configure_sensor(int fd) {
    if (i2c_write_reg(fd, MEAS_RATE_REG, 0x0A) < 0) { // Example: Set measurement rate
        fprintf(stderr, "Error writing to measurement rate register\n");
        return -1;
    }
    printf("Sensor configured.\n");
    return 0;
}

// Data acquisition function
int read_sensor_data(int fd, float *lux, int *prox) {
    int lux_raw = i2c_read_reg(fd, LUX_REG);
    int prox_raw = i2c_read_reg(fd, PROX_REG);

    if (lux_raw < 0 || prox_raw < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *lux = (float)lux_raw * LUX_SCALE;
    *prox = prox_raw * PROX_SCALE;

    return 0;
}

// Data logging function
int log_data(FILE *fp, float lux, int prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, lux, prox);
    fflush(fp); // Ensure data is written to file immediately

    printf("%s,%.2f,%d\n", timestamp, lux, prox);

    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor verification failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor configuration failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    float lux;
    int proximity;

    // Main loop
    while (program_running) {
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            log_data(log_file, lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        usleep(100000); // 100ms delay
    }

    // Close resources
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

