#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define DISTANCE_THRESHOLD 20.0  // Distance threshold in cm
#define BUZZER_DURATION 500      // Buzzer duration in milliseconds

// Global variables
volatile static uint32_t start_tick = 0;
volatile static uint32_t end_tick = 0;
volatile static int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t start, uint32_t end);
void set_buzzer(int state);
void print_distance(double distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin rising and falling edges
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 2; // Indicate falling edge received
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start, uint32_t end) {
    double time_taken = (double)(end - start) / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0;   // Distance in cm
    return distance;
}

// Function to set the buzzer state
void set_buzzer(int state) {
    gpioWrite(BUZZER_PIN, state);
}

// Function to print the distance to stdout
void print_distance(double distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo pulse to be received
        while (echo_received != 2) {
            gpioDelay(1000); // Wait 1ms
        }

        // Calculate distance
        double distance = calculate_distance(start_tick, end_tick);

        // Print distance
        print_distance(distance);

        // Set buzzer state
        if (distance < DISTANCE_THRESHOLD) {
            set_buzzer(1); // Turn buzzer on
            gpioDelay(BUZZER_DURATION); // Keep buzzer on for 500ms
            set_buzzer(0); // Turn buzzer off
        } else {
            set_buzzer(0); // Ensure buzzer is off
        }

        // Reset echo_received flag
        echo_received = 0;

        // Wait for 1 second
        gpioDelay(1000000); // Wait 1 second (1000000 microseconds)
    }

    // Cleanup (should not reach here in normal operation due to the infinite loop)
    gpioTerminate();
    return 0;
}

