#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_GATE 18
#define PWM_FREQUENCY 50
#define DISTANCE_THRESHOLD_OPEN 250 // mm
#define DISTANCE_THRESHOLD_CLOSE 200 // mm
#define DISTANCE_HYSTERESIS 220 // mm
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void control_gate(uint16_t distance);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check model ID (0xEEAA)
    uint8_t model_id = 0xEE;
    uint8_t model_id_reg = 0xAA;
    char buf[2];
    buf[0] = model_id;
    buf[1] = model_id_reg;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing model ID register address: %d\n", i2c_handle);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error reading model ID: %d\n", i2c_handle);
        return -1;
    }

    if (buf[1] != 0xAA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0x%02X)\n", buf[1], 0xAA);
        return -1;
    }

    // Set timing budget (20ms)
    uint8_t timing_budget_reg = 0x41;
    uint8_t timing_budget_value = 0x0A; // 20ms = 0x0A
    buf[0] = timing_budget_reg;
    buf[1] = timing_budget_value;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing timing budget register: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance(uint16_t *distance) {
    uint8_t cmd = 0x00; // Register to read distance from
    char buf[2];

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing distance register address: %d\n", i2c_handle);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error reading distance: %d\n", i2c_handle);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Control the servo motor to open or close the gate
void control_gate(uint16_t distance) {
    static int gate_open = 0; // 0 = closed, 1 = open
    static int pulse_width = 0;

    if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
        // Open the gate
        if (pulse_width < 1000) {
            pulse_width += 10;
            gpioPWM(GPIO_GATE, pulse_width);
            gpioDelay(10); // Small delay for smooth transition
        } else {
            pulse_width = 1000;
            gpioPWM(GPIO_GATE, pulse_width);
            gate_open = 1;
            log_event("Gate opened");
        }
    } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
        // Close the gate
        if (pulse_width > 2000) {
            pulse_width -= 10;
            gpioPWM(GPIO_GATE, pulse_width);
            gpioDelay(10); // Small delay for smooth transition
        } else {
            pulse_width = 2000;
            gpioPWM(GPIO_GATE, pulse_width);
            gate_open = 0;
            log_event("Gate closed");
        }
    } else {
        // Maintain current state
        gpioPWM(GPIO_GATE, pulse_width);
    }
}

// Log an event to the log file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(GPIO_GATE, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_GATE, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_GATE, 2000); // Set PWM range to 2000 for finer control

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t distance;

    // Main loop
    while (program_running) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            control_gate(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(GPIO_GATE, 0); // Stop PWM
    fclose(log_file);
    gpioTerminate();

    return 0;
}

