#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_ANGLE 0.0
#define MAX_ANGLE 180.0
#define TIMEOUT_US 50000        // 50ms timeout

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, stopping servo and exiting...\n", signal);
    program_running = 0;
    set_servo_pulse(SERVO_PIN, 500); // Set servo to 0 degrees
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for rising edge with timeout
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for falling edge with timeout
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 for us to s conversion, and by 2 for one-way distance

    return distance;
}

// Function to map distance to servo angle
int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return 0;
    } else if (distance > MAX_DISTANCE) {
        return 180;
    } else {
        // Linear interpolation
        float angle = (distance - MIN_DISTANCE) * (180.0 / (MAX_DISTANCE - MIN_DISTANCE));
        return (int)angle;
    }
}

// Function to set servo angle using pigpio
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid angle: %d\n", angle);
        return -1; // Indicate error
    }

    // Calculate pulse width (500us - 2500us)
    int pulse_width = 500 + (int)((float)angle / 180.0 * 2000.0);

    if (set_servo_pulse(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", pulse_width);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo (optional, but recommended)
    gpioSetPWMrange(SERVO_PIN, 20000); // 20ms period (50Hz)
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50Hz

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor and servo control program\n");
    printf("Press Ctrl+C to exit\n");

    // Main loop
    while (program_running) {
        // Measure distance
        float distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed\n");
        } else {
            // Map distance to angle
            int angle = map_distance_to_angle(distance);

            // Set servo angle
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Error: Failed to set servo angle\n");
            }

            // Print distance and angle
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        // Pause for 100ms
        gpioDelay(100000); // 100ms
    }

    // Stop servo and terminate pigpio (should not reach here if signal handler works)
    set_servo_pulse(SERVO_PIN, 500); // Set servo to 0 degrees
    gpioTerminate();

    return 0;
}

