#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define WHO_AM_I 0x75
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read a single byte from the MPU-6050
int read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading byte from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to read a 16-bit word from the MPU-6050
int read_word(int handle, uint8_t reg) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading word from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to initialize the MPU-6050
int init_mpu6050(int handle) {
    // Verify WHO_AM_I register
    int who_am_i = read_byte(handle, WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: MPU-6050 not found. WHO_AM_I register returned 0x%02X\n", who_am_i);
        return -1;
    }

    // Set accelerometer range to +/- 2g
    if (i2cWriteByteData(handle, 0x1C, 0x00) < 0) {
        fprintf(stderr, "Error setting accelerometer range\n");
        return -1;
    }

    // Set gyroscope range to +/- 250 degrees/second
    if (i2cWriteByteData(handle, 0x1B, 0x00) < 0) {
        fprintf(stderr, "Error setting gyroscope range\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer and gyroscope data
        int16_t accel_x = read_word(i2c_handle, ACCEL_XOUT_H);
        int16_t accel_y = read_word(i2c_handle, ACCEL_XOUT_H + 2);
        int16_t accel_z = read_word(i2c_handle, ACCEL_XOUT_H + 4);
        int16_t gyro_x = read_word(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = read_word(i2c_handle, GYRO_XOUT_H + 2);
        int16_t gyro_z = read_word(i2c_handle, GYRO_XOUT_H + 4);

        // Print the data to stdout
        printf("%d,%d,%d,%d,%d,%d\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

