#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 command for high repeatability measurement
#define SHT40_MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// CRC-8 initial value
#define CRC8_INITIAL_VALUE 0x00

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, SHT40_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate temperature CRC
    uint8_t temp_crc = data[2];
    uint8_t temp_data[2] = {data[0], data[1]};
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }

    // Validate humidity CRC
    uint8_t hum_crc = data[5];
    uint8_t hum_data[2] = {data[3], data[4]};
    if (crc8(hum_data, 2) != hum_crc) {
        fprintf(stderr, "Humidity CRC error\n");
        return -1;
    }

    // Convert temperature to Celsius
    uint16_t temp_raw = (data[0] << 8) | data[1];
    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;

    // Convert humidity to percentage
    uint16_t hum_raw = (data[3] << 8) | data[4];
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature and humidity
        result = read_sht40(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SHT40 sensor\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup (should not reach here in normal operation due to the while loop)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

