// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_temperatures();
float convert_temperature(unsigned int raw_temp);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads ambient and object temperatures from the sensor
sensor_data_t read_temperatures() {
    sensor_data_t data;
    unsigned char buffer[4];
    int result;

    // Read ambient temperature
    result = i2cReadI2CBlockData(i2c_handle, AMBIENT_TEMP_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", result);
        data.ambient_temp = -273.15; // Indicate error
    } else {
        unsigned int raw_ambient = (buffer[1] << 8) | buffer[0];
        data.ambient_temp = convert_temperature(raw_ambient);
    }

    // Read object temperature
    result = i2cReadI2CBlockData(i2c_handle, OBJECT_TEMP_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading object temperature: %d\n", result);
        data.object_temp = -273.15; // Indicate error
    } else {
        unsigned int raw_object = (buffer[1] << 8) | buffer[0];
        data.object_temp = convert_temperature(raw_object);
    }

    return data;
}

// Converts raw temperature data to Celsius
float convert_temperature(unsigned int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Logs the temperature data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.ambient_temp, data.object_temp);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_temperatures();

        if (data.ambient_temp != -273.15 && data.object_temp != -273.15) {
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Clean up and exit
    cleanup();
    return 0;
}

