// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int sts30_address;
    const char *log_file_name;
    const char *error_log_file_name;
} config_t;

config_t config = {
    I2C_BUS,
    STS30_ADDR,
    LOG_FILE,
    ERROR_LOG_FILE
};

// Function to read temperature from the STS30-DIS sensor
double read_temperature() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buf[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command to sensor.");
        return ERROR_TEMP;
    }

    gpioDelay(20); // Wait for measurement (at least 20ms)

    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        log_error("Failed to read temperature data from sensor.");
        return ERROR_TEMP;
    }

    // Convert the data
    int temp_raw = (buf[0] << 8) | buf[1];
    double temperature = -45.0 + (175.0 * temp_raw) / 65535.0;

    return temperature;
}

// Function to log temperature to a file
void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        log_error("Log file is not open.");
    }
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s, %s\n", timestamp, message);
        fflush(error_log_file);
    } else {
        fprintf(stderr, "Error: Could not write to error log file. Message: %s\n", message);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(config.i2c_bus, config.sts30_address, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        gpioTerminate();
        return 1;
