#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define RETRY_COUNT 3
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// CRC-8 polynomial and initial value
const unsigned char CRC_POLYNOMIAL = 0x31;
const unsigned char CRC_INITIAL_VALUE = 0xFF;

// Function prototypes
int init_i2c();
int read_sensor_data(unsigned char *data);
int validate_crc(const unsigned char *data, int offset, unsigned char checksum);
SensorData process_sensor_data(const unsigned char *data);
int log_sensor_data(SensorData data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    int result;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteByte(i2c_handle, MEASURE_HIGH_REPEATABILITY);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }

        gpioDelay(10); // Wait for measurement (at least 10ms)

        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait 1ms before retry
        }
    }
    return -1; // Failure after all retries
}

// Validate CRC checksum
int validate_crc(const unsigned char *data, int offset, unsigned char checksum) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < 2; ++i) {
        crc ^= data[offset + i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == checksum);
}

