SensorData process_sensor_data(const unsigned char *data) {
    SensorData sensor_data;
    // Temperature
    int temp_raw = (data[0] << 8) | data[1];
    sensor_data.temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;

    // Humidity
    int humidity_raw = (data[3] << 8) | data[4];
    sensor_data.humidity = -6.0 + 125.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Log sensor data to file
int log_sensor_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char sensor_data[6];
    SensorData processed_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 0, sensor_data[1]) && validate_crc(sensor_data, 3, sensor_data[5])) {
                // Process sensor data
                processed_data = process_sensor_data(sensor_data);

                // Log sensor data
                log_sensor_data(processed_data);
            } else {
                fprintf(stderr, "CRC validation failed!\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data!\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0); // Sleep for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

