float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write to I2C register
int write_i2c(int handle, int reg, int val) {
    int result = i2cWriteByteData(handle, reg, val);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read from I2C register
int read_i2c(int handle, int reg, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return result;
}

// Read sensor data (temperature and humidity)
int read_sensor_data(int handle, sensor_data_t *data) {
    char buf[2];
    uint16_t raw_temp, raw_humidity;
    int retries = 3;

    // Read temperature
    while (retries > 0) {
        if (write_i2c(handle, TEMP_CMD, 0) == 0) {
            gpioDelay(20); // Wait for measurement (datasheet specifies < 20ms)
            if (read_i2c(handle, 0, buf, 2) == 2) {
                raw_temp = (buf[0] << 8) | buf[1];
                data->temperature = convert_temperature(raw_temp);
                break;
            } else {
                fprintf(stderr, "Failed to read temperature, retrying...\n");
                retries--;
                gpioDelay(10); // Small delay before retry
            }
        } else {
            fprintf(stderr, "Failed to write temperature command, retrying...\n");
            retries--;
            gpioDelay(10);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        return -1;
    }

    // Read humidity
    retries = 3;
    while (retries > 0) {
        if (write_i2c(handle, HUM_CMD, 0) == 0) {
            gpioDelay(20); // Wait for measurement
            if (read_i2c(handle, 0, buf, 2) == 2) {
                raw_humidity = (buf[0] << 8) | buf[1];
                data->humidity = convert_humidity(raw_humidity);
                break;
            } else {
                fprintf(stderr, "Failed to read humidity, retrying...\n");
                retries--;
                gpioDelay(10);
            }
        } else {
            fprintf(stderr, "Failed to write humidity command, retrying...\n");
            retries--;
            gpioDelay(10);
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read humidity after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Log data to file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Log data
            if (log_data(log_file, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }

            // Print to console
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

