#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDRESS 0x25

// Define the continuous measurement command
#define SDP800_MEASURE_CMD 0x362F

// Define the number of bytes to read from the sensor
#define READ_BYTES 9

// Define the log file name
#define LOG_FILE "airflow_data.txt"

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Function prototypes
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
int validate_crc(unsigned char data[], int len);
float convert_pressure(int raw_pressure, int scale_factor);
float convert_temperature(int raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int raw_pressure;
    int raw_temperature;
    int scale_factor;
} sensor_data_t;

// Function to write data to the I2C device
int i2c_write(int fd, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int i2c_read(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to validate the CRC-8 checksum
int validate_crc(unsigned char data[], int len) {
    for (int i = 0; i < len; i += 3) {
        unsigned char crc = data[i + 2];
        unsigned char polynomial = 0x31;
        unsigned char data_byte = data[i];

        for (int j = 0; j < 8; j++) {
            if ((crc ^ data_byte) & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }

        if (crc != data[i + 2]) {
            fprintf(stderr, "CRC validation failed for data at index %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Function to convert raw pressure to Pascals
float convert_pressure(int raw_pressure, int scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Function to convert raw temperature to degrees Celsius
float convert_temperature(int raw_temperature) {
    return (float)raw_temperature / 200.0f;
}

// Function to log the data to a file
int log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure(Pa),Temperature(C)\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger continuous measurement
        unsigned char cmd[2] = {(SDP800_MEASURE_CMD >> 8) & 0xFF, SDP800_MEASURE_CMD & 0xFF};
        if (i2c_write(i2c_fd, cmd, 2) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying in 100ms\n");
            usleep(100000); // 100ms
            continue;
        }

        // Wait for the measurement to complete (at least 45ms)
        usleep(45000);

        // Read the data from the sensor
        unsigned char data[READ_BYTES];
        if (i2c_read(i2c_fd, data, READ_BYTES) != 0) {
            fprintf(stderr, "Failed to read data, retrying in 100ms\n");
            usleep(100000); // 100ms
            continue;
        }

        // Validate the CRC checksums
        if (validate_crc(data, READ_BYTES) != 0) {
            fprintf(stderr, "CRC validation failed, skipping data point\n");
            usleep(100000); // 100ms
            continue;
        }

        // Extract the raw data
        int raw_pressure = (data[0] << 8) | data[1];
        int raw_temperature = (data[3] << 8) | data[4];
        int scale_factor = (data[6] << 8) | data[7];

        // Convert the raw data to pressure and temperature
        float pressure = convert_pressure(raw_pressure, scale_factor);
        float temperature = convert_temperature(raw_temperature);

        // Log the data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 100ms
        usleep(100000);
    }

    // Close the I2C bus (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

