int log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        return -1;
    }
    return 0;
}

// Read temperature from STS30
int read_sts30(float *temperature) {
    unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    unsigned char data[3];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command.");
        return -1;
    }

    gpioDelay(15000); // Wait 15ms

    result = i2cReadDevice(i2c_handle, data, 3);
    if (result != 3) {
        log_error("Failed to read temperature data.");
        return -1;
    }

