    if (validate_crc(data, 2) != 0) {
        log_error("CRC validation failed.");
        return -1;
    }

    // Convert data to temperature
    int raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return 0;
}

