#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "sht40_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(unsigned char data[], unsigned char checksum);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from SHT40
int read_sensor_data(sensor_data_t *data) {
    unsigned char buffer[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 8.5 ms)
    gpioDelay(8500); // 8500 microseconds = 8.5 milliseconds

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Extract temperature and humidity values
    int temperature_raw = (buffer[0] << 8) | buffer[1];
    int humidity_raw = (buffer[3] << 8) | buffer[4];

    // Validate CRC for temperature
    if (validate_crc(buffer, buffer[2]) != 0) {
        fprintf(stderr, "CRC validation failed for temperature\n");
        data->temperature = -999.0; // Indicate error
    } else {
        data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    }

    // Validate CRC for humidity
    if (validate_crc(buffer + 3, buffer[5]) != 0) {
        fprintf(stderr, "CRC validation failed for humidity\n");
        data->humidity = -999.0; // Indicate error
    } else {
        data->humidity = -6.0 + 125.0 * (float)humidity_raw / 65535.0;
    }

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(unsigned char data[], unsigned char checksum) {
    unsigned char crc = 0xFF;
    unsigned char i, bit;

    for (i = 0; i < 2; i++) {
        crc ^= data[i];
        for (bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
        if (crc != checksum) {
            return -1; // CRC check failed
        }
    }
    return 0; // CRC check passed
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data.temperature == -999.0 || data.humidity == -999.0) {
        fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    }
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

