    int16_t temperature_raw = (raw_data[3] << 8) | raw_data[4];

    data.pressure = (float)pressure_raw / PRESSURE_SCALE_FACTOR;
    data.temperature = (float)temperature_raw / TEMPERATURE_SCALE_FACTOR + TEMPERATURE_OFFSET;

    return data;
}

