        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint8_t raw_data[6];
    while (!terminate) {
        // Read data from sensor
        if (read_data(i2c_handle, raw_data, 6) == 0) {
            // Validate CRC checksums
            if (validate_crc(raw_data, 0, raw_data[2]) && validate_crc(raw_data, 3, raw_data[5])) {
