            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000); // Wait 1 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

