#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define FAN_GPIO 18
#define TEMP_HIGH 28.0
#define TEMP_LOW 27.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

TemperatureReading temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature(float *temperature);
void control_fan(float temperature);
void add_to_buffer(float temperature);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from Si7021 sensor
int read_temperature(float *temperature) {
    int retries = 0;
    int result;
    unsigned char data[2];

    while (retries < 3) {
        result = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d\n", result);
            gpioDelay(10); // Wait before retrying
            retries++;
            continue;
        }

        gpioDelay(30); // Wait for measurement (datasheet specifies 20ms for 14-bit resolution)

        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature data: %d\n", result);
            gpioDelay(10); // Wait before retrying
            retries++;
            continue;
        }

        // Convert raw data to temperature (Celsius)
        int raw_temp = (data[0] << 8) | data[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after 3 retries.\n");
    return -1; // Failure
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMP_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("Fan ON (Temperature: %.2f\u00b0C)\n", temperature);
    } else if (temperature < TEMP_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("Fan OFF (Temperature: %.2f\u00b0C)\n", temperature);
    }
}

// Function to add temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index].timestamp = time(NULL);
    temperature_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature History ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&temperature_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f\u00b0C\n", time_str, temperature_buffer[index].temperature);
    }
    printf("---------------------------\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f\u00b0C\n", temperature);
            control_fan(temperature);
            add_to_buffer(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

