#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define GPIO_LED 17
#define BUFFER_SIZE 20
#define CO2_THRESHOLD 1000.0f
#define MEASUREMENT_INTERVAL_SEC 5

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_REINIT 0x3646

// Structure for sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t co2_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
int validate_checksum(uint8_t *data, int len);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index);
void control_led(float co2);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SCD40 sensor
int initialize_sensor() {
    // Stop periodic measurement
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to stop periodic measurement.\n");
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed

    // Reinit the sensor
    buf[0] = (CMD_REINIT >> 8) & 0xFF;
    buf[1] = CMD_REINIT & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to reinit sensor.\n");
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed

    // Start periodic measurement
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement.\n");
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char cmd[2];
    char buf[9];
    uint8_t checksum;

    // Prepare the read measurement command
    cmd[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = CMD_READ_MEASUREMENT & 0xFF;

    // Send the read measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send read measurement command.\n");
        return -1;
    }
    gpioDelay(1); // Small delay after writing the command

    // Read 9 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read sensor data.\n");
        return -1;
    }

    // Extract data and validate checksums
    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temperature_raw = (buf[3] << 8) | buf[4];
    uint16_t humidity_raw = (buf[6] << 8) | buf[7];

    checksum = buf[2];
    if (validate_checksum(buf, 2) != 0) {
        fprintf(stderr, "Error: CO2 checksum validation failed.\n");
        return -1;
    }

    checksum = buf[5];
    if (validate_checksum(buf + 3, 2) != 0) {
        fprintf(stderr, "Error: Temperature checksum validation failed.\n");
        return -1;
    }

    checksum = buf[8];
    if (validate_checksum(buf + 6, 2) != 0) {
        fprintf(stderr, "Error: Humidity checksum validation failed.\n");
        return -1;
    }

    // Convert raw data to physical units
    data->co2 = (float)co2_raw;
    data->temperature = -45 + 175 * ((float)temperature_raw / 65535.0f);
    data->humidity = 100 * ((float)humidity_raw / 65535.0f);

    return 0;
}

// Function to validate CRC-8 checksum
int validate_checksum(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != data[len]) {
        return -1;
    }
    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to get data from the circular buffer
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    if (index < 0 || index >= buffer->count) {
        sensor_data_t empty_data = {0.0f, 0.0f, 0.0f}; // Return default values if out of bounds
        return empty_data;
    }
    int actual_index = (buffer->head - buffer->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[actual_index];
}

// Function to control the LED based on CO2 level
void control_led(float co2) {
    if (co2 > CO2_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    // Stop periodic measurement
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to stop periodic measurement during cleanup.\n");
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set GPIO back to input mode

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO_LED as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open I2C handle
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    co2_buffer.head = 0;
    co2_buffer.count = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate checksums
            if (validate_checksum((uint8_t *)&sensor_data.co2, 2) == 0 &&
                validate_checksum((uint8_t *)&sensor_data.temperature, 2) == 0 &&
                validate_checksum((uint8_t *)&sensor_data.humidity, 2) == 0) {

                // Add data to circular buffer
                add_to_buffer(&co2_buffer, sensor_data);

                // Control LED
                control_led(sensor_data.co2);

                // Print data to stdout
                printf("CO2: %.2f ppm, Temperature: %.2f °C, Humidity: %.2f %%RH\n",
                       sensor_data.co2, sensor_data.temperature, sensor_data.humidity);
            } else {
                fprintf(stderr, "Error: Checksum validation failed, discarding data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        // Wait for the next measurement interval
        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

