#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define GPIO_PIN 4
#define TIMEOUT_US 50000 // 50ms
#define LOG_FILE "temperature_log.txt"
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0
#define NUM_FAILURES 3

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int failure_count = 0;

// Structure to hold timestamp data
typedef struct {
    uint64_t rising_edge;
    uint64_t falling_edge;
} Timestamps;

// Function prototypes
int initialize_gpio();
int read_sensor(Timestamps *timestamps);
float calculate_temperature(Timestamps timestamps);
int log_temperature(float temperature);
void handle_signal(int signal);
void cleanup();

// Signal handler
void handle_signal(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Optional: Set pull-down resistor

    return 0;
}

// Read sensor data with timeout
int read_sensor(Timestamps *timestamps) {
    uint32_t start_tick, end_tick;
    int result;

    // Wait for rising edge with timeout
    result = gpioRead(GPIO_PIN);
    if (result < 0) {
        fprintf(stderr, "Error reading GPIO: %d\n", result);
        return 1; // Indicate error
    }

    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == result) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return 1; // Indicate timeout
        }
    }

    timestamps->rising_edge = gpioTick();

    // Wait for falling edge with timeout
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) != result) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return 1; // Indicate timeout
        }
    }

    timestamps->falling_edge = gpioTick();

    return 0; // Indicate success
}

// Calculate temperature from pulse width
float calculate_temperature(Timestamps timestamps) {
    uint64_t pulse_width = timestamps.falling_edge - timestamps.rising_edge;
    float temperature;

    if (pulse_width == 0) {
        return -273.15; // Return absolute zero if pulse width is zero
    }

    temperature = 0.0625 * pulse_width - 50.0;

    return temperature;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (fprintf(log_file, "%s, %.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    Timestamps timestamps;
    float temperature;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor data
        if (read_sensor(&timestamps) == 0) {
            // Calculate temperature
            temperature = calculate_temperature(timestamps);

            // Validate temperature
            if (temperature >= MIN_TEMP && temperature <= MAX_TEMP) {
                // Log temperature
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Error logging temperature\n");
                }
                printf("Temperature: %.2f °C\n", temperature);
                failure_count = 0; // Reset failure count on success
            } else {
                fprintf(stderr, "Temperature out of range: %.2f °C\n", temperature);
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Error logging temperature\n");
                }
                failure_count++;
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            if (log_temperature(-999.0) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
            failure_count++;
        }

        // Check for sensor malfunction
        if (failure_count >= NUM_FAILURES) {
            fprintf(stderr, "SENSOR MALFUNCTION: %d consecutive failures\n", failure_count);
            if (log_temperature(-999.0) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

