#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define DATA_LEN 6
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds
#define LOG_FILE "environmental_data.txt"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
int validate_crc(uint8_t data[], int len);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
float add_offset(float temperature, float humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char data[DATA_LEN];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            continue;
        }

        gpioDelay(15); // Wait for measurement (at least 15ms)

        result = i2cReadDevice(i2c_handle, data, DATA_LEN);
        if (result != DATA_LEN) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(data, 2)) {
            fprintf(stderr, "Temperature CRC validation failed (attempt %d)\n", i + 1);
            return -1;
        }

        // Validate CRC for humidity
        if (!validate_crc(data + 3, 2)) {
            fprintf(stderr, "Humidity CRC validation failed (attempt %d)\n", i + 1);
            return -1;
        }

        *temperature = (data[0] << 8) | data[1];
        *humidity = (data[3] << 8) | data[4];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Validate CRC
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            bit = crc & 0x80;
            if (bit) {
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                crc = (crc << 1);
            }
        }
    }

    return (crc == data[len]);
}

// Convert temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + (175.0 * (float)raw_temp / 65535.0);
}

// Convert humidity to relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Add sinusoidal offset
float add_offset(float temperature, float humidity) {
    time_t now = time(NULL);
    float offset_temp = 2.0 * sin(2 * M_PI * now / (60 * 60)); // 2°C offset, period 1 hour
    float offset_humidity = 5.0 * sin(2 * M_PI * now / (60 * 60)); // 5% RH offset, period 1 hour

    return temperature + offset_temp, humidity + offset_humidity;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", buf, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() != 0) {
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    while (!terminate) {
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            temperature = convert_temperature(raw_temperature);
            humidity = convert_humidity(raw_humidity);

            temperature = add_offset(temperature, humidity).temperature;
            humidity = add_offset(temperature, humidity).humidity;

            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            log_data(NAN, NAN); // Log NaN values
        }

        gpioDelay(SLEEP_DURATION * 1000); // Sleep for 5 seconds
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

