#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define MEASURE_ARG 0x00
#define MEASURE_CMD_HIGH 0x24
#define MEASURE_CMD_LOW 0x00
#define DATA_LENGTH 6
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xC5
#define SAMPLE_INTERVAL 5 // seconds
#define FILENAME "environment.csv"

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_command(int handle, uint16_t command);
int read_data(int handle, char *data, int length);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const char *data, int length);
int log_data(const char *timestamp, float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Function to write a command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *data, int length) {
    int result = i2cReadDevice(handle, data, length);
    if (result != length) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksums
int validate_crc(const char *data, int length) {
    uint8_t temp_data[2];
    temp_data[0] = data[0];
    temp_data[1] = data[1];

    uint8_t crc_temp = crc8(temp_data, 2);
    if (crc_temp != data[2]) {
        fprintf(stderr, "Temperature CRC validation failed: expected 0x%02X, got 0x%02X\n", data[2], crc_temp);
        return -1;
    }

    temp_data[0] = data[3];
    temp_data[1] = data[4];

    crc_temp = crc8(temp_data, 2);
    if (crc_temp != data[5]) {
        fprintf(stderr, "Humidity CRC validation failed: expected 0x%02X, got 0x%02X\n", data[5], crc_temp);
        return -1;
    }

    return 0;
}

// Function to log data to a CSV file
int log_data(const char *timestamp, float temperature, float humidity) {
    if (fp == NULL) {
        fprintf(stderr, "File not opened for logging\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SHT35_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen(FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s\n", FILENAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Temperature (C),Humidity (%%)\n");
    }
    rewind(fp);

    // Main loop
    while (!terminate) {
        // Measure temperature and humidity
        if (write_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to write measurement command\n");
            break;
        }

        gpioDelay(15); // Wait at least 15 ms

        char data[DATA_LENGTH];
        if (read_data(i2c_handle, data, DATA_LENGTH) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Validate CRC checksums
        if (validate_crc(data, DATA_LENGTH) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            break;
        }

        // Convert raw data to temperature and humidity
        uint16_t temperature_raw = (data[0] << 8) | data[1];
        uint16_t humidity_raw = (data[3] << 8) | data[4];

        float temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
        float humidity = 100.0 * (float)humidity_raw / 65535.0;

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20]; // YYYY-MM-DDTHH:MM:SSZ\0

        time(&rawtime);
        timeinfo = gmtime(&rawtime); // Use gmtime for UTC time
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log data
        if (log_data(timestamp, temperature, humidity) != 0) {
            fprintf(stderr, "Failed to log data\n");
            break;
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    return 0;
}

