#define MEASURE_HUMID_HOLD 0xE5
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0x00
#define LOG_FILE "environment.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define TIMEOUT_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
int verify_crc(unsigned char msb, unsigned char lsb, unsigned char crc);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char buf[3];
    int result;
    int retries = 0;

    // Measure temperature
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, MEASURE_TEMP_HOLD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }
        gpioDelay(30); // Wait for measurement (datasheet specifies 20ms)
        result = i2cReadDevice(i2c_handle, (char *)buf, 3);
        if (result == 3) {
            if (verify_crc(buf[0], buf[1], buf[2])) {
                unsigned int raw_temp = (buf[0] << 8) | buf[1];
                *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Temperature CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature data: %d\n", result);
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read temperature after multiple retries\n");
        return -1;
    }

    // Measure humidity
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, MEASURE_HUMID_HOLD);
        if (result != 0) {
            fprintf(stderr, "Error writing humidity command: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }
        gpioDelay(30); // Wait for measurement
        result = i2cReadDevice(i2c_handle, (char *)buf, 3);
        if (result == 3) {
            if (verify_crc(buf[0], buf[1], buf[2])) {
                unsigned int raw_humidity = (buf[0] << 8) | buf[1];
                *humidity = (125.0 * raw_humidity / 65536.0) - 6;
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Humidity CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Error reading humidity data: %d\n", result);
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read humidity after multiple retries\n");
        return -1;
    }

    return 0;
}

// CRC-8 checksum verification function
int verify_crc(unsigned char msb, unsigned char lsb, unsigned char crc) {
    unsigned char data[2] = {msb, lsb};
    unsigned char crc_calculated = CRC_INITIAL;
    int i;

    for (i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated == crc);
}

// Data logging function
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

