#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define PRESSURE_MSB 0x00
#define PRESSURE_LSB 0x01
#define TEMPERATURE_MSB 0x02
#define TEMPERATURE_LSB 0x03
#define SCALE_FACTOR_MSB 0x04
#define SCALE_FACTOR_LSB 0x05
#define SCALE_FACTOR_LSB2 0x06
#define SCALE_FACTOR_MSB2 0x07
#define CRC_PRESSURE 0x08
#define CRC_TEMPERATURE 0x09
#define CONVERSION_TIME_US 50000 // 50ms
#define LOG_FILE "airflow.dat"
#define SAMPLE_INTERVAL_S 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(uint8_t msb, uint8_t lsb, uint8_t crc);
sensor_data_t convert_data(uint16_t pressure_raw, uint16_t temperature_raw, uint16_t scale_factor);
int log_data(FILE *file, float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t msb, uint8_t lsb, uint8_t crc) {
    uint8_t data[2] = {msb, lsb};
    uint8_t calculated_crc = crc8(data, 2);
    return (calculated_crc == crc);
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(uint16_t pressure_raw, uint16_t temperature_raw, uint16_t scale_factor) {
    sensor_data_t data;
    data.pressure = (float)pressure_raw / (float)scale_factor;
    data.temperature = (float)temperature_raw / (float)scale_factor;
    return data;
}

// Log data to file
int log_data(FILE *file, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
