    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(uint8_t msb, uint8_t lsb, uint8_t crc);
sensor_data_t convert_data(uint16_t pressure_raw, uint16_t temperature_raw, uint16_t scale_factor);
