#define PWM_FREQUENCY 25000 // Hz
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(int *raw_data);
float convert_to_pressure(int raw_data);
float calculate_flow_rate(float pressure);
void control_fan(float flow_rate);
void log_data(float pressure, float flow_rate);
