    // Flow rate calculation (example, adjust based on sensor datasheet)
    // Flow rate (SLPM) = Pressure (Pa) * Scaling factor
    // Scaling factor needs to be determined experimentally
    float scaling_factor = 0.1; // Example scaling factor
    return pressure * scaling_factor;
}

void control_fan(float flow_rate) {
    // Map flow rate to PWM duty cycle (0-100%)
    int duty_cycle = (int)(flow_rate * 100.0); // Assuming max flow rate is 100 SLPM
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(FAN_GPIO, duty_cycle); // Set PWM duty cycle
}

void log_data(float pressure, float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

void cleanup() {
    // Turn off the fan
    gpioPWM(FAN_GPIO, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

