#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // Hz
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(int *raw_data);
float convert_to_pressure(int raw_data);
float calculate_flow_rate(float pressure);
void control_fan(float flow_rate);
void log_data(float pressure, float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for sensor calibration data (example)
typedef struct {
    float offset;
    float sensitivity;
} sensor_calibration_t;

// Global calibration data (example)
sensor_calibration_t calibration = {0.0, 1.0}; // Default values

int main() {
    int raw_data;
    float pressure, flow_rate;

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        if (read_sensor_data(&raw_data) == 0) {
            pressure = convert_to_pressure(raw_data);
            flow_rate = calculate_flow_rate(pressure);
            control_fan(flow_rate);
            log_data(pressure, flow_rate);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x28, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Configure FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_sensor_data(int *raw_data) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return 1;
    }

    *raw_data = (buffer[0] << 8) | buffer[1];
    return 0;
}

float convert_to_pressure(int raw_data) {
    // Conversion formula from Honeywell Zephyr HAFBLF0100A2AX5 datasheet
    // Pressure (Pa) = (Raw Data - Zero Offset) * Sensitivity
    // Assuming zero offset is 0 and sensitivity is 1 for simplicity.
    // In a real application, these values would be calibrated.
    return (float)raw_data; // Simple conversion for demonstration
}

float calculate_flow_rate(float pressure) {
    // Flow rate calculation (example, adjust based on sensor datasheet)
    // Flow rate (SLPM) = Pressure (Pa) * Scaling factor
    // Scaling factor needs to be determined experimentally
    float scaling_factor = 0.1; // Example scaling factor
    return pressure * scaling_factor;
}

void control_fan(float flow_rate) {
    // Map flow rate to PWM duty cycle (0-100%)
    int duty_cycle = (int)(flow_rate * 100.0); // Assuming max flow rate is 100 SLPM
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(FAN_GPIO, duty_cycle); // Set PWM duty cycle
}

void log_data(float pressure, float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

void cleanup() {
    // Turn off the fan
    gpioPWM(FAN_GPIO, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

