#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// CO2 thresholds for ventilation control
#define CO2_LOW 800
#define CO2_HIGH 1200

// Global variables
int i2c_handle;
FILE *log_file;
bool running = true;

// Function prototypes
int init_scd30();
int read_scd30_data(float *co2, float *temperature, float *humidity);
void log_data(float co2, float temperature, float humidity);
void ventilation_control(float co2);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the SCD30 sensor
int init_scd30() {
    // Start periodic measurement
    char cmd[2] = {SCD30_CMD_START_PERIODIC_MEASUREMENT >> 8, SCD30_CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the SCD30 sensor
int read_scd30_data(float *co2, float *temperature, float *humidity) {
    char cmd[2] = {SCD30_CMD_READ_MEASUREMENT >> 8, SCD30_CMD_READ_MEASUREMENT & 0xFF};
    char buffer[18];
    int result;

