#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define CMD_TRIGGER_MEASUREMENT 0x2400
#define SCALE_FACTOR 60.0
#define SAMPLE_INTERVAL_DEFAULT 1000 // milliseconds
#define SAMPLE_INTERVAL_MIN 100
#define SAMPLE_INTERVAL_MAX 10000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sdp32(sensor_data_t *data);
void verify_crc8(uint8_t data[], uint8_t checksum);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void print_data(sensor_data_t data);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], int *sample_interval);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SDP32 sensor
int read_sdp32(sensor_data_t *data) {
    char buf[9];
    int result;

    // Trigger measurement
    char cmd[2] = {(CMD_TRIGGER_MEASUREMENT >> 8) & 0xFF, CMD_TRIGGER_MEASUREMENT & 0xFF};
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write trigger command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(10000); // 10 ms

    // Read data
    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Verify CRC for pressure
    verify_crc8((uint8_t *)buf, buf[2]);
    if (buf[2] != 0) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }

    // Verify CRC for temperature
    verify_crc8((uint8_t *)(buf + 3), buf[5]);
    if (buf[5] != 0) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Verify CRC for scale factor
    verify_crc8((uint8_t *)(buf + 6), buf[8]);
    if (buf[8] != 0) {
        fprintf(stderr, "Scale factor CRC check failed\n");
        return -1;
    }

    // Convert raw data to physical values
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->scale_factor = (uint16_t)((buf[6] << 8) | buf[7]);

    return 0;
}

// Function to verify CRC-8 checksum
void verify_crc8(uint8_t data[], uint8_t checksum) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < 8; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != checksum) {
        fprintf(stderr, "CRC check failed! Expected: 0x%02X, Calculated: 0x%02X\n", checksum, crc);
    }
}

// Function to convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / SCALE_FACTOR;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / SCALE_FACTOR;
}

// Function to print the sensor data with a timestamp
void print_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C, Scale Factor: %.2f\n",
           timestamp, convert_pressure(data.pressure), convert_temperature(data.temperature), (float)data.scale_factor / 100.0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], int *sample_interval) {
    if (argc > 1) {
        char *endptr;
        long interval = strtol(argv[1], &endptr, 10);

        if (*endptr != '\0' || interval < SAMPLE_INTERVAL_MIN || interval > SAMPLE_INTERVAL_MAX) {
            fprintf(stderr, "Invalid sample interval. Using default value of %d ms.\n", SAMPLE_INTERVAL_DEFAULT);
            *sample_interval = SAMPLE_INTERVAL_DEFAULT;
            return -1;
        }

        *sample_interval = (int)interval;
        return 0;
    } else {
        *sample_interval = SAMPLE_INTERVAL_DEFAULT;
        return 0;
    }
}

int main(int argc, char *argv[]) {
    sensor_data_t sensor_data;
    int sample_interval;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &sample_interval) != 0) {
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("SDP32 sensor reader started. Sampling interval: %d ms\n", sample_interval);

    // Main loop
    while (!terminate) {
        if (read_sdp32(&sensor_data) == 0) {
            print_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(sample_interval * 1000); // Convert ms to microseconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("SDP32 sensor reader stopped.\n");
    return 0;
}

