#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SDP810 I2C address
#define SDP810_ADDR 0x25

// SDP810 command to trigger measurement (continuous mode)
#define SDP810_TRIGGER_CMD 0x362F

// CRC-8 polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature) {
    uint8_t buffer[9];
    int result;

    // Trigger measurement
    result = i2cWriteWordData(i2c_handle, 0x00, SDP810_TRIGGER_CMD); // Register address is not used for command
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 45ms)
