#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HDC1000_ADDR 0x40
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_REG 0x02
#define MEASUREMENT_CONFIG 0x00 // Temperature and Humidity, 14-bit
#define CONVERSION_DELAY_MS 20
#define READ_DELAY_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_hdc1000(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HDC1000_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HDC1000
int read_hdc1000(sensor_data_t *data) {
    unsigned char buf[4];
    int result;

    // Configure the sensor for temperature and humidity measurement
    result = i2cWriteByteData(i2c_handle, CONFIG_REG, MEASUREMENT_CONFIG);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete
    gpioDelay(CONVERSION_DELAY_MS * 1000); // Delay in microseconds

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, (char *)buf, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature/humidity data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    int raw_temp = (buf[0] << 8) | buf[1];
    int raw_humidity = (buf[2] << 8) | buf[3];

    data->temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Log temperature and humidity data
void log_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_hdc1000(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", READ_DELAY_S);
        }

        sleep(READ_DELAY_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

