#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define SLEEP_DURATION_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7051_address;
    int sleep_duration;
} config_t;

config_t config = {I2C_BUS, SI7051_ADDR, SLEEP_DURATION_SEC};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature != -1000.0) { // Assuming -1000.0 indicates an error
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        time_sleep(config.sleep_duration);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.si7051_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from Si7051
float read_temperature() {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1000.0;
    }

    // Wait for measurement to complete (typical conversion time is 20ms)
    time_sleep(0.05); // Wait 50ms

    // Read temperature data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1000.0;
    }

    // Convert raw data to temperature (Celsius)
    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    return temperature;
}

// Log temperature to console
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

