#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x60
#define PRESSURE_REG 0x00 // Replace with actual register address
#define SAFE_MIN_PRESSURE 200.0
#define SAFE_MAX_PRESSURE 250.0
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int read_pressure(int handle, float *pressure);
int log_pressure(FILE *file, float pressure);
void check_pressure_range(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data (optional)
typedef struct {
    float pressure;
    time_t timestamp;
} sensor_data_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read pressure from the sensor
int read_pressure(int handle, float *pressure) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        i2cClose(handle);
        handle = open_i2c_device(I2C_BUS, MLX90821_ADDR);
        if (handle < 0) {
            fprintf(stderr, "Failed to re-open I2C device\n");
            return -1;
        }
        return -1; // Indicate failure after retry
    }

    // Convert raw data to pressure (example conversion, adjust as needed)
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    *pressure = (float)raw_pressure / 10.0; // Example scaling

    return 0;
}

// Function to log pressure to a file
int log_pressure(FILE *file, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(file); // Ensure data is written immediately
    return 0;
}

// Function to check if pressure is within a safe range
void check_pressure_range(float pressure) {
    if (pressure < SAFE_MIN_PRESSURE || pressure > SAFE_MAX_PRESSURE) {
        fprintf(stderr, "Warning: Pressure out of safe range: %.2f kPa\n", pressure);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, MLX90821_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Check file size to determine if header should be written
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to end for appending

    float pressure;

    // Main loop
    while (!terminate) {
        if (read_pressure(i2c_handle, &pressure) == 0) {
            log_pressure(log_file, pressure);
            check_pressure_range(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying I2C connection\n");
            i2cClose(i2c_handle);
            i2c_handle = open_i2c_device(I2C_BUS, MLX90821_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device\n");
                terminate = 1; // Exit loop if re-opening fails
            }
        }
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

