#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1 MB

int i2c_handle;
FILE *log_file;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(unsigned char *data);
SensorData process_sensor_data(const unsigned char *data);
int log_data(const SensorData *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from the HIH6130 sensor
int read_sensor_data(unsigned char *data) {
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 40ms)
    gpioDelay(40000); // 40ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    return 0;
}

// Process raw sensor data
SensorData process_sensor_data(const unsigned char *data) {
    SensorData sensor_data;
    unsigned int raw_humidity, raw_temperature;

    // Combine status bits, humidity MSB, humidity LSB, temperature MSB, temperature LSB
    unsigned int status = (data[0] >> 6) & 0x03; // Extract status bits
    raw_humidity = ((data[0] & 0x3F) << 8) | data[1];
    raw_temperature = (data[2] << 6) | (data[3] >> 2);

    // Check sensor status
    if (status != 0) {
        fprintf(stderr, "Sensor status error: %d\n", status);
        sensor_data.temperature = -999.0; // Indicate error
        sensor_data.humidity = -999.0;
        return sensor_data;
    }

    // Convert raw data to temperature and humidity
    sensor_data.humidity = ((float)raw_humidity / 16383) * 100;
    sensor_data.temperature = ((float)raw_temperature / 16383) * 165 - 40;

    return sensor_data;
}

// Log data to file with timestamp
int log_data(const SensorData *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

