        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data->temperature, data->humidity) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk

    // Check log file size and rotate if necessary
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    fseek(log_file, 0, SEEK_SET);

    if (file_size > MAX_LOG_SIZE) {
        fclose(log_file);
        log_file = fopen(LOG_FILE, "w"); // Open in write mode to truncate
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file for writing.\n");
            return -1;
        }
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    unsigned char data[4];
    SensorData sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file for appending.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Process sensor data
            sensor_data = process_sensor_data(data);

            // Log data
            if (sensor_data.temperature != -999.0 && sensor_data.humidity != -999.0) {
                if (log_data(&sensor_data) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error: Invalid sensor data, not logging.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

