    }
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read SENT data from the sensor
int read_sent_data(sensor_data_t *data) {
    int sync_pulse_width, status_nibble_width, data_nibble_width, checksum_nibble_width;
    int i;

    // Read synchronization pulse
    gpioSetTimerFuncEx(0, TICK_TIME, 0, NULL); // Disable timer
    gpioSetTimerFuncEx(0, SYNC_PULSE_MIN, 1, NULL); // Enable timer for sync pulse
    gpioDelay(SYNC_PULSE_MAX * TICK_TIME); // Wait for sync pulse
    sync_pulse_width = gpioTick();

    if (sync_pulse_width < SYNC_PULSE_MIN || sync_pulse_width > SYNC_PULSE_MAX) {
        fprintf(stderr, "Error: Invalid sync pulse width: %d\n", sync_pulse_width);
        return -1;
    }

    // Read status nibble
    gpioSetTimerFuncEx(0, TICK_TIME, 0, NULL); // Disable timer
    gpioSetTimerFuncEx(0, DATA_PULSE_MIN, 1, NULL); // Enable timer for data nibble
    gpioDelay(DATA_PULSE_MAX * TICK_TIME); // Wait for data nibble
    status_nibble_width = gpioTick();

    if (status_nibble_width < DATA_PULSE_MIN || status_nibble_width > DATA_PULSE_MAX) {
        fprintf(stderr, "Error: Invalid status nibble width: %d\n", status_nibble_width);
        return -1;
    }

    data->status = (status_nibble_width - DATA_PULSE_MIN) / (DATA_PULSE_MAX - DATA_PULSE_MIN) * (STATUS_NIBBLE_MAX - STATUS_NIBBLE_MIN) + STATUS_NIBBLE_MIN;

    // Read data nibbles
    gpioSetTimerFuncEx(0, TICK_TIME, 0, NULL); // Disable timer
    gpioSetTimerFuncEx(0, DATA_PULSE_MIN, 1, NULL); // Enable timer for data nibble
    gpioDelay(DATA_PULSE_MAX * TICK_TIME); // Wait for data nibble
    data_nibble_width = gpioTick();

    if (data_nibble_width < DATA_PULSE_MIN || data_nibble_width > DATA_PULSE_MAX) {
        fprintf(stderr, "Error: Invalid data nibble width: %d\n", data_nibble_width);
        return -1;
    }

    data->data1 = (data_nibble_width - DATA_PULSE_MIN) / (DATA_PULSE_MAX - DATA_PULSE_MIN) * (DATA_NIBBLE_MAX - DATA_NIBBLE_MIN) + DATA_NIBBLE_MIN;

    gpioSetTimerFuncEx(0, TICK_TIME, 0, NULL); // Disable timer
    gpioSetTimerFuncEx(0, DATA_PULSE_MIN, 1, NULL); // Enable timer for data nibble
    gpioDelay(DATA_PULSE_MAX * TICK_TIME); // Wait for data nibble
    data_nibble_width = gpioTick();

    if (data_nibble_width < DATA_PULSE_MIN || data_nibble_width > DATA_PULSE_MAX) {
        fprintf(stderr, "Error: Invalid data nibble width: %d\n", data_nibble_width);
        return -1;
    }

    data->data2 = (data_nibble_width - DATA_PULSE_MIN) / (DATA_PULSE_MAX - DATA_PULSE_MIN) * (DATA_NIBBLE_MAX - DATA_NIBBLE_MIN) + DATA_NIBBLE_MIN;

    gpioSetTimerFuncEx(0, TICK_TIME, 0, NULL); // Disable timer
    gpioSetTimerFuncEx(0, DATA_PULSE_MIN, 1, NULL); // Enable timer for data nibble
    gpioDelay(DATA_PULSE_MAX * TICK_TIME); // Wait for data nibble
    data_nibble_width = gpioTick();

    if (data_nibble_width < DATA_PULSE_MIN || data_nibble_width > DATA_PULSE_MAX) {
        fprintf(stderr, "Error: Invalid data nibble width: %d\n", data_nibble_width);
        return -1;
    }

    data->data3 = (data_nibble_width - DATA_PULSE_MIN) / (DATA_PULSE_MAX - DATA_PULSE_MIN) * (DATA_NIBBLE_MAX - DATA_NIBBLE_MIN) + DATA_NIBBLE_MIN;

    // Read checksum nibble
    gpioSetTimerFuncEx(0, TICK_TIME, 0, NULL); // Disable timer
    gpioSetTimerFuncEx(0, DATA_PULSE_MIN, 1, NULL); // Enable timer for data nibble
    gpioDelay(DATA_PULSE_MAX * TICK_TIME); // Wait for data nibble
    checksum_nibble_width = gpioTick();

    if (checksum_nibble_width < DATA_PULSE_MIN || checksum_nibble_width > DATA_PULSE_MAX) {
        fprintf(stderr, "Error: Invalid checksum nibble width: %d\n", checksum_nibble_width);
        return -1;
    }

    data->checksum = (checksum_nibble_width - DATA_PULSE_MIN) / (DATA_PULSE_MAX - DATA_PULSE_MIN) * (CHECKSUM_NIBBLE_MAX - CHECKSUM_NIBBLE_MIN) + CHECKSUM_NIBBLE_MIN;

    return 0;
}

// Function to validate the checksum
int validate_checksum(sensor_data_t *data) {
    int calculated_checksum = (data->status + data->data1 + data->data2 + data->data3) % 16;
    if (calculated_checksum != data->checksum) {
        fprintf(stderr, "Error: Checksum mismatch! Calculated: %d, Received: %d\n", calculated_checksum, data->checksum);
        return -1;
    }
    return 0;
}

// Function to log the pressure data to a file
int log_pressure_data(sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Convert nibbles to pressure (example conversion, adjust as needed)
    float pressure = (float)(data->data1 * 100 + data->data2) / 10.0; // Example: 0.1 Pa per unit

    snprintf(log_entry, sizeof(log_entry), "%s, Pressure: %.2f Pa", timestamp, pressure);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s\n", log_entry);
    fclose(fp);

    return 0;
}

int main() {
    sensor_data_t sensor_data;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Brake pressure monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data
        if (read_sent_data(&sensor_data) == 0) {
            // Validate checksum
            if (validate_checksum(&sensor_data) == 0) {
                // Log pressure data
                if (log_pressure_data(&sensor_data) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Checksum validation failed.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Clean up GPIO
    gpioTerminate();

    fprintf(stderr, "Brake pressure monitoring stopped.\n");

    return 0;
}

