#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define DATA_LENGTH 6
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_interface();
int write_command(int handle, uint8_t command);
int read_data(int handle, uint8_t *data, int length);
uint8_t calculate_crc(uint8_t data[], int length);
int validate_crc(uint8_t data[], int length, uint8_t crc);
int read_sensor_data(int handle, sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C interface
int open_i2c_interface() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write command to SHT40
int write_command(int handle, uint8_t command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result < 0) {
        fprintf(stderr, "Failed to write command 0x%02X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from SHT40
int read_data(int handle, uint8_t *data, int length) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, length);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int length, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, length);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC validation failed! Calculated: 0x%02X, Received: 0x%02X\n", calculated_crc, crc);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t raw_data[DATA_LENGTH];

    if (write_command(handle, MEASURE_HIGH_PRECISION) != 0) {
        return -1;
    }
    gpioDelay(85000); // Wait at least 8.5 ms

    if (read_data(handle, raw_data, DATA_LENGTH) != 0) {
        return -1;
    }

    // Validate CRC for temperature data
    if (validate_crc(raw_data, 2, raw_data[2]) != 0) {
        return -1;
    }

    // Validate CRC for humidity data
    if (validate_crc(raw_data + 3, 2, raw_data[5]) != 0) {
        return -1;
    }

    // Convert raw data to temperature and humidity
    int32_t temperature_raw = (raw_data[0] << 8) | raw_data[1];
    int32_t humidity_raw = (raw_data[3] << 8) | raw_data[4];

    data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C interface
    if (open_i2c_interface() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

