#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 5 // seconds

// Structure to hold temperature data and timestamp
typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureData;

// Circular buffer structure
typedef struct {
    TemperatureData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
int i2c_handle;
CircularBuffer buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
void add_to_buffer(float temperature);
void persist_buffer_to_file();
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Add a temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    time_t now = time(NULL);
    buffer.data[buffer.head].timestamp = now;
    buffer.data[buffer.head].temperature = temperature;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) {
        buffer.count++;
    }
}

// Read temperature from TMP117 sensor
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius (see TMP117 datasheet)
    temperature = (float)((int16_t)raw_temp) * 0.0078125;
    return temperature;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Persist the circular buffer to a file
void persist_buffer_to_file() {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        return;
    }

    int start_index = (buffer.count == BUFFER_SIZE) ? buffer.head : 0;
    for (int i = 0; i < buffer.count; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        if (fwrite(&buffer.data[index], sizeof(TemperatureData), 1, fp) != 1) {
            fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            fclose(fp);
            return;
        }
    }

    fclose(fp);
    printf("Temperature log saved to temperature_log.dat\n");
}

