#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 commands
#define SHTC3_MEASURE_NORMAL 0x7866

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Temperature and humidity ranges
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define HUMID_MIN 0.0
#define HUMID_MAX 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} shtc3_data_t;

// Function prototypes
int init_i2c();
int read_shtc3(shtc3_data_t *data);
int validate_crc(uint8_t data[], int len);
int validate_data(shtc3_data_t data);
int log_data(shtc3_data_t data);
void signal_handler(int signal);
int cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHTC3 sensor
int read_shtc3(shtc3_data_t *data) {
    uint8_t cmd[2] = {(SHTC3_MEASURE_NORMAL >> 8) & 0xFF, SHTC3_MEASURE_NORMAL & 0xFF};
    uint8_t raw_data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Wait for measurement to complete (at least 12.4 ms)
    gpioDelay(12500); // 12500 microseconds = 12.5 milliseconds

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)raw_data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Validate CRC for temperature data
    if (!validate_crc(raw_data, 2)) {
        fprintf(stderr, "Temperature CRC validation failed.\n");
        return -1;
    }

    // Validate CRC for humidity data
    if (!validate_crc(raw_data + 2, 2)) {
        fprintf(stderr, "Humidity CRC validation failed.\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temperature_raw = (raw_data[0] << 8) | raw_data[1];
    uint16_t humidity_raw = (raw_data[3] << 8) | raw_data[4];

    data->temperature = 175.0 * temperature_raw / 65535.0 - 45.0;
    data->humidity = 100.0 * humidity_raw / 65535.0;

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Validate temperature and humidity data
int validate_data(shtc3_data_t data) {
    if (data.temperature < TEMP_MIN || data.temperature > TEMP_MAX) {
        fprintf(stderr, "Temperature out of range: %.2f\n", data.temperature);
        return -1;
    }
    if (data.humidity < HUMID_MIN || data.humidity > HUMID_MAX) {
        fprintf(stderr, "Humidity out of range: %.2f\n", data.humidity);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(shtc3_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
int cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    shtc3_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_shtc3(&sensor_data) == 0) {
            // Validate data
            if (validate_data(sensor_data) == 0) {
                // Log data
                log_data(sensor_data);

                // Print data to stdout
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
            } else {
                fprintf(stderr, "Invalid sensor data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5000000 microseconds = 5 seconds
    }

    // Cleanup and exit
    cleanup();
    gpioTerminate();
    return 0;
}

