#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp117_address;
    const char *log_file_name;
    int sample_interval;
} config_t;

config_t config = {I2C_BUS, TMP117_ADDR, LOG_FILE, SAMPLE_INTERVAL_SEC};

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.tmp117_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius
    float temperature = (float)(raw_temp >> 4) * 0.0078125;
    return temperature;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(config.log_file_name, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C with retry mechanism
    int init_attempts = 0;
    while (init_i2c() != 0 && init_attempts < 3) {
        fprintf(stderr, "I2C initialization failed, retrying... (%d/3)\n", init_attempts + 1);
        gpioDelay(1000); // Wait 1 second before retrying
        init_attempts++;
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "I2C initialization failed after multiple retries. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping logging.\n");
        }

        gpioDelay(config.sample_interval * 1000); // Delay for sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

