        fprintf(stderr, "Attempting to re-initialize I2C (attempt %d/%d)\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
        sleep(1); // Wait before retrying
        reinit_attempts++;
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to initialize I2C after multiple attempts. Exiting.\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[4];
    sensor_data_t processed_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log data
            if (log_data(&processed_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

