// Define GPIO pin for DHT11
#define DHT11_PIN 4

// Define error codes
#define ERROR_TIMEOUT -1
#define ERROR_CHECKSUM -2
#define ERROR_SENSOR_ABSENT -3

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
} DHT11Data;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to generate a delay in microseconds
void delay_us(int microseconds) {
    gpioDelay(microseconds);
}

// Function to read the DHT11 sensor
int read_dht11(DHT11Data *data) {
    int i, j;
    int data_bits[40] = {0};

    // 1. Send start signal
    gpioSetMode(DHT11_PIN, PI_OUTPUT);
    gpioWrite(DHT11_PIN, 0);
    delay_us(18000); // 18ms
    gpioWrite(DHT11_PIN, 1);
    delay_us(20); // 20us

    // 2. Set GPIO to input and wait for response
    gpioSetMode(DHT11_PIN, PI_INPUT);
    delay_us(40); // Wait for sensor to pull low

    if (gpioRead(DHT11_PIN) != 0) {
        fprintf(stderr, "Error: DHT11 did not pull low.\n");
        return ERROR_SENSOR_ABSENT;
    }

    delay_us(80); // Wait for 80us
    if (gpioRead(DHT11_PIN) != 1) {
        fprintf(stderr, "Error: DHT11 did not pull high.\n");
        return ERROR_SENSOR_ABSENT;
    }
    delay_us(80); // Wait for 80us

    // 3. Read 40 data bits
    for (i = 0; i < 40; i++) {
        // Wait for low
        delay_us(50); // Wait for 50us
        if (gpioRead(DHT11_PIN) != 0) {
            fprintf(stderr, "Error: DHT11 did not pull low during data bit %d.\n", i);
            return ERROR_TIMEOUT;
        }

        // Measure high time
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpioRead(DHT11_PIN) == 0) {
            // Wait for high
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        long high_time = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        if (high_time > 70) {
            data_bits[i] = 1;
        } else {
            data_bits[i] = 0;
        }
    }

    // 4. Verify checksum
    int checksum = (data_bits[0] + data_bits[1] + data_bits[2] + data_bits[3]) & 0xFF;
    if (checksum != (data_bits[4] + data_bits[5] + data_bits[6] + data_bits[7])) {
        fprintf(stderr, "Error: Checksum mismatch.\n");
        return ERROR_CHECKSUM;
    }

    // 5. Extract data
    data->humidity = (data_bits[0] << 8) | data_bits[1];
    data->temperature = (data_bits[2] << 8) | data_bits[3];

    return 0; // Success
}

// Function to log data to a file
void log_data(const DHT11Data *data) {
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, data->humidity, data->temperature);
    fclose(fp);
}

// Function to log errors to a file
