    FILE *fp = fopen("dht11_errors.txt", "a");
    if (fp == NULL) {
        perror("Error opening error file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%d,%s\n", timestamp, error_code, message);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    DHT11Data data;

    // Main loop
    while (program_running) {
        int result = read_dht11(&data);

        if (result == 0) {
            log_data(&data);
        } else {
            log_error(result, "DHT11 read failed");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Clean up
    gpioTerminate();

    return 0;
}

