#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDRESS 0x44
#define MEASURE_COMMAND 0x2C06
#define RETRY_COUNT 3
#define LOG_FILE "sht31d_data.log"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int address);
int write_i2c(int handle, int data);
int read_i2c(int handle, char *buffer, int count);
unsigned char crc8(const unsigned char *data, int len);
int validate_crc(unsigned char data[], int index, unsigned char checksum);
int read_sensor_data(int handle, sensor_data_t *data);
int log_data(FILE *file, float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write data to I2C device
int write_i2c(int handle, int data) {
    int result = i2cWriteByteData(handle, 0, data);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c(int handle, char *buffer, int count) {
    int result = i2cReadI2CBlockData(handle, 0, buffer, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }
    return result;
}

// CRC-8 validation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(unsigned char data[], int index, unsigned char checksum) {
    unsigned char calculated_checksum = crc8(data, 2);
    return (calculated_checksum == checksum);
}

// Read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    char buffer[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (write_i2c(handle, MEASURE_COMMAND) == 0) {
            gpioDelay(15); // Wait for measurement (at least 15ms)
            if (read_i2c(handle, buffer, 6) == 6) {
                // Validate CRC for temperature
                if (validate_crc(buffer, 0, buffer[2])) {
                    // Validate CRC for humidity
                    if (validate_crc(buffer + 3, 0, buffer[5])) {
                        // Convert data
                        int temperature_raw = (buffer[0] << 8) | buffer[1];
                        int humidity_raw = (buffer[3] << 8) | buffer[4];

                        data->temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
                        data->humidity = 100.0 * (float)humidity_raw / 65535.0;

                        return 0; // Success
                    } else {
                        fprintf(stderr, "Humidity CRC validation failed\n");
                    }
                } else {
                    fprintf(stderr, "Temperature CRC validation failed\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            fprintf(stderr, "Failed to write measurement command\n");
        }

        retries++;
        gpioDelay(10); // Small delay before retrying
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Log data to file
int log_data(FILE *file, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, SHT31_ADDRESS);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            if (log_data(log_file, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

