#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_pigpio();
int open_i2c_device(int bus, int addr);
int read_lm75b(int handle, float *temperature);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_fan(float average);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read temperature from LM75B sensor
int read_lm75b(int handle, float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (Celsius)
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            raw_temp = raw_temp >> 5; // Shift right by 5 bits
            *temperature = raw_temp * 0.125;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read LM75B after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Add temperature to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate running average
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control fan based on average temperature
void control_fan(float average) {
    if (average > TEMP_THRESHOLD_HIGH && gpioRead(FAN_GPIO) == 0) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("Fan ON (Average: %.2f°C)\n", average);
    } else if (average < TEMP_THRESHOLD_LOW && gpioRead(FAN_GPIO) == 1) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("Fan OFF (Average: %.2f°C)\n", average);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, LM75B_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Configure FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer temp_buffer = {{0.0}, 0, 0};

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature;

        // Read temperature from LM75B
        if (read_lm75b(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f°C\n", temperature);

            // Add temperature to circular buffer
            add_to_buffer(&temp_buffer, temperature);

            // Calculate running average
            float average = calculate_average(&temp_buffer);

            // Control fan
            control_fan(average);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

