#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SAMPLE_INTERVAL_SEC 1
#define PRESSURE_THRESHOLD 5.0
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 polynomial
uint8_t crc8(const uint8_t *data, size_t len, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize the I2C connection
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the SDP810 sensor
int read_sdp810(sensor_data_t *data) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buffer[9];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(45000); // 45ms delay

    if (i2cReadDevice(i2c_handle, (char *)buffer, 9) != 9) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2, 0xFF) != buffer[2] ||
        crc8(buffer + 3, 2, 0xFF) != buffer[5] ||
        crc8(buffer + 6, 2, 0xFF) != buffer[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data->pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    data->temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Function to log data to a file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->pressure, data->temperature);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Function to check pressure threshold and print warning
void check_pressure_threshold(const sensor_data_t *data) {
    if (data->pressure > PRESSURE_THRESHOLD) {
        fprintf(stderr, "Warning: Pressure exceeds threshold (%.2f Pa > %.2f Pa)\n", data->pressure, PRESSURE_THRESHOLD);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sdp810(&sensor_data) == 0) {
            log_data(&sensor_data);
            check_pressure_threshold(&sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

