#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_HIGH 28.0
#define TEMP_LOW 27.0
#define HIBERNATE_TEMP 30.0
#define HYSTERESIS_DELAY 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void control_led(float temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
void hibernate();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read temperature from STTS2004
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius
    temperature = (float)((int16_t)raw_temp >> 4) * 0.0625;
    return temperature;
}

// Function to control the LED with hysteresis
void control_led(float temperature) {
    static int led_state = 0; // 0 = off, 1 = on
    static time_t last_change_time = 0;

    if (temperature > TEMP_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        led_state = 1;
        last_change_time = time(NULL);
    } else if (temperature < TEMP_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        led_state = 0;
        last_change_time = time(NULL);
    }

    // Hysteresis delay
    if (led_state == 1 && (time(NULL) - last_change_time) < HYSTERESIS_DELAY) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        led_state = 0;
    } else if (led_state == 0 && (time(NULL) - last_change_time) < HYSTERESIS_DELAY) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        led_state = 1;
    }
}

// Function to log temperature to stdout
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("%s Temperature: %.2f °C\n", buf, temperature);
}

// Function to simulate hibernation
void hibernate() {
    printf("Hibernating...\n");
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

int main() {
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            log_temperature(temperature);
            control_led(temperature);

            if (temperature > HIBERNATE_TEMP) {
                hibernate();
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Exiting.\n");
            break;
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate(); // Release pigpio resources

    return 0;
}

