#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5
#define READ_TEMP_CMD 0xE0
#define RETRY_COUNT 3
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
int validate_sensor();
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char buf[2];
    int result;
    int retries = 0;

    // Measure Humidity
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, MEASURE_HUMID_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing humidity command: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms
            retries++;
            continue;
        }
        gpioDelay(20); // Wait 20ms
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "Error reading humidity data: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read humidity after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

    // Measure Temperature
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms
            retries++;
            continue;
        }
        gpioDelay(20); // Wait 20ms
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "Error reading temperature data: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = (175.72 * raw_temperature) / 65536.0 - 46.85;

    return 0;
}

// Validate sensor
int validate_sensor() {
    unsigned char buf[2];
    int result;
    int retries = 0;

    // Read Electronic ID
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, 0xF2); // Command to read Electronic ID
        if (result != 0) {
            fprintf(stderr, "Error writing electronic ID command: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms
            retries++;
            continue;
        }
        gpioDelay(20); // Wait 20ms
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "Error reading electronic ID data: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read electronic ID after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int electronic_id = (buf[0] << 8) | buf[1];

    // Read Firmware Revision
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, 0xF3); // Command to read Firmware Revision
        if (result != 0) {
            fprintf(stderr, "Error writing firmware revision command: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms
            retries++;
            continue;
        }
        gpioDelay(20); // Wait 20ms
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "Error reading firmware revision data: %d, retry %d\n", result, retries + 1);
            gpioDelay(1000); // Wait 1ms
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read firmware revision after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    unsigned int firmware_revision = (buf[0] << 8) | buf[1];

    // Check if the sensor is present (example values, adjust as needed)
    if (electronic_id != 0x00 && firmware_revision != 0x00) {
        printf("Sensor validated: Electronic ID = 0x%X, Firmware Revision = 0x%X\n", electronic_id, firmware_revision);
        return 0;
    } else {
        fprintf(stderr, "Error: Sensor not detected or invalid. Electronic ID = 0x%X, Firmware Revision = 0x%X\n", electronic_id, firmware_revision);
        return -1;
    }
}

// Log data to file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Validate sensor
    if (validate_sensor() != 0) {
        fprintf(stderr, "Sensor validation failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data.temperature, &sensor_data.humidity) == 0) {
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

