#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x03
#define SCALE_FACTOR_REG 0x06
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    float scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], uint8_t checksum);
int log_data(float pressure, float temperature, float scale_factor);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement on the SDP810
int trigger_measurement() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP810
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], uint8_t checksum) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < 8; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != checksum) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(float pressure, float temperature, float scale_factor) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, pressure, temperature, scale_factor);
    fflush(log_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[9];
    sensor_data_t sensor_values;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (at least 50ms)
        gpioDelay(50000); // 50ms

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(sensor_data, sensor_data[2]) != 0) {
            fprintf(stderr, "Error validating CRC, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        if (validate_crc(sensor_data + 3, sensor_data[4]) != 0) {
            fprintf(stderr, "Error validating CRC, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Extract data
        int16_t raw_pressure = (sensor_data[0] << 8) | sensor_data[1];
        int16_t raw_temperature = (sensor_data[3] << 8) | sensor_data[4];
        uint32_t raw_scale_factor = (sensor_data[6] << 16) | (sensor_data[7] << 8) | sensor_data[8];

        // Convert data to physical units (refer to SDP810 datasheet)
        sensor_values.pressure = (float)raw_pressure / 30.0; // Pa
        sensor_values.temperature = (float)raw_temperature / 200.0; // °C
        sensor_values.scale_factor = (float)raw_scale_factor / 1000.0; // Example scaling

        // Log data
        if (log_data(sensor_values.pressure, sensor_values.temperature, sensor_values.scale_factor) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

