#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_ADDR 0x62
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_DIR "/var/log/scd40_error.log"
#define MEASUREMENT_INTERVAL 5 // seconds
#define LOGGING_INTERVAL 60    // seconds
#define STOP_MEASUREMENT_CMD 0x365E

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;
circular_buffer_t data_buffer;
pthread_t logging_thread;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_sensor_data(sensor_data_t *data);
unsigned char crc8(const unsigned char *data, int len);
int validate_crc(unsigned char data[], int data_len, unsigned char checksum);
int stop_periodic_measurement();
int create_log_directory();
int write_error_log(const char *message);
void *logging_thread_func(void *arg);
int write_data_to_csv();
void signal_handler(int signal);
void init_circular_buffer(circular_buffer_t *cb);
int add_to_circular_buffer(circular_buffer_t *cb, sensor_data_t data);
int get_from_circular_buffer(circular_buffer_t *cb, sensor_data_t *data);

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        write_error_log("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char cmd[2] = {(STOP_MEASUREMENT_CMD >> 8) & 0xFF, STOP_MEASUREMENT_CMD & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        write_error_log("Failed to send stop measurement command");
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed
    char start_cmd[2] = {(STOP_MEASUREMENT_CMD >> 8) & 0xFF, STOP_MEASUREMENT_CMD & 0xFF};
    if (i2cWriteDevice(i2c_handle, start_cmd, 2) != 0) {
        write_error_log("Failed to send start periodic measurement command");
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char cmd[2] = {0xE4, 0xB8}; // Read measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        write_error_log("Failed to send read measurement command");
        return -1;
    }
    gpioDelay(1); // Wait for the sensor to prepare data

    char buffer[9];
    if (i2cReadDevice(i2c_handle, buffer, 9) != 9) {
        write_error_log("Failed to read sensor data");
        return -1;
    }

    // Extract data
    unsigned short co2 = (buffer[0] << 8) | buffer[1];
    unsigned short temperature = (buffer[3] << 8) | buffer[4];
    unsigned short humidity = (buffer[6] << 8) | buffer[7];

    // CRC validation
    if (!validate_crc(buffer, 2, buffer[2]) || !validate_crc(buffer + 3, 2, buffer[5]) || !validate_crc(buffer + 6, 2, buffer[8])) {
        write_error_log("CRC validation failed");
        return -1;
    }

    // Convert to float (temperature and humidity are big-endian)
    data->co2 = co2;
    data->temperature = -45 + 175 * (float)temperature / 65535.0;
    data->humidity = 100 * (float)humidity / 65535.0;
    data->timestamp = time(NULL);

    return 0;
}

// CRC-8 validation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(unsigned char data[], int data_len, unsigned char checksum) {
    unsigned char calculated_crc = crc8(data, data_len);
    return (calculated_crc == checksum);
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char cmd[2] = {(STOP_MEASUREMENT_CMD >> 8) & 0xFF, STOP_MEASUREMENT_CMD & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        write_error_log("Failed to send stop periodic measurement command");
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed
    return 0;
}

// Create log directory
int create_log_directory() {
    if (mkdir(LOG_DIR, 0755) != 0 && errno != EEXIST) {
        write_error_log("Failed to create log directory");
        return -1;
    }
    return 0;
}

// Write error log
int write_error_log(const char *message) {
    FILE *fp = fopen(ERROR_LOG_DIR, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Logging thread function
void *logging_thread_func(void *arg) {
    while (running) {
        sleep(LOGGING_INTERVAL);
        if (!running) break; // Check the running flag

        write_data_to_csv();
    }
    return NULL;
}

// Write data to CSV file
int write_data_to_csv() {
    pthread_mutex_lock(&data_buffer.mutex);
    if (data_buffer.count == 0) {
        pthread_mutex_unlock(&data_buffer.mutex);
        return 0; // Nothing to write
    }

    // Create filename
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char filename[50];
    snprintf(filename, sizeof(filename), "%sdata_%d-%02d-%02d_%02d-%02d-%02d.csv", LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

    // Create directory if it doesn't exist
    char dir_path[50];
    snprintf(dir_path, sizeof(dir_path), "%s..", LOG_DIR);
    if (mkdir(dir_path, 0755) != 0 && errno != EEXIST) {
        write_error_log("Failed to create parent log directory");
        pthread_mutex_unlock(&data_buffer.mutex);
        return -1;
    }

    // Write header if the file is new
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fp = fopen(filename, "w");
        if (fp == NULL) {
            write_error_log("Failed to open CSV file for writing");
            pthread_mutex_unlock(&data_buffer.mutex);
            return -1;
        }
        fprintf(fp, "Timestamp,CO2,Temperature,Humidity\n");
    } else {
        fclose(fp);
    }

    // Write data
    sensor_data_t data;
    int i;
    for (i = 0; i < data_buffer.count; i++) {
        data = data_buffer.buffer[(data_buffer.head - data_buffer.count + i + BUFFER_SIZE) % BUFFER_SIZE];
        fprintf(fp, "%ld,%d,%.2f,%.2f\n", data.timestamp, data.co2, data.temperature, data.humidity);
    }

    fclose(fp);
    pthread_mutex_unlock(&data_buffer.mutex);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Shutting down...\n");
        running = 0;
    }
}

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

// Add data to circular buffer
int add_to_circular_buffer(circular_buffer_t *cb, sensor_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

// Get data from circular buffer
int get_from_circular_buffer(circular_buffer_t *cb, sensor_data_t *data) {
    pthread_mutex_lock(&cb->mutex);
    if (cb->count == 0) {
        pthread_mutex_unlock(&cb->mutex);
        return -1; // Buffer is empty
    }
    *data = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    cb->count--;
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        write_error_log("pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create log directory
    if (create_log_directory() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&data_buffer);

    // Create logging thread
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        write_error_log("Failed to create logging thread");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler
    signal(SIGINT, signal_handler);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t data;
    while (running) {
        if (read_sensor_data(&data) == 0) {
            add_to_circular_buffer(&data_buffer, data);
        }
        sleep(MEASUREMENT_INTERVAL);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for logging thread to finish
    pthread_join(logging_thread, NULL);

    // Flush remaining data
    write_data_to_csv();

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

