int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], uint8_t crc);
sensor_data_t process_sensor_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// CRC-8 polynomial and initial value
uint8_t crc8_polynomial = 0x31;
uint8_t crc8_initial = 0xFF;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement on the SDP810
int trigger_measurement() {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP810
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t crc_calculated = crc8_initial;
    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ crc8_polynomial;
            } else {
                crc_calculated <<= 1;
            }
        }
