            gpioDelay(1000); // Wait 1 second before retrying
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
            continue; // Skip to the next iteration
        }

        // Validate CRC and process data
        int crc_error = 0;
        for (int i = 0; i < 3; i++) {
