#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define AMBIENT_HYSTERESIS 25.0
#define OBJECT_HYSTERESIS 28.0
#define OBJECT_ON_THRESHOLD 30.0
#define AMBIENT_OFF_THRESHOLD 20.0
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_mlx90614(float *ambient_temp, float *object_temp);
float convert_to_celsius(uint16_t raw_temp);
void control_fan(float object_temp);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx90614_address;
    int fan_gpio;
    float ambient_hysteresis;
    float object_hysteresis;
    float object_on_threshold;
    float ambient_off_threshold;
    char *log_file_name;
} config_t;

config_t config = {
    I2C_BUS,
    MLX90614_ADDR,
    FAN_GPIO,
    AMBIENT_HYSTERESIS,
    OBJECT_HYSTERESIS,
    OBJECT_ON_THRESHOLD,
    AMBIENT_OFF_THRESHOLD,
    LOG_FILE
};

int main() {
    float ambient_temp, object_temp;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperatures
        if (read_mlx90614(&ambient_temp, &object_temp) == 0) {
            // Log temperatures
            log_temperature(ambient_temp, object_temp);

            // Control fan
            control_fan(object_temp);
        } else {
            fprintf(stderr, "Failed to read temperatures. Skipping logging and fan control.\n");
        }

        // Wait 2 seconds
        gpioDelay(2000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.mlx90614_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from MLX90614
int read_mlx90614(float *ambient_temp, float *object_temp) {
    uint16_t raw_ambient, raw_object;
    int retries = 3;

    while (retries > 0) {
        raw_ambient = i2cReadWordData(i2c_handle, AMBIENT_TEMP_REG);
        if (raw_ambient >= 0) break; // Success
        fprintf(stderr, "I2C read error (ambient): %d, retries remaining: %d\n", raw_ambient, retries);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) return 1; // Error

    retries = 3;
    while (retries > 0) {
        raw_object = i2cReadWordData(i2c_handle, OBJECT_TEMP_REG);
        if (raw_object >= 0) break; // Success
        fprintf(stderr, "I2C read error (object): %d, retries remaining: %d\n", raw_object, retries);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) return 1; // Error

    *ambient_temp = convert_to_celsius(raw_ambient);
    *object_temp = convert_to_celsius(raw_object);

    return 0;
}

// Convert raw temperature to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Control fan with hysteresis
void control_fan(float object_temp) {
    static int fan_on = 0;

    if (object_temp > config.object_on_threshold && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Object Temp: %.2f\u00b0C)\n", object_temp);
    } else if (object_temp < config.object_off_threshold && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Object Temp: %.2f\u00b0C)\n", object_temp);
    }
}

// Log temperature to file
void log_temperature(float ambient_temp, float object_temp) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (ambient_temp < -273.0 || object_temp < -273.0) {
        fprintf(stderr, "Invalid temperature reading. Skipping logging.\n");
        return;
    }

    fprintf(log_file, "%s, Ambient: %.2f\u00b0C, Object: %.2f\u00b0C\n", timestamp, ambient_temp, object_temp);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d. Terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
}

