#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
int server_fd;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    char buf[1] = {MEASURE_CMD};
    char read_buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }

        gpioDelay(10); // Wait 10ms for measurement

        if (i2cReadDevice(i2c_handle, read_buf, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned short temperature_raw = (read_buf[0] << 8) | read_buf[1];
        unsigned short humidity_raw = (read_buf[3] << 8) | read_buf[4];

        data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
        data->humidity = 100.0 * (float)humidity_raw / 65535.0;

        // Clamp humidity to 0-100%
        if (data->humidity < 0.0) data->humidity = 0.0;
        if (data->humidity > 100.0) data->humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to format sensor data into an HTML string
void format_html(sensor_data_t data, char *html_buffer, size_t buffer_size) {
    snprintf(html_buffer, buffer_size, 
             "HTTP/1.1 200 OK\r\n" 
             "Content-Type: text/html\r\n" 
             "\r\n" 
             "<!DOCTYPE html><html><head><title>SHT40 Sensor Data</title></head><body>" 
             "Temperature: %.2f &deg;C, Humidity: %.2f %%<br><br>" 
             "</body></html>", data.temperature, data.humidity);
}

// Function to send HTTP response
int send_http_response(const char *html_buffer) {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 8080
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 8080
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }

    if (accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen) < 0) {
        perror("accept");
        close(server_fd);
        return -1;
    }

    send(server_fd, html_buffer, strlen(html_buffer), 0);
    close(server_fd);
    return 0;
}

int main() {
    sensor_data_t sensor_data;
    char html_buffer[1024];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (read_sht40(&sensor_data) == 0) {
            format_html(sensor_data, html_buffer, sizeof(html_buffer));
            if (send_http_response(html_buffer) != 0) {
                fprintf(stderr, "Error sending HTTP response.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

