#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define CSV_FILE "temperature_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp102_address;
    const char *log_file_name;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
float read_temperature(int handle);
char* format_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_temperature(const char *timestamp, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Read temperature from TMP102
float read_temperature(int handle) {
    char buf[2];
    int result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    float temperature = raw_temp * 0.0625;
    return temperature;
}

// Format timestamp
char* format_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%d %H:%M:%S", tm_info);
    return timestamp_str;
}

// Log temperature to CSV file
int log_temperature(const char *timestamp, float temperature) {
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fclose(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, TMP102_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature(i2c_handle);

        if (temperature > -999.0) { // Check for read error
            // Format timestamp
            char timestamp[20];
            format_timestamp(timestamp, sizeof(timestamp));

            // Log temperature
            if (log_temperature(timestamp, temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature, skipping logging.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

