#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02
#define MEASUREMENT_CONFIG_REG 0x0F
#define DEVICE_ID_REG 0xFE

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the HDC2010 sensor
int init_hdc2010() {
    // Configure the sensor for temperature and humidity measurement
    // Trigger measurement by writing to MEASUREMENT_CONFIG register
    char config_data[2] = {MEASUREMENT_CONFIG_REG, 0x00}; // Reset config
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for reset

    config_data[0] = MEASUREMENT_CONFIG_REG;
    config_data[1] = 0x01; // Enable temperature and humidity measurement
    result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity data from the HDC2010 sensor
int read_hdc2010(sensor_data_t *data) {
    char buf[4];
    int result;

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading temperature/humidity data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (buf[0] << 8) | buf[1];
    uint16_t raw_humidity = (buf[2] << 8) | buf[3];

    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (init_hdc2010() != 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity data
        if (read_hdc2010(&sensor_data) == 0) {
            // Print temperature and humidity readings
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

