// SDP800-500Pa I2C address
#define SDP800_ADDR 0x25

// I2C bus
#define I2C_BUS 1

// Measurement command
#define MEASURE_CMD 0x362F

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// CRC-8 initial value
#define CRC_INITIAL_VALUE 0xFF

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data, uint8_t crc)
{
    uint8_t shift_register = crc;
    for (int i = 0; i < 8; i++)
    {
        if ((shift_register ^ data) & 0x80)
        {
            shift_register = (shift_register << 1) ^ CRC_POLYNOMIAL;
        }
        else
        {
            shift_register <<= 1;
        }
    }
    return shift_register;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t buffer[6];
    int result;

    // Send measurement command
    result = i2cWriteWordData(i2c_handle, 0, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 45ms)
    gpioDelay(45000); // 45ms

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Extract pressure and temperature values
    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    // Validate CRC checksums
    if (calculate_crc(buffer[2], buffer[2]) != buffer[2] ||
        calculate_crc(buffer[5], buffer[5]) != buffer[5]) {
        fprintf(stderr, "CRC checksum error\n");
        return -1;
    }

    return 0;
}

