#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SSR_GPIO 17
#define TARGET_TEMP_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define SAMPLE_RATE 1.0 // Hz
#define CONTROL_PERIOD 1.0 // seconds
#define MAX_TEMP 300.0 // Maximum safe temperature (Celsius)

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_fp = NULL;
static FILE *profile_fp = NULL;

// Structure to hold PID state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function Prototypes
int read_thermocouple(int spi_handle, float *temperature);
int load_target_profile(const char *filename, float *profile, int *profile_size);
float calculate_pid_output(float setpoint, float actual_temperature, PIDState *pid_state);
int set_ssr_duty_cycle(int gpio_pin, float duty_cycle);
int log_temperature(float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX6675 via SPI
int read_thermocouple(int spi_handle, float *temperature) {
    unsigned char tx_buf[2] = {0x00, 0x00}; // Dummy data for reading
    unsigned char rx_buf[2];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Extract temperature data (ignoring fault bit)
    int16_t raw_temp = (rx_buf[0] << 8) | rx_buf[1];
    raw_temp >>= 3; // Shift right to get rid of fault bit and extra bits

    *temperature = (float)raw_temp * 0.25;

    return 0;
}

// Function to load target temperature profile from file
int load_target_profile(const char *filename, float *profile, int *profile_size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening target profile file");
        return -1;
    }

    // Determine the number of data points
    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) != NULL && count < 100) { // Limit to 100 points for safety
        count++;
    }
    rewind(fp);

    *profile_size = count;
    if (*profile_size == 0) {
        fprintf(stderr, "Target profile file is empty.\n");
        fclose(fp);
        return -1;
    }

    *profile = (float *)malloc(*profile_size * sizeof(float));
    if (*profile == NULL) {
        perror("Error allocating memory for target profile");
        fclose(fp);
        return -1;
    }

    for (int i = 0; i < *profile_size; i++) {
        if (fscanf(fp, "%f", &(*profile)[i]) != 1) {
            fprintf(stderr, "Error reading target temperature from file.\n");
            free(*profile);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

// Function to calculate PID output
float calculate_pid_output(float setpoint, float actual_temperature, PIDState *pid_state) {
    float error = setpoint - actual_temperature;
    pid_state->integral += error * SAMPLE_RATE;
    float derivative = (error - pid_state->previous_error) / SAMPLE_RATE;
    float output = Kp * error + Ki * pid_state->integral + Kd * derivative;
    pid_state->previous_error = error;

    // Clamp the output to the range [0, 1]
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set SSR duty cycle using PWM
int set_ssr_duty_cycle(int gpio_pin, float duty_cycle) {
    gpioPWM(gpio_pin, (int)(duty_cycle * 255.0)); // pigpio uses 0-255 for PWM
    return 0;
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_fp, "Timestamp,Temperature(C)\n"); // Write header if file is new
    }

    fprintf(log_fp, "%s,%.2f\n", timestamp, temperature);
    fflush(log_fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SSR_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SSR_GPIO, 1000); // 1 kHz PWM frequency
    gpioSetPWMrange(SSR_GPIO, 255); // Set PWM range to 0-255

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (profile_fp != NULL) {
        fclose(profile_fp);
    }
    gpioWrite(SSR_GPIO, 0); // Turn off SSR
    gpioTerminate();
}

int main() {
    float target_profile[100]; // Assuming a maximum of 100 data points
    int profile_size = 0;
    float setpoint;
    float actual_temperature;
    float pid_output;
    float duty_cycle;
    time_t start_time, current_time;
    double elapsed_time;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Load target temperature profile
    if (load_target_profile(TARGET_TEMP_FILE, &target_profile, &profile_size) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    start_time = time(NULL);
    while (running) {
        elapsed_time = difftime(time(NULL), start_time);

        // Get current time
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        // Read temperature from thermocouple
        if (read_thermocouple(spi_handle, &actual_temperature) == 0) {
            printf("%s - Temperature: %.2f C\n", timestamp, actual_temperature);

            // Log temperature
            if (log_temperature(actual_temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }

            // Check for sensor failure (example: max temperature exceeded)
            if (actual_temperature > MAX_TEMP) {
                fprintf(stderr, "%s - CRITICAL ERROR: Thermocouple reading exceeds maximum safe temperature (%.2f C > %.2f C)!\n", timestamp, actual_temperature, MAX_TEMP);
                running = 0; // Stop the process
            }

            // Determine setpoint from target profile
            if (elapsed_time < profile_size * CONTROL_PERIOD) {
                setpoint = target_profile[(int)(elapsed_time / CONTROL_PERIOD)];
            } else {
                setpoint = target_profile[profile_size - 1]; // Use last setpoint if beyond profile duration
            }

            // Calculate PID output
            pid_output = calculate_pid_output(setpoint, actual_temperature, &pid_state);

            // Scale PID output to duty cycle (0.0 to 1.0)
            duty_cycle = pid_output;

            // Set SSR duty cycle
            if (set_ssr_duty_cycle(SSR_GPIO, duty_cycle) != 0) {
                fprintf(stderr, "Error setting SSR duty cycle.\n");
            }

            printf("%s - PID Output: %.2f, Duty Cycle: %.2f\n", timestamp, pid_output, duty_cycle);

        } else {
            fprintf(stderr, "%s - Error reading thermocouple.\n", timestamp);
        }

        gpioDelay(1000000 / (int)(1.0 / SAMPLE_RATE)); // Delay to achieve desired sample rate
    }

    // Cleanup and exit
    cleanup();
    free(target_profile);
    return 0;
}

