                running = 0; // Stop the process
            }

            // Determine setpoint from target profile
            if (elapsed_time < profile_size * CONTROL_PERIOD) {
                setpoint = target_profile[(int)(elapsed_time / CONTROL_PERIOD)];
            } else {
                setpoint = target_profile[profile_size - 1]; // Use last setpoint if beyond profile duration
            }

            // Calculate PID output
            pid_output = calculate_pid_output(setpoint, actual_temperature, &pid_state);

            // Scale PID output to duty cycle (0.0 to 1.0)
            duty_cycle = pid_output;

            // Set SSR duty cycle
            if (set_ssr_duty_cycle(SSR_GPIO, duty_cycle) != 0) {
                fprintf(stderr, "Error setting SSR duty cycle.\n");
            }

            printf("%s - PID Output: %.2f, Duty Cycle: %.2f\n", timestamp, pid_output, duty_cycle);

        } else {
            fprintf(stderr, "%s - Error reading thermocouple.\n", timestamp);
        }

        gpioDelay(1000000 / (int)(1.0 / SAMPLE_RATE)); // Delay to achieve desired sample rate
    }

    // Cleanup and exit
    cleanup();
    free(target_profile);
    return 0;
}

