#include <math.h>

// Constants
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define LOG_FILE "greenhouse.log"
#define TEMPERATURE_FILE_PATH "/sys/bus/w1/devices/28-xxxxxxxxxxxx/w1_slave" // Replace with your sensor's ID
#define TEMPERATURE_READ_INTERVAL 5 // seconds

// PID Gains
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
float read_temperature();
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void set_heater_state(int state);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(float temperature, float setpoint, float pid_output, int pwm_duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from DS18B20 sensor
float read_temperature() {
    FILE *fp;
    char buffer[256];
    char *token;
    float temperature = -1000.0; // Initialize to an invalid value
    int crc_error = 0;

    fp = fopen(TEMPERATURE_FILE_PATH, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file %s\n", TEMPERATURE_FILE_PATH);
        return -1000.0;
    }

    // Read the file twice to get the most recent reading
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature file (1st read)\n");
        fclose(fp);
        return -1000.0;
    }
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature file (2nd read)\n");
        fclose(fp);
        return -1000.0;
    }

    fclose(fp);

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "Error: CRC check failed\n");
        return -1000.0;
    }

    // Extract temperature from the file
    token = strstr(buffer, "t=");
    if (token != NULL) {
        temperature = atof(token + 2) / 1000.0; // Temperature in Celsius
    } else {
        fprintf(stderr, "Error: Could not find temperature in file\n");
        return -1000.0;
    }

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set the heater state (on/off)
void set_heater_state(int state) {
    gpioWrite(HEATER_GPIO, state);
}

// Function to set the PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float temperature, float setpoint, float pid_output, int pwm_duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    set_heater_state(0);
    set_pwm_duty_cycle(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float setpoint;
    float temperature;
    float pid_output;
    int pwm_duty_cycle;
    float integral = 0.0;
    float previous_error = 0.0;

    // Parse command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read temperature
        temperature = read_temperature();

        if (temperature < -900.0) {
            fprintf(stderr, "Error: Could not read temperature, using previous value or exiting\n");
            // Consider implementing a default temperature or exiting if temperature reading fails consistently
        }

        // Calculate PID output
        pid_output = calculate_pid(setpoint, temperature, &integral, &previous_error);

        // Convert PID output to PWM duty cycle (0-1000)
        pwm_duty_cycle = (int)(pid_output * 1000.0 / 50.0); // Assuming a proportional gain of 50 to map PID output to 0-1, then scale to 0-1000

        // Set heater state and PWM duty cycle
        if (temperature < setpoint) {
            set_heater_state(1);
        } else {
            set_heater_state(0);
            set_pwm_duty_cycle(0);
        }
        set_pwm_duty_cycle(pwm_duty_cycle);

        // Log data
        log_data(temperature, setpoint, pid_output, pwm_duty_cycle);

        // Wait for the next reading
        sleep(TEMPERATURE_READ_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

