#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASURE_CMD 0xBE
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_aht20(float *humidity);
void control_relay(float humidity);
void log_humidity(float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode.\n");
        return -1;
    }
    gpioWrite(GPIO_RELAY, 0); // Initialize relay to OFF
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read humidity from AHT20 sensor
int read_aht20(float *humidity) {
    unsigned char cmd[1] = {MEASURE_CMD};
    unsigned char data[6];
    int result;

    // Trigger measurement
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result == 0) break; // Success
        fprintf(stderr, "I2C write failed (attempt %d): %d\n", i + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    gpioDelay(80 * 1000); // Wait 80ms

    // Read data
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) break; // Success
        fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (result != 6) {
        fprintf(stderr, "Failed to read data after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Verify status byte
    if ((data[0] & 0x80) != 0) {
        fprintf(stderr, "Sensor busy.\n");
        return -1;
    }

    // Calculate humidity
    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
    *humidity = ((float)humidity_raw / 0x100000) * 100;

    return 0;
}

// Control dehumidifier relay
void control_relay(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(GPIO_RELAY, 1); // Turn ON
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(GPIO_RELAY, 0); // Turn OFF
    }
}

// Log humidity data
void log_humidity(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is OFF
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO and I2C
    if (init_gpio() != 0 || init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float humidity;

    // Main loop
    while (!terminate) {
        if (read_aht20(&humidity) == 0) {
            log_humidity(humidity);
            control_relay(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity.\n");
        }

        gpioDelay(5000 * 1000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

