char *format_json(float temperature, float humidity);
int post_data(const char *json_data, const char *url);
void signal_handler(int signal);
int init_i2c();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    syslog(LOG_INFO, "I2C device opened successfully.");
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        syslog(LOG_INFO, "I2C device closed.");
    }
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated.");
    closelog();
}

// Read temperature and humidity from HTU21D
int read_htu21d(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[3];
    int result;
    unsigned int raw_temperature, raw_humidity;

    // Measure temperature
    result = i2cWriteByte(i2c_handle, MEASURE_TEMP_NOHOLD);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to write temperature measurement command: %d", result);
        return -1;
    }
    gpioDelay(50); // Wait for measurement

    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read temperature data: %d", result);
        return -1;
    }

    raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = -46.85 + 175.72 * (float)raw_temperature / 65536.0;

    // Measure humidity
    result = i2cWriteByte(i2c_handle, MEASURE_HUMIDITY_NOHOLD);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to write humidity measurement command: %d", result);
        return -1;
    }
    gpioDelay(50); // Wait for measurement

    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %d", result);
        return -1;
    }

    raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = -6.0 + 125.0 * (float)raw_humidity / 65536.0;

    return 0;
}

