char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);
    return json_string;
}

// Post data to server
int post_data(const char *json_data, const char *url) {
    int sock = 0, valread;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation error");
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address / Address not supported");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection Failed");
        close(sock);
        return -1;
    }

    char post_data[256];
    snprintf(post_data, sizeof(post_data), "POST %s HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", url, strlen(json_data), json_data);

    if (send(sock, post_data, strlen(post_data), 0) < 0) {
        syslog(LOG_ERR, "Send failed");
        close(sock);
        return -1;
    }

    valread = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        syslog(LOG_ERR, "Receive failed");
        close(sock);
        return -1;
    }
    buffer[valread] = '\0';
    syslog(LOG_INFO, "Server response: %s", buffer);

    close(sock);
    return 0;
}

int main() {
    float temperature, humidity;
    char *json_data;

    // Initialize syslog
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

