    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Humidity sensor started.");

    while (running) {
        if (read_htu21d(i2c_handle, &temperature, &humidity) == 0) {
            syslog(LOG_INFO, "Temperature: %.2f C, Humidity: %.2f %%", temperature, humidity);

            json_data = format_json(temperature, humidity);
            if (json_data != NULL) {
                if (post_data(json_data, SERVER_URL) == 0) {
                    syslog(LOG_INFO, "Data posted successfully.");
                } else {
                    syslog(LOG_ERR, "Failed to post data.");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read sensor data.");
        }

        sleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

