#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
static volatile int running = 1;
static int i2c_handle_tmp117 = -1;
static int i2c_handle_aht20 = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(int bus, int addr);
int read_tmp117(int i2c_handle, float *temperature);
int read_aht20(int i2c_handle, float *humidity);
int read_pir(int gpio_pin, int *motion_detected);
int log_data(FILE *fp, float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion_detected;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read temperature from TMP117
int read_tmp117(int i2c_handle, float *temperature) {
    char buf[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read == 2) {
            // Convert raw data to temperature (Celsius)
            int raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (float)raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading TMP117 (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read humidity from AHT20
int read_aht20(int i2c_handle, float *humidity) {
    char buf[6];
    int retries = 0;
    int bytes_read;

    // Trigger measurement (single shot mode)
    buf[0] = 0xAC;  // Command byte
    buf[1] = 0x33;  // Argument byte
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error triggering AHT20 measurement: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(80); // Wait for measurement (at least 75ms)

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 6);
        if (bytes_read == 6) {
            // Check status bit (bit 7 of byte 0)
            if ((buf[0] & 0x80) == 0) {
                // Convert raw data to humidity (%RH)
                unsigned long humidity_raw = ((unsigned long)buf[1] << 12) | ((unsigned long)buf[2] << 4) | (buf[3] >> 4);
                *humidity = ((float)humidity_raw / 0x100000) * 100;
                return 0; // Success
            } else {
                fprintf(stderr, "AHT20 busy (attempt %d).\n", retries + 1);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        } else {
            fprintf(stderr, "Error reading AHT20 (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read motion detection from PIR sensor
int read_pir(int gpio_pin, int *motion_detected) {
    *motion_detected = gpioRead(gpio_pin);
    return 0;
}

// Function to log data to CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C for TMP117
    i2c_handle_tmp117 = init_i2c(I2C_BUS, TMP117_ADDR);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "TMP117 initialization failed. Continuing without TMP117.\n");
    }

    // Initialize I2C for AHT20
    i2c_handle_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "AHT20 initialization failed. Continuing without AHT20.\n");
    }

    // Open log file
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char filename[64];
    strftime(filename, sizeof(filename), "%Y-%m-%d.csv", &tm);
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        float temperature = 0.0;
        float humidity = 0.0;
        int motion_detected = 0;

        // Read sensor data
        if (i2c_handle_tmp117 >= 0) {
            if (read_tmp117(i2c_handle_tmp117, &temperature) != 0) {
                fprintf(stderr, "Failed to read temperature.\n");
            }
        }

        if (i2c_handle_aht20 >= 0) {
            if (read_aht20(i2c_handle_aht20, &humidity) != 0) {
                fprintf(stderr, "Failed to read humidity.\n");
            }
        }

        if (read_pir(PIR_GPIO, &motion_detected) != 0) {
            fprintf(stderr, "Failed to read motion detection.\n");
        }

        // Log data
        if (log_data(log_file, temperature, humidity, motion_detected) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

