#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define SPI channel for MCP3008
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz

// Define MCP3008 channel for DHT22 data
#define DHT22_CHANNEL 0

// Define server address and port
#define SERVER_IP   "192.168.1.100"
#define SERVER_PORT 5000

// Define PWM range
#define PWM_RANGE 1024

// Define DHT22 data structure
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global variables
volatile sig_atomic_t program_running = 1;
int pwm_red_pin, pwm_green_pin, pwm_blue_pin;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_pwm(int pin);
int read_dht22_data(DHT22Data *data);
int read_cpu_load();
void map_load_to_color(int cpu_load, int *red, int *green, int *blue);
void send_data_to_server(float temperature, float humidity, int red, int green, int blue);
int read_mcp3008(int channel);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    // Set RGB LED pins as output
    pinMode(RED_PIN, OUTPUT);
    pinMode(GREEN_PIN, OUTPUT);
    pinMode(BLUE_PIN, OUTPUT);

    // Initialize PWM
    if (init_pwm(RED_PIN) == -1 || init_pwm(GREEN_PIN) == -1 || init_pwm(BLUE_PIN) == -1) {
        return -1;
    }

    pwm_red_pin = RED_PIN;
    pwm_green_pin = GREEN_PIN;
    pwm_blue_pin = BLUE_PIN;

    return 0;
}

// Initialize PWM on a given pin
int init_pwm(int pin) {
    pinMode(pin, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for desired PWM frequency (e.g., 50Hz)
    return 0;
}

// Read DHT22 data using MCP3008 ADC
int read_dht22_data(DHT22Data *data) {
    // Read raw data from MCP3008
    int raw_data = read_mcp3008(DHT22_CHANNEL);

    // Convert raw data to temperature and humidity (example conversion)
    // This is a placeholder; replace with actual DHT22 conversion logic
    // based on your specific sensor and ADC configuration.
    data->temperature = (float)raw_data / 10.0; // Example: 0-1023 -> 0-10.23
    data->humidity = (float)(raw_data % 10) / 10.0; // Example: 0-9 -> 0-0.9

    // Validate sensor readings
    if (data->temperature < -40.0 || data->temperature > 80.0) {
        fprintf(stderr, "Error: Invalid temperature reading: %.2f\n", data->temperature);
        return -1;
    }
    if (data->humidity < 0.0 || data->humidity > 100.0) {
        fprintf(stderr, "Error: Invalid humidity reading: %.2f\n", data->humidity);
        return -1;
    }

    return 0;
}

// Read CPU load from /proc/stat
int read_cpu_load() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0;
    static unsigned long long prev_idle_total = 0;
    static unsigned long long prev_iowait_total = 0;
    static unsigned long long prev_irq_total = 0;
    static unsigned long long prev_softirq_total = 0;
    static unsigned long long prev_steal_total = 0;
    static unsigned long long prev_guest_total = 0;
    static unsigned long long prev_guest_nice_total = 0;
    static int first_read = 1;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;
    unsigned long long irq_total = irq + softirq + steal;
    unsigned long long guest_total = guest + guest_nice;

    if (first_read) {
        prev_user = user;
        prev_nice = nice;
        prev_system = system;
        prev_idle = idle;
        prev_iowait = iowait;
        prev_irq = irq;
        prev_softirq = softirq;
        prev_steal = steal;
        prev_guest = guest;
        prev_guest_nice = guest_nice;
        prev_total = total;
        prev_idle_total = idle_total;
        prev_iowait_total = iowait;
        prev_irq_total = irq;
        prev_softirq_total = softirq;
        prev_steal_total = steal;
        prev_guest_total = guest;
        prev_guest_nice_total = guest_nice;
        first_read = 0;
        fclose(fp);
        return 0;
    }

    unsigned long long delta_user = user - prev_user;
    unsigned long long delta_nice = nice - prev_nice;
    unsigned long long delta_system = system - prev_system;
    unsigned long long delta_idle = idle - prev_idle;
    unsigned long long delta_iowait = iowait - prev_iowait;
    unsigned long long delta_irq = irq - prev_irq;
    unsigned long long delta_softirq = softirq - prev_softirq;
    unsigned long long delta_steal = steal - prev_steal;
    unsigned long long delta_guest = guest - prev_guest;
    unsigned long long delta_guest_nice = guest_nice - prev_guest_nice;

    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle_total = idle_total - prev_idle_total;
    unsigned long long delta_irq_total = irq_total - prev_irq_total;
    unsigned long long delta_guest_total = guest_total - prev_guest_total;

    unsigned long long idle_time = delta_total - delta_idle_total - delta_irq_total - delta_steal - delta_guest_total;
    unsigned long long total_time = delta_total;

    float cpu_usage = (float)(total - idle_time) / total_time * 100.0;

    prev_user = user;
    prev_nice = nice;
    prev_system = system;
    prev_idle = idle;
    prev_iowait = iowait;
    prev_irq = irq;
    prev_softirq = softirq;
    prev_steal = steal;
    prev_guest = guest;
    prev_guest_nice = guest_nice;
    prev_total = total;
    prev_idle_total = idle_total;
    prev_iowait_total = iowait;
    prev_irq_total = irq;
    prev_softirq_total = softirq;
    prev_steal_total = steal;
    prev_guest_total = guest;
    prev_guest_nice_total = guest_nice;

    fclose(fp);
    return (int)cpu_usage;
}

// Map CPU load to RGB color values
void map_load_to_color(int cpu_load, int *red, int *green, int *blue) {
    if (cpu_load < 50) {
        // Green to Yellow
        *red = 0;
        *green = 255 - (int)((float)cpu_load / 50.0 * 255.0);
        *blue = 0;
    } else {
        // Yellow to Red
        *red = (int)((float)(cpu_load - 50) / 50.0 * 255.0);
        *green = 255 - (int)((float)(cpu_load - 50) / 50.0 * 255.0);
        *blue = 0;
    }
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Send data to server
void send_data_to_server(float temperature, float humidity, int red, int green, int blue) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Error converting IP address: %s\n", strerror(errno));
        close(sockfd);
        return;
    }

    // Format the data into a comma-separated string
    snprintf(buffer, sizeof(buffer), "%.2f,%.2f,%d,%d,%d", temperature, humidity, red, green, blue);

    if (sendto(sockfd, buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
    }

    close(sockfd);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() == -1) {
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return 1;
    }

    printf("RGB LED and DHT22 data transmission started. Press Ctrl+C to exit.\n");

    while (program_running) {
        DHT22Data dht22_data;
        int cpu_load;
        int red, green, blue;

        // Read DHT22 data
        if (read_dht22_data(&dht22_data) == -1) {
            fprintf(stderr, "Error reading DHT22 data.\n");
        }

        // Read CPU load
        cpu_load = read_cpu_load();
        if (cpu_load == -1) {
            fprintf(stderr, "Error reading CPU load.\n");
        }

        // Map CPU load to color
        map_load_to_color(cpu_load, &red, &green, &blue);

        // Set RGB LED color
        pwmWrite(pwm_red_pin, PWM_RANGE - red);
        pwmWrite(pwm_green_pin, PWM_RANGE - green);
        pwmWrite(pwm_blue_pin, PWM_RANGE - blue);

        // Send data to server
        send_data_to_server(dht22_data.temperature, dht22_data.humidity, red, green, blue);

        // Wait 500ms
        delay(500);
    }

    // Turn off RGB LED
    pwmWrite(pwm_red_pin, 0);
    pwmWrite(pwm_green_pin, 0);
    pwmWrite(pwm_blue_pin, 0);

    // Clean up wiringPi
    wiringPiSetupGpio(); // Reinitialize to allow cleanup

    printf("Exiting.\n");
    return 0;
}

