#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define BUFFER_SIZE 20

// Temperature thresholds (Celsius)
#define TEMP_LOW 25.0
#define TEMP_MED 40.0
#define TEMP_HIGH 60.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} log_entry_t;

log_entry_t log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(float *temperature);
int calculate_duty_cycle(float temperature);
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    unsigned char spi_data[4];
    int result;

    result = spiRead(spi_handle, spi_data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    // Check for fault bits
    if (spi_data[3] & 0x01) {
        fprintf(stderr, "MAX31855 fault: Open circuit\n");
        return -1;
    }
    if (spi_data[3] & 0x02) {
        fprintf(stderr, "MAX31855 fault: Short to GND\n");
        return -1;
    }
    if (spi_data[3] & 0x04) {
        fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        return -1;
    }

    // Extract temperature data (bits 18-31, signed 14-bit value)
    int16_t raw_temp = ((spi_data[0] << 8) | spi_data[1]) >> 2;
    *temperature = (float)raw_temp * 0.25;

    return 0; // Indicate success
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature < TEMP_MED) {
        duty_cycle = (int)((temperature - TEMP_LOW) / (TEMP_MED - TEMP_LOW) * 50);
    } else if (temperature < TEMP_HIGH) {
        duty_cycle = (int)(((temperature - TEMP_MED) / (TEMP_HIGH - TEMP_MED) * 150) + 50);
    } else {
        duty_cycle = 200;
    }

    return duty_cycle;
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("Timestamp: %s, Temperature: %.2f C, Duty Cycle: %d\n", time_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float temperature;
    int duty_cycle;
    time_t current_time;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Configure PWM on FAN_GPIO
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(&temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set PWM duty cycle
            gpioPWM(FAN_GPIO, duty_cycle);

            // Get current timestamp
            current_time = time(NULL);

            // Add data to circular buffer
            add_to_buffer(current_time, temperature, duty_cycle);
        } else {
            // Error reading temperature, skip fan update
            fprintf(stderr, "Error reading temperature, skipping fan update.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI interface
    spiClose(spi_handle);

    // Print the contents of the circular buffer
    print_buffer();

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

