#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8 // GPIO8
#define LOG_FILE "rtd_log.csv"
#define READ_INTERVAL 5 // seconds

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_FAULT_REG 0x01
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_RTD_CONFIG_REG 0x03

// RTD Constants
#define RTD_NOMINAL_RESISTANCE 100.0 // Ohms
#define RTD_REFERENCE_RESISTANCE 430.0 // Ohms
#define RTD_RATED_TEMPERATURE 0.0 // Celsius
#define RTD_A 3.9083e-3
#define RTD_B -5.775e-7
#define RTD_C 8.775e-12

// Global Variables
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_spi();
int read_max31865(uint8_t *data);
float read_temperature();
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int cs_pin;
    char *log_file;
    int read_interval;
} config_t;

// Function to initialize the SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MAX31865
int read_max31865(uint8_t *data) {
    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiRead(spi_handle, (char *)data, 4);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != 4) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the temperature from the MAX31865
float read_temperature() {
    uint8_t data[4];
    int fault;

    if (read_max31865(data) != 0) {
        fprintf(stderr, "Error reading MAX31865 data\n");
        return -1000.0; // Indicate an error
    }

    // Check for fault
    fault = (data[1] >> 0) & 0x07;
    if (fault) {
        fprintf(stderr, "MAX31865 Fault: 0x%02X\n", fault);
        if (fault & 0x01) fprintf(stderr, "  Open circuit\n");
        if (fault & 0x02) fprintf(stderr, "  Short to VCC\n");
        if (fault & 0x04) fprintf(stderr, "  Short to GND\n");
        return -1000.0; // Indicate an error
    }

    // Extract RTD MSB and LSB
    int16_t rtd_raw = ((data[2] << 8) | data[3]) >> 1;

    // Convert RTD raw value to resistance
    float rtd_resistance = ((float)rtd_raw / 32768.0) * RTD_REFERENCE_RESISTANCE;

    // Convert resistance to temperature using Callendar-Van Dusen equation
    float temperature = RTD_RATED_TEMPERATURE + (RTD_A + RTD_B * rtd_resistance + RTD_C * rtd_resistance * rtd_resistance) * rtd_resistance;

    return temperature;
}

// Function to log the temperature to a file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping log\n");
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

