#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Oversampling settings
#define OVERSAMPLING_TEMP 1 // x1
#define OVERSAMPLING_PRESS 1 // x1
#define OVERSAMPLING_HUM 1  // x1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int bme280_init();
int bme280_read_calibration_data();
int bme280_read_data(float *temperature, float *humidity, float *pressure);
void log_data(float temperature, float humidity, float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the BME280 sensor
int bme280_init() {
    // Set oversampling and power mode
    char ctrl_meas = (OVERSAMPLING_TEMP << 5) | (OVERSAMPLING_PRESS << 2) | 0x03; // Temperature x1, Pressure x1, Normal mode
    char ctrl_hum = OVERSAMPLING_HUM; // Humidity x1
    char config = (0x00 << 5) | (0x00 << 2) | 0x00; // t_sb = 0.5ms, filter off

    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUM, ctrl_hum) < 0) {
        fprintf(stderr, "Error writing to CTRL_HUM register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, BME280_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, ctrl_meas) < 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read calibration data from the BME280
int bme280_read_calibration_data() {
    uint8_t buffer[26];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)buffer, 26) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    calib.dig_T1 = (uint16_t)(buffer[1] << 8 | buffer[0]);
    calib.dig_T2 = (int16_t)(buffer[3] << 8 | buffer[2]);
    calib.dig_T3 = (int16_t)(buffer[5] << 8 | buffer[4]);
    calib.dig_P1 = (uint16_t)(buffer[7] << 8 | buffer[6]);
    calib.dig_P2 = (int16_t)(buffer[9] << 8 | buffer[8]);
    calib.dig_P3 = (int16_t)(buffer[11] << 8 | buffer[10]);
    calib.dig_P4 = (int16_t)(buffer[13] << 8 | buffer[12]);
    calib.dig_P5 = (int16_t)(buffer[15] << 8 | buffer[14]);
    calib.dig_P6 = (int16_t)(buffer[17] << 8 | buffer[16]);
    calib.dig_P7 = (int16_t)(buffer[19] << 8 | buffer[18]);
    calib.dig_P8 = (int16_t)(buffer[21] << 8 | buffer[20]);
    calib.dig_P9 = (int16_t)(buffer[23] << 8 | buffer[22]);
    calib.dig_H1 = buffer[25];

    uint8_t buffer_h[7];
    if (i2cReadI2CBlockData(i2c_handle, 0xE1, (char *)buffer_h, 7) < 0) {
        fprintf(stderr, "Error reading humidity calibration data: %s\n", strerror(errno));
        return -1;
    }

    calib.dig_H2 = (int16_t)(buffer_h[1] << 8 | buffer_h[0]);
    calib.dig_H3 = buffer_h[2];
    calib.dig_H4 = (int16_t)(buffer_h[3] << 4 | (buffer_h[4] & 0x0F));
    calib.dig_H5 = (int16_t)(buffer_h[5] << 4 | (buffer_h[4] >> 4));
    calib.dig_H6 = (int8_t)buffer_h[6];

    return 0;
}

