    while (!terminate) {
        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(&raw_pressure) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            gpioDelay(50000); // Wait 50ms before retrying
            continue;
        }

        // Calculate pressure
        pressure = calculate_pressure(raw_temp, raw_pressure);

        // Add reading to circular buffer
        add_reading(pressure);

        // Calculate rolling average
        average_pressure = calculate_average();

        // Check for deviation and trigger alert
        if (fabs(pressure - average_pressure) > 5.0) {
            trigger_alert();
        }

        // Wait 50ms
        gpioDelay(50000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

