// Function to read calibration data from the BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to validate calibration data
int validate_calibration_data() {
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0) {
        fprintf(stderr, "Error: Calibration data is invalid (zero value)\n");
        return -1;
    }
    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    char write_buf[2] = {BMP180_REG_CONTROL, 0x2E}; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, write_buf, 2) != 0) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, write_buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for temperature read\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    char write_buf[2] = {BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)}; // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, write_buf, 2) != 0) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(10000); // Wait 10ms (adjust based on OSS)

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, write_buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for pressure read\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in pascals
double calculate_pressure(int raw_pressure, int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)ac2 * b6) / pow(2, 11);
    long b3 = (((long)ac1 * 4 + x3 + x4 + 2) / 4);

    unsigned long b4 = ((unsigned long)ac4 * (unsigned long)(x3 + x4 + 32768)) / pow(2, 15);
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    long p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);

    double pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure;
}

// Function to log data to a file
void log_data(double temperature, double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, pressure);
    fflush(log_file);
}

// Timer callback function
void timer_callback() {
    int raw_temp, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }

    temperature = calculate_temperature(raw_temp);
    pressure = calculate_pressure(raw_pressure, raw_temp);

    log_data(temperature, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Validate calibration data
    if (validate_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up hardware timer interrupt
    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer interrupt\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Clean up
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

