#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define DUTY_MIN 0
#define DUTY_MAX 255
#define LOG_FILE "fan_log.txt"
#define READ_INTERVAL_SEC 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
float read_cpu_temp();
int map_temp_to_duty_cycle(float temp);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(float temp, int duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error reading temperature from file: %s\n", strerror(errno));
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli_celsius / 1000.0;
    return temp_celsius;
}

// Function to map temperature to PWM duty cycle
int map_temp_to_duty_cycle(float temp) {
    int duty_cycle;

    if (temp < TEMP_MIN) {
        duty_cycle = DUTY_MIN;
    } else if (temp > TEMP_MAX) {
        duty_cycle = DUTY_MAX;
    } else {
        duty_cycle = (int)(((temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * (DUTY_MAX - DUTY_MIN));
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(PWM_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(float temp, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %d\n", timestamp, temp, duty_cycle);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set GPIO18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop PWM
    gpioPWM(PWM_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    float temp;
    int duty_cycle;

    if (initialize() != 0) {
        return 1;
    }

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (running) {
        temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
        } else {
            duty_cycle = map_temp_to_duty_cycle(temp);
            if (set_pwm_duty_cycle(duty_cycle) != 0) {
                fprintf(stderr, "Error setting PWM duty cycle.\n");
            }
            if (log_data(temp, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    printf("Temperature-controlled fan stopped.\n");
    return 0;
}

