    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(bmp280_address);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Trying alternate address.\n");
        i2c_fd = init_i2c(BMP280_ALTERNATE_ADDRESS);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to initialize I2C with alternate address.\n");
            return 1;
        }
        bmp280_address = BMP280_ALTERNATE_ADDRESS;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) < 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw data.\n");
            // Attempt to re-initialize I2C
            close(i2c_fd);
            i2c_fd = init_i2c(bmp280_address);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            if (read_calibration_data(i2c_fd) < 0) {
                fprintf(stderr, "Failed to re-read calibration data. Exiting.\n");
                break;
            }
            continue; // Skip to the next iteration
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);

        // Log data
        if (log_data(temperature, pressure) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

