#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define ALERT_LED_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_fd;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
double running_average = 0.0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
double read_temperature();
void update_buffer(double temp);
double calculate_average();
void control_led(double avg_temp);
void *led_control_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Structure to pass data to the LED control thread
typedef struct {
    double running_average;
} led_data_t;

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Read temperature from LM75 sensor
double read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_fd, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    double temp = raw_temp * 0.125; // Each bit is 0.125 degrees

    return temp;
}

// Update circular buffer with new temperature reading
void update_buffer(double temp) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Calculate running average of temperature readings
double calculate_average() {
    double sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    running_average = sum / BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
    return running_average;
}

// Control alert LED based on running average
void control_led(double avg_temp) {
    if (avg_temp > TEMP_THRESHOLD) {
        gpioWrite(ALERT_LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(ALERT_LED_GPIO, 0); // Turn LED off
    }
}

// LED control thread function
void *led_control_thread(void *arg) {
    led_data_t *data = (led_data_t *)arg;
    double avg_temp = data->running_average;

    while (program_running) {
        control_led(avg_temp);
        gpioDelay(100000); // 100ms delay
    }
    pthread_exit(NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(ALERT_LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_fd);
    gpioSetMode(ALERT_LED_GPIO, PI_INPUT); // Release GPIO
    pthread_mutex_destroy(&buffer_mutex);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO mode for alert LED
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create LED control thread
    pthread_t led_thread;
    led_data_t led_data;
    led_data.running_average = 0.0; // Initialize average
    if (pthread_create(&led_thread, NULL, led_control_thread, &led_data) != 0) {
        fprintf(stderr, "Failed to create LED control thread\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        double temp = read_temperature();
        if (temp > -999.0) { // Check for valid temperature reading
            update_buffer(temp);
            double avg_temp = calculate_average();
            led_data.running_average = avg_temp; // Update shared data for LED thread
            pthread_mutex_lock(&buffer_mutex);
            for (int i = 0; i < BUFFER_SIZE; i++) {
                printf("Buffer[%d]: %.2f\n", i, temperature_buffer[i]);
            }
            pthread_mutex_unlock(&buffer_mutex);
            printf("Temperature: %.2f, Average: %.2f\n", temp, avg_temp);
        } else {
            fprintf(stderr, "Failed to read temperature, attempting re-initialization...\n");
            i2cClose(i2c_fd);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                program_running = 0; // Exit loop if re-initialization fails
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Join LED control thread
    pthread_join(led_thread, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

