#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <cjson/cJSON.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define TARGET_TEMPERATURE 25.0 // Default target temperature
#define KP 1.0 // Default Kp
#define KI 0.1 // Default Ki
#define KD 0.01 // Default Kd
#define MAX_TEMPERATURE 80.0 // Failsafe temperature
#define LOG_FILE "heater.log"

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

// Global variables
int spi_handle;
double target_temperature = TARGET_TEMPERATURE;
double kp = KP;
double ki = KI;
double kd = KD;
double integral = 0.0;
double previous_error = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename);
double read_temperature();
double calculate_pid(double current_temperature);
void set_pwm_duty_cycle(int duty_cycle);
void log_message(const char *message);
void signal_handler(int signal);
void failsafe();

// Function to read configuration from JSON file
int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    cJSON *json = cJSON_ParseFP(fp, filename);
    if (json == NULL) {
        fprintf(stderr, "Error parsing JSON file: %s\n", cJSON_GetErrorPtr());
        fclose(fp);
        return -1;
    }

    cJSON *target_temp = cJSON_GetObjectItemCaseSensitive(json, "target_temperature");
    if (cJSON_IsNumber(target_temp)) {
        target_temperature = target_temp->valuedouble;
    }

    cJSON *kp_val = cJSON_GetObjectItemCaseSensitive(json, "kp");
    if (cJSON_IsNumber(kp_val)) {
        kp = kp_val->valuedouble;
    }

    cJSON *ki_val = cJSON_GetObjectItemCaseSensitive(json, "ki");
    if (cJSON_IsNumber(ki_val)) {
        ki = ki_val->valuedouble;
    }

    cJSON *kd_val = cJSON_GetObjectItemCaseSensitive(json, "kd");
    if (cJSON_IsNumber(kd_val)) {
        kd = kd_val->valuedouble;
    }

    fclose(fp);
    cJSON_Delete(json);
    return 0;
}

// Function to read temperature from MAX31865
double read_temperature() {
    unsigned char data[5];
    int rtd_raw;
    double rtd_resistance;
    double temperature;

    // Read RTD MSB and LSB
    data[0] = MAX31865_RTD_MSB_REG;
    if (spiXfer(spi_handle, data, data, 1) != 0) {
        log_message("Error reading RTD MSB");
        return -1000.0; // Indicate error
    }
    data[0] = MAX31865_RTD_LSB_REG;
    if (spiXfer(spi_handle, data, data, 1) != 0) {
        log_message("Error reading RTD LSB");
        return -1000.0; // Indicate error
    }

    rtd_raw = (data[0] << 8) | data[1];

    // Read Fault Register
    data[0] = MAX31865_FAULT_REG;
    if (spiXfer(spi_handle, data, data, 1) != 0) {
        log_message("Error reading Fault Register");
        return -1000.0; // Indicate error
    }

    // Check for faults
    if (data[0] != 0) {
        fprintf(stderr, "MAX31865 Fault: 0x%02X\n", data[0]);
        log_message("MAX31865 Fault detected");
        return -1000.0; // Indicate error
    }

    // Convert RTD raw value to resistance (PT100)
    rtd_resistance = ((double)rtd_raw / 32768.0) * 430.0; // 430 ohm reference resistor

    // Convert resistance to temperature (approximation)
    temperature = (rtd_resistance - 100.0) / 0.385; // PT100 approximation

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = kp * error + ki * integral + kd * derivative;
    previous_error = error;

    // Clamp the output to the range 0-1000
    if (output < 0) output = 0;
    if (output > 1000) output = 1000;

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Function to log messages to file
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, shutting down...");
    terminate = 1;
}

// Failsafe function
void failsafe() {
    log_message("Failsafe triggered!");
    set_pwm_duty_cycle(0);
    gpioTerminate();
    exit(1);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Read configuration from file
    if (read_config("config.json") != 0) {
        fprintf(stderr, "Failed to read configuration, using defaults\n");
    }

    // Configure PWM
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        log_message("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Configure MAX31865 (Mode 1, 500kHz)
    unsigned char config_data[2];
    config_data[0] = MAX31865_CONFIG_REG;
    config_data[1] = 0xC2; // VBIAS, Auto conversion, 50/60 Hz filter, 500kHz
    if (spiWrite(spi_handle, config_data, 2) != 0) {
        log_message("Failed to configure MAX31865");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Heater control started");

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();
        if (temperature < -999.0) {
            failsafe();
        }

        int pid_output = (int)calculate_pid(temperature);
        set_pwm_duty_cycle(pid_output);

        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Temperature: %.2f C, PID Output: %d", temperature, pid_output);
        log_message(log_buffer);

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    set_pwm_duty_cycle(0);
    spiClose(spi_handle);
    gpioTerminate();

    log_message("Heater control stopped");

    return 0;
}

