    double temperature;
    double pressure;
    struct timeval timestamp;
} Reading;

// Circular buffer structure
typedef struct {
    Reading buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
int i2c_handle;
