// Function to initialize the circular buffer
void initialize_circular_buffer() {
    reading_buffer.head = 0;
    reading_buffer.count = 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    uint8_t data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
