#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define HEATER_GPIO 17
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 0.8
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_max31855(int spi_handle, float *internal_temperature, float *thermocouple_temperature, int *fault);
float calculate_pi_control(float target_temperature, float current_temperature, float *integral, float dt);
void set_heater_duty_cycle(int gpio, float duty_cycle);
void log_data(float thermocouple_temperature, float internal_temperature, int fault, float duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// PI controller parameters
float Kp = 1.0;
float Ki = 0.1;
float integral = 0.0;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set heater GPIO as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Thermocouple Temperature (C),Internal Temperature (C),Fault,Duty Cycle (%)\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read data from MAX31855
int read_max31855(int spi_handle, float *internal_temperature, float *thermocouple_temperature, int *fault) {
    unsigned char data[4];
    int result = spiRead(spi_handle, data, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed\n");
        return 1; // Indicate error
    }

    // Check for fault bits
    *fault = (data[3] >> 6) & 0x01; // Open circuit
    *fault |= ((data[3] >> 5) & 0x01) << 1; // Short to ground
    *fault |= ((data[3] >> 4) & 0x01) << 2; // Short to VCC

    if (*fault) {
        fprintf(stderr, "MAX31855 fault detected\n");
        return 1; // Indicate error
    }

    // Extract thermocouple temperature
    int16_t thermocouple_raw = ((data[0] << 8) | data[1]) >> 2;
    *thermocouple_temperature = thermocouple_raw * 0.25;

    // Extract internal temperature
    int16_t internal_raw = ((data[2] << 8) | data[3]) >> 4;
    *internal_temperature = internal_raw * 0.0625;

    return 0; // Indicate success
}

// Function to calculate PI controller output
float calculate_pi_control(float target_temperature, float current_temperature, float *integral, float dt) {
    float error = target_temperature - current_temperature;
    *integral += error * dt;

    // Anti-windup
    if (*integral > 100) *integral = 100;
    if (*integral < -100) *integral = -100;

    float output = Kp * error + Ki * (*integral);

    return output;
}

// Function to set heater duty cycle
void set_heater_duty_cycle(int gpio, float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_value = (int)(duty_cycle * 255.0);
    gpioPWM(gpio, pwm_value);
}

// Function to log data
void log_data(float thermocouple_temperature, float internal_temperature, int fault, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%.2f\n", timestamp, thermocouple_temperature, internal_temperature, fault, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    // Turn off heater
    set_heater_duty_cycle(HEATER_GPIO, 0.0);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    float thermocouple_temperature, internal_temperature;
    int fault;
    float pi_output;
    float dt = 1.0; // Time step (1 second)
    float duty_cycle;

    if (initialize()) {
        return 1;
    }

    while (!terminate) {
        if (read_max31855(spi_handle, &internal_temperature, &thermocouple_temperature, &fault) == 0) {
            pi_output = calculate_pi_control(TARGET_TEMPERATURE, thermocouple_temperature, &integral, dt);
            duty_cycle = pi_output; // Assuming pi_output is the duty cycle
            set_heater_duty_cycle(HEATER_GPIO, duty_cycle);
            log_data(thermocouple_temperature, internal_temperature, fault, duty_cycle);
        } else {
            // Set duty cycle to 0% on error
            set_heater_duty_cycle(HEATER_GPIO, 0.0);
            log_data(thermocouple_temperature, internal_temperature, fault, 0.0);
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

