#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY 5 // seconds
#define JSON_BUFFER_SIZE 128

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to read DHT22 data
int read_dht22_data(DHT22Data *data) {
    int i, j;
    unsigned int data_buffer[5] = {0, 0, 0, 0, 0};
    unsigned int pulse_lengths[85];

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1 ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30 us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read response
    for (i = 0; i < 85; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1); // 1 us
            if (count > 200) {
                syslog(LOG_ERR, "DHT22 timeout");
                return -1;
            }
        }
        pulse_lengths[i] = count;
    }

    // Decode data
    for (i = 0; i < 40; i++) {
        int index = 2 * i + 1;
        data_buffer[i / 8] <<= 1;
        if (pulse_lengths[index] > 40) {
            data_buffer[i / 8] |= 1;
        }
    }

    // Validate checksum
    if (data_buffer[4] != ((data_buffer[0] + data_buffer[1] + data_buffer[2] + data_buffer[3]) & 0xFF)) {
        syslog(LOG_ERR, "DHT22 checksum error");
        return -1;
    }

    // Convert data
    data->humidity = (float)((data_buffer[0] << 8) + data_buffer[1]) / 10.0;
    data->temperature = (float)(((data_buffer[2] & 0x7F) << 8) + data_buffer[3]) / 10.0;
    if (data_buffer[2] & 0x80) {
        data->temperature *= -1;
    }

    return 0;
}

// Function to format data as JSON
int format_json(float temperature, float humidity, char *json_buffer, size_t buffer_size) {
    int ret = snprintf(json_buffer, buffer_size, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    if (ret < 0 || ret >= buffer_size) {
        syslog(LOG_ERR, "JSON formatting error");
        return -1;
    }
    return 0;
}

// Function to post data to server
int post_data(const char *url, const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main() {
    int retries;
    DHT22Data dht22_data;
    char json_buffer[JSON_BUFFER_SIZE];

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_dht22_data(&dht22_data) == 0) {
                if (format_json(dht22_data.temperature, dht22_data.humidity, json_buffer, JSON_BUFFER_SIZE) == 0) {
                    if (post_data("http://yourserver.com/api/humidity", json_buffer) != 0) {
                        syslog(LOG_ERR, "Failed to post data after %d retries", retries + 1);
                    } else {
                        syslog(LOG_INFO, "Data posted successfully");
                    }
                    break; // Exit retry loop on success
                } else {
                    syslog(LOG_ERR, "Failed to format JSON after %d retries", retries + 1);
                }
            } else {
                syslog(LOG_ERR, "Failed to read DHT22 data after %d retries", retries + 1);
            }
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(RETRY_DELAY);
            }
        }

        if (retries == MAX_RETRIES) {
            syslog(LOG_ERR, "Max retries reached, skipping this iteration");
        }

        sleep(60); // Wait 60 seconds
    }

    // Clean up
    gpioTerminate();
    closelog();

    return 0;
}

