#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Oversampling setting
#define OSS 3

// GPIO pin for push-button
#define BUTTON_GPIO 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000 // 200ms

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile unsigned int last_interrupt_time = 0;
static FILE *log_file = NULL;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temperature);
float calculate_pressure(int raw_pressure, float temperature);
void interrupt_handler(int gpio, int level, unsigned int tick, void *user);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char buf[22];
    int result = i2cReadI2CBlockData(i2c_handle, 0xAA, buf, 22);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int *raw_temperature) {
    char buf[2];
    char write_buf[2] = {BMP180_REG_CONTROL, 0x2E};
    int result;

    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing temperature conversion command: %d\n", result);
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms

    write_buf[0] = BMP180_REG_MSB;
