#include <pigpio.h>
#include <getopt.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2
#define READ_INTERVAL 10
#define JSON_BUFFER_SIZE 128

// Structure to hold DHT22 data
typedef struct {
    float humidity;
    float temperature;
} DHT22Data;

// Global variables
static char *url = "http://your-library-api.com/api/humidity";
static volatile int running = 1;

// Function prototypes
int read_dht22(DHT22Data *data);
int validate_checksum(unsigned char data[], int len);
int post_data(const char *json_data);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Logging function
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// DHT22 reading function
int read_dht22(DHT22Data *data) {
    int retries = 0;
    int result;
    unsigned char buf[5] = {0, 0, 0, 0, 0};
    unsigned char checksum;
    int i;

    while (retries < MAX_RETRIES) {
        // 1. Start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // > 1ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(0.00003); // 20-40us
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        // 2. Wait for response
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            if (timeout++ > 100) {
                log_message(LOG_ERR, "DHT22: Timeout waiting for response.");
                goto retry;
            }
            gpioDelay(0.0001); // 100us
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            if (timeout++ > 100) {
                log_message(LOG_ERR, "DHT22: Timeout waiting for response.");
                goto retry;
            }
            gpioDelay(0.0001); // 100us
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            if (timeout++ > 100) {
                log_message(LOG_ERR, "DHT22: Timeout waiting for response.");
                goto retry;
            }
            gpioDelay(0.0001); // 100us
        }

        // 3. Read data
        for (i = 0; i < 40; i++) {
            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 0) {
                if (timeout++ > 100) {
                    log_message(LOG_ERR, "DHT22: Timeout waiting for data bit.");
                    goto retry;
                }
                gpioDelay(0.0001); // 100us
            }

            long t = gpioTick();

            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 1) {
                if (timeout++ > 100) {
                    log_message(LOG_ERR, "DHT22: Timeout waiting for data bit.");
                    goto retry;
                }
                gpioDelay(0.0001); // 100us
            }

            long diff = gpioTick() - t;
            if (diff > 40) {
                buf[i / 8] |= (1 << (7 - (i % 8)));
            }
        }

        // 4. Read checksum
        gpioSetMode(DHT22_GPIO, PI_INPUT);
        gpioDelay(0.00003); // 20-40us
        checksum = gpioRead(DHT22_GPIO);
        gpioDelay(0.00003); // 20-40us

        // 5. Validate checksum
        if (validate_checksum(buf, 4) == 0) {
            // 6. Convert data
            data->humidity = (float)(((buf[0] << 8) | buf[1]) / 10.0);
            data->temperature = (float)((((buf[2] & 0x7F) << 8) | buf[3]) / 10.0);
            if (buf[2] & 0x80) {
                data->temperature *= -1;
            }
            return 0; // Success
        } else {
            log_message(LOG_ERR, "DHT22: Checksum validation failed.");
        }

        retry:
        retries++;
        if (retries < MAX_RETRIES) {
            log_message(LOG_WARNING, "DHT22: Retry attempt...");
            sleep(BACKOFF_DELAY * (1 << retries));
        } else {
            log_message(LOG_ERR, "DHT22: Max retries reached.");
            return -1; // Failure
        }
    }

    return -1; // Failure after all retries
}

// Checksum validation function
int validate_checksum(unsigned char data[], int len) {
    unsigned char checksum = data[len - 1];
    unsigned char calculated_checksum = 0;
    for (int i = 0; i < len - 1; i++) {
        calculated_checksum += data[i];
    }
    return (checksum == (calculated_checksum & 0xFF));
}

// POST data function
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    int retries = 0;
    struct curl_slist *headers = NULL;

    while (retries < MAX_RETRIES) {
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                log_message(LOG_ERR, curl_easy_strerror(res));
                curl_easy_cleanup(curl);
                curl_slist_free_all(headers);
                if (res == CURLE_HTTP_RETURNED_ERROR && (200 <= res && res < 300)) {
                    retries++;
                    log_message(LOG_WARNING, "HTTP POST failed, retrying...");
                    sleep(BACKOFF_DELAY * (1 << retries));
                } else {
                    log_message(LOG_ERR, "HTTP POST failed, giving up.");
                    curl_easy_cleanup(curl);
                    curl_slist_free_all(headers);
                    return -1;
                }
            } else {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    log_message(LOG_INFO, "HTTP POST successful.");
                    curl_easy_cleanup(curl);
                    curl_slist_free_all(headers);
                    return 0;
                } else {
                    log_message(LOG_ERR, "HTTP POST failed, giving up.");
                    curl_easy_cleanup(curl);
                    curl_slist_free_all(headers);
                    return -1;
                }
            }
        } else {
            log_message(LOG_ERR, "curl_easy_init() failed");
            return -1;
        }
    }
    return -1;
}

int main(int argc, char *argv[]) {
    int opt;
    DHT22Data dht22_data;
    char json_data[JSON_BUFFER_SIZE];

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "DHT22 monitor started.");

    // Main loop
    while (running) {
        if (read_dht22(&dht22_data) == 0) {
            // Format data as JSON
            snprintf(json_data, JSON_BUFFER_SIZE, "{\"humidity\": %.2f, \"temperature\": %.2f}", dht22_data.humidity, dht22_data.temperature);

            // Post data to server
            if (post_data(json_data) != 0) {
                log_message(LOG_ERR, "Failed to post data.");
            }
        } else {
            log_message(LOG_ERR, "Failed to read DHT22 sensor.");
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup
    gpioTerminate();
    closelog();

    return 0;
}

