#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

// Define constants
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Define temperature thresholds (in Celsius)
#define TEMP_THRESHOLD_1 45
#define TEMP_THRESHOLD_2 55
#define TEMP_THRESHOLD_3 65

// Define fan states
#define FAN_STATE_0 0
#define FAN_STATE_1 1
#define FAN_STATE_2 2
#define FAN_STATE_3 3

// Global variables
static volatile int keep_running = 1;
static int max_state = 0; // Maximum fan speed

// Function prototypes
int read_cpu_temp();
int read_fan_state();
int set_fan_state(int state);
int map_temp_to_state(int temp);
int log_event(const char *message);
void signal_handler(int sig);

// Function to read CPU temperature from file
int read_cpu_temp() {
    int fd, temp = -1;
    char buffer[10];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fd = open(TEMP_FILE, O_RDONLY);
        if (fd < 0) {
            log_event("Error opening temperature file");
            return -1;
        }

        if (read(fd, buffer, sizeof(buffer) - 1) < 0) {
            log_event("Error reading temperature file");
            close(fd);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        close(fd);
        buffer[sizeof(buffer) - 1] = '\0'; // Ensure null termination
        temp = atoi(buffer) / 1000; // Convert to Celsius
        return temp;
    }

    log_event("Failed to read temperature after multiple retries");
    return -1; // Indicate failure
}

// Function to read fan state from file
int read_fan_state() {
    int fd, state = -1;
    char buffer[10];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fd = open(FAN_FILE, O_RDONLY);
        if (fd < 0) {
            log_event("Error opening fan file");
            return -1;
        }

        if (read(fd, buffer, sizeof(buffer) - 1) < 0) {
            log_event("Error reading fan file");
            close(fd);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        close(fd);
        buffer[sizeof(buffer) - 1] = '\0'; // Ensure null termination
        state = atoi(buffer);
        return state;
    }

    log_event("Failed to read fan state after multiple retries");
    return -1; // Indicate failure
}

// Function to set fan state to file
int set_fan_state(int state) {
    int fd;
    char buffer[10];
    int retries = 0;

    if (state > max_state) {
        log_event("Invalid fan state. State exceeds maximum allowed.");
        return -1;
    }

    while (retries < MAX_RETRIES) {
        fd = open(FAN_FILE, O_WRONLY);
        if (fd < 0) {
            log_event("Error opening fan file for writing");
            return -1;
        }

        snprintf(buffer, sizeof(buffer), "%d", state);
        if (write(fd, buffer, strlen(buffer)) < 0) {
            log_event("Error writing fan state");
            close(fd);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        close(fd);
        return 0; // Success
    }

    log_event("Failed to write fan state after multiple retries");
    return -1; // Indicate failure
}

// Function to map temperature to fan state
int map_temp_to_state(int temp) {
    if (temp < TEMP_THRESHOLD_1) {
        return FAN_STATE_0;
    } else if (temp < TEMP_THRESHOLD_2) {
        return FAN_STATE_1;
    } else if (temp < TEMP_THRESHOLD_3) {
        return FAN_STATE_2;
    } else {
        return FAN_STATE_3;
    }
}

// Function to log events to file
int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal, shutting down...");
        set_fan_state(FAN_STATE_0); // Set fan to 0
        keep_running = 0;
        exit(0);
    }
}

int main() {
    int temp, fan_state, desired_state;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check if the log file exists and is writable
    if (access(LOG_FILE, W_OK) != 0) {
        fprintf(stderr, "Error: Could not write to log file. Check permissions.\n");
        return 1;
    }

    // Check if the cooling device's max_state is defined
    char max_state_path[100];
    snprintf(max_state_path, sizeof(max_state_path), "/sys/class/thermal/cooling_device0/max_state");
    int max_state_fd = open(max_state_path, O_RDONLY);
    if (max_state_fd < 0) {
        fprintf(stderr, "Error: Could not open max_state file. Check permissions.\n");
        return 1;
    }
    if (read(max_state_fd, &max_state, sizeof(max_state)) < 0) {
        fprintf(stderr, "Error: Could not read max_state file. Check permissions.\n");
        close(max_state_fd);
        return 1;
    }
    close(max_state_fd);

    if (max_state <= 0) {
        fprintf(stderr, "Error: Invalid max_state value. Check permissions.\n");
        return 1;
    }

    log_event("Fan control program started");

    while (keep_running) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp < 0) {
            log_event("Error reading CPU temperature, using previous value.");
            // Consider using a default temperature or previous valid reading here
            continue; // Skip to the next iteration
        }

        // Map temperature to desired fan state
        desired_state = map_temp_to_state(temp);

        // Check if the desired state is different from the current state
        fan_state = read_fan_state();
        if (fan_state < 0) {
            log_event("Error reading fan state, using previous value.");
            // Consider using a default fan state or previous valid reading here
            continue; // Skip to the next iteration
        }

        if (desired_state != fan_state) {
            // Set the fan state
            if (set_fan_state(desired_state) == 0) {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Fan state changed to %d (Temperature: %d°C, Desired State: %d)", desired_state, temp, desired_state);
                log_event(log_message);
            } else {
                log_event("Error setting fan state.");
            }
        }

        // Wait for 5 seconds
        sleep(5);
    }

    log_event("Fan control program stopped");

    return 0;
}

