#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define PWM_FREQUENCY 1000 // 1 kHz
#define LOG_INTERVAL 1 // seconds

// PID Gains
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold PID state
typedef struct {
    float integral;
    float previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function Prototypes
float read_temperature();
void set_heater_pwm(int duty_cycle);
float calculate_pid(float setpoint, float actual_temperature, float *previous_error, float *integral, PIDState *pid_state);
void log_data(float temperature, int duty_cycle, float pid_output);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int i;
    float temperature = -1000.0; // Initialize to an invalid value
    int fault;

    if (spiRead(spi_handle, data, 4) != 4) {
        fprintf(stderr, "Error reading SPI data\n");
        return -1000.0;
    }

    // Extract fault bits
    fault = (data[3] >> 6) & 0x07;

    // Check for fault conditions
    if (fault) {
        switch (fault) {
            case 0x01: // Open circuit
                fprintf(stderr, "MAX31855 Fault: Open circuit\n");
                break;
            case 0x02: // Short to GND
                fprintf(stderr, "MAX31855 Fault: Short to GND\n");
