FILE *log_file = NULL;

// Function prototypes
float get_cpu_temperature();
int set_pwm_duty_cycle(int duty_cycle);
int log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Function to get CPU temperature from /sys/class/thermal/thermal_zone0/temp
float get_cpu_temperature() {
    FILE *fp;
    int temp_milli_celsius;
    float temp_celsius;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
