        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli_celsius / 1000.0;
    return temp_celsius;
}

// Function to set PWM duty cycle using pigpio
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle.\n");
        return -1; // Indicate error
    }
    return 0;
}

