    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Get CPU temperature
        temperature = get_cpu_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error: Could not get CPU temperature.\n");
            // Continue to the next iteration even if temperature reading fails
        } else {
            // Map temperature to duty cycle
            if (temperature <= TEMP_LOW) {
                duty_cycle = DUTY_LOW;
            } else if (temperature >= TEMP_HIGH) {
                duty_cycle = DUTY_HIGH;
            } else {
                duty_cycle = DUTY_LOW + (int)(((temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW)) * (DUTY_HIGH - DUTY_LOW));
            }

            // Set PWM duty cycle
            if (set_pwm_duty_cycle(duty_cycle) != 0) {
                fprintf(stderr, "Error: Failed to set PWM duty cycle.\n");
            }

            // Log data
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }

            printf("Temperature: %.2f C, Duty Cycle: %d%%\n", temperature, duty_cycle);
        }

        sleep(5);
    }

    // Turn off the fan
    set_pwm_duty_cycle(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cooling system stopped.\n");

    return 0;
}

