#include <pigpio.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define I2C bus
#define I2C_BUS 1

// Define retry count
#define RETRY_COUNT 3

// Define CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C handles
int i2c_handle1 = -1;
int i2c_handle2 = -1;

// Function prototypes
int read_sensor(int i2c_handle, unsigned char *data);
int validate_checksum(unsigned char *data);
int log_data(unsigned char *data1, unsigned char *data2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from the sensor
int read_sensor(int i2c_handle, unsigned char *data) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result == 3) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d attempts.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to validate the checksum
int validate_checksum(unsigned char *data) {
    unsigned char crc = 0xFF;
    unsigned char data_bytes[2] = {data[0], data[1]};

    for (int i = 0; i < 2; i++) {
        crc ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != data[2]) {
        fprintf(stderr, "Checksum validation failed!\n");
        return -1;
    }
    return 0;
}

// Function to log the data to a file
int log_data(unsigned char *data1, unsigned char *data2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

