#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Define the number of pulses per revolution (360 degrees)
#define PULSES_PER_REVOLUTION 360

// Global variables
volatile int current_state = 0; // Current state of the quadrature state machine
volatile int pulse_count = 0;   // Number of pulses detected
volatile double angular_position = 0.00; // Normalized angular position in degrees
FILE *log_file = NULL;             // File pointer for the log file

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_position(double position);
void encoder_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Structure to hold the last tick for debouncing
typedef struct {
    uint32_t last_tick_a;
    uint32_t last_tick_b;
} encoder_state_t;

encoder_state_t encoder_state;

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Configure GPIO17 as an input with pull-up resistor
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);

    // Configure GPIO18 as an input with pull-up resistor
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Set up interrupt handlers for both sensors
    if (gpioSetISRFuncEx(SENSOR_A_GPIO, RISING_EDGE, 0, encoder_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for sensor A\n");
        cleanup_gpio();
        return -1;
    }

    if (gpioSetISRFuncEx(SENSOR_B_GPIO, RISING_EDGE, 0, encoder_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for sensor B\n");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to clean up the GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

// Function to log the current angular position to a file
void log_position(double position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, position);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Interrupt handler function for both sensors
void encoder_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    static int last_gpio = -1; // Store the last GPIO that triggered the interrupt

    if (gpio != last_gpio) {
        // Debouncing: Check if the time between the current and last interrupt is less than 1ms
        if (tick - encoder_state.last_tick_a > 1000 || tick - encoder_state.last_tick_b > 1000) {
            encoder_state.last_tick_a = tick;
            encoder_state.last_tick_b = tick;

            switch (gpio) {
                case SENSOR_A_GPIO:
                    switch (current_state) {
                        case 0:
                            current_state = 1;
                            break;
                        case 2:
                            current_state = 3;
                            break;
                    }
                    break;
                case SENSOR_B_GPIO:
                    switch (current_state) {
                        case 0:
                            current_state = 2;
                            break;
                        case 1:
                            current_state = 0;
                            break;
                    }
                    break;
            }

            // Update pulse count based on the new state
            if (current_state == 1) {
                pulse_count++;
            } else if (current_state == 3) {
                pulse_count--;
            }

            // Calculate angular position
            angular_position = (double)pulse_count * 360.0 / PULSES_PER_REVOLUTION;

            // Log the position
            log_position(angular_position);
        }
        last_gpio = gpio;
    }
}

// Signal handler function for SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

int main() {
    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() < 0) {
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until a signal is received)
    while (1) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

