    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.red, &sensor_data.ir) == 0) {
            // Log the data
            log_data(sensor_data.red, sensor_data.ir);

            // Control the LED
            control_led(sensor_data.ir);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize the pigpio library, I2C, GPIO, and log file
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,red,ir\n");
    }
    rewind(log_file);

    return 0;
}

// Read red and infrared data from the ADPD144RI sensor
int read_sensor_data(int *red, int *ir) {
    char buf[4];
    int result;

    // Read red data
    result = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read red data: %d\n", result);
        return 1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read IR data
    result = i2cReadI2CBlockData(i2c_handle, IR_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read IR data: %d\n", result);
        return 1;
    }
    *ir = (buf[1] << 8) | buf[0];

    return 0;
}

// Log the timestamp, red, and IR data to the CSV file
void log_data(int red, int ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control the LED based on the IR value
void control_led(int ir_value) {
    if (ir_value > IR_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    // Close I2C device
    i2cClose(i2c_handle);

    // Turn off LED
    gpioWrite(GPIO_LED, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

