#include <string.h>

#define AUDIO_GPIO 17
#define GAIN_GPIO 18
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.txt"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log the timestamp and level to a file
void log_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s %d\n", timestamp, level);
    fclose(fp);
}

// Function to detect rising edges on the audio GPIO
int detect_rising_edge() {
    int current_level = gpioRead(AUDIO_GPIO);
    gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    int new_level = gpioRead(AUDIO_GPIO);

    if (current_level == 0 && new_level == 1) {
        return 1; // Rising edge detected
    } else {
        return 0; // No rising edge detected
    }
}

