    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(AUDIO_GPIO, PI_INPUT);

    // Set GPIO18 as output and set to LOW for 60dB gain
    gpioSetMode(GAIN_GPIO, PI_OUTPUT);
    gpioWrite(GAIN_GPIO, 0); // Set to LOW

    // Print startup message
    printf("Audio event detection started. Logging to %s\n", LOG_FILE);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (detect_rising_edge()) {
            log_event(1);
            printf("Rising edge detected and logged.\n");
        }
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

