int validate_crc(const char *data, int length, uint8_t crc);
float convert_to_flow_rate(uint16_t raw_value);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

