int open_i2c_connection(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Writes a command to the I2C device
int write_i2c_command(int handle, uint16_t command) {
    char buffer[2];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buffer, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Reads data from the I2C device
int read_i2c_data(int handle, char *buffer, int count) {
