// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float calculate_iaq(uint16_t tvoc, uint16_t eco2);
int log_data(float iaq, uint16_t tvoc, uint16_t eco2);
void signal_handler(int signal);
