// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->tvoc = (buf[0] << 8) | buf[1];
    data->eco2 = (buf[2] << 8) | buf[3];

    return 0;
}

// Calculate IAQ index (example formula)
float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    // Simple linear mapping for demonstration purposes
    float iaq = (float)tvoc / 100.0 + (float)eco2 / 500.0;
    return iaq;
}

// Log data to CSV file
int log_data(float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
int cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    float iaq;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);
            printf("IAQ: %.2f, TVOC: %u ppb, eCO2: %u ppm\n", iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", READ_INTERVAL_SEC);
        }
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

