#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>

#define GPIO_PIN 17 // BCM GPIO 17, physical pin 11
#define POLLING_INTERVAL_MS 100
#define TAMPER_THRESHOLD_SEC 5

volatile sig_atomic_t program_running = 1;
volatile unsigned long last_interrupt_time = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(GPIO_PIN, INPUT);
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    int value = digitalRead(GPIO_PIN);
    if (value == -1) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to log the intrusion event
void log_intrusion() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Intrusion detected at: %s\n", timestamp);
}

// Function to reset the timer
void reset_timer() {
    last_interrupt_time = 0;
}

int main() {
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO pin
    if (initialize_gpio() == -1) {
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value == -1) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        unsigned long current_time = millis();

        if (sensor_value == HIGH) {
            if (last_interrupt_time == 0) {
                last_interrupt_time = current_time;
            }

            if (current_time - last_interrupt_time >= TAMPER_THRESHOLD_SEC * 1000) {
                log_intrusion();
                reset_timer();
            }
        } else {
            reset_timer();
        }

        delay(POLLING_INTERVAL_MS);
    }

    // Cleanup and exit
    printf("Cleaning up and exiting.\n");
    return EXIT_SUCCESS;
}

