#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define FORMAT SND_PCM_FORMAT_S16_LE
#define PERIOD_SIZE 1024
#define NUM_PERIODS 4
#define CAPTURE_DURATION 10 // seconds

// Global variables
snd_pcm_t *pcm_handle;
FILE *audio_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold ALSA configuration
typedef struct {
    snd_pcm_t *pcm_handle;
    snd_pcm_hw_params_t *hw_params;
} alsa_config_t;

// Signal handler for graceful termination
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize ALSA
int init_alsa(alsa_config_t *config) {
    int rc;
    snd_pcm_hw_params_t *hw_params = snd_pcm_hw_params_malloc();
    if (!hw_params) {
        fprintf(stderr, "Error: Unable to allocate hardware parameters structure.\n");
        return -1;
    }

    rc = snd_pcm_open(&config->pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error: Unable to open PCM device: %s\n", snd_strerror(rc));
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    rc = snd_pcm_hw_params_any(config->pcm_handle, hw_params);
    if (rc < 0) {
        fprintf(stderr, "Error: Unable to set hardware parameters: %s\n", snd_strerror(rc));
        snd_pcm_close(config->pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    rc = snd_pcm_hw_params_set_access(config->pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "Error: Unable to set access type: %s\n", snd_strerror(rc));
        snd_pcm_close(config->pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

