    if (rc < 0) {
        fprintf(stderr, "Error: Unable to set sample format: %s\n", snd_strerror(rc));
        snd_pcm_close(config->pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    rc = snd_pcm_hw_params_set_channels(config->pcm_handle, hw_params, NUM_CHANNELS);
    if (rc < 0) {
        fprintf(stderr, "Error: Unable to set channel count: %s\n", snd_strerror(rc));
        snd_pcm_close(config->pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    rc = snd_pcm_hw_params_set_rate_near(config->pcm_handle, hw_params, &rate, 0);
    if (rc < 0) {
        fprintf(stderr, "Error: Unable to set sample rate: %s\n", snd_strerror(rc));
        snd_pcm_close(config->pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    rc = snd_pcm_hw_params_set_period_size(config->pcm_handle, hw_params, PERIOD_SIZE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error: Unable to set period size: %s\n", snd_strerror(rc));
        snd_pcm_close(config->pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    rc = snd_pcm_hw_params_set_periods(config->pcm_handle, hw_params, NUM_PERIODS, 0);
    if (rc < 0) {
