}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initially set to left channel
    return 0;
}

// Function to write audio data to file
int write_audio_data(const short *buffer, int frames) {
    size_t bytes_written = fwrite(buffer, sizeof(short), frames, audio_file);
    if (bytes_written != frames) {
        fprintf(stderr, "Error: Failed to write all data to file\n");
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup(alsa_config_t *config) {
    if (config->pcm_handle) {
        snd_pcm_drain(config->pcm_handle);
        snd_pcm_close(config->pcm_handle);
    }
    if (audio_file) {
        fclose(audio_file);
    }
    gpioTerminate();
}

int main() {
    alsa_config_t alsa_config;
    short *buffer;
    int rc;
    int frames_to_read = PERIOD_SIZE * NUM_PERIODS; // Number of frames to read at a time
    int total_frames = SAMPLE_RATE * CAPTURE_DURATION; // Total number of frames to capture

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize ALSA
    if (init_alsa(&alsa_config) != 0) {
        fprintf(stderr, "Error: ALSA initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        cleanup(&alsa_config);
        return 1;
    }

    // Allocate buffer for audio data
    buffer = (short *)malloc(frames_to_read * sizeof(short));
    if (!buffer) {
        fprintf(stderr, "Error: Failed to allocate buffer\n");
        cleanup(&alsa_config);
        return 1;
    }

    // Open audio file for writing
    audio_file = fopen("audio_capture.pcm", "wb");
    if (!audio_file) {
        fprintf(stderr, "Error: Failed to open audio file\n");
        free(buffer);
        cleanup(&alsa_config);
        return 1;
    }

    // Capture audio data
    printf("Capturing audio for %d seconds...\n", CAPTURE_DURATION);
    for (int i = 0; i < total_frames && !terminate; ++i) {
        rc = snd_pcm_readi(alsa_config.pcm_handle, buffer, frames_to_read);
        if (rc == -EPIPE) {
            fprintf(stderr, "Error: Overrun occurred\n");
            snd_pcm_prepare(alsa_config.pcm_handle);
        } else if (rc < 0) {
            fprintf(stderr, "Error: Unable to read audio data: %s\n", snd_strerror(rc));
            break;
        } else if (rc != frames_to_read) {
            fprintf(stderr, "Error: Short read, read %d frames instead of %d\n", rc, frames_to_read);
        } else {
            // Toggle GPIO pin for channel selection
            gpioWrite(GPIO_PIN, i % 2); // 0 for left, 1 for right
            gpioDelay(1); // Small delay to ensure the signal is stable

            // Write audio data to file
            if (write_audio_data(buffer, rc) != 0) {
                break;
            }
        }
    }

    // Cleanup resources
    printf("Cleaning up resources...\n");
    free(buffer);
    cleanup(&alsa_config);

    printf("Audio capture complete.\n");
    return 0;
}

