#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 100
#define PWM_DUTY_CYCLE 128 // 50% duty cycle (0-255)

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void start_fan_pwm();
void stop_fan_pwm();
void log_event(const char *event_type);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    int pwm_started;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    state.gpio_initialized = 1;

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("System Start");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) {
            // Flame detected
            if (!state.pwm_started) {
                start_fan_pwm();
                state.pwm_started = 1;
                log_event("Flame Detected");
            }
        } else {
            // No flame detected
            if (state.pwm_started) {
                stop_fan_pwm();
                state.pwm_started = 0;
            }
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup
    stop_fan_pwm();
    if (state.gpio_initialized) {
        gpioTerminate();
    }
    if (log_file != NULL) {
        log_event("System Shutdown");
        fclose(log_file);
    }

    return 0;
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(FAN_PWM_PIN, 255);

    return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int count = 0;
    int last_value = 1; // Initialize to no flame (HIGH)

    // Read the sensor multiple times for debouncing
    for (int i = 0; i < 5; i++) {
        int value = gpioRead(FLAME_SENSOR_PIN);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", FLAME_SENSOR_PIN, value);
            return -1; // Indicate error
        }
        if (value == 0) {
            last_value = 0; // Flame detected
            break;
        }
        gpioDelay(DEBOUNCE_TIME / 5); // Divide debounce time for multiple reads
        count++;
    }

    return last_value;
}

// Function to start the fan PWM
void start_fan_pwm() {
    gpioPWM(FAN_PWM_PIN, PWM_DUTY_CYCLE);
}

// Function to stop the fan PWM
void stop_fan_pwm() {
    gpioPWM(FAN_PWM_PIN, 0);
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

