#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FRAME_TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define HEATMAP_SIZE 32768 // 32KB
#define NUM_CHIRPS 64
#define NUM_SAMPLES 256
#define START_FREQUENCY 77000000000.0 // 77 GHz
#define END_FREQUENCY 79000000000.0   // 79 GHz
#define FRAME_PERIOD_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    double start_frequency;
    double end_frequency;
    int num_chirps;
    int num_samples;
} radar_config_t;

// Function prototypes
int initialize();
int configure_radar(radar_config_t config);
int capture_frame(uint8_t *heatmap_data);
int log_frame(uint8_t *heatmap_data, struct timespec timestamp, int frame_number);
void data_ready_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Callback function for data ready interrupt
void data_ready_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        uint8_t *heatmap_data = (uint8_t *)malloc(HEATMAP_SIZE);
        if (heatmap_data == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for heatmap data\n");
            return;
        }

        struct timespec timestamp;
        if (clock_gettime(CLOCK_REALTIME, &timestamp) == -1) {
            perror("clock_gettime");
            free(heatmap_data);
            return;
        }

        int frame_number = 0; // Assuming frame number increments with each valid frame
        if (capture_frame(heatmap_data) == 0) {
            if (log_frame(heatmap_data, timestamp, frame_number) != 0) {
                fprintf(stderr, "Error: Failed to log frame\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to capture frame\n");
        }

        free(heatmap_data);
    }
}

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FRAME_TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN); // Pull down to avoid floating

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    log_file = fopen("radar_data.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header to log file
    uint32_t magic_number = 0x4144;
    fwrite(&magic_number, sizeof(uint32_t), 1, log_file);
    fwrite(&START_FREQUENCY, sizeof(double), 1, log_file);
    fwrite(&END_FREQUENCY, sizeof(double), 1, log_file);
    fwrite(&NUM_CHIRPS, sizeof(int), 1, log_file);
    fwrite(&NUM_SAMPLES, sizeof(int), 1, log_file);

    return 0;
}

// Function to configure the radar sensor (dummy implementation)
int configure_radar(radar_config_t config) {
    // In a real implementation, this function would send configuration commands
    // to the radar sensor via SPI.
    printf("Configuring radar with start frequency: %.2f GHz, end frequency: %.2f GHz, num chirps: %d, num samples: %d\n",
           config.start_frequency / 1000000000.0, config.end_frequency / 1000000000.0, config.num_chirps, config.num_samples);
    return 0;
}

// Function to capture a frame from the radar sensor
int capture_frame(uint8_t *heatmap_data) {
    // Perform SPI transfer to read heatmap data
    int bytes_read = spiRead(spi_handle, heatmap_data, HEATMAP_SIZE);
    if (bytes_read != HEATMAP_SIZE) {
        fprintf(stderr, "Error: SPI read failed (read %d bytes, expected %d)\n", bytes_read, HEATMAP_SIZE);
        return -1;
    }
    return 0;
}

// Function to log a frame to the binary file
int log_frame(uint8_t *heatmap_data, struct timespec timestamp, int frame_number) {
    // Write timestamp and frame number to the log file
    fwrite(&timestamp, sizeof(struct timespec), 1, log_file);
    fwrite(&frame_number, sizeof(int), 1, log_file);
    fwrite(heatmap_data, HEATMAP_SIZE, 1, log_file);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        return 1;
    }

    // Configure the radar sensor
    radar_config_t radar_config = {
        .start_frequency = START_FREQUENCY,
        .end_frequency = END_FREQUENCY,
        .num_chirps = NUM_CHIRPS,
        .num_samples = NUM_SAMPLES
    };
    if (configure_radar(radar_config) != 0) {
        fprintf(stderr, "Error: Radar configuration failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on data ready pin
    if (gpioSetISRFuncEx(DATA_READY_PIN, RISING_EDGE, 0, data_ready_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set up interrupt\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Do other tasks here, if needed
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up and exit
    gpioSetISRFuncEx(DATA_READY_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Radar data acquisition terminated.\n");
    return 0;
}

