#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/flame_detection.log"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int value = gpioRead(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        } else {
            if (value == 0) {
                if (log_message("Flame Detected: YES") != 0) {
                    fprintf(stderr, "Failed to log message.\n");
                }
            } else {
                if (log_message("Flame Detected: NO") != 0) {
                    fprintf(stderr, "Failed to log message.\n");
                }
            }
        }
        gpioDelay(1000); // 1 second delay
    }

    gpioTerminate();
    return 0;
}

