#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensor outputs
#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    int left_value, center_value, right_value;
    int result;

    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register SIGINT handler.\n");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register SIGTERM handler.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins as inputs
    result = gpioSetMode(LEFT_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input. Error code: %d\n", LEFT_PIN, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(CENTER_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input. Error code: %d\n", CENTER_PIN, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(RIGHT_PIN, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input. Error code: %d\n", RIGHT_PIN, result);
        gpioTerminate();
        return 1;
    }

    // Main loop to read sensor data
    while (!terminate) {
        // Read the current state of each GPIO pin
        left_value = gpioRead(LEFT_PIN);
        center_value = gpioRead(CENTER_PIN);
        right_value = gpioRead(RIGHT_PIN);

        // Print the sensor data to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated successfully.\n");

    return 0;
}

