        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read the state of all channels
int read_all_channels(int *channel_states) {
    for (int i = 0; i < num_channels; i++) {
        int state = gpioRead(gpio_pins[i]);
        if (state < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pins[i], state);
            return -1; // Indicate an error
        }
        channel_states[i] = state;
    }
    return 0; // Indicate success
}

// Function to log the channel states with a timestamp
void log_channel_states(int *channel_states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s ", timestamp);

    for (int i = 0; i < num_channels; i++) {
        printf("%d", channel_states[i]);
        if (i < num_channels - 1) {
            printf(" ");
        }
    }
    printf("\n");
}

