#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 sensor outputs
const int sensor_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to control the main loop
volatile sig_atomic_t running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN); // Enable pull-down resistor
    }
    return 0;
}

// Function to read the sensor data
int read_sensor_data(int *data) {
    for (int i = 0; i < num_channels; i++) {
        data[i] = gpioRead(sensor_pins[i]);
    }
    return 0;
}

// Function to print the sensor data with a timestamp
void print_sensor_data(int *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] ", timestamp);

    for (int i = 0; i < num_channels; i++) {
        printf("CH%d=%d", i + 1, data[i]);
        if (i < num_channels - 1) {
            printf(" ");
        }
    }
    printf("\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int sensor_data[num_channels];

    // Main loop
    while (running) {
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            print_sensor_data(sensor_data);
        }

        gpioDelay(100000); // 100ms delay
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

