    while (program_running) {
        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp\n");
            break;
        }

        // Read the sensor channels
        int *channel_states = read_sensor_channels();
        if (channel_states == NULL) {
            fprintf(stderr, "Failed to read sensor channels\n");
