#define TILT_SENSOR_GPIO 7 // BCM pin 7

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    gpioTerminate();
    exit(0);
}

int main() {
    int tilt_state = -1; // Initialize to an invalid state
    int current_state;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Print startup banner
    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        current_state = gpioRead(TILT_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", TILT_SENSOR_GPIO);
            gpioTerminate();
            return 1;
        }

        if (current_state != tilt_state) {
            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            tilt_state = current_state;
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

