#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02

#define REG_UCOEF0 0x13
#define REG_UCOEF1 0x14
#define REG_UCOEF2 0x15
#define REG_UCOEF3 0x16

#define REG_PARAM_WR 0x17
#define REG_COMMAND 0x18
#define REG_HW_KEY 0x07

#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_ALS_IR_DATA0 0x24
#define REG_ALS_IR_DATA1 0x25
#define REG_UVINDEX0 0x2C
#define REG_UVINDEX1 0x2D

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float uv_index;
    uint16_t als_visible;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_sensor_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, REG_UCOEF0, 0x7B) < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF0: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_UCOEF1, 0x67) < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF1: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_UCOEF2, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF2: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_UCOEF3, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF3: %s\n", strerror(errno));
        return -1;
    }

    // Enable ALS force mode
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to enable ALS force mode: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint8_t buffer[4];

    // Read ALS Visible data
    if (i2cReadI2CBlockData(i2c_handle, REG_ALS_VIS_DATA0, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Error reading ALS Visible data: %s\n", strerror(errno));
        data.als_visible = 0; // Set to 0 on error
    } else {
        data.als_visible = (buffer[1] << 8) | buffer[0];
    }

    // Read UV Index data
    if (i2cReadI2CBlockData(i2c_handle, REG_UVINDEX0, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Error reading UV Index data: %s\n", strerror(errno));
        data.uv_index = 0.0; // Set to 0.0 on error
    } else {
        data.uv_index = (float)((buffer[1] << 8) | buffer[0]) / 100.0; // UV Index is stored as a value * 100
    }

    return data;
}

// Function to log sensor data to a CSV file
void log_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, data.uv_index, data.als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV Index,ALS Visible\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_sensor_data(data);
        printf("UV Index: %.2f, ALS Visible: %u\n", data.uv_index, data.als_visible);
        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

