#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_LOG_FILE "flow_log.txt"
#define START_COMMAND 0x3066
#define MEASUREMENT_COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int start_sensor(int i2c_handle);
int read_flow_rate(int i2c_handle, float *flow_rate);
unsigned char crc8(const unsigned char *data, int len);
void log_error(const char *message);
float calculate_average_flow(float flow1, float flow2);
void set_alarm(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Starts the sensor
int start_sensor(int i2c_handle) {
    char buf[2];
    buf[0] = (START_COMMAND >> 8) & 0xFF;
    buf[1] = START_COMMAND & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to start sensor");
        return -1;
    }
    return 0;
}

// Reads the flow rate from the sensor
int read_flow_rate(int i2c_handle, float *flow_rate) {
    char buf[2];
    buf[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    buf[1] = MEASUREMENT_COMMAND & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send measurement command");
        return -1;
    }

    gpioDelay(100); // Wait for measurement (adjust as needed)

    char data[3];
    result = i2cReadDevice(i2c_handle, data, 3);
    if (result != 3) {
        log_error("Failed to read flow rate");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2]) {
        log_error("CRC validation failed");
        return -1;
    }

    // Convert raw data to flow rate (example conversion, adjust as needed)
    int16_t raw_flow = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_flow / 100.0; // Example scaling factor

    return 0;
}

// Calculates the CRC8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Logs an error message to the log file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    perror(message); // Also print to stderr
}

// Calculates the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Sets the alarm GPIO pin
void set_alarm(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

