    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set alarm GPIO pin as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float flow1, flow2, avg_flow;
    while (!terminate) {
        // Start sensors
        if (start_sensor(i2c_handle1) != 0) {
            log_error("Failed to start sensor 1");
        }
        if (start_sensor(i2c_handle2) != 0) {
            log_error("Failed to start sensor 2");
        }

        gpioDelay(100); // Wait for sensors to be ready

        // Read flow rates
        if (read_flow_rate(i2c_handle1, &flow1) != 0) {
            flow1 = 0.0; // Set to 0 to avoid affecting average
        }
        if (read_flow_rate(i2c_handle2, &flow2) != 0) {
            flow2 = 0.0; // Set to 0 to avoid affecting average
        }

        // Calculate average flow rate
        avg_flow = calculate_average_flow(flow1, flow2);

        // Log data
        fprintf(log_file, "Flow 1: %.2f ml/min, Flow 2: %.2f ml/min, Average: %.2f ml/min\n", flow1, flow2, avg_flow);
        fflush(log_file);

        // Control alarm
        if (avg_flow < 0.5) {
            set_alarm(ALARM_GPIO, 1); // Activate alarm
        } else {
            set_alarm(ALARM_GPIO, 0); // Deactivate alarm
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    set_alarm(ALARM_GPIO, 0); // Ensure alarm is off on exit
    gpioTerminate();

    return 0;
}

