#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 50

// Structure to hold the timestamp and sensor value
typedef struct {
    time_t timestamp;
    int value;
} SensorData;

// Circular buffer
SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int value);
void dump_buffer();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            add_to_buffer(sensor_value);
            printf("Obstacle detected!\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 50ms
    }

    // Dump the buffer before exiting
    dump_buffer();

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize the pigpio library and configure GPIO4
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT); // Set GPIO4 as input
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add a new entry to the circular buffer
void add_to_buffer(int value) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].value = value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to dump the contents of the circular buffer to stdout
void dump_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = circular_buffer[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char time_str[64];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Value: %d\n", time_str, circular_buffer[i].value);
    }
    printf("--- End of Log ---\n");
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("SIGINT received. Exiting gracefully...\n");
        program_running = 0;
    }
}

