#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define SDA_PIN 2
#define SCL_PIN 3
#define SAMPLE_INTERVAL_MS 500
#define MAX_ACTIVE_TIME_S 1
#define CSV_FILENAME "fan_health.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int set_sensor_mode(int mode);
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
int write_csv_header();
int write_csv_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);
char* iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Get ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Set sensor mode
int set_sensor_mode(int mode) {
    char buf[1];
    buf[0] = mode;
    int result = i2cWriteDevice(i2c_fd, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result = i2cReadDevice(i2c_fd, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Write CSV header
int write_csv_header() {
    csv_file = fopen(CSV_FILENAME, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file for writing\n");
        return -1;
    }

    fprintf(csv_file, "Timestamp,X,Y,Z\n");
    fflush(csv_file);
    return 0;
}

// Write CSV data
int write_csv_data(int16_t x, int16_t y, int16_t z) {
    char *timestamp = iso8601_timestamp();
    if (csv_file == NULL) {
        fprintf(stderr, "CSV file not opened\n");
        free(timestamp);
        return -1;
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file);
    free(timestamp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
