#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define SDA_PIN 2
#define SCL_PIN 3
#define SAMPLE_INTERVAL_MS 500
#define MAX_ACTIVE_TIME_S 1
#define CSV_FILENAME "fan_health.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int set_sensor_mode(int mode);
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
int write_csv_header();
int write_csv_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);
char* iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Get ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

