#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18

// Define the stall duration (2 seconds in milliseconds)
#define STALL_DURATION 2000

// Define the log file name
#define LOG_FILE "stall_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
} SensorData;

// Function prototypes
int initialize_gpio();
SensorData read_sensors();
int is_stall_confirmed(SensorData data);
int log_stall();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    return 0;
}

// Function to read the sensor values
SensorData read_sensors() {
    SensorData data;
    data.sensor1_value = gpioRead(SENSOR1_PIN);
    data.sensor2_value = gpioRead(SENSOR2_PIN);
    return data;
}

// Function to check if a stall is confirmed
int is_stall_confirmed(SensorData data) {
    return (data.sensor1_value == 0 && data.sensor2_value == 0);
}

// Function to log a stall event to the file
int log_stall() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the log file exists. If not, create it and add a header.
    if (access(LOG_FILE, F_OK) == -1) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file for writing");
            return 1;
        }
        fprintf(log_file, "Timestamp,Sensor1,Sensor2\n");
    } else {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file for appending");
            return 1;
        }
    }

    fprintf(log_file, "%s,0,0\n", timestamp);
    fclose(log_file);
    return 0;
}

// Function to clean up resources before exiting
void cleanup() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        SensorData sensor_data = read_sensors();

        if (is_stall_confirmed(sensor_data)) {
            printf("Stall confirmed!\n");
            if (log_stall() != 0) {
                fprintf(stderr, "Error logging stall event.\n");
            }
        }

        gpioDelay(10); // Delay to avoid excessive CPU usage
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

