#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TMAG5170 I2C address
#define TMAG5170_ADDR 0x08

// TMAG5170 register addresses
#define TMAG5170_REG_X_AXIS 0x01
#define TMAG5170_REG_Y_AXIS 0x03
#define TMAG5170_REG_Z_AXIS 0x05
#define TMAG5170_REG_CONFIG 0x0F

// Configuration values
#define TMAG5170_CONTINUOUS_MODE 0x00 // Continuous conversion mode
#define TMAG5170_RANGE_50MT 0x00      // 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
sensor_data_t read_sensor_data();
char* get_iso8601_timestamp();
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0); // I2C bus 1, address 0x08, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Sensor configuration function
int configure_sensor() {
    char buf[2];
    buf[0] = TMAG5170_REG_CONFIG;
    buf[1] = TMAG5170_CONTINUOUS_MODE | (TMAG5170_RANGE_50MT << 1); // Combine mode and range

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[1];
    char read_buf[6];

    // Read X axis
    buf[0] = TMAG5170_REG_X_AXIS;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to X axis register: %d\n", result);
        data.x = 0; // Set to 0 to avoid garbage values
    } else {
        result = i2cReadDevice(i2c_handle, read_buf, 2);
        if (result != 0) {
            fprintf(stderr, "Failed to read X axis data: %d\n", result);
            data.x = 0;
        } else {
            data.x = (int16_t)((read_buf[0] << 8) | read_buf[1]);
        }
    }

    // Read Y axis
    buf[0] = TMAG5170_REG_Y_AXIS;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to Y axis register: %d\n", result);
        data.y = 0;
    } else {
        result = i2cReadDevice(i2c_handle, read_buf, 2);
        if (result != 0) {
            fprintf(stderr, "Failed to read Y axis data: %d\n", result);
            data.y = 0;
        } else {
            data.y = (int16_t)((read_buf[0] << 8) | read_buf[1]);
        }
    }

    // Read Z axis
    buf[0] = TMAG5170_REG_Z_AXIS;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to Z axis register: %d\n", result);
        data.z = 0;
    } else {
        result = i2cReadDevice(i2c_handle, read_buf, 2);
        if (result != 0) {
            fprintf(stderr, "Failed to read Z axis data: %d\n", result);
            data.z = 0;
        } else {
            data.z = (int16_t)((read_buf[0] << 8) | read_buf[1]);
        }
    }

    return data;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log data to CSV file
int log_data(sensor_data_t data) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);    // Free the allocated memory

