#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <errno.h>

// Configuration
#define SENSOR_PIN 4 // BCM GPIO 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_WINDOW_MS 1000 // 1 second
#define DEBOUNCE_DELAY_US 500 // 0.5 ms

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
int running = 1;
FILE *log_file = NULL;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int pulse_count, int sample_window_ms);
int log_rpm(double rpm);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt handler for rising edge detection
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
    gpioDelay(DEBOUNCE_DELAY_US); // Debounce
}

// Function to calculate RPM
double calculate_rpm(int pulse_count, int sample_window_ms) {
    return (double)pulse_count * 60000.0 / sample_window_ms;
}

// Function to log RPM to file
int log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    pthread_mutex_lock(&pulse_mutex);
    int current_pulse_count = pulse_count;
    pthread_mutex_unlock(&pulse_mutex);

    if (log_file != NULL) {
        fprintf(log_file, "%s %.2f\n", timestamp, rpm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    printf("%s %.2f\n", timestamp, rpm);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // unused
    running = 0;
    printf("Caught signal, exiting gracefully...\n");
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return -1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPI initialisation failed\n");
        gpioTerminate();
        return -1;
    }

    // Configure sensor pin as input with pull-up
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(SENSOR_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioSetISRFuncEx(SENSOR_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Reset pulse count
        pthread_mutex_lock(&pulse_mutex);
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        // Wait for sample window
        usleep(SAMPLE_WINDOW_MS * 1000); // Convert ms to us

        // Calculate RPM
        double rpm = calculate_rpm(pulse_count, SAMPLE_WINDOW_MS);

        // Log RPM
        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Failed to log RPM\n");
        }

        // Read SPI data and log
        unsigned char spi_data[2];
        wiringPiSPIDataRW(SPI_CHANNEL, spi_data, 2);
        int adc_value = (spi_data[0] << 8) | spi_data[1];
        printf("ADC Value: %d\n", adc_value);

    }

    // Cleanup and exit
    cleanup();
    return 0;
}

