#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_PIN 23
#define LED_PIN 18

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor();
int control_led(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sensor_pin;
    int led_pin;
} gpio_config_t;

// Global GPIO configuration
gpio_config_t gpio_config = {SENSOR_PIN, LED_PIN};

int main() {
    // Open syslog for logging
    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    log_event("Program started");

    // Main loop
    int last_state = 0; // Store the last sensor state
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1 && last_state == 0) {
            // Touch detected
            log_event("Touch detected");
            control_led(1); // Turn LED on
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            last_state = 1;
        } else if (sensor_value == 0 && last_state == 1) {
            // Touch released
            log_event("Touch released");
            control_led(0); // Turn LED off
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            last_state = 0;
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // Cleanup
    log_event("Program exiting");
    control_led(0); // Turn LED off
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog

    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(gpio_config.sensor_pin, PI_INPUT);
    gpioSetMode(gpio_config.led_pin, PI_OUTPUT);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(gpio_config.sensor_pin);
}

// Function to control the LED
int control_led(int state) {
    return gpioWrite(gpio_config.led_pin, state);
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", buf, message);
    syslog(LOG_INFO, "%s", log_message);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, exiting...");
}

