#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Set LED to LOW initially

    return 0;
}

// Function to detect touch with debouncing
int detect_touch() {
    int touch_detected = 0;
    int last_state = gpioRead(TOUCH_SENSOR_PIN);

    if (last_state == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO %d\n", TOUCH_SENSOR_PIN);
        return 0; // Or handle the error appropriately
    }

    if (gpioSetAlertFunc(TOUCH_SENSOR_PIN, touch_callback) != 0) {
        fprintf(stderr, "Error setting alert function for GPIO %d\n", TOUCH_SENSOR_PIN);
        return 0; // Or handle the error appropriately
    }

    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce

    return touch_detected;
}

// Callback function for rising edge detection
void touch_callback(int gpio, int level, uint32_t tick) {
    if (gpio == TOUCH_SENSOR_PIN && level == 1) {
        // Toggle the LED
        int current_led_state = gpioRead(LED_PIN);
        gpioWrite(LED_PIN, !current_led_state);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor application started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        detect_touch();
        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup
    gpioTerminate();
    fprintf(stderr, "GPIO resources released.\n");

    return 0;
}

