#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN 27
#define LED2_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 100

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Structure to store log events
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} log_event_t;

// Circular buffer structure
typedef struct {
    log_event_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow_count;
} circular_buffer_t;

// Global variables
static volatile int running = 1;
static circular_buffer_t log_buffer;

// Function prototypes
int init_gpio();
int read_sensor(int pin);
int write_led(int pin, int state);
void add_to_buffer(circular_buffer_t *buffer, int sensor_pin, time_t timestamp, int state);
int get_from_buffer(circular_buffer_t *buffer, log_event_t *event);
void print_buffer(circular_buffer_t *buffer);
void signal_handler(int signal);
void cleanup();

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Write LED value
int write_led(int pin, int state) {
    gpioWrite(pin, state);
    return 0;
}

// Add event to circular buffer
void add_to_buffer(circular_buffer_t *buffer, int sensor_pin, time_t timestamp, int state) {
    buffer->buffer[buffer->head].sensor_pin = sensor_pin;
    buffer->buffer[buffer->head].timestamp = timestamp;
    buffer->buffer[buffer->head].state = state;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->overflow_count++;
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE; // Advance tail to overwrite oldest
    } else {
        buffer->count++;
    }
}

// Get event from circular buffer
int get_from_buffer(circular_buffer_t *buffer, log_event_t *event) {
    if (buffer->count == 0) {
        return 1; // Buffer is empty
    }

    *event = buffer->buffer[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    buffer->count--;
    return 0;
}

// Print circular buffer contents
void print_buffer(circular_buffer_t *buffer) {
    printf("Log Buffer Contents:\n");
    log_event_t event;
    int i = 0;
    while (get_from_buffer(buffer, &event) == 0) {
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&event.timestamp));
        printf("[%d] Sensor: %d, Timestamp: %s, State: %d\n", i++, event.sensor_pin, timestamp_str, event.state);
    }
    printf("Overflow Count: %d\n", buffer->overflow_count);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
