    return gpioRead(pin);
}

// Write LED value
int write_led(int pin, int state) {
    gpioWrite(pin, state);
    return 0;
}

// Add event to circular buffer
void add_to_buffer(circular_buffer_t *buffer, int sensor_pin, time_t timestamp, int state) {
    buffer->buffer[buffer->head].sensor_pin = sensor_pin;
    buffer->buffer[buffer->head].timestamp = timestamp;
    buffer->buffer[buffer->head].state = state;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->overflow_count++;
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE; // Advance tail to overwrite oldest
    } else {
        buffer->count++;
    }
}

// Get event from circular buffer
int get_from_buffer(circular_buffer_t *buffer, log_event_t *event) {
    if (buffer->count == 0) {
        return 1; // Buffer is empty
    }

    *event = buffer->buffer[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    buffer->count--;
    return 0;
}

