#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
volatile unsigned long last_interrupt_time1 = 0;
volatile unsigned long last_interrupt_time2 = 0;
volatile int sensor1_state = 0; // 0: LOW, 1: HIGH
volatile int sensor2_state = 0; // 0: LOW, 1: HIGH
FILE *log_file = NULL;

// Function prototypes
void sensor1_interrupt(void);
void sensor2_interrupt(void);
double calculate_rpm(unsigned long time_difference_us);
void log_data(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Interrupt routine for sensor 1
void sensor1_interrupt(void) {
    unsigned long current_time = micros();
    if (current_time - last_interrupt_time1 > DEBOUNCE_TIME * 1000) {
        sensor1_state = digitalRead(SENSOR1_PIN);
        last_interrupt_time1 = current_time;
    }
}

// Interrupt routine for sensor 2
void sensor2_interrupt(void) {
    unsigned long current_time = micros();
    if (current_time - last_interrupt_time2 > DEBOUNCE_TIME * 1000) {
        sensor2_state = digitalRead(SENSOR2_PIN);
        last_interrupt_time2 = current_time;
    }
}

// Function to calculate RPM
double calculate_rpm(unsigned long time_difference_us) {
    // Assuming one pulse per revolution
    return 60000000.0 / time_difference_us; // Convert microseconds to seconds
}

// Function to log data to a CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    // Reset GPIO pins to input mode (safer)
    pinMode(SENSOR1_PIN, INPUT);
    pinMode(SENSOR2_PIN, INPUT);

    exit(0);
}

int main(void) {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as input with pull-up resistors
    pinMode(SENSOR1_PIN, INPUT);
    pullUpDnControl(SENSOR1_PIN, PUD_UP);
    pinMode(SENSOR2_PIN, INPUT);
    pullUpDnControl(SENSOR2_PIN, PUD_UP);

    // Attach interrupt routines to the GPIO pins
    if (wiringPiISR(SENSOR1_PIN, INT_EDGE_BOTH, sensor1_interrupt) < 0) {
        fprintf(stderr, "Error setting up ISR for sensor 1: %s\n", strerror(errno));
        return 1;
    }
    if (wiringPiISR(SENSOR2_PIN, INT_EDGE_BOTH, sensor2_interrupt) < 0) {
        fprintf(stderr, "Error setting up ISR for sensor 2: %s\n", strerror(errno));
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned long last_time = 0;
    unsigned long current_time;
    double rpm;
    int prev_sensor1_state = 0;
    int prev_sensor2_state = 0;

    printf("Monitoring shaft RPM... Press Ctrl+C to exit.\n");

    while (1) {
        delay(10); // Small delay to avoid busy-waiting

        // Read sensor states
        sensor1_state = digitalRead(SENSOR1_PIN);
        sensor2_state = digitalRead(SENSOR2_PIN);

        // Log data
        log_data(sensor1_state, sensor2_state);

        // Calculate RPM
        current_time = micros();
        if (last_time != 0) {
            unsigned long time_difference_us = current_time - last_time;
            rpm = calculate_rpm(time_difference_us);
            printf("RPM: %.2f\n", rpm);
        }
        last_time = current_time;

        // Debounce and handle state changes
        if (sensor1_state != prev_sensor1_state) {
            last_interrupt_time1 = micros();
        }
        if (sensor2_state != prev_sensor2_state) {
            last_interrupt_time2 = micros();
        }

        prev_sensor1_state = sensor1_state;
        prev_sensor2_state = sensor2_state;
    }

    return 0;
}

