#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define POLLING_INTERVAL_MS 100
#define ALARM_DURATION_S 5
#define TILT_THRESHOLD_S 2

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(const char *event_type, int sensor1_value, int sensor2_value);
void activate_alarm();
void deactivate_alarm();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor state
typedef struct {
    int sensor1_state;
    int sensor2_state;
    time_t alarm_start_time;
} SensorState;

SensorState sensor_state = {0, 0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Log sensor readings
        log_event("sensor_read", sensor1_value, sensor2_value);

        // Check for alarm conditions
        if (sensor1_value == 1 || sensor2_value == 1) {
            if (sensor_state.sensor1_state == 0 && sensor_state.sensor2_state == 0) {
                // Tilt start
                log_event("tilt_start", sensor1_value, sensor2_value);
                activate_alarm();
                sensor_state.alarm_start_time = time(NULL);
            } else if (sensor_state.sensor1_state == 1 && sensor_state.sensor2_state == 1) {
                // Threshold exceeded
                log_event("threshold_exceeded", sensor1_value, sensor2_value);
            }
        } else {
            // Tilt end
            log_event("tilt_end", sensor1_value, sensor2_value);
            deactivate_alarm();
        }

        // Check for alarm duration
        if (sensor_state.alarm_start_time != 0) {
            time_t current_time = time(NULL);
            if (difftime(current_time, sensor_state.alarm_start_time) >= ALARM_DURATION_S) {
                deactivate_alarm();
                sensor_state.alarm_start_time = 0; // Reset alarm start time
            }
        }

        // Wait for the next polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);

    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Initialize alarm to LOW

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Log event to file
int log_event(const char *event_type, int sensor1_value, int sensor2_value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - Sensor1: %d, Sensor2: %d\n", buf, event_type, sensor1_value, sensor2_value);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }
}

// Activate alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set alarm pin HIGH
}

// Deactivate alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0); // Set alarm pin LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    deactivate_alarm();

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

