#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define ALERT_LED_PIN 17
#define THRESHOLD 500.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_RATE_MS 100
#define LED_ON_DURATION_MS 1000

// Sensor Registers (Example - adjust based on D7S-A0011 datasheet)
#define CTRL1_REG 0x10
#define X_AXIS_LSB_REG 0x20
#define Y_AXIS_LSB_REG 0x22
#define Z_AXIS_LSB_REG 0x24

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
double calculate_magnitude(sensor_data_t data);
void log_event(double magnitude);
void trigger_alert();
void signal_handler(int signal);
char* iso8601_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize the sensor
int initialize_sensor() {
    // Example: Clear power-down bit in CTRL1 register (adjust based on datasheet)
    char buf[2];
    buf[0] = CTRL1_REG;
    buf[1] = 0x00; // Example value to clear power-down bit

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to CTRL1 register: %s\n", strerror(errno));
        return -1;
    }

    // Add more initialization steps as needed based on the sensor datasheet
    return 0;
}

// Function to read sensor data with retries
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[1];
    char read_buf[6]; // 2 bytes per axis (X, Y, Z)
    int result;

    // Read X axis
    buf[0] = X_AXIS_LSB_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to X_AXIS_LSB_REG: %s\n", strerror(errno));
        data.x = 0; // Set to 0 to avoid using uninitialized data
    } else {
        result = i2cReadDevice(i2c_handle, read_buf, 2);
        if (result != 0) {
            fprintf(stderr, "Error reading X axis data: %s\n", strerror(errno));
            data.x = 0; // Set to 0 to avoid using uninitialized data
        } else {
            data.x = (int16_t)((read_buf[1] << 8) | read_buf[0]);
        }
    }

    // Read Y axis
    buf[0] = Y_AXIS_LSB_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to Y_AXIS_LSB_REG: %s\n", strerror(errno));
        data.y = 0; // Set to 0 to avoid using uninitialized data
    } else {
        result = i2cReadDevice(i2c_handle, read_buf, 2);
        if (result != 0) {
            fprintf(stderr, "Error reading Y axis data: %s\n", strerror(errno));
            data.y = 0; // Set to 0 to avoid using uninitialized data
        } else {
            data.y = (int16_t)((read_buf[1] << 8) | read_buf[0]);
        }
    }

    // Read Z axis
    buf[0] = Z_AXIS_LSB_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to Z_AXIS_LSB_REG: %s\n", strerror(errno));
        data.z = 0; // Set to 0 to avoid using uninitialized data
    } else {
        result = i2cReadDevice(i2c_handle, read_buf, 2);
        if (result != 0) {
            fprintf(stderr, "Error reading Z axis data: %s\n", strerror(errno));
            data.z = 0; // Set to 0 to avoid using uninitialized data
        } else {
            data.z = (int16_t)((read_buf[1] << 8) | read_buf[0]);
        }
    }

    return data;
}

// Function to calculate Euclidean vibration magnitude
double calculate_magnitude(sensor_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to log an event to the log file
void log_event(double magnitude) {
    char* timestamp = iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, magnitude);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    free(timestamp);
}

// Function to trigger the alert (turn on LED)
void trigger_alert() {
    gpioWrite(ALERT_LED_PIN, 1); // Turn on LED
    gpioDelay(LED_ON_DURATION_MS); // Wait for specified duration
    gpioWrite(ALERT_LED_PIN, 0); // Turn off LED
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for the alert LED
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);
    gpioWrite(ALERT_LED_PIN, 0); // Ensure LED is off initially

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, 0x50, 0); // Assuming default I2C address 0x50
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sensor_data_t sensor_data = read_sensor_data();
        double magnitude = calculate_magnitude(sensor_data);

        if (magnitude > THRESHOLD) {
            printf("Earthquake-like event detected! Magnitude: %.2f\n", magnitude);
            log_event(magnitude);
            trigger_alert();
        }

        gpioDelay(SAMPLE_RATE_MS); // Delay for specified sample rate
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(ALERT_LED_PIN, 0); // Turn off LED before exiting
    gpioTerminate();

    return 0;
}

