#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/file.h>

// Define GPIO pins for the flame sensors
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Define the log file path
#define LOG_FILE "/var/log/flame_events.log"

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Structure to hold sensor data
typedef struct {
    int pin;
    struct gpiod_line *line;
    int id;
} sensor_t;

// Global array to store sensor data
sensor_t sensors[5];

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor(int pin);
int debounce_sensor(int pin);
int log_event(int sensor_id);
void cleanup_gpio(void);
void signal_handler(int sig);
int acquire_line(struct gpiod_chip *chip, int pin);
int release_line(struct gpiod_chip *chip, int pin);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize the GPIO chip and acquire lines
int initialize_gpio(void) {
    struct gpiod_chip *chip;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Initialize sensor data
    sensors[0].pin = GPIO_2;
    sensors[0].id = 1;
    sensors[1].pin = GPIO_3;
    sensors[1].id = 2;
    sensors[2].pin = GPIO_4;
    sensors[2].id = 3;
    sensors[3].pin = GPIO_17;
    sensors[3].id = 4;
    sensors[4].pin = GPIO_27;
    sensors[4].id = 5;

    // Acquire lines for each sensor
    for (int i = 0; i < 5; i++) {
        sensors[i].line = acquire_line(chip, sensors[i].pin);
        if (!sensors[i].line) {
            syslog(LOG_ERR, "Failed to acquire line for GPIO %d", sensors[i].pin);
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                release_line(chip, sensors[j].pin);
            }
            gpiod_chip_close(chip);
            return -1;
        }
    }

    syslog(LOG_INFO, "GPIO initialized successfully.");
    return 0;
}

// Function to acquire a GPIO line
int acquire_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line for GPIO %d: %s", pin, strerror(errno));
        return NULL;
    }

    int ret = gpiod_line_request(line, "flame_monitor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request line for GPIO %d: %s", pin, strerror(errno));
        gpiod_line_release(line);
        return NULL;
    }

    return line;
}

// Function to release a GPIO line
int release_line(struct gpiod_chip *chip, int pin) {
    if (sensors[pin - 2].line) {
        gpiod_line_release(sensors[pin - 2].line);
        sensors[pin - 2].line = NULL;
    }
    return 0;
}

// Function to read the sensor value
int read_sensor(int pin) {
    struct gpiod_line *line = sensors[pin - 2].line;
    if (!line) {
        syslog(LOG_ERR, "Line not acquired for GPIO %d", pin);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read value from GPIO %d: %s", pin, strerror(errno));
        return -1;
    }

    return value;
}

// Function to debounce the sensor
int debounce_sensor(int pin) {
    struct gpiod_line *line = sensors[pin - 2].line;
    if (!line) {
        syslog(LOG_ERR, "Line not acquired for GPIO %d", pin);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read value from GPIO %d: %s", pin, strerror(errno));
        return -1;
    }

    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = DEBOUNCE_TIME_MS * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&delay, NULL);

    int debounced_value = gpiod_line_get_value(line);
    if (debounced_value < 0) {
        syslog(LOG_ERR, "Failed to read value from GPIO %d: %s", pin, strerror(errno));
        return -1;
    }

    return (debounced_value == 0) ? 1 : 0; // Return 1 if LOW, 0 if HIGH
}

// Function to log the event
int log_event(int sensor_id) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return -1;
    }

    // Acquire exclusive lock
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, sensor_id);
    fflush(fp);

    // Release lock
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file: %s", strerror(errno));
    }

    fclose(fp);
    return 0;
}

// Function to cleanup the GPIO chip and release lines
void cleanup_gpio(void) {
    syslog(LOG_INFO, "Cleaning up GPIO...");

    // Release lines for each sensor
    for (int i = 0; i < 5; i++) {
        release_line(NULL, sensors[i].pin); // Pass NULL for chip, as it's not needed here
    }

    // Close the GPIO chip
    //gpiod_chip_close(chip); // chip is not defined here, it's only defined in initialize_gpio

    syslog(LOG_INFO, "GPIO cleanup complete.");
}

int main(void) {
    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting...");
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 5; i++) {
            int pin = sensors[i].pin;
            int value = read_sensor(pin);

            if (value < 0) {
                syslog(LOG_ERR, "Failed to read sensor on GPIO %d", pin);
                continue; // Continue to the next sensor
            }

            if (value == 0) { // Flame detected (LOW signal)
                if (debounce_sensor(pin) == 1) { // Debounce confirmed LOW
                    syslog(LOG_INFO, "Flame detected on GPIO %d", pin);
                    if (log_event(sensors[i].id) != 0) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d", sensors[i].id);
                    }
                }
            }
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close syslog
    closelog();

    return 0;
}

