                continue; // Continue to the next sensor
            }

            if (value == 0) { // Flame detected (LOW signal)
                if (debounce_sensor(pin) == 1) { // Debounce confirmed LOW
                    syslog(LOG_INFO, "Flame detected on GPIO %d", pin);
                    if (log_event(sensors[i].id) != 0) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d", sensors[i].id);
                    }
                }
            }
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close syslog
    closelog();

    return 0;
}

