// Define the GPIO pins for the TTP226 sensor
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log a touch event to the console
void log_touch_event(int sensor_index, int pin, int touch_state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
        return;
    }

    printf("%s Sensor %d (GPIO %d): %s\n", timestamp, sensor_index, pin, touch_state ? "Touched" : "Released");
    free(timestamp); // Free the allocated memory
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN); // Enable pull-down resistor
    }

    return 0;
}

// Function to read the touch states from the sensor pins
int read_touch_states(int *touch_states) {
    for (int i = 0; i < num_channels; i++) {
        int state = gpioRead(sensor_pins[i]);
        if (state < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", sensor_pins[i], strerror(errno));
            return -1; // Indicate an error
        }
        touch_states[i] = state;
    }
    return 0; // Indicate success
}

int main() {
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to install signal handler");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int previous_touch_states[8] = {0}; // Initialize previous states

    // Main loop
    while (!terminate) {
        int touch_states[8];

        // Read the current touch states
        if (read_touch_states(touch_states) != 0) {
            fprintf(stderr, "Error reading touch states, exiting.\n");
            break; // Exit the loop on error
        }

        // Check for state changes and log them
        for (int i = 0; i < num_channels; i++) {
            if (touch_states[i] != previous_touch_states[i]) {
                log_touch_event(i, sensor_pins[i], touch_states[i]);
                previous_touch_states[i] = touch_states[i];
            }
        }

        gpioDelay(50000); // Delay for 50ms
    }

    // Clean up GPIO resources
    gpioTerminate();

    return 0;
}

