#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_DATA_REG 0x04
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_pwm();
int read_veml7700(int *lux);
int map_lux_to_brightness(int lux);
int set_led_brightness(int brightness);
int log_data(int lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize PWM
int init_pwm() {
    if (gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        return -1;
    }
    if (gpioSetPWMrange(GPIO_LED, 100) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        return -1;
    }
    return 0;
}

// Read lux value from VEML7700
int read_veml7700(int *lux) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_DATA_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    uint16_t raw_value = (buf[1] << 8) | buf[0];
    *lux = (int)raw_value; // VEML7700 returns big-endian
    return 0;
}

// Map lux value to brightness level
int map_lux_to_brightness(int lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set LED brightness using PWM
int set_led_brightness(int brightness) {
    if (gpioPWM(GPIO_LED, brightness) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(int lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Lux: %d, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_veml7700(&lux) == 0) {
            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            if (set_led_brightness(brightness) != 0) {
                log_data(lux, 0, -2); // Error setting brightness
            } else {
                // Log data
                log_data(lux, brightness, 0);
            }
        } else {
            // Log error
            log_data(0, 0, -1); // Error reading lux
        }

        // Wait 1 second
        sleep(1);
    }

    // Cleanup
    set_led_brightness(0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

