#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for touch sensor channels
#define TOUCH_CHANNEL_1 2
#define TOUCH_CHANNEL_2 3
#define TOUCH_CHANNEL_3 4
#define TOUCH_CHANNEL_4 5
#define TOUCH_CHANNEL_5 6
#define TOUCH_CHANNEL_6 7
#define TOUCH_CHANNEL_7 8
#define TOUCH_CHANNEL_8 9

// Define GPIO pin for alert LED
#define ALERT_LED 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_channel(int channel);
int debounce_channel(int channel, int *last_state);
int log_touch_event(int channel);
void control_alert_led(int all_channels_released);
void signal_handler(int signal);
int setup();
void cleanup();

// Structure to hold the last state of each channel
struct {
    int channel1;
    int channel2;
    int channel3;
    int channel4;
    int channel5;
    int channel6;
    int channel7;
    int channel8;
} last_states = {0, 0, 0, 0, 0, 0, 0, 0};

int main() {
    if (setup() != 0) {
        fprintf(stderr, "Setup failed. Exiting.\n");
        return 1;
    }

    while (running) {
        // Read touch sensor channels
        int channel1_state = read_touch_channel(TOUCH_CHANNEL_1);
        int channel2_state = read_touch_channel(TOUCH_CHANNEL_2);
        int channel3_state = read_touch_channel(TOUCH_CHANNEL_3);
        int channel4_state = read_touch_channel(TOUCH_CHANNEL_4);
        int channel5_state = read_touch_channel(TOUCH_CHANNEL_5);
        int channel6_state = read_touch_channel(TOUCH_CHANNEL_6);
        int channel7_state = read_touch_channel(TOUCH_CHANNEL_7);
        int channel8_state = read_touch_channel(TOUCH_CHANNEL_8);

        // Debounce channels
        debounce_channel(TOUCH_CHANNEL_1, &last_states.channel1);
        debounce_channel(TOUCH_CHANNEL_2, &last_states.channel2);
        debounce_channel(TOUCH_CHANNEL_3, &last_states.channel3);
        debounce_channel(TOUCH_CHANNEL_4, &last_states.channel4);
        debounce_channel(TOUCH_CHANNEL_5, &last_states.channel5);
        debounce_channel(TOUCH_CHANNEL_6, &last_states.channel6);
        debounce_channel(TOUCH_CHANNEL_7, &last_states.channel7);
        debounce_channel(TOUCH_CHANNEL_8, &last_states.channel8);

        // Check if all channels are released
        int all_channels_released = (channel1_state == 0 && last_states.channel1 == 0 &&
                                     channel2_state == 0 && last_states.channel2 == 0 &&
                                     channel3_state == 0 && last_states.channel3 == 0 &&
                                     channel4_state == 0 && last_states.channel4 == 0 &&
                                     channel5_state == 0 && last_states.channel5 == 0 &&
                                     channel6_state == 0 && last_states.channel6 == 0 &&
                                     channel7_state == 0 && last_states.channel7 == 0 &&
                                     channel8_state == 0 && last_states.channel8 == 0);

        // Control alert LED
        control_alert_led(all_channels_released);

        // Small delay
        gpioDelay(50); // 50ms delay
    }

    cleanup();
    return 0;
}

int setup() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins for touch sensor channels as inputs with pull-down resistors
    gpioSetMode(TOUCH_CHANNEL_1, PI_INPUT);
    gpioSetPullUpDown(TOUCH_CHANNEL_1, PI_PUD_DOWN);
    gpioSetMode(TOUCH_CHANNEL_2, PI_INPUT);
    gpioSetPullUpDown(TOUCH_CHANNEL_2, PI_PUD_DOWN);
    gpioSetMode(TOUCH_CHANNEL_3, PI_INPUT);
    gpioSetPullUpDown(TOUCH_CHANNEL_3, PI_PUD_DOWN);
    gpioSetMode(TOUCH_CHANNEL_4, PI_INPUT);
    gpioSetPullUpDown(TOUCH_CHANNEL_4, PI_PUD_DOWN);
    gpioSetMode(TOUCH_CHANNEL_5, PI_INPUT);
    gpioSetPullUpDown(TOUCH_CHANNEL_5, PI_PUD_DOWN);
    gpioSetMode(TOUCH_CHANNEL_6, PI_INPUT);
    gpioSetPullUpDown(TOUCH_CHANNEL_6, PI_PUD_DOWN);
    gpioSetMode(TOUCH_CHANNEL_7, PI_INPUT);
    gpioSetPullUpDown(TOUCH_CHANNEL_7, PI_PUD_DOWN);
    gpioSetMode(TOUCH_CHANNEL_8, PI_INPUT);
    gpioSetPullUpDown(TOUCH_CHANNEL_8, PI_PUD_DOWN);

    // Set GPIO pin for alert LED as output
    gpioSetMode(ALERT_LED, PI_OUTPUT);

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

void cleanup() {
    // Turn off alert LED
    gpioWrite(ALERT_LED, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

int initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

int read_touch_channel(int channel) {
    return gpioRead(channel);
}

int debounce_channel(int channel, int *last_state) {
    int current_state = gpioRead(channel);
    if (current_state != *last_state) {
        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce time in microseconds
        if (gpioRead(channel) == current_state) {
            *last_state = current_state;
            return current_state;
        }
    }
    return *last_state;
}

int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s – Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

void control_alert_led(int all_channels_released) {
    static int led_state = 0; // Keep track of the LED state

    if (all_channels_released && led_state == 0) {
        gpioWrite(ALERT_LED, 1); // Turn LED on
        led_state = 1;
