#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE_FACTOR 0.01
#define SLEEP_DURATION_US 1000000 // 1 second

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int configure_opt3001();
int read_opt3001(float *lux_value);
char *format_data(float lux_value);
int write_to_log(const char *data);
void signal_handler(int signal);

// Structure to hold configuration data (optional)
typedef struct {
    int i2c_bus;
    int opt3001_address;
    const char *log_file_name;
} config_t;

config_t config = {I2C_BUS, OPT3001_ADDR, "light_data.txt"};

int main() {
    float lux_value;
    char *data_string;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001() != 0) {
        fprintf(stderr, "OPT3001 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read OPT3001 data
        if (read_opt3001(&lux_value) == 0) {
            // Format data
            data_string = format_data(lux_value);

            // Write to log file
            if (write_to_log(data_string) != 0) {
                fprintf(stderr, "Failed to write to log file\n");
            }

            // Print to stdout
            printf("%s\n", data_string);

            free(data_string); // Free allocated memory
        } else {
            fprintf(stderr, "Failed to read OPT3001 data\n");
        }

        // Sleep for 1 second
        usleep(SLEEP_DURATION_US);
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.opt3001_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure OPT3001
int configure_opt3001() {
    uint16_t config_value = 0x8000; // Continuous conversion mode, 800ms conversion time
    char buf[3];

    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to write to configuration register\n");
        return 1;
    }

    gpioDelay(100000); // Wait 100ms
    return 0;
}

// Read OPT3001 data
int read_opt3001(float *lux_value) {
    char buf[2];
    uint16_t raw_result;
    int result;

    buf[0] = RESULT_REG;

    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to result register: %d\n", result);
        return 1;
    }

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from result register: %d\n", result);
        return 1;
    }

    // Byte swap the result
    raw_result = (buf[0] << 8) | buf[1];

    // Convert to lux
    *lux_value = (float)raw_result * LUX_SCALE_FACTOR;

    return 0;
}

// Format data
char *format_data(float lux_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0
    static char data_string[50]; // Static to keep memory valid after function returns

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(data_string, sizeof(data_string), "%s, %.2f", timestamp, lux_value);

    return data_string;
}

// Write to log file
int write_to_log(const char *data) {
    if (fprintf(log_file, "%s\n", data) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return 1;
    }
    fflush(log_file); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

