#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17

// Define log file name
#define LOG_FILE "fire_events.log"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int set_alert_pin(int state);
int log_event(const char *message);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int flame_sensor_pin;
    int alert_pin;
} gpio_config_t;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value >= 0) {
        return value;
    } else {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate an error
    }
}

// Function to set the alert pin
int set_alert_pin(int state) {
    int result = gpioWrite(ALERT_PIN, state);
    if (result == 0) {
        return 0;
    } else {
        fprintf(stderr, "Error writing to alert pin: %d\n", result);
        return 1; // Indicate an error
    }
}

// Function to log an event to the log file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) { // Flame detected (LOW signal)
            printf("Flame detected!\n");
            log_event("Flame detected!");

            if (set_alert_pin(1) == 0) { // Set alert pin HIGH
                gpioDelay(1000); // Wait for 1 second
                set_alert_pin(0); // Set alert pin LOW
            }
        } else if (sensor_value > 0) {
            // No flame detected
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    printf("Cleaning up...\n");

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Reset GPIO pins to LOW
    set_alert_pin(0);

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

