#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDRESS 0x36
#define MEASUREMENT_COMMAND 0x3608
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t flow_rate;
    uint8_t crc;
    uint8_t flags;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_flow_rate(int16_t raw_flow);
char* get_status(float flow_rate);
int log_data(float flow_rate, uint8_t flags, char* status);
void signal_handler(int signal);
int crc8(const uint8_t *data, size_t len);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the SLF3S-1300F
int read_sensor_data(sensor_data_t *data) {
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    char buffer[3];

    if (i2cWriteDevice(i2c_handle, command, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(2); // Wait at least 2ms

    if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    data->flow_rate = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->crc = buffer[2];
    data->flags = 0; // Assuming no flags are available in the data

    return 0;
}

// Convert raw flow rate to ml/min
float convert_flow_rate(int16_t raw_flow) {
    // Sensitivity is 0.05 ml/min per LSB (adjust if needed based on datasheet)
    return (float)raw_flow * 0.05;
}

// Get status string based on flow rate
char* get_status(float flow_rate) {
    if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
        return "INVALID";
    } else {
        return "OK";
    }
}

// Log data to CSV file
int log_data(float flow_rate, uint8_t flags, char* status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("cooling_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// CRC-8 checksum calculation
int crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;
    float flow_rate;
    char* status;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate CRC
            uint8_t crc_data[2] = {sensor_data.flow_rate >> 8, sensor_data.flow_rate & 0xFF};
            if (crc8(crc_data, 2) != sensor_data.crc) {
                fprintf(stderr, "CRC error\n");
                log_data(0.0, 0, "ERROR");
                // Attempt recovery (re-initialize I2C)
                i2cClose(i2c_handle);
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "Re-initialization failed, exiting\n");
                    program_running = 0;
                    break;
                }
                gpioDelay(1000); // Wait before next attempt
                continue;
            }

            // Convert flow rate
            flow_rate = convert_flow_rate(sensor_data.flow_rate);

            // Get status
            status = get_status(flow_rate);

            // Log data
            if (log_data(flow_rate, sensor_data.flags, status) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            log_data(0.0, 0, "ERROR");
            // Attempt recovery (re-initialize I2C)
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting\n");
                program_running = 0;
                break;
            }
            gpioDelay(1000); // Wait before next attempt
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

