#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <wiringPi.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the log file name
#define LOG_FILE "path_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} SensorData;

// Function prototypes
int initialize_gpio();
SensorData read_sensors();
char* generate_iso8601_timestamp();
int write_to_log(const char *timestamp, const SensorData *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    // Set the GPIO pins as input
    pinMode(LEFT_SENSOR_PIN, INPUT);
    pinMode(MIDDLE_SENSOR_PIN, INPUT);
    pinMode(RIGHT_SENSOR_PIN, INPUT);

    return 0;
}

// Function to read the sensor values
SensorData read_sensors() {
    SensorData data;
    data.left = digitalRead(LEFT_SENSOR_PIN);
    data.middle = digitalRead(MIDDLE_SENSOR_PIN);
    data.right = digitalRead(RIGHT_SENSOR_PIN);
    return data;
}

// Function to generate an ISO 8601 timestamp
char* generate_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp: %s\n", strerror(errno));
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to write the data to the log file
int write_to_log(const char *timestamp, const SensorData *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data->left, data->middle, data->right);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    return 0;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() == -1) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
        fflush(log_file);
    }

    printf("Starting sensor logging. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        SensorData sensor_data = read_sensors();

        // Generate timestamp
        char *timestamp = generate_iso8601_timestamp();
        if (timestamp == NULL) {
            program_running = 0; // Exit loop if timestamp generation fails
            continue; // Skip to the next iteration
        }

        // Write data to log file
        if (write_to_log(timestamp, &sensor_data) == -1) {
            program_running = 0; // Exit loop if log writing fails
        }

        free(timestamp); // Free the allocated memory

        // Wait for 50 milliseconds
        delay(50);
    }

    // Clean up and exit
    printf("Cleaning up and exiting.\n");

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO resources (not strictly needed with wiringPi, but good practice)
    // wiringPiSetupGpio(); // Re-initialize to reset pins

    return 0;
}

