// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the flame detection event to the console and file
void log_flame_event() {
    char* timestamp = get_timestamp();
    printf("Flame detected at: %s\n", timestamp);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s - Flame detected\n", timestamp);
    fclose(fp);
}

// Callback function for flame detection
void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (gpio == FLAME_SENSOR_GPIO && level == 0) { // Falling edge detected
        log_flame_event();
    }
}

