#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <sys/stat.h>
#include <sys/types.h>

// Define GPIO pins
#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO 24

// Define GPIO chip number
#define GPIOCHIP 4

// Define log file name
#define LOG_FILE "touch_log.txt"

// Global variables
static int gpiochip_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_request(int gpio, const char *name);
int gpio_unexport(int gpio);
int gpio_set_direction(int gpio, const char *direction);
int gpio_read(int gpio);
int gpio_write(int gpio, int value);
int log_event(int led_state);
void signal_handler(int sig);
int setup_gpio(int gpio, const char *direction);
int cleanup_gpio(int gpio);
int open_log_file(const char *filename);
int close_log_file(FILE *file);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        fprintf(stderr, "Received signal %d, terminating...\n", sig);
    }
}

// Function to request a GPIO line
int gpio_request(int gpio, const char *name) {
    struct gpio_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = name;
    config.flags = 0; // Request direction is determined by set_direction

    if (ioctl(gpiochip_fd, GPIO_REQUEST, &config) < 0) {
        perror("gpio_request");
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO line
int gpio_unexport(int gpio) {
    if (ioctl(gpiochip_fd, GPIO_UNEXPORT, &gpio) < 0) {
        perror("gpio_unexport");
        return -1;
    }
    return 0;
}

// Function to set the direction of a GPIO line
int gpio_set_direction(int gpio, const char *direction) {
    struct gpio_set_direction_config config;
    memset(&config, 0, sizeof(config));
    config.gpio = gpio;
    if (strcmp(direction, "in") == 0) {
        config.flags = GPIO_DIRECTION_INPUT;
    } else if (strcmp(direction, "out") == 0) {
        config.flags = GPIO_DIRECTION_OUTPUT;
    } else {
        fprintf(stderr, "Invalid direction: %s\n", direction);
        return -1;
    }

    if (ioctl(gpiochip_fd, GPIO_SET_DIRECTION, &config) < 0) {
        perror("gpio_set_direction");
        return -1;
    }
    return 0;
}

// Function to read the value of a GPIO line
int gpio_read(int gpio) {
    struct gpio_get_value_config config;
    memset(&config, 0, sizeof(config));
    config.gpio = gpio;

    if (ioctl(gpiochip_fd, GPIO_GET_VALUE, &config) < 0) {
        perror("gpio_read");
        return -1;
    }
    return config.value;
}

// Function to write a value to a GPIO line
int gpio_write(int gpio, int value) {
    struct gpio_set_value_config config;
    memset(&config, 0, sizeof(config));
    config.gpio = gpio;
    config.value = value;

    if (ioctl(gpiochip_fd, GPIO_SET_VALUE, &config) < 0) {
        perror("gpio_write");
        return -1;
    }
    return 0;
}

// Function to log an event to the log file
int log_event(int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LED State: %d\n", timestamp, led_state);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }
}

// Function to setup GPIO
int setup_gpio(int gpio, const char *direction) {
    if (gpio_set_direction(gpio, direction) < 0) {
        fprintf(stderr, "Failed to set direction for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO
int cleanup_gpio(int gpio) {
    if (gpio_unexport(gpio) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to open the log file
int open_log_file(const char *filename) {
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("fopen");
        return -1;
    }
    return 0;
}

// Function to close the log file
int close_log_file(FILE *file) {
    if (file != NULL) {
        fclose(file);
        file = NULL; // Ensure file pointer is NULL after closing
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }
}

int main() {
    int touch_value, led_state = 0; // Initial LED state is off

    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open log file
    if (open_log_file(LOG_FILE) < 0) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    // Open GPIO chip
    gpiochip_fd = open("/sys/class/gpio/gpiochip4", O_RDWR);
    if (gpiochip_fd < 0) {
        perror("open");
        close_log_file(log_file);
        return 1;
    }

    // Request GPIO lines
    if (gpio_request(TOUCH_SENSOR_GPIO, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request touch sensor GPIO.\n");
        close(gpiochip_fd);
        close_log_file(log_file);
        return 1;
    }
    if (gpio_request(LED_GPIO, "led") < 0) {
        fprintf(stderr, "Failed to request LED GPIO.\n");
        cleanup_gpio(TOUCH_SENSOR_GPIO);
        close(gpiochip_fd);
        close_log_file(log_file);
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(TOUCH_SENSOR_GPIO, "in") < 0) {
        fprintf(stderr, "Failed to setup touch sensor GPIO.\n");
        cleanup_gpio(TOUCH_SENSOR_GPIO);
        cleanup_gpio(LED_GPIO);
        close(gpiochip_fd);
        close_log_file(log_file);
        return 1;
    }
    if (setup_gpio(LED_GPIO, "out") < 0) {
        fprintf(stderr, "Failed to setup LED GPIO.\n");
        cleanup_gpio(TOUCH_SENSOR_GPIO);
        cleanup_gpio(LED_GPIO);
        close(gpiochip_fd);
        close_log_file(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        touch_value = gpio_read(TOUCH_SENSOR_GPIO);
        if (touch_value < 0) {
            fprintf(stderr, "Failed to read touch sensor value.\n");
            break;
        }

        if (touch_value == 1) {
            // Touch detected
            led_state = !led_state; // Toggle LED state
            gpio_write(LED_GPIO, led_state);
            log_event(led_state);
            sleep(1); // Debounce: Wait for 1 second
        }

        usleep(100000); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    cleanup_gpio(TOUCH_SENSOR_GPIO);
    cleanup_gpio(LED_GPIO);
    close(gpiochip_fd);
    close_log_file(log_file);

    printf("Exiting.\n");
    return 0;
}

