#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_touch_sensor();
void toggle_led(int state);
int log_touch_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Turn off the LED
    gpioWrite(LED_PIN, 0);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED
void toggle_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log the touch event
int log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format the timestamp as UTC ISO 8601
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Open the log file in append mode
    if (log_file == NULL) {
        log_file = fopen("touch_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1; // Indicate failure
        }
    }

    // Write the timestamp to the log file
    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate failure
    }

    // Flush the buffer to ensure data is written to the file
    fflush(log_file);

    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_UP); // Or PI_PUD_DOWN if needed

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0; // Store the last state of the touch sensor
    int current_state = 0;
    int debounce_counter = 0;

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the touch sensor
        current_state = read_touch_sensor();

        // Detect rising edge (LOW to HIGH transition)
        if (current_state == 1 && last_state == 0) {
            printf("Touch detected!\n");

            // Toggle the LED
            toggle_led(1 - gpioRead(LED_PIN)); // Toggle the LED state

            // Log the touch event
            if (log_touch_event() != 0) {
                fprintf(stderr, "Error logging touch event.\n");
            }

            // Reset debounce counter
            debounce_counter = 0;
        }

        // Debounce the sensor
        if (current_state == 1) {
            debounce_counter++;
            if (debounce_counter >= DEBOUNCE_TIME) {
                last_state = 1; // Update last state to HIGH
            }
        } else {
            debounce_counter = 0; // Reset if not touched
            last_state = 0; // Update last state to LOW
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(LED_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

