// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the log file name
#define LOG_FILE "magnet_log.txt"

// Structure to hold sensor data
typedef struct {
    int pin;
    int initial_state;
    int current_state;
} sensor_t;

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(int sensor_id, int state);
void handle_signal(int signal);
void cleanup();

// Signal handler function
void handle_signal(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);

    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int pin) {
    int state = gpioRead(pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO pin %d\n", pin);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log an event to the log file
int log_event(int sensor_id, int state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s - Sensor %d: %s\n", buf, sensor_id, state ? "Magnet Removed" : "Magnet Present");
    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

