    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Define sensors
    sensor_t sensors[] = {
        {SENSOR1_PIN, -1, -1},
        {SENSOR2_PIN, -1, -1},
        {SENSOR3_PIN, -1, -1}
    };
    int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

    // Main loop
