#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HEART_RATE_REG 0x24
#define CONFIG_REG 0x30
#define SAMPLE_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t led_drive_strength;
    uint8_t measurement_mode;
} sensor_config_t;

// Function prototypes
int init_i2c();
int read_sensor_register(int handle, uint8_t reg, uint8_t *data, int count);
int write_sensor_register(int handle, uint8_t reg, uint8_t data);
int read_part_id(int handle, uint8_t *part_id);
int read_hw_revision(int handle, uint8_t *hw_rev);
int configure_sensor(int handle, sensor_config_t config);
int read_heart_rate(int handle, uint16_t *heart_rate);
float apply_moving_average(uint16_t *data, int size);
int validate_bpm(float bpm);
int log_bpm(float bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor register with retry
int read_sensor_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X, count %d): %d, retries remaining: %d\n", reg, count, result, retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, count %d)\n", reg, count);
    return -1; // Failure
}

// Write sensor register
int write_sensor_register(int handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result != 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, data 0x%02X): %d\n", reg, data, result);
        return -1;
    }
    return 0;
}

// Read PART_ID register
int read_part_id(int handle, uint8_t *part_id) {
    if (read_sensor_register(handle, PART_ID_REG, part_id, 1) != 0) {
        return -1;
    }
    return 0;
}

// Read HW_REV register
int read_hw_revision(int handle, uint8_t *hw_rev) {
    if (read_sensor_register(handle, HW_REV_REG, hw_rev, 1) != 0) {
        return -1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor(int handle, sensor_config_t config) {
    // Example configuration (adjust as needed based on datasheet)
    if (write_sensor_register(handle, CONFIG_REG, config.led_drive_strength) != 0) return -1;
    if (write_sensor_register(handle, CONFIG_REG + 1, config.measurement_mode) != 0) return -1;

    // Add more configuration registers as needed

    return 0;
}

// Read heart rate register
int read_heart_rate(int handle, uint16_t *heart_rate) {
    uint8_t data[2];
    if (read_sensor_register(handle, HEART_RATE_REG, data, 2) != 0) {
        return -1;
    }

    *heart_rate = (data[0] << 8) | data[1];
    return 0;
}

// Apply moving average filter
float apply_moving_average(uint16_t *data, int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += data[i];
    }
    return sum / size;
}

// Validate BPM
int validate_bpm(float bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Log BPM to file
int log_bpm(float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    uint8_t part_id, hw_rev;
    uint16_t heart_rate_samples[SAMPLE_SIZE];
    float bpm;
    int i;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    if (read_part_id(i2c_handle, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_hw_revision(i2c_handle, &hw_rev) != 0) {
        fprintf(stderr, "Failed to read HW_REV\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x52 || hw_rev != 0x10) {
        fprintf(stderr, "Incorrect PART_ID (0x%02X) or HW_REV (0x%02X). Sensor not found or incorrect.\n", part_id, hw_rev);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    sensor_config_t config = { .led_drive_strength = 0x3F, .measurement_mode = 0x01 }; // Example values
    if (configure_sensor(i2c_handle, config) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read heart rate samples
        for (i = 0; i < SAMPLE_SIZE; i++) {
            if (read_heart_rate(i2c_handle, &heart_rate_samples[i]) != 0) {
                fprintf(stderr, "Failed to read heart rate sample %d\n", i);
                // Consider adding a delay before retrying
                gpioDelay(100000); // 100ms
                continue; // Skip to the next sample
            }
        }

        // Apply moving average filter
        bpm = apply_moving_average(heart_rate_samples, SAMPLE_SIZE);

        // Validate BPM
        if (validate_bpm(bpm)) {
            // Log BPM
            log_bpm(bpm);
            printf("BPM: %.2f\n", bpm);
        } else {
            fprintf(stderr, "Invalid BPM value: %.2f\n", bpm);
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

