#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Release GPIO line
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT); // Set to input to avoid spurious output
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_OFF); // Disable pull-up

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a flame detection event
void log_flame_detection() {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

