    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT); // Set to input to avoid spurious output
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_OFF); // Disable pull-up
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

