// Define GPIO pins for the touch sensor channels
#define TOUCH_CHANNEL_1 5
#define TOUCH_CHANNEL_2 6
#define TOUCH_CHANNEL_3 7
#define TOUCH_CHANNEL_4 8
#define TOUCH_CHANNEL_5 9
#define TOUCH_CHANNEL_6 10
#define TOUCH_CHANNEL_7 11
#define TOUCH_CHANNEL_8 12

// Define GPIO pins for the binary counter output
#define COUNTER_BIT_0 17
#define COUNTER_BIT_1 18
#define COUNTER_BIT_2 19
#define COUNTER_BIT_3 20
#define COUNTER_BIT_4 21
#define COUNTER_BIT_5 22
#define COUNTER_BIT_6 23
#define COUNTER_BIT_7 24

// Define the number of touch sensor channels
#define NUM_CHANNELS 8

// Define the number of counter bits
#define NUM_BITS 8

// Define the delay between sensor readings in milliseconds
#define READ_DELAY_MS 10

// Define the stabilization delay in milliseconds
#define STABILIZATION_DELAY_MS 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int channel);
int update_counter(int channel, int value);
int set_counter_output(int counter_value);
int log_event(int channel, int counter_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    // Reset all output pins to 0
    for (int i = 0; i < NUM_BITS; i++) {
        gpioWrite(COUNTER_BIT_0 + i, 0);
    }

    // Terminate the pigpio library
    gpioTerminate();

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set touch sensor pins as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(TOUCH_CHANNEL_1 + i, PI_INPUT);
        gpioSetPullUpDown(TOUCH_CHANNEL_1 + i, PI_PUD_DOWN); // Use pull-down resistors
    }

    // Set counter output pins as outputs
    for (int i = 0; i < NUM_BITS; i++) {
        gpioSetMode(COUNTER_BIT_0 + i, PI_OUTPUT);
        gpioWrite(COUNTER_BIT_0 + i, 0); // Initialize all bits to 0
    }

    return 0;
}

// Read the touch sensor value for a given channel
int read_touch_sensor(int channel) {
    int value = gpioRead(channel);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", channel, strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

