int update_counter(int channel, int value) {
    int current_counter = 0;
    // Read the current state of the counter bits
    for (int i = 0; i < NUM_BITS; i++) {
        current_counter <<= 1;
        current_counter |= gpioRead(COUNTER_BIT_0 + i);
    }

    // Increment the counter if the touch sensor is active
    if (value == 1) {
        current_counter = (current_counter + 1) % 256; // Wrap around to 0 if necessary
    }

    // Convert the counter value to an 8-bit binary string
    char bit_string[9]; // 8 bits + null terminator
    snprintf(bit_string, sizeof(bit_string), "%08d", current_counter);

    // Set the GPIO pins based on the binary string
    for (int i = 0; i < NUM_BITS; i++) {
        gpioWrite(COUNTER_BIT_0 + i, (bit_string[i] == '1') ? 1 : 0);
    }

    return current_counter;
}

