    char bit_string[9]; // 8 bits + null terminator
    snprintf(bit_string, sizeof(bit_string), "%08d", counter_value);

    // Set the GPIO pins based on the binary string
    for (int i = 0; i < NUM_BITS; i++) {
        int value = (bit_string[i] == '1') ? 1 : 0;
        if (gpioWrite(COUNTER_BIT_0 + i, value) < 0) {
            fprintf(stderr, "Error writing to GPIO %d: %s\n", COUNTER_BIT_0 + i, strerror(errno));
            return -1; // Indicate an error
        }
    }
    return 0;
}

// Log the event to the log file
int log_event(int channel, int counter_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
        fflush(log_file); // Ensure the data is written to the file immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.  Logging to stdout instead.\n");
        printf("%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
        return -1; // Indicate an error
    }
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Warning: Could not open log file: %s. Logging to stdout only.\n", strerror(errno));
    }

    // Stabilization delay
    gpioDelay(STABILIZATION_DELAY_MS * 1000); // Convert milliseconds to microseconds

    int current_counter = 0;
    // Main loop
    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int sensor_value = read_touch_sensor(TOUCH_CHANNEL_1 + i);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor on channel %d, skipping.\n", i + 1);
                continue; // Skip to the next channel
            }

            if (sensor_value == 1) {
                current_counter = update_counter(i + 1, sensor_value);
                log_event(i + 1, current_counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, current_counter);
            }
        }

        gpioDelay(READ_DELAY_MS * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

