        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("tracking_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup_gpio();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);
        int sensor4_value = read_sensor(SENSOR4_PIN);

        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1 || sensor4_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping log entry\n");
        } else {
            if (log_data(log_file, sensor1_value, sensor2_value, sensor3_value, sensor4_value) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup and exit
    fclose(log_file);
    cleanup_gpio();
    printf("Program terminated successfully.\n");
    return 0;
}

