int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control the LED
int control_led(int state) {
    int result = gpioWrite(LED_PIN, state);
    if (result < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", LED_PIN, result);
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to file
int log_data(time_t timestamp, int sensor1, int sensor2, int led_state) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, sensor1, sensor2, led_state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
