        fprintf(stderr, "Failed to set GPIO %d to input\n", SENSOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", SENSOR2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,led_state\n");
    }
    fflush(log_file);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor data
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor data, exiting.\n");
            break;
        }

        // Determine LED state
        int led_state = 0; // Default to off
        if (sensor1_value == 0 && sensor2_value == 0) {
            led_state = 1; // Turn on LED if both sensors detect an obstacle
        }

        // Control LED
        if (control_led(led_state) < 0) {
            fprintf(stderr, "Error controlling LED, exiting.\n");
            break;
        }

        // Get current timestamp
        time_t current_time = time(NULL);

        // Log data
        if (log_data(current_time, sensor1_value, sensor2_value, led_state) < 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break;
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

