#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 4
#define LED_OUTPUT_PIN 17

// Define sampling rate and LED on/off times
#define SAMPLING_RATE 8000 // Hz
#define LED_ON_TIME 100    // ms
#define LED_OFF_TIME 100   // ms

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to get current timestamp in milliseconds
long long get_timestamp_ms()
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000);
}

// Function to control the LED
void control_led(int on)
{
    gpioWrite(LED_OUTPUT_PIN, on);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as input\n", AUDIO_INPUT_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_OUTPUT_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_OUTPUT_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR)
    {
        perror("signal");
        gpioTerminate();
        return 1;
    }

    // Main sampling loop
    while (!terminate)
    {
        // Read audio input pin
        int audio_level = gpioRead(AUDIO_INPUT_PIN);

        // Check for sound peak event
        if (audio_level == 1)
        {
            // Get timestamp
            long long timestamp = get_timestamp_ms();

            // Print timestamp
            printf("Timestamp: %lld ms\n", timestamp);

            // Turn on LED
            control_led(1);

            // Wait for LED on time
            gpioDelay(LED_ON_TIME * 1000); // Convert ms to us

            // Turn off LED
            control_led(0);

            // Wait for LED off time
            gpioDelay(LED_OFF_TIME * 1000); // Convert ms to us
        }

        // Delay to achieve desired sampling rate
        gpioDelay(125000); // 125 us delay for 8 kHz sampling rate
    }

    // Clean up and exit
    printf("Exiting gracefully...\n");
    control_led(0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
    return 0;
}

