#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SI1175_ADDR 0x60

// Define the ALS data registers
#define ALS_LSB_REG 0x22
#define ALS_MSB_REG 0x23

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read ALS data from the Si1175 sensor
int read_als_data(int i2c_handle, uint16_t *als_data) {
    char buffer[2];
    int result;

    // Read the LSB register
    result = i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1; // Indicate an error
    }

    // Combine the LSB and MSB into a 16-bit value
    *als_data = (buffer[1] << 8) | buffer[0];

    return 0; // Indicate success
}

int main() {
    uint16_t als_data;
    struct timespec sleep_time;
    struct timespec ts;
    char timestamp[30];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ALS data
        if (read_als_data(i2c_handle, &als_data) == 0) {
            // Get current timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            printf("%s.%09ld Raw ALS Value: %u\n", timestamp, ts.tv_nsec, als_data);
        } else {
            fprintf(stderr, "Failed to read ALS data. Retrying...\n");
        }

        // Sleep for 100 milliseconds
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

