#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 2
#define MIDDLE_SENSOR_PIN 3
#define RIGHT_SENSOR_PIN 4

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
    }
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor values to stdout
void log_sensor_values(int left, int middle, int right) {
    printf("L:%d M:%d R:%d\n", left, middle, right);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    // Main loop to poll the sensors
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Check for errors during sensor reading
        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue; // Skip logging and delay
        }

        // Log the sensor values
        log_sensor_values(left_value, middle_value, right_value);

        // Delay for 100ms
        gpioDelay(100);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

