#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>

// Define GPIO pins for each channel
#define GPIO5 5
#define GPIO6 6
#define GPIO13 13
#define GPIO19 19
#define GPIO26 26
#define GPIO12 12
#define GPIO16 16
#define GPIO20 20

// Number of channels
#define NUM_CHANNELS 8

// Structure to hold GPIO pin information
typedef struct {
    int pin;
    char *name;
} gpio_t;

// Array of GPIO pins
gpio_t channels[NUM_CHANNELS] = {
    {GPIO5, "TP1"},
    {GPIO6, "TP2"},
    {GPIO13, "TP3"},
    {GPIO19, "TP4"},
    {GPIO26, "TP5"},
    {GPIO12, "TP6"},
    {GPIO16, "TP7"},
    {GPIO20, "TP8"}
};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to initialize a GPIO pin for input
int gpio_init(int pin) {
    FILE *fp;
    char buffer[64];

    // Export the GPIO pin
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/export");
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", buffer, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);

    // Set the GPIO pin direction to input
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", buffer, strerror(errno));
        return -1;
    }
    fprintf(fp, "in");
    fclose(fp);

    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int pin) {
    FILE *fp;
    char buffer[64];
    char value;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(buffer, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", buffer, strerror(errno));
        return -1;
    }
    value = fgetc(fp);
    fclose(fp);

    if (value == '0') {
        return 0;
    } else if (value == '1') {
        return 1;
    } else {
        fprintf(stderr, "Error reading GPIO %d value: %s\n", pin, strerror(errno));
        return -1;
    }
}

// Function to format the sensor data into a string
int format_data(int *channel_values, char *buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, buffer_size, "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), ".%03ld] ", ts.tv_nsec / 1000000);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), "%sCH%d=%d ", i == 0 ? "" : (i == NUM_CHANNELS - 1) ? "" : "", i + 1, channel_values[i]);
    }
    return 0;
}

// Function to write the formatted string to stdout
int write_to_stdout(const char *data) {
    if (fputs(data, stdout) == EOF) {
        fprintf(stderr, "Error writing to stdout: %s\n", strerror(errno));
        return -1;
    }
    fflush(stdout); // Ensure data is written immediately
    return 0;
}

int main() {
    int channel_values[NUM_CHANNELS];
    char data_buffer[256];
    fd_set readfds;
    struct timeval timeout;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpio_init(channels[i].pin) != 0) {
            fprintf(stderr, "Failed to initialize GPIO %d\n", channels[i].pin);
            return 1;
        }
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        for (int i = 0; i < NUM_CHANNELS; i++) {
            channel_values[i] = gpio_read(channels[i].pin);
            if (channel_values[i] == -1) {
                fprintf(stderr, "Failed to read GPIO %d\n", channels[i].pin);
                return 1;
            }
        }

        // Format data
        if (format_data(channel_values, data_buffer, sizeof(data_buffer)) != 0) {
            fprintf(stderr, "Failed to format data\n");
            return 1;
        }

        // Write data to stdout
        if (write_to_stdout(data_buffer) != 0) {
            fprintf(stderr, "Failed to write data to stdout\n");
            return 1;
        }

        // Polling interval
        usleep(200000); // 200ms
    }

    // Cleanup: Unexport GPIO pins
    for (int i = 0; i < NUM_CHANNELS; i++) {
        FILE *fp;
        char buffer[64];

        snprintf(buffer, sizeof(buffer), "/sys/class/gpio/unexport");
        fp = fopen(buffer, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening %s: %s\n", buffer, strerror(errno));
        } else {
            fprintf(fp, "%d", channels[i].pin);
            fclose(fp);
        }
    }

    return 0;
}

