#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

// Define hue transition duration (seconds)
#define HUE_TRANSITION_DURATION 5

// Define number of steps for linear interpolation
#define NUM_STEPS 50

// Structure to represent an RGB color
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Global variables
volatile sig_atomic_t program_running = 1;
double start_time = 0.0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
RGBColor generate_random_hue();
RGBColor interpolate_hue(RGBColor start_color, RGBColor end_color, double elapsed_time, int num_steps);
void set_led_color(RGBColor color);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
}

// Initialize GPIO pins and pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    return 0;
}

// Cleanup GPIO pins and pigpio library
void cleanup_gpio() {
    // Turn off LED
    set_led_color((RGBColor){0, 0, 0});

    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");
}

// Generate a random hue (RGB color)
RGBColor generate_random_hue() {
    RGBColor color;
    color.red = rand() % 256;
    color.green = rand() % 256;
    color.blue = rand() % 256;
    return color;
}

// Interpolate between two hues
RGBColor interpolate_hue(RGBColor start_color, RGBColor end_color, double elapsed_time, int num_steps) {
    RGBColor interpolated_color;
    double progress = elapsed_time / (HUE_TRANSITION_DURATION * 1.0);

    // Clamp progress to [0, 1]
    if (progress < 0.0) progress = 0.0;
    if (progress > 1.0) progress = 1.0;

    interpolated_color.red = start_color.red + (end_color.red - start_color.red) * progress;
    interpolated_color.green = start_color.green + (end_color.green - start_color.green) * progress;
    interpolated_color.blue = start_color.blue + (end_color.blue - start_color.blue) * progress;

    // Clamp values to [0, 255]
    if (interpolated_color.red < 0) interpolated_color.red = 0;
    if (interpolated_color.red > 255) interpolated_color.red = 255;
    if (interpolated_color.green < 0) interpolated_color.green = 0;
    if (interpolated_color.green > 255) interpolated_color.green = 255;
    if (interpolated_color.blue < 0) interpolated_color.blue = 0;
    if (interpolated_color.blue > 255) interpolated_color.blue = 255;

    return interpolated_color;
}

// Set the color of the RGB LED using PWM
void set_led_color(RGBColor color) {
    gpioPWM(RED_PIN, color.red);
    gpioPWM(GREEN_PIN, color.green);
    gpioPWM(BLUE_PIN, color.blue);
}

// Log an error message to syslog
void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
    perror(message);
}

int main() {
    // Open syslog
    openlog("rgb_fader", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Seed random number generator
    srand(time(NULL));

    // Main loop
    while (program_running) {
        // Generate random start and end hues
        RGBColor start_hue = generate_random_hue();
        RGBColor end_hue = generate_random_hue();

        // Calculate start time
        start_time = time(NULL);

        // Fade between hues
        for (int i = 0; i < NUM_STEPS; i++) {
            double elapsed_time = (double)i / NUM_STEPS * HUE_TRANSITION_DURATION;
            RGBColor current_color = interpolate_hue(start_hue, end_hue, elapsed_time, NUM_STEPS);
            set_led_color(current_color);
            usleep(10000); // 10ms delay
        }

        // Wait for the remaining time to complete the transition
        double remaining_time = HUE_TRANSITION_DURATION - (double)NUM_STEPS / NUM_STEPS * HUE_TRANSITION_DURATION;
        if (remaining_time > 0) {
            sleep((int)remaining_time);
        }

        // Generate new random hues
        start_hue = generate_random_hue();
        end_hue = generate_random_hue();
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close syslog
    closelog();

    return 0;
}

