#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A
#define GPIO_LED 17
#define RED_THRESHOLD 200

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init(int i2c_fd);
int tcs34725_read_raw(int i2c_fd, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear);
void tcs34725_calibrate(uint16_t red, uint16_t green, uint16_t blue, uint16_t clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue);
void gpio_control(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// TCS34725 initialization function
int tcs34725_init(int i2c_fd) {
    // Enable power and RGBC
    uint8_t enable_data = 0x03; // PON | AEN
    if (write(i2c_fd, &enable_data, 1) != 1) {
        fprintf(stderr, "Error writing to TCS34725_ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time (ATIME) - approximately 154ms
    uint8_t atime_data = 0xEB; // 101ms * 2 = 202ms, but we want 154ms
    if (write(i2c_fd, &atime_data, 1) != 1) {
        fprintf(stderr, "Error writing to TCS34725_ATIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set gain (AGAIN) - 1x gain
    uint8_t gain_data = 0x00; // 1x gain
    if (write(i2c_fd, &gain_data, 1) != 1) {
        fprintf(stderr, "Error writing to TCS34725_CONTROL register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// TCS34725 read raw data function
int tcs34725_read_raw(int i2c_fd, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t data[8];

    if (read(i2c_fd, data, 8) != 8) {
        fprintf(stderr, "Error reading from TCS34725: %s\n", strerror(errno));
        return -1;
    }

    *clear = (data[1] << 8) | data[0];
    *red   = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue  = (data[7] << 8) | data[6];

    return 0;
}

// TCS34725 calibration function
void tcs34725_calibrate(uint16_t red, uint16_t green, uint16_t blue, uint16_t clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue) {
    // Simple calibration (replace with your calibration routine)
    *calibrated_red = (float)red;
    *calibrated_green = (float)green;
    *calibrated_blue = (float)blue;
}

// GPIO control function
void gpio_control(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    uint16_t red, green, blue, clear;
    float calibrated_red, calibrated_green, calibrated_blue;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (tcs34725_read_raw(i2c_fd, &red, &green, &blue, &clear) == 0) {
            // Calibrate data
            tcs34725_calibrate(red, green, blue, clear, &calibrated_red, &calibrated_green, &calibrated_blue);

            // Print calibrated values
            printf("R: %.2f, G: %.2f, B: %.2f, C: %u\n", calibrated_red, calibrated_green, calibrated_blue, clear);

            // Control LED based on red value
            if (calibrated_red > RED_THRESHOLD) {
                gpio_control(GPIO_LED, 1); // Turn LED on
            } else {
                gpio_control(GPIO_LED, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting re-initialization...\n");
            // Attempt to re-initialize the sensor
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip the rest of the loop
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                fprintf(stderr, "Error re-setting I2C slave address: %s\n", strerror(errno));
                terminate = 1;
                continue;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                terminate = 1;
                continue;
            }
        }

        // Wait 200ms
        usleep(200000); // 200ms = 200000 microseconds
    }

    // Cleanup
    fprintf(stderr, "Cleaning up resources...\n");
    gpio_control(GPIO_LED, 0); // Turn off LED
    close(i2c_fd);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

