        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    uint16_t red, green, blue, clear;
    float calibrated_red, calibrated_green, calibrated_blue;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (tcs34725_read_raw(i2c_fd, &red, &green, &blue, &clear) == 0) {
            // Calibrate data
            tcs34725_calibrate(red, green, blue, clear, &calibrated_red, &calibrated_green, &calibrated_blue);

            // Print calibrated values
            printf("R: %.2f, G: %.2f, B: %.2f, C: %u\n", calibrated_red, calibrated_green, calibrated_blue, clear);

            // Control LED based on red value
            if (calibrated_red > RED_THRESHOLD) {
                gpio_control(GPIO_LED, 1); // Turn LED on
            } else {
                gpio_control(GPIO_LED, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting re-initialization...\n");
            // Attempt to re-initialize the sensor
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip the rest of the loop
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                fprintf(stderr, "Error re-setting I2C slave address: %s\n", strerror(errno));
                terminate = 1;
                continue;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                terminate = 1;
                continue;
            }
        }

        // Wait 200ms
        usleep(200000); // 200ms = 200000 microseconds
    }

    // Cleanup
    fprintf(stderr, "Cleaning up resources...\n");
    gpio_control(GPIO_LED, 0); // Turn off LED
    close(i2c_fd);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

