#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_ADDR 0x23
#define I2C_BUS 1
#define GPIO_LED 18 // BCM GPIO18
#define NUM_LEDS 10
#define PWM_FREQUENCY 800000 // 800 kHz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_bh1750();
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read lux value from BH1750 sensor
float read_bh1750() {
    char config_cmd[1] = {0x10}; // Continuous high resolution mode
    char buf[2];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, config_cmd, 1);
        if (result == 0) {
            gpioDelay(180); // Wait for measurement (at least 180ms)
            result = i2cReadDevice(i2c_handle, buf, 2);
            if (result == 2) {
                unsigned int raw_value = (buf[0] << 8) | buf[1];
                return (float)raw_value / 1.2; // Convert to lux
            } else {
                fprintf(stderr, "Error reading from I2C device: %d\n", result);
            }
        } else {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
        }
        retries--;
        gpioDelay(100); // Wait before retrying
    }

    fprintf(stderr, "Failed to read from BH1750 after multiple retries.\n");
    return -1.0; // Indicate error
}

// Function to map lux value to brightness level (logarithmic scale)
int map_lux_to_brightness(float lux) {
    if (lux < 0) return 0; // Handle error case
    float log_lux = log10(lux + 1); // Add 1 to avoid log(0)
    float normalized_brightness = log_lux / log10(1000); // Normalize to 0-1 (assuming max lux is 1000)
    return (int)(normalized_brightness * NUM_LEDS);
}

// Function to set the brightness of the WS2812B strip using hardware PWM
void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > NUM_LEDS) brightness = NUM_LEDS;

    // Generate PWM signal for brightness level
    for (int i = 0; i < brightness; i++) {
        gpioWrite(GPIO_LED, 1); // Clock high
        gpioDelay(0.8); // 0.8us
        gpioWrite(GPIO_LED, 0); // Clock low
        gpioDelay(0.45); // 0.45us
    }

    // Turn off remaining LEDs
    for (int i = brightness; i < NUM_LEDS; i++) {
        gpioWrite(GPIO_LED, 1); // Clock high
        gpioDelay(0.8); // 0.8us
        gpioWrite(GPIO_LED, 0); // Clock low
        gpioDelay(11.2); // 11.2us
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_LED, 1); // Set range to 1 for on/off

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ambient light sensor and WS2812B control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux = read_bh1750();
        if (lux >= 0) {
            int brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);
        } else {
            fprintf(stderr, "Error reading lux value, skipping LED update.\n");
        }
        gpioDelay(50); // Delay between readings
    }

    // Clean up and terminate
    set_led_brightness(0); // Turn off LEDs
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

