#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define NUM_LEDS 8
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold LED color data
typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} led_color_t;

// Function prototypes
int init_i2c(const char *bus);
int init_spi(const char *device);
int read_bh1750(int fd);
void set_apa102_brightness(int fd, int brightness);
void send_apa102_frame(int fd, uint8_t *data, int len);
void cleanup(int signal);
uint8_t map_light_to_brightness(int light_level);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Turn off all LEDs
    uint8_t end_frame[4] = {0x00, 0x00, 0x00, 0x00};
    send_apa102_frame(spi_fd, end_frame, 4);

    // Close I2C and SPI devices
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }

    exit(0);
}

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, 0x23) < 0) { // BH1750 address
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize SPI device
int init_spi(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed Hz
    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed Hz");
        close(fd);
        return -1;
    }

    return fd;
}

// Read light level from BH1750 sensor
int read_bh1750(int fd) {
    uint8_t command = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &command, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(120000); // Wait for conversion (120ms)

    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

// Map light level to brightness (0-255)
uint8_t map_light_to_brightness(int light_level) {
    // Use a logarithmic mapping to better represent human perception of light
    double log_light_level = log10(light_level + 1); // Add 1 to avoid log(0)
    double brightness = (log_light_level / log10(10000)) * 255.0; // Assuming max light level is 10000 lux
    if (brightness > 255.0) brightness = 255.0;
    if (brightness < 0.0) brightness = 0.0;
    return (uint8_t)brightness;
}

// Set brightness of all LEDs in the APA102 strip
void set_apa102_brightness(int fd, int brightness) {
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end_frame[4] = {0x00, 0x00, 0x00, 0x00};

    // Start frame
    send_apa102_frame(fd, start_frame, 4);

    // LED frames
    for (int i = 0; i < NUM_LEDS; i++) {
        led_color_t color;
        color.red = brightness;
        color.green = brightness;
        color.blue = brightness;

        uint8_t led_frame[4];
        led_frame[0] = color.red;
        led_frame[1] = color.green;
        led_frame[2] = color.blue;
        led_frame[3] = 0xE0; // Global brightness (max)

        send_apa102_frame(fd, led_frame, 4);
    }

    // End frame
    send_apa102_frame(fd, end_frame, 4);
}

// Send a frame of data to the APA102 strip
void send_apa102_frame(int fd, uint8_t *data, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)data,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, cleanup);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    printf("Initialization complete. Running...\n");

    while (!terminate) {
        // Read light level
        int light_level = read_bh1750(i2c_fd);
        if (light_level < 0) {
            fprintf(stderr, "Failed to read light level. Continuing.\n");
            usleep(100000); // 100ms
            continue;
        }

        // Map light level to brightness
        uint8_t brightness = map_light_to_brightness(light_level);

        // Set APA102 brightness
        set_apa102_brightness(spi_fd, brightness);

        // Wait before next iteration
        usleep(50000); // 50ms
    }

    return 0;
}

