int read_bh1750(int handle);
float average_readings(int valid_sensors, int *sensor_handles);
int init_apa102(int spi_handle);
void set_apa102_brightness(int spi_handle, float brightness);
void fade_brightness(int spi_handle, float target_brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read data from BH1750 sensor
int read_bh1750(int handle) {
    if (handle < 0) {
        fprintf(stderr, "Invalid I2C handle\n");
        return -1;
    }

    // Send start measurement command (High Resolution Mode)
    if (i2cWriteByteData(handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", handle);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200); // Wait 200ms

    // Read two bytes of data
    int data = i2cReadWordData(handle, 0x00);
    if (data < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", handle);
        return -1;
    }

    // Convert to lux
    return (int)data;
}

// Average valid sensor readings
float average_readings(int valid_sensors, int *sensor_handles) {
    if (valid_sensors == 0) {
        return 0.0;
    }

    int sum = 0;
    for (int i = 0; i < valid_sensors; i++) {
        int reading = read_bh1750(sensor_handles[i]);
        if (reading >= 0) {
            sum += reading;
        }
    }

    return (float)sum / valid_sensors;
}

// Initialize APA102 LED strip
int init_apa102(int spi_handle) {
    if (spi_handle < 0) {
        fprintf(stderr, "Invalid SPI handle\n");
        return -1;
    }

    // Send start frame (0x00 0x00 0x00 0x00)
