#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// WS2812B GPIO pin (BCM numbering)
#define WS2812B_GPIO 18

// Gamma correction exponent
#define GAMMA 2.2

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int veml7700_init();
float read_lux();
float apply_gamma_correction(float lux);
void set_led_brightness(float brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VEML7700 sensor
int veml7700_init() {
    // Configuration: Integration time = 100ms, Gain = 1/8
    uint16_t config_value = 0x0000; // Default configuration

    // Write configuration to the sensor
    if (i2cWriteWordData(i2c_handle, VEML7700_CONFIG, config_value) < 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register\n");
        return -1;
    }
    return 0;
}

// Read ambient light data from VEML7700
float read_lux() {
    uint16_t als_data;
    int retries = 3;

    while (retries > 0) {
        als_data = i2cReadWordData(i2c_handle, VEML7700_ALS_DATA);
        if (als_data >= 0) {
            // Convert raw data to lux (example formula, adjust as needed)
            float lux = (float)als_data * 0.0576; // Example conversion factor
            return lux;
        } else {
            fprintf(stderr, "Error reading from VEML7700 ALS data register, retrying...\n");
            gpioDelay(100); // 100ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read lux after multiple retries\n");
    return -1.0; // Indicate error
}

// Apply gamma correction to brightness value
float apply_gamma_correction(float lux) {
    return powf(lux, 1.0 / GAMMA);
}

// Set LED brightness using bit-banging
void set_led_brightness(float brightness) {
    // Convert brightness to 0-255 range
    int brightness_int = (int)(brightness * 255.0);

    // WS2812B timing parameters (in nanoseconds)
    int t0h = 350;   // 0.8us
    int t0l = 700;   // 1.6us
    int t1h = 700;   // 1.6us
    int t1l = 350;   // 0.8us
    int reset_time = 50000; // 50us reset pulse

    // Send start pulse
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
    gpioWrite(WS2812B_GPIO, 0);
    gpioDelay(reset_time);
    gpioWrite(WS2812B_GPIO, 1);
    gpioDelay(50); // Small delay after reset pulse

    // Send color data
    for (int i = 0; i < 8; i++) {
        if (brightness_int & (1 << (7 - i))) {
            gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(t1h);
            gpioWrite(WS2812B_GPIO, 0);
            gpioDelay(t1l);
        } else {
            gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
            gpioWrite(WS2812B_GPIO, 0);
            gpioDelay(t0h);
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(t0l);
        }
    }

    // Turn off the LED by setting all bits to 0
    for (int i = 0; i < 24; i++) {
        gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
        gpioWrite(WS2812B_GPIO, 0);
        gpioDelay(t0h);
        gpioWrite(WS2812B_GPIO, 1);
        gpioDelay(t0l);
    }

    gpioSetMode(WS2812B_GPIO, PI_INPUT); // Release the GPIO pin
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (veml7700_init() < 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ambient light
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value\n");
        } else {
            // Apply gamma correction
            float brightness = apply_gamma_correction(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            // Print lux and brightness values
            printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);
        }

        // Pause for 200ms
        gpioDelay(200);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

