    int i, flame_detected = 0;

    printf("Starting self-test...\n");

    // Blink LED twice
    for (i = 0; i < 2; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(500000); // 500 ms
        gpioWrite(LED_PIN, 0);
        gpioDelay(500000); // 500 ms
    }

