#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0
#define MAX_LUX 1000
#define SLEEP_SECONDS 1

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c(const char *bus);
int read_bh1750(int fd, float *lux);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
float map_lux_to_frequency(float lux);
void set_gpio_frequency(int pin, float frequency);
void cleanup(int signal);

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read lux value from BH1750 sensor
int read_bh1750(int fd, float *lux) {
    uint8_t command = 0x10; // Continuous high resolution mode
    uint8_t buffer[2];

    if (write(fd, &command, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(200000); // Wait for measurement (at least 180ms)

    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Map lux value to frequency
float map_lux_to_frequency(float lux) {
    float frequency = MIN_FREQUENCY + (lux / (MAX_LUX + 1)) * (MAX_FREQUENCY - MIN_FREQUENCY);
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;
    return frequency;
}

// Set GPIO pin frequency (using software PWM)
void set_gpio_frequency(int pin, float frequency) {
    if (frequency <= 0) return; // Avoid division by zero

    long period_ns = 1000000000L / frequency; // Period in nanoseconds
    long high_time_ns = period_ns / 2;         // 50% duty cycle

    struct timespec high_time = {0, high_time_ns};
    struct timespec low_time = {0, period_ns - high_time_ns};

    int i = 0;
    while (program_running) {
        nanosleep(&high_time, NULL);
        nanosleep(&low_time, NULL);
        i++;
        if (i > 1000000) break; // Limit the number of cycles to avoid busy-waiting
    }
}

// Cleanup function for signal handling
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    program_running = 0;

    // Unexport GPIO pin
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/unexport");
        exit(1);
    }

    len = snprintf(buffer, sizeof(buffer), "%d", GPIO_PIN);
    if (write(fd, buffer, len) < 0) {
        perror("Error writing to /sys/class/gpio/unexport");
        close(fd);
        exit(1);
    }

    close(fd);

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    exit(0);
}

int main() {
    // Install signal handler
    signal(SIGINT, cleanup);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        close(i2c_fd);
        return 1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", GPIO_PIN);
    if (write(fd, buffer, len) < 0) {
        perror("Error writing to /sys/class/gpio/export");
        close(fd);
        close(i2c_fd);
        return 1;
    }

    close(fd);

    // Set GPIO direction to output
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        close(i2c_fd);
        return 1;
    }

    if (write(fd, "out", 3) < 0) {
        perror("Error writing to GPIO direction file");
        close(fd);
        close(i2c_fd);
        return 1;
    }

    close(fd);

    // Initialize circular buffer
    CircularBuffer lux_buffer = {{0.0}, 0, 0};

    // Main loop
    while (program_running) {
        float lux = 0.0;
        int read_attempts = 0;
        int max_attempts = 3;

        // Retry reading sensor data
        while (read_attempts < max_attempts) {
            if (read_bh1750(i2c_fd, &lux) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Error reading sensor data. Attempt %d of %d\n", read_attempts + 1, max_attempts);
                read_attempts++;
                sleep(1); // Wait before retrying
            }
        }

        if (read_attempts == max_attempts) {
            fprintf(stderr, "Failed to read sensor data after %d attempts. Skipping.\n", max_attempts);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Add lux value to circular buffer
        add_to_buffer(&lux_buffer, lux);

        // Calculate average lux
        float average_lux = calculate_average(&lux_buffer);

        // Map lux to frequency
        float frequency = map_lux_to_frequency(average_lux);

        // Set GPIO frequency
        set_gpio_frequency(GPIO_PIN, frequency);

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    return 0;
}

