        // Add lux value to circular buffer
        add_to_buffer(&lux_buffer, lux);

        // Calculate average lux
        float average_lux = calculate_average(&lux_buffer);

        // Map lux to frequency
        float frequency = map_lux_to_frequency(average_lux);

        // Set GPIO frequency
        set_gpio_frequency(GPIO_PIN, frequency);

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    return 0;
}

