// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment mapping
const int segments[] = {4, 1, 22, 23, 24, 25, 12, 21}; // GPIO pins for segments a-g, dp

// Define digit patterns (common cathode)
