#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <linux/gpiod.h>
#include <poll.h>
#include <signal.h>
#include <time.h>

#include <stdint.h>

#define	TRUE	(1==1)
#define	FALSE	(!TRUE)

#define	LED		17
#define	BUTTON	18

static volatile int	running = 1 ;
static struct gpiod_chip	*chip ;
static struct gpiod_line	*ledLine, *buttonLine ;
static struct gpiod_line_request_config buttonConfig ;

static void sigIntHandler (int sig)
{
  printf ("SigInt: Cleaning up and exiting\n") ;
  running = 0 ;
}

static int buttonISR (unsigned int data)
{
  static int		pressed = FALSE ;
  static struct timespec	pressTime, releaseTime ;
  int			ret ;

  if (data == 0)
  {
    clock_gettime (CLOCK_MONOTONIC, &pressTime) ;
    pressed = TRUE ;
  }
  else
  {
    if (pressed)
    {
      clock_gettime (CLOCK_MONOTONIC, &releaseTime) ;
      if ((releaseTime.tv_sec - pressTime.tv_sec) < 1)
      {
	printf ("Button Pressed\n") ;
	ledLine_set_value (ledLine, 0) ;
	running = 0 ;
      }
      pressed = FALSE ;
    }
  }

  return 0 ;
}

int main (int argc, char *argv [])
{
  struct timespec		ledOn, ledOff ;
  struct pollfd			pollFD ;
  int				ret ;
  int				irq ;

  signal (SIGINT, sigIntHandler) ;

  if ((chip = gpiod_chip_open_by_name ("gpiochip0")) == NULL)
  {
    fprintf (stderr, "Unable to open GPIO chip: %s\n", strerror (errno)) ;
    exit (EXIT_FAILURE) ;
  }

  if ((ledLine = gpiod_chip_get_line (chip, LED)) == NULL)
  {
    fprintf (stderr, "Unable to open GPIO line %d: %s\n", LED, strerror (errno)) ;
    exit (EXIT_FAILURE) ;
  }

  if ((buttonLine = gpiod_chip_get_line (chip, BUTTON)) == NULL)
  {
    fprintf (stderr, "Unable to open GPIO line %d: %s\n", BUTTON, strerror (errno)) ;
    exit (EXIT_FAILURE) ;
  }

  if (gpiod_line_request_output (ledLine, "blink_button", 0) < 0)
  {
    fprintf (stderr, "Unable to request GPIO line %d as output: %s\n", LED, strerror (errno)) ;
    exit (EXIT_FAILURE) ;
  }

  if (gpiod_line_request_input (buttonLine, "blink_button", 1) < 0)
  {
    fprintf (stderr, "Unable to request GPIO line %d as input: %s\n", BUTTON, strerror (errno)) ;
    exit (EXIT_FAILURE) ;
  }

  ledOn.tv_sec = 1 ;
  ledOn.tv_nsec = 0 ;
  ledOff.tv_sec = 1 ;
  ledOff.tv_nsec = 0 ;

  while (running)
  {
    ledLine_set_value (ledLine, 1) ;
    nanosleep (&ledOn, NULL) ;

    ledLine_set_value (ledLine, 0) ;
    nanosleep (&ledOff, NULL) ;

    pollFD.fd = gpiod_line_get_fd (buttonLine) ;
    pollFD.events = POLLPRI | POLLERR ;

    ret = poll (&pollFD, 1, 1000) ;

    if (ret < 0)
    {
      if (errno == EINTR)
	break ;
      fprintf (stderr, "poll failed: %s\n", strerror (errno)) ;
      break ;
    }

    if (ret > 0)
    {
      if (pollFD.revents & POLLPRI)
      {
	irq = gpiod_line_event (buttonLine) ;
	if (irq < 0)
	{
	  fprintf (stderr, "gpiod_line_event failed: %s\n", strerror (errno)) ;
	  break ;
	}

	if (irq > 0)
	{
	  buttonISR (irq) ;
	}
	else if (irq < 0)
	{
	  buttonISR (irq) ;
	}
      }
      else if (pollFD.revents & POLLERR)
      {
	fprintf (stderr, "GPIO poll error\n") ;
	break ;
      }
    }
  }

  gpiod_line_release (ledLine) ;
  gpiod_line_release (buttonLine) ;
  gpiod_chip_close (chip) ;

  exit (EXIT_SUCCESS) ;
}

