#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <wiringPi.h>

#define	LED		1
#define	BUTTON	2

int main (void)
{
  int buttonState = 0 ;
  int ledState = 0 ;
  int buttonValue ;

  printf ("Raspberry Pi - Blinking LED\n") ;
  printf ("============================\n") ;

  if (wiringPiSetup () == -1)
    exit (1) ;

  pinMode (LED, OUTPUT) ;
  pinMode (BUTTON, INPUT) ;
  pullUpDnControl (BUTTON, PUD_UP) ;

  printf ("Press the button to blink the LED\n") ;

  for (;;)
  {
    buttonValue = digitalRead (BUTTON) ;

    if (buttonValue != buttonState)
    {
      buttonState = buttonValue ;

      if (buttonState == LOW)
      {
	ledState = !ledState ;
	digitalWrite (LED, ledState) ;
	delay (500) ;
      }
      else
      {
	digitalWrite (LED, LOW) ;
	delay (500) ;
      }
    }
  }

  return 0 ;
}

