#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for impact interrupt
#define IMPACT_GPIO 17

// Default impact threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double impact_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int init_gpio();
int read_accelerometer(accelerometer_data_t *data);
double calculate_magnitude(accelerometer_data_t data);
void handle_impact();
void log_data(accelerometer_data_t data, double magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure accelerometer (10 Hz, normal mode, all axes enabled)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Initialize GPIO pin
int init_gpio() {
    if (gpioSetMode(IMPACT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer(accelerometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", i2c_handle);
        return -1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate G-force magnitude
double calculate_magnitude(accelerometer_data_t data) {
    double x = (double)data.x / 16384.0; // Assuming +/- 2G sensitivity
    double y = (double)data.y / 16384.0;
    double z = (double)data.z / 16384.0;
    return sqrt(x * x + y * y + z * z);
}

// Handle impact
void handle_impact() {
    gpioWrite(IMPACT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(50000);          // Wait 50ms
    gpioWrite(IMPACT_GPIO, 0); // Set GPIO LOW
}

// Log data to file
void log_data(accelerometer_data_t data, double magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", s, data.x, data.y, data.z, magnitude);
    fclose(fp);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioSetMode(IMPACT_GPIO, PI_INPUT); // Set back to input
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    accelerometer_data_t data;
    double magnitude;

    printf("Monitoring impact... Threshold: %.2f G\n", impact_threshold);

    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&data) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(data);

            // Check for impact
            if (magnitude > impact_threshold) {
                printf("Impact detected! Magnitude: %.2f G\n", magnitude);
                handle_impact();
                log_data(data, magnitude);
            }

            // Log data
            log_data(data, magnitude);
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        gpioDelay(100000); // 10 Hz (100ms delay)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

