#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_REG 0x00
#define RED_REG 0x02
#define GREEN_REG 0x04
#define BLUE_REG 0x06
#define GPIO_LED 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
uint16_t combine_als(uint8_t lsb, uint8_t msb);
void control_led(uint16_t als_value);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[8];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Read ALS
        if (i2cReadI2CBlockData(i2c_handle, ALS_REG, (char *)buffer, 8) != 8) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            retries++;
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Combine ALS data
        data->als = combine_als(buffer[1], buffer[0]);
        data->red = (uint16_t)buffer[3] << 8 | buffer[2];
        data->green = (uint16_t)buffer[5] << 8 | buffer[4];
        data->blue = (uint16_t)buffer[7] << 8 | buffer[6];

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Combine ALS LSB and MSB into a 16-bit unsigned value
uint16_t combine_als(uint8_t lsb, uint8_t msb) {
    return (uint16_t)msb << 8 | lsb;
}

// Control LED brightness using hardware PWM
void control_led(uint16_t als_value) {
    // Map ALS value to PWM duty cycle (0-1000)
    int duty_cycle = (int)(((float)als_value / 65535.0) * PWM_RANGE);

    // Ensure duty cycle is within valid range
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(GPIO_LED, duty_cycle);
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.als, data.red, data.green, data.blue);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set GPIO back to input mode
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_LED, PWM_RANGE);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            control_led(sensor_data.als);
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

