#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define FXOS8700CQ_ADDR 0x1F
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0xC7
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define XYZ_DATA_CFG 0x0E
#define STATUS 0x00
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define IMPACT_THRESHOLD 2.0f // g
#define ODR_200HZ 0x02
#define RANGE_2G 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int verify_who_am_i();
int configure_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z);
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i() != 0) {
        fprintf(stderr, "WHO_AM_I verification failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;
    float magnitude;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            // Calculate acceleration magnitude
            magnitude = calculate_acceleration_magnitude(sensor_data.x, sensor_data.y, sensor_data.z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                if (log_impact(sensor_data.x, sensor_data.y, sensor_data.z, magnitude) != 0) {
                    fprintf(stderr, "Failed to log impact\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Verify WHO_AM_I register
int verify_who_am_i() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return 1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return 1;
    }
    printf("WHO_AM_I verification successful\n");
    return 0;
}

// Configure the sensor
int configure_sensor() {
    // Standby mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %d\n", i2c_handle);
        return 1;
    }
    gpioDelay(1000); // 1ms delay

    // Set range to ±2g
    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, RANGE_2G) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG (range): %d\n", i2c_handle);
        return 1;
    }
    gpioDelay(1000); // 1ms delay

    // Set output data rate to 200 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, ODR_200HZ) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (ODR): %d\n", i2c_handle);
        return 1;
    }
    gpioDelay(1000); // 1ms delay

    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (enable): %d\n", i2c_handle);
        return 1;
    }
    gpioDelay(1000); // 1ms delay

    printf("Sensor configured successfully\n");
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return 1;
    }

    // Combine MSB and LSB for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate acceleration magnitude
float calculate_acceleration_magnitude(int16_t x, int16_t y, int16_t z) {
    // Convert raw values to g (assuming ±2g range)
    float x_g = (float)x / 4096.0f; // 2^12 = 4096
    float y_g = (float)y / 4096.0f;
    float z_g = (float)z / 4096.0f;

    return (float)sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact to file
int log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, (float)x, (float)y, (float)z, magnitude);
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed, exiting...\n");
}

