#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDRESS 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SAMPLE_PERIOD_US 5000 // 50ms
#define NUM_SAMPLES 100
#define ALERT_THRESHOLD 50.0f
#define GYRO_SENSITIVITY 0.00875f // 8.75 mdps/digit

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int verify_sensor();
int configure_gyro();
gyro_data_t read_gyro_data();
void calibrate_gyro(gyro_data_t *data, float *x_offset, float *y_offset, float *z_offset);
void apply_offsets(gyro_data_t raw_data, float x_offset, float y_offset, float z_offset, gyro_data_t *calibrated_data);
int log_data(gyro_data_t data);
void check_alert(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor presence
int verify_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }
    printf("Gyroscope sensor verified!\n");
    return 0;
}

// Configure gyroscope
int configure_gyro() {
    // Enable all axes and set data rate to 100Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", i2c_handle);
        return -1;
    }

    // Set full-scale range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read raw gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) < 0) { // Enable auto-increment
        fprintf(stderr, "Error reading gyro data: %d\n", i2c_handle);
        data.x = 0.0f;
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    data.x = (float)x;
    data.y = (float)y;
    data.z = (float)z;

    return data;
}

// Calibrate gyroscope
void calibrate_gyro(gyro_data_t *data, float *x_offset, float *y_offset, float *z_offset) {
    float x_sum = 0.0f;
    float y_sum = 0.0f;
    float z_sum = 0.0f;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < NUM_SAMPLES; i++) {
        data[i] = read_gyro_data();
        x_sum += data[i].x;
        y_sum += data[i].y;
        z_sum += data[i].z;
        gpioDelay(SAMPLE_PERIOD_US);
    }

    *x_offset = x_sum / NUM_SAMPLES;
    *y_offset = y_sum / NUM_SAMPLES;
    *z_offset = z_sum / NUM_SAMPLES;

    printf("Calibration complete.\n");
    printf("X offset: %f\n", *x_offset);
    printf("Y offset: %f\n", *y_offset);
    printf("Z offset: %f\n", *z_offset);
}

// Apply offsets to raw data
void apply_offsets(gyro_data_t raw_data, float x_offset, float y_offset, float z_offset, gyro_data_t *calibrated_data) {
    calibrated_data->x = raw_data.x - x_offset;
    calibrated_data->y = raw_data.y - y_offset;
    calibrated_data->z = raw_data.z - z_offset;
}

// Log data to file
int log_data(gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f,%.4f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file);

    return 0;
}

// Check for alert condition
void check_alert(gyro_data_t data) {
    if (fabs(data.x) > ALERT_THRESHOLD) {
        fprintf(stderr, "ALERT: X axis exceeded threshold (%.2f dps)\n", data.x);
        fprintf(log_file, "ALERT: X axis exceeded threshold (%.2f dps)\n", data.x);
    }
    if (fabs(data.y) > ALERT_THRESHOLD) {
        fprintf(stderr, "ALERT: Y axis exceeded threshold (%.2f dps)\n", data.y);
        fprintf(log_file, "ALERT: Y axis exceeded threshold (%.2f dps)\n", data.y);
    }
    if (fabs(data.z) > ALERT_THRESHOLD) {
        fprintf(stderr, "ALERT: Z axis exceeded threshold (%.2f dps)\n", data.z);
        fprintf(log_file, "ALERT: Z axis exceeded threshold (%.2f dps)\n", data.z);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure gyroscope
    if (configure_gyro() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate gyroscope
    gyro_data_t gyro_data[NUM_SAMPLES];
    float x_offset, y_offset, z_offset;
    calibrate_gyro(gyro_data, &x_offset, &y_offset, &z_offset);

    // Main loop
    gyro_data_t raw_data, calibrated_data;
    while (!terminate) {
        // Read raw data
        raw_data = read_gyro_data();

        // Apply offsets
        apply_offsets(raw_data, x_offset, y_offset, z_offset, &calibrated_data);

        // Log data
        log_data(calibrated_data);

        // Check for alert condition
        check_alert(calibrated_data);

        // Delay
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

