    float x_offset, y_offset, z_offset;
    calibrate_gyro(gyro_data, &x_offset, &y_offset, &z_offset);

    // Main loop
    gyro_data_t raw_data, calibrated_data;
    while (!terminate) {
        // Read raw data
        raw_data = read_gyro_data();

        // Apply offsets
        apply_offsets(raw_data, x_offset, y_offset, z_offset, &calibrated_data);

        // Log data
        log_data(calibrated_data);

        // Check for alert condition
        check_alert(calibrated_data);

        // Delay
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

