#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

// LSM303DLHC register addresses
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A  0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M  0x03

// Scaling factors
#define ACCEL_SCALE 0.001 // +/- 2g range
#define MAG_SCALE 0.00014 // +/- 1.3 Gauss range

// Global variables
int i2c_handle_accel;
int i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lsm303();
int read_accel_data(int16_t *x, int16_t *y, int16_t *z);
int read_mag_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z);
void log_data(float heading, int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the LSM303DLHC sensor
int init_lsm303() {
    // Initialize accelerometer
    if (i2cWriteByteData(i2c_handle_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) { // Enable all axes, 50Hz data rate
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }

    // Initialize magnetometer
    if (i2cWriteByteData(i2c_handle_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) { // Continuous conversion mode
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) < 0) { // Read multiple bytes with auto-increment
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Read magnetometer data
int read_mag_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, LSM303_MAG_OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to file
void log_data(float heading, int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d,%d,%d,%d,%d\n", timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C bus for accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C bus for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303DLHC
    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z;
    int16_t mag_x, mag_y, mag_z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_accel_data(&accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (read_mag_data(&mag_x, &mag_y, &mag_z) < 0) {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate heading
        heading = calculate_heading(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Log data
        log_data(heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Wait 100ms
        gpioDelay(100);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

