// Read distance from VL6180X sensor
int read_distance() {
    int distance = -1;
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01) < 0) {
            fprintf(stderr, "Error writing to SYSRANGE_START register\n");
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        gpioDelay(5000); // Wait 5ms for measurement

        int range = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_VAL);
        if (range < 0) {
            fprintf(stderr, "Error reading from RESULT_RANGE_VAL register\n");
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        distance = range;
        break; // Exit retry loop on success
    }

    if (distance == -1) {
        fprintf(stderr, "Failed to read distance after multiple retries\n");
    }

    return distance;
}

// Log data to file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately

    if (distance < 100) {
        fprintf(log_file, "%s, DOOR_OPEN\n", timestamp);
    } else {
        fprintf(log_file, "%s, DOOR_CLOSED\n", timestamp);
    }
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL6180X sensor
    if (init_vl6180x() < 0) {
        fprintf(stderr, "VL6180X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int distance = read_distance();
        if (distance != -1) {
            log_data(distance);
        }
        gpioDelay(100000); // 100ms delay
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

