#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define I2C addresses for the two sensors
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define the I2C bus
#define I2C_BUS 1

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 10

// Define the number of bytes to read from each sensor
#define NUM_BYTES 2

// Global variables for I2C handles and log file
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Structure to hold sensor data and timestamp
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int i2c_bus, int i2c_address);
int read_sensor_data(int i2c_handle, int16_t *sample);
int calculate_tdoa(int16_t sensor1_sample, int16_t sensor2_sample);
int log_data(FILE *log_file, struct timespec timestamp, int16_t sensor1_sample, int16_t sensor2_sample, int tdoa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close the log file if it is open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C device
int open_i2c_device(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", i2c_address, handle);
        return -1;
    }
    return handle;
}

// Function to read data from a sensor
int read_sensor_data(int i2c_handle, int16_t *sample) {
    char buffer[NUM_BYTES];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, NUM_BYTES);

    if (bytes_read != NUM_BYTES) {
        fprintf(stderr, "Failed to read data from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *sample = (int16_t)((buffer[1] << 8) | buffer[0]);
    return 0;
}

// Function to calculate the TDOA
int calculate_tdoa(int16_t sensor1_sample, int16_t sensor2_sample) {
    // Simple TDOA calculation: difference in samples
    return abs(sensor1_sample - sensor2_sample);
}

// Function to log data to a file
int log_data(FILE *log_file, struct timespec timestamp, int16_t sensor1_sample, int16_t sensor2_sample, int tdoa) {
    if (fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", timestamp.tv_sec, timestamp.tv_nsec, sensor1_sample, sensor2_sample, tdoa) < 0) {
        fprintf(stderr, "Failed to write data to log file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = open_i2c_device(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = open_i2c_device(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from sensors
        int16_t sensor1_sample, sensor2_sample;

        if (read_sensor_data(i2c_handle1, &sensor1_sample) != 0) {
            fprintf(stderr, "Error reading sensor 1, skipping sample\n");
            continue;
        }

        if (read_sensor_data(i2c_handle2, &sensor2_sample) != 0) {
            fprintf(stderr, "Error reading sensor 2, skipping sample\n");
            continue;
        }

        // Get timestamp
        struct timespec timestamp;
        if (clock_gettime(CLOCK_REALTIME, &timestamp) == -1) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue;
        }

        // Calculate TDOA
        int tdoa = calculate_tdoa(sensor1_sample, sensor2_sample);

        // Log data
        if (log_data(log_file, timestamp, sensor1_sample, sensor2_sample, tdoa) != 0) {
            fprintf(stderr, "Error logging data, skipping sample\n");
            continue;
        }

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

