#define REG_ACCEL_ZOUT 0x0E
#define REG_SMPL_PRD  0x36
#define REG_GLOB_CMD  0x68
#define REG_DIAG_STS  0x56

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Function Prototypes
int adis16488_read_register(int spi_handle, uint8_t reg_address, uint16_t *data);
int adis16488_write_register(int spi_handle, uint8_t reg_address, uint16_t data);
int adis16488_read_gyro_accel_data(int spi_handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
int adis16488_convert_data(uint16_t raw_data, float *converted_data);
int adis16488_initialize(int spi_handle);
