void signal_handler(int signal);

// Structure to hold IMU data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} imu_data_t;

// Function to read a register from the ADIS16488A
int adis16488_read_register(int spi_handle, uint8_t reg_address, uint16_t *data) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the command word (MSB = 0, register address, dummy byte)
    tx_buffer[0] = 0x00; // Command MSB
    tx_buffer[1] = reg_address; // Register address
    tx_buffer[2] = 0x00; // Dummy byte

    gpioDelay(40000); // 40 us stall time

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 3) {
        fprintf(stderr, "Error: spiXfer failed (read) with code %d\n", result);
        return -1;
    }

    // Combine the received bytes into a 16-bit value
    *data = (rx_buffer[1] << 8) | rx_buffer[2];

    return 0;
}

// Function to write a register in the ADIS16488A
int adis16488_write_register(int spi_handle, uint8_t reg_address, uint16_t data) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the command word (MSB = 1, register address, data)
    tx_buffer[0] = 0x01; // Command MSB
    tx_buffer[1] = reg_address; // Register address
    tx_buffer[2] = (data >> 8) & 0xFF; // Data MSB

    gpioDelay(40000); // 40 us stall time

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 3) {
        fprintf(stderr, "Error: spiXfer failed (write) with code %d\n", result);
        return -1;
    }

    // Combine the received bytes into a 16-bit value
    *rx_buffer = (rx_buffer[1] << 8) | rx_buffer[2];

    return 0;
}

// Function to read gyroscope and accelerometer data
int adis16488_read_gyro_accel_data(int spi_handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (adis16488_read_register(spi_handle, REG_GYRO_XOUT, &raw_gyro_x) != 0) return -1;
    if (adis16488_read_register(spi_handle, REG_GYRO_YOUT, &raw_gyro_y) != 0) return -1;
    if (adis16488_read_register(spi_handle, REG_GYRO_ZOUT, &raw_gyro_z) != 0) return -1;
    if (adis16488_read_register(spi_handle, REG_ACCEL_XOUT, &raw_accel_x) != 0) return -1;
    if (adis16488_read_register(spi_handle, REG_ACCEL_YOUT, &raw_accel_y) != 0) return -1;
    if (adis16488_read_register(spi_handle, REG_ACCEL_ZOUT, &raw_accel_z) != 0) return -1;

    if (adis16488_convert_data(raw_gyro_x, gyro_x) != 0) return -1;
    if (adis16488_convert_data(raw_gyro_y, gyro_y) != 0) return -1;
    if (adis16488_convert_data(raw_gyro_z, gyro_z) != 0) return -1;
    if (adis16488_convert_data(raw_accel_x, accel_x) != 0) return -1;
    if (adis16488_convert_data(raw_accel_y, accel_y) != 0) return -1;
    if (adis16488_convert_data(raw_accel_z, accel_z) != 0) return -1;

