    *converted_data = (float)raw_data * 0.005; // Gyroscope
    return 0;
}

// Function to initialize the ADIS16488A
int adis16488_initialize(int spi_handle) {
    // Reset the device
    if (adis16488_write_register(spi_handle, REG_GLOB_CMD, 0x0004) != 0) {
        fprintf(stderr, "Error: Failed to reset device\n");
