        fprintf(stderr, "Error: Failed to set sample period\n");
        return -1;
    }

    return 0;
}

// Cleanup function to close SPI and file
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
