    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec ts;
    struct timespec req = {0, 100000000}; // 100 ms
    imu_data_t imu_data;
    int retry_count = 0;
    const int max_retries = 3;

    while (running) {
        // Read IMU data
        if (adis16488_read_gyro_accel_data(spi_handle, &imu_data.gyro_x, &imu_data.gyro_y, &imu_data.gyro_z, &imu_data.accel_x, &imu_data.accel_y, &imu_data.accel_z) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Log data to CSV file
                fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                        ts.tv_sec, ts.tv_nsec,
                        imu_data.gyro_x, imu_data.gyro_y, imu_data.gyro_z,
                        imu_data.accel_x, imu_data.accel_y, imu_data.accel_z);
                fflush(fp); // Ensure data is written to file immediately
                retry_count = 0; // Reset retry count on success
            } else {
                fprintf(stderr, "Error: clock_gettime failed\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read IMU data, retry %d/%d\n", retry_count + 1, max_retries);
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Error: Max retries reached, exiting\n");
                running = 0; // Exit the loop after max retries
            }
        }

        // Delay using nanosleep
        nanosleep(&req, NULL);
    }

    return 0;
}

