#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define GYRO_XOUT 0x04
#define GYRO_YOUT 0x06
#define GYRO_ZOUT 0x08
#define ACCEL_XOUT 0x0A
#define ACCEL_YOUT 0x0C
#define ACCEL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8 // GPIO8 (BCM)

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a register from the ADIS16448
int read_register(int spi_handle, uint8_t register_address, int16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Set bit 7 of the register address to indicate a read operation
    tx_buffer[0] = (register_address | 0x80) & 0xFF; // Ensure it's an 8-bit value
    tx_buffer[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X\n", register_address);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *data = (rx_buffer[0] << 8) | rx_buffer[1];

    return 0;
}

// Function to convert raw data to physical units
void convert_data(int16_t raw_data, float *scaled_data) {
    // Gyroscope scale: 0.02 dps/LSB
    *scaled_data = (float)raw_data * 0.02;

    // Accelerometer scale: 0.00025 g/LSB
    *scaled_data /= 1000.0; // Convert g to dps for comparison
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate CS initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
        int16_t accel_x_raw, accel_y_raw, accel_z_raw;
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Read gyroscope data
        if (read_register(spi_handle, GYRO_XOUT, &gyro_x_raw) != 0) {
            fprintf(stderr, "Error reading GYRO_XOUT\n");
            continue; // Skip to the next iteration
        }
        if (read_register(spi_handle, GYRO_YOUT, &gyro_y_raw) != 0) {
            fprintf(stderr, "Error reading GYRO_YOUT\n");
            continue;
        }
        if (read_register(spi_handle, GYRO_ZOUT, &gyro_z_raw) != 0) {
            fprintf(stderr, "Error reading GYRO_ZOUT\n");
            continue;
        }

        // Read accelerometer data
        if (read_register(spi_handle, ACCEL_XOUT, &accel_x_raw) != 0) {
            fprintf(stderr, "Error reading ACCEL_XOUT\n");
            continue;
        }
        if (read_register(spi_handle, ACCEL_YOUT, &accel_y_raw) != 0) {
            fprintf(stderr, "Error reading ACCEL_YOUT\n");
            continue;
        }
        if (read_register(spi_handle, ACCEL_ZOUT, &accel_z_raw) != 0) {
            fprintf(stderr, "Error reading ACCEL_ZOUT\n");
            continue;
        }

        // Convert raw data to physical units
        convert_data(gyro_x_raw, &gyro_x);
        convert_data(gyro_y_raw, &gyro_y);
        convert_data(gyro_z_raw, &gyro_z);
        convert_data(accel_x_raw, &accel_x);
        convert_data(accel_y_raw, &accel_y);
        convert_data(accel_z_raw, &accel_z);

        // Log the data to the console
        printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps  |  Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close SPI device
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

