#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the MPU-6886
int16_t read_mpu6886_value(int i2c_handle, uint8_t reg)
{
    int retries = 3;
    int16_t value = 0;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, reg);
        if (result >= 0) {
            value = (int16_t)result;
            return value;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6886 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer values
        int16_t accel_x = read_mpu6886_value(i2c_handle, ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6886_value(i2c_handle, ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6886_value(i2c_handle, ACCEL_XOUT_H + 4);

        // Read gyroscope values
        int16_t gyro_x = read_mpu6886_value(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = read_mpu6886_value(i2c_handle, GYRO_XOUT_H + 2);
        int16_t gyro_z = read_mpu6886_value(i2c_handle, GYRO_XOUT_H + 4);

        // Print the values
        printf("Accel: X=%6d, Y=%6d, Z=%6d  ", accel_x, accel_y, accel_z);
        printf("Gyro: X=%6d, Y=%6d, Z=%6d\n", gyro_x, gyro_y, gyro_z);

        // Wait 50 ms
        gpioDelay(50000);
    }

    // This point will not be reached unless there's an error or the program is interrupted.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

