#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define LED_GPIO 17
#define ACCEL_SCALE 256.0f // LSB/g for ±2g range
#define ACCEL_THRESHOLD 2.5f // g
#define SAMPLE_PERIOD 0.01f // 10 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_adxl345();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void control_led(int on);
void log_event(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize ADXL345
int init_adxl345() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, 0x00);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%X\n", device_id);
        return -1;
    }

    // Set data format: full resolution, ±2g range
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int result = i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g units
    *x = (float)x_raw / ACCEL_SCALE;
    *y = (float)y_raw / ACCEL_SCALE;
    *z = (float)z_raw / ACCEL_SCALE;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log event to file
void log_event(float x, float y, float z, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n",
            timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z, magnitude;

    // Main loop
