        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

