#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x1A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define LED_GPIO 17
#define ACCEL_RANGE_2G 1024.0f
#define ACCEL_SENSITIVITY 0.244f // mg/LSB for +/- 2g range
#define THRESHOLD 2.0f
#define LED_ON_TIME 500 // milliseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mma8451q();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_data(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize MMA8451Q accelerometer
int init_mma8451q() {
    // Set to active mode, 100 Hz data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from MMA8451Q
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char raw_data[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((raw_data[0] << 8) | raw_data[1]) >> 2;
    *y = (int16_t)((raw_data[2] << 8) | raw_data[3]) >> 2;
    *z = (int16_t)((raw_data[4] << 8) | raw_data[5]) >> 2;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = x * ACCEL_SENSITIVITY / 1000.0f;
    float y_g = y * ACCEL_SENSITIVITY / 1000.0f;
    float z_g = z * ACCEL_SENSITIVITY / 1000.0f;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %d, %d, %.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0 || who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("MMA8451Q WHO_AM_I value: 0x%02X (Expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);

    // Initialize accelerometer
    if (init_mma8451q() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                gpioWrite(LED_GPIO, 1); // Turn LED on
                gpioDelay(LED_ON_TIME * 1000); // Wait for 500ms
                gpioWrite(LED_GPIO, 0); // Turn LED off
            }

            log_data(x, y, z, magnitude);
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

