    *x = (int16_t)((raw_data[0] << 8) | raw_data[1]) >> 2;
    *y = (int16_t)((raw_data[2] << 8) | raw_data[3]) >> 2;
    *z = (int16_t)((raw_data[4] << 8) | raw_data[5]) >> 2;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = x * ACCEL_SENSITIVITY / 1000.0f;
    float y_g = y * ACCEL_SENSITIVITY / 1000.0f;
    float z_g = z * ACCEL_SENSITIVITY / 1000.0f;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %d, %d, %.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0 || who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("MMA8451Q WHO_AM_I value: 0x%02X (Expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);

    // Initialize accelerometer
    if (init_mma8451q() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                gpioWrite(LED_GPIO, 1); // Turn LED on
                gpioDelay(LED_ON_TIME * 1000); // Wait for 500ms
                gpioWrite(LED_GPIO, 0); // Turn LED off
            }

            log_data(x, y, z, magnitude);
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

