#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <stdbool.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH_FF 0x28
#define ADXL345_REG_TIME_FF 0x29
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_POWER_CTL 0x2D

// GPIO pin for interrupt
#define GPIO_PIN 17

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int adxl345_init(int fd);
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// I2C read byte function
int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return value;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    // Verify device ID
    int devid = i2c_read_byte(fd, ADXL345_REG_DEVID);
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set free-fall threshold
    if (i2c_write_byte(fd, ADXL345_REG_THRESH_FF, 0x0A) != 0) {
        fprintf(stderr, "Error: Failed to set free-fall threshold\n");
        return -1;
    }

    // Set free-fall time
    if (i2c_write_byte(fd, ADXL345_REG_TIME_FF, 0x20) != 0) {
        fprintf(stderr, "Error: Failed to set free-fall time\n");
        return -1;
    }

    // Enable free-fall interrupt
    if (i2c_write_byte(fd, ADXL345_REG_INT_ENABLE, 0x40) != 0) {
        fprintf(stderr, "Error: Failed to enable free-fall interrupt\n");
        return -1;
    }

    // Put ADXL345 in standby mode
    if (i2c_write_byte(fd, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error: Failed to set standby mode\n");
        return -1;
    }

    return 0;
}

// ADXL345 read acceleration function
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    uint8_t reg = ADXL345_REG_DATAX0;

    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("I2C read failed");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Log data to file function
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s.%03d,%d,%d,%d\n", timestamp, (int)(time() * 1000) % 1000, x, y, z);
    fflush(fp);

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    if (level == 0) { // Falling edge
        int16_t x, y, z;
        if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data in interrupt handler\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;

    // Disable interrupt
    gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, NULL, NULL);

    // Close I2C file descriptor
    close(i2c_fd);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error: Could not set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "w");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Milliseconds,X,Y,Z\n");

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Could not set interrupt handler\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1);
    }

    return 0;
}

