#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_XL 0x28

// Accelerometer and gyroscope scales
#define ACCEL_SCALE 0.061  // mg/LSB for ±2g range
#define GYRO_SCALE 8.75   // mdps/LSB for ±250 dps range

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2  // g
#define IMPACT_THRESHOLD 2.5   // g
#define FREEFALL_DURATION 0.5  // seconds
#define IMPACT_WINDOW 1.0      // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, LSM6DSR_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: ±2g, 104 Hz
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL1_XL, 0x80) < 0) { // 104 Hz, 2g
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: ±250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL2_G, 0x80) < 0) { // 104 Hz, 250 dps
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data from the LSM6DSR
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }
    raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g and dps
    data->accel_x = (float)raw_accel_x * ACCEL_SCALE / 1000.0f;
    data->accel_y = (float)raw_accel_y * ACCEL_SCALE / 1000.0f;
    data->accel_z = (float)raw_accel_z * ACCEL_SCALE / 1000.0f;
    data->gyro_x = (float)raw_gyro_x * GYRO_SCALE / 1000.0f;
    data->gyro_y = (float)raw_gyro_y * GYRO_SCALE / 1000.0f;
    data->gyro_z = (float)raw_gyro_z * GYRO_SCALE / 1000.0f;

    return 0;
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Implement fall detection state machine
void fall_detection(sensor_data_t data) {
    static int freefall_start_time = 0;
    static int impact_detected = 0;
    static int freefall_detected = 0;
    static time_t impact_window_start = 0;

    float accel_magnitude = sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);

    if (accel_magnitude < FREEFALL_THRESHOLD) {
        if (freefall_start_time == 0) {
            freefall_start_time = time(NULL);
        }
        if (difftime(time(NULL), freefall_start_time) >= FREEFALL_DURATION) {
            if (!freefall_detected) {
                freefall_detected = 1;
                printf("FREEFALL detected\n");
            }
        }
    } else {
        freefall_start_time = 0;
        freefall_detected = 0;
    }

    if (accel_magnitude > IMPACT_THRESHOLD) {
        if (!impact_detected) {
            impact_detected = 1;
            impact_window_start = time(NULL);
            printf("IMPACT detected\n");
        }
    } else {
        impact_detected = 0;
    }

    if (impact_detected && difftime(time(NULL), impact_window_start) <= IMPACT_WINDOW) {
        printf("FALL DETECTED\n");
    }

    if (freefall_detected && !impact_detected) {
        freefall_detected = 0;
    }
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X(g),Accel_Y(g),Accel_Z(g),Gyro_X(dps),Gyro_Y(dps),Gyro_Z(dps)\n");
    }
    rewind(log_file);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
            fall_detection(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }
        gpioDelay(10000); // 10 ms delay (104 Hz)
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

