#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define ADIS16266 register addresses
#define WHO_AM_I_REG 0x02
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Define scale factor
#define SCALE_FACTOR 0.0305 // deg/sec/LSB

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int spi_read_register(uint8_t reg_addr, uint16_t *data);
int spi_write_register(uint8_t reg_addr, uint16_t data);
int verify_who_am_i();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read a register from the ADIS16266
int spi_read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of register address to indicate read operation
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to write a register to the ADIS16266
int spi_write_register(uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    // Clear MSB of register address to indicate write operation
    tx_buf[0] = reg_addr & 0x7F;
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    tx_buf[0] = 0x00; // Dummy byte
    tx_buf[1] = (data & 0xFF); // LSB of data

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to verify the WHO_AM_I register
int verify_who_am_i() {
    uint16_t who_am_i;
    if (spi_read_register(WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x4052) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x4052, got 0x%04X\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I check passed. Device ID: 0x%04X\n", who_am_i);
    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    uint16_t raw_x, raw_y, raw_z;

    if (spi_read_register(XGYRO_OUT, &raw_x) != 0) {
        fprintf(stderr, "Error reading XGYRO_OUT register\n");
        data.x = 0.0; // Set to 0.0 in case of error
    } else {
        data.x = (float)((int16_t)raw_x) * SCALE_FACTOR;
    }

