#define WHO_AM_I_VALUE 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SENSITIVITY 8.75 // mdps/LSB
#define SAMPLE_INTERVAL_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    double x;
    double y;
    double z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to get ISO 8601 timestamp with nanosecond precision
char* get_iso8601_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t t = ts.tv_sec;
    struct tm* tm_info = localtime(&t);
    static char buffer[30]; // Increased buffer size for nanoseconds
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), ".%09ldZ", ts.tv_nsec);
    return buffer;
}

// Function to initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int result;

    // Verify WHO_AM_I register
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
        if (result >= 0 && result == WHO_AM_I_VALUE) {
            printf("Gyroscope WHO_AM_I register verified: 0x%02X\n", result);
            break;
        } else {
            fprintf(stderr, "Error: Gyroscope WHO_AM_I register check failed. Retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Gyroscope WHO_AM_I register check failed after multiple retries. Exiting.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100Hz data rate, enable all axes)
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F); // 0x0F = 0b00001111
        if (result == 0) {
            printf("CTRL_REG1 configured successfully\n");
            break;
        } else {
            fprintf(stderr, "Error: CTRL_REG1 configuration failed. Retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Error: CTRL_REG1 configuration failed after multiple retries. Exiting.\n");
        return -1;
    }

    // Configure CTRL_REG4 (Set sensitivity)
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00); // +/- 250 dps
        if (result == 0) {
            printf("CTRL_REG4 configured successfully\n");
            break;
        } else {
            fprintf(stderr, "Error: CTRL_REG4 configuration failed. Retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Error: CTRL_REG4 configuration failed after multiple retries. Exiting.\n");
        return -1;
    }

    return 0;
}

