gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;
    int result;

    // Read all six bytes at once
    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error: I2C read failed. Read %d bytes, expected 6.\n", result);
        data.x = 0.0; // Set to 0 to avoid using uninitialized values
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, and convert to double
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    data.x = (double)raw_x / 114.285; // Convert to mdps
    data.y = (double)raw_y / 114.285;
    data.z = (double)raw_z / 114.285;

    return data;
}

// Function to log data to a CSV file
void log_data(gyro_data_t data) {
    char* timestamp = get_iso8601_timestamp();
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

