// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x4C

// Define the register addresses for X, Y, and Z axes
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL 100

// Define the error value for sensor absence
#define SENSOR_ABSENCE_ERROR 0xFFFF

// Global variables for I2C handle and file pointer
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the D7S-0001
int read_sensor_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result;

    // Read X axis data
    result = i2cReadI2CBlockData(i2c_handle, REG_X_LSB, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine LSB and MSB for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to log data to the CSV file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Cleaning up...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header line if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    // Main loop to sample and log data
    int16_t x, y, z;
    while (1) {
        if (read_sensor_data(i2c_handle, &x, &y, &z) == 0) {
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping sample.\n");
        }

        gpioDelay(SAMPLING_INTERVAL * 1000); // Delay for 100ms
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

