// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);

    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log the sensor state to a file
int log_sensor_state(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(fp, "%ld,%d,%d\n", milliseconds, sensor1_state, sensor2_state);
    fclose(fp);
    return 0;
}

// Function to check if both sensors are active
int check_conveyor_halt(int sensor1_state, int sensor2_state) {
    return (sensor1_state == 1 && sensor2_state == 1);
}

// Function to handle conveyor halt
void handle_conveyor_halt() {
    printf("Conveyor halted!\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Conveyor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Log sensor states
        if (log_sensor_state(sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging sensor state\n");
        }

        // Check for conveyor halt
        if (check_conveyor_halt(sensor1_state, sensor2_state)) {
            handle_conveyor_halt();
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Conveyor monitoring stopped.\n");

    return 0;
}

