#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x1A
#define CTRL_REG1 0x2A
#define DATA_X_MSB 0x01
#define DATA_RATE_100HZ 0x01
#define ACTIVE_MODE 0x01
#define FALL_THRESHOLD 45.0
#define LOG_FILE "fall_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_accelerometer();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt(int16_t x, int16_t y, int16_t z);
void log_fall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize the accelerometer
int init_accelerometer() {
    // Verify sensor identity
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    // Configure the accelerometer
    int status = i2cWriteByteData(i2c_handle, CTRL_REG1, DATA_RATE_100HZ | ACTIVE_MODE);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, DATA_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine MSB and LSB, right-shift by 4
    *x = ((int16_t)buffer[0] << 8 | (int16_t)buffer[1]) >> 4;
    *y = ((int16_t)buffer[2] << 8 | (int16_t)buffer[3]) >> 4;
    *z = ((int16_t)buffer[4] << 8 | (int16_t)buffer[5]) >> 4;

    return 0;
}

// Calculate tilt angle
float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 2048.0; // Assuming sensitivity of 2048 LSB/g
    float y_g = (float)y / 2048.0;
    float z_g = (float)z / 2048.0;

    float tilt_x = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180 / M_PI;
    float tilt_y = atan2(-x_g, sqrt(y_g * y_g + z_g * z_g)) * 180 / M_PI;
    float tilt_z = atan2(sqrt(x_g * x_g + y_g * y_g), z_g) * 180 / M_PI;

    return tilt_x;
}

// Log a fall event
void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MMA8452Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize accelerometer
    if (init_accelerometer() != 0) {
        fprintf(stderr, "Accelerometer initialization failed.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float tilt;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            // Calculate tilt
            tilt = calculate_tilt(x, y, z);

            // Check for fall
            if (fabs(tilt) > FALL_THRESHOLD) {
                log_fall(x, y, z);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

