#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Sensitivity (mG/LSB)
#define SENSITIVITY 0.146

// Alert threshold (mG)
#define ALERT_THRESHOLD 800.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration data
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
    float x_scale;
    float y_scale;
    float z_scale;
} calibration_data_t;

// Function prototypes
int init_i2c();
int init_lis3mdl();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
float calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, calibration_data_t cal_data);
float calculate_magnitude(float x, float y, float z);
void log_data(float x, float y, float z);
void check_alert(float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Initialize LIS3MDL
int init_lis3mdl() {
    // Set CTRL_REG1 to 0x70 (10 Hz, continuous conversion, normal mode)
    if (i2cWriteByteData(i2c_fd, LIS3MDL_CTRL_REG1, 0x70) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set CTRL_REG3 to 0x00 (±4 gauss)
    if (i2cWriteByteData(i2c_fd, LIS3MDL_CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG3\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_fd, LIS3MDL_OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate data
float calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, calibration_data_t cal_data) {
    float x = (float)raw_x * SENSITIVITY - cal_data.x_offset * SENSITIVITY;
    float y = (float)raw_y * SENSITIVITY - cal_data.y_offset * SENSITIVITY;
    float z = (float)raw_z * SENSITIVITY - cal_data.z_offset * SENSITIVITY;

    x *= cal_data.x_scale;
    y *= cal_data.y_scale;
    z *= cal_data.z_scale;

    return sqrt(x * x + y * y + z * z);
}

// Calculate magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file);
}

// Check for alert
void check_alert(float magnitude) {
    if (magnitude > ALERT_THRESHOLD) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(stderr, "%s - Metal detector alert! Magnitude: %.2f mG\n", timestamp, magnitude);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3MDL
    if (init_lis3mdl() < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    calibration_data_t cal_data = {X_OFFSET, Y_OFFSET, Z_OFFSET, X_SCALE, Y_SCALE, Z_SCALE};

    int retry_count = 0;
    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        float magnitude;

        // Read magnetometer data
        if (read_magnetometer(&raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate data
            magnitude = calibrate_data(raw_x, raw_y, raw_z, cal_data);

            // Log data
            log_data((float)raw_x, (float)raw_y, (float)raw_z);

            // Check for alert
            check_alert(magnitude);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying...\n");
            retry_count++;
            if (retry_count > 3) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(100); // 10 Hz sampling rate (100 ms delay)
    }

    // Close I2C connection and log file
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

