#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_PARTID 0x02
#define ADXL354B_REG_RESET 0x1D
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_STATUS 0x03
#define ADXL354B_REG_XDATA_L 0x08
#define ADXL354B_REG_XDATA_H 0x09
#define ADXL354B_REG_YDATA_L 0x0A
#define ADXL354B_REG_YDATA_H 0x0B
#define ADXL354B_REG_ZDATA_L 0x0C
#define ADXL354B_REG_ZDATA_H 0x0D

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t reg, uint8_t *data, int len);
int spi_write_register(uint8_t reg, uint8_t data);
int adxl354b_reset();
int adxl354b_verify_partid(uint16_t expected_partid);
int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(uint8_t reg, uint8_t *data, int len) {
    char tx[2];
    char rx[len + 2];

    tx[0] = reg | 0x80; // Set MSB for read
    tx[1] = 0x00;       // Dummy byte for reading

    for (int i = 0; i < len; i++) {
        tx[1] = 0x00; // Reset dummy byte
    }

    if (spiXfer(spi_handle, tx, rx, len + 2) != len + 2) {
        fprintf(stderr, "SPI read error at register 0x%02X\n", reg);
        return -1;
    }

    memcpy(data, rx + 1, len);
    return 0;
}

// SPI Write Register Function
int spi_write_register(uint8_t reg, uint8_t data) {
    char tx[2];
    char rx[2];

    tx[0] = reg & 0x7F; // Clear MSB for write
    tx[1] = data;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write error at register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// ADXL354B Reset Function
int adxl354b_reset() {
    if (spi_write_register(ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// ADXL354B Verify Part ID Function
int adxl354b_verify_partid(uint16_t expected_partid) {
    uint8_t data[2];
    if (spi_read_register(ADXL354B_REG_PARTID, data, 2) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }

    uint16_t partid = (data[0] << 8) | data[1];
    if (partid != expected_partid) {
        fprintf(stderr, "Incorrect PARTID: expected 0x%04X, got 0x%04X\n", expected_partid, partid);
        return -1;
    }

    printf("ADXL354B PARTID verified: 0x%04X\n", partid);
    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (spi_read_register(ADXL354B_REG_XDATA_L, data, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
