    char tx[2];
    char rx[len + 2];

    tx[0] = reg | 0x80; // Set MSB for read
    tx[1] = 0x00;       // Dummy byte for reading

    for (int i = 0; i < len; i++) {
        tx[1] = 0x00; // Reset dummy byte
    }

    if (spiXfer(spi_handle, tx, rx, len + 2) != len + 2) {
        fprintf(stderr, "SPI read error at register 0x%02X\n", reg);
