    imu_data_t data;
    uint8_t tx_buffer[2];
    uint8_t rx_buffer[2];
    int16_t raw_data;

    // Read Gyro X
    tx_buffer[0] = (ADIS16362_GYRO_XOUT | 0x80); // Set MSB for read
    tx_buffer[1] = 0x00; // Dummy byte
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    raw_data = (rx_buffer[0] << 8) | rx_buffer[1];
