    tx_buffer[0] = (ADIS16362_ACCEL_XOUT | 0x80);
    tx_buffer[1] = 0x00;
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    raw_data = (rx_buffer[0] << 8) | rx_buffer[1];
    data.accel_x = (double)raw_data * ACCEL_SCALE;

    // Read Accel Y
    tx_buffer[0] = (ADIS16362_ACCEL_YOUT | 0x80);
    tx_buffer[1] = 0x00;
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    raw_data = (rx_buffer[0] << 8) | rx_buffer[1];
    data.accel_y = (double)raw_data * ACCEL_SCALE;

    // Read Accel Z
    tx_buffer[0] = (ADIS16362_ACCEL_ZOUT | 0x80);
    tx_buffer[1] = 0x00;
    spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    raw_data = (rx_buffer[0] << 8) | rx_buffer[1];
    data.accel_z = (double)raw_data * ACCEL_SCALE;

    return data;
}

// Log IMU data to file
void log_imu_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (ts.tv_sec * 1000000000LL) + (ts.tv_nsec);

    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
