}

// Cleanup resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize log file
    if (initialize_log_file() != 0) {
        cleanup();
        return 1;
    }

    printf("IMU data logging started. Press Ctrl+C to stop.\n");

    // Main loop
    while (!terminate) {
        imu_data_t data = read_imu_data();
        log_imu_data(data);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    // Cleanup and exit
    cleanup();
    printf("IMU data logging stopped.\n");
    return 0;
}

