#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pin connected to the sensor
#define SENSOR_PIN 17

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the self-parking sequence start
void log_start() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Self-parking sequence started\n", timestamp);
}

// Function to log the self-parking sequence completion
void log_complete() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Self-parking sequence completed\n", timestamp);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    printf("Self-parking system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            log_start();
            gpioDelay(5000); // Simulate self-parking sequence (5 seconds)
            log_complete();
        } else if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break; // Exit loop on sensor read error
        }
        gpioDelay(1000); // Check every 1 second
    }

    // Clean up and exit
    gpioTerminate();
    printf("Self-parking system stopped.\n");
    return 0;
}

