#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to read the sensor values
int read_sensors(int gpio1, int gpio2) {
    int sensor1_value = gpioRead(gpio1);
    int sensor2_value = gpioRead(gpio2);

    if (sensor1_value < 0) {
        fprintf(stderr, "Error reading sensor 1 (GPIO %d): %d\n", gpio1, sensor1_value);
        return -1; // Indicate an error
    }
    if (sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor 2 (GPIO %d): %d\n", gpio2, sensor2_value);
        return -1; // Indicate an error
    }

    return sensor1_value + (sensor2_value << 1); // Combine the sensor values into a single integer
}

// Function to log the sensor data with a timestamp
void log_data(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
           sensor1_value ? "Clear" : "Obstacle",
           sensor2_value ? "Clear" : "Obstacle");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int sensor_data = read_sensors(SENSOR1_GPIO, SENSOR2_GPIO);

        if (sensor_data >= 0) {
            // Extract sensor values from the combined integer
            int sensor1_value = (sensor_data >> 0) & 1;
            int sensor2_value = (sensor_data >> 1) & 1;

            log_data(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Error reading sensors, retrying...\n");
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

