#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal Handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    terminate = 1;
}

// Function to read data from ADIS16266 register
int16_t read_adis16266_register(int spi_handle, uint8_t address) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the transmit buffer: address (MSB set) + 2 dummy bytes
    tx_buffer[0] = address | 0x80; // Set MSB to indicate read
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error during SPI transaction: %d\n", result);
        return -1; // Indicate error
    }

    // Extract the 16-bit data from the receive buffer
    int16_t data = (rx_buffer[1] << 8) | rx_buffer[2];

    return data;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        int16_t x_gyro = read_adis16266_register(spi_handle, ADIS16266_REG_XGYRO_OUT);
        int16_t y_gyro = read_adis16266_register(spi_handle, ADIS16266_REG_YGYRO_OUT);
        int16_t z_gyro = read_adis16266_register(spi_handle, ADIS16266_REG_ZGYRO_OUT);

        // Check for errors during read operations
        if (x_gyro == -1 || y_gyro == -1 || z_gyro == -1) {
            fprintf(stderr, "Error reading gyroscope data\n");
            continue; // Skip to the next iteration
        }

        // Apply scale factor
        float x_rate = (float)x_gyro * 0.02;
        float y_rate = (float)y_gyro * 0.02;
        float z_rate = (float)z_gyro * 0.02;

        // Print the angular rates
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close SPI interface and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

