#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_XL 0x28

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int read_burst(int handle, uint8_t reg, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error reading burst from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    if (result != count) {
        fprintf(stderr, "Short read: expected %d bytes, got %d\n", count, result);
        return -1;
    }
    return 0;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr(int handle) {
    // Check WHO_AM_I register
    int who_am_i = read_register(handle, LSM6DSR_WHO_AM_I);
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 104 Hz, +/- 2g
    if (write_register(handle, LSM6DSR_CTRL1_XL, 0x50) < 0) return -1; // 104 Hz, 2g

    // Configure gyroscope: 104 Hz, 250 dps
    if (write_register(handle, LSM6DSR_CTRL2_G, 0x50) < 0) return -1; // 104 Hz, 250 dps

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_lsm6dsr_data(int handle, float *ax, float *ay, float *az, float *gx, float *gy, float *gz) {
    char buffer[12];

    // Read gyroscope data (6 bytes)
    if (read_burst(handle, LSM6DSR_OUTX_L_G, buffer, 6) < 0) return -1;

    // Read accelerometer data (6 bytes)
    if (read_burst(handle, LSM6DSR_OUTX_L_XL, buffer + 6, 6) < 0) return -1;

    // Convert raw data to physical units (assuming +/- 2g and +/- 250 dps)
    int16_t raw_gx = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_gy = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_gz = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t raw_ax = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_ay = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_az = (int16_t)((buffer[11] << 8) | buffer[10]);

    *ax = (float)raw_ax * 0.061 / 1000.0; // mg to g
    *ay = (float)raw_ay * 0.061 / 1000.0;
    *az = (float)raw_az * 0.061 / 1000.0;
    *gx = (float)raw_gx * 8.75 / 1000.0; // dps to deg/s
    *gy = (float)raw_gy * 8.75 / 1000.0;
    *gz = (float)raw_gz * 8.75 / 1000.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr(i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float ax, ay, az, gx, gy, gz;
    while (!terminate) {
        if (read_lsm6dsr_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("%f,%f,%f,%f,%f,%f\n", ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Error reading LSM6DSR data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

