#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_STATUS 0x00
#define FXOS8700_OUT_X_MSB 0x01

// Global variable for I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a register from the FXOS8700
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to write a register to the FXOS8700
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to write register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to initialize the FXOS8700 sensor
int initialize_sensor(int handle) {
    uint8_t who_am_i;

    // Check WHO_AM_I register
    if (read_register(handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != 0xC7) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X. Expected 0xC7.\n", who_am_i);
        return -1;
    }

    // Set accelerometer range to +/- 2g
    if (write_register(handle, FXOS8700_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Error setting accelerometer range.\n");
        return -1;
    }

    // Set magnetometer hybrid mode and ODR to 100 Hz
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x15) != 0) {
        fprintf(stderr, "Error setting magnetometer hybrid mode and ODR.\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    uint8_t data[12];
    int result, retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, (char *)data, 12);
        if (result == 12) {
            // Combine bytes to form 14-bit accelerometer values
            *accel_x = (int16_t)(((data[0] << 6) | (data[1] >> 2)));
            *accel_y = (int16_t)(((data[2] << 6) | (data[3] >> 2)));
            *accel_z = (int16_t)(((data[4] << 6) | (data[5] >> 2)));

            // Combine bytes to form 16-bit magnetometer values
            *mag_x = (int16_t)((data[6] << 8) | data[7]);
            *mag_y = (int16_t)((data[8] << 8) | data[9]);
            *mag_z = (int16_t)((data[10] << 8) | data[11]);

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data: %d. Retrying...\n", result);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

