#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define chip and line names
#define CHIP_NAME "gpiochip0"
#define LINE_A_NAME "gpio17"
#define LINE_B_NAME "gpio27"

// Define log file name
#define LOG_FILE "access_log.txt"

// Define security code range
#define MIN_CODE 100000
#define MAX_CODE 999999

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_a = NULL;
static struct gpiod_line *line_b = NULL;
static FILE *log_file = NULL;

// Function prototypes
int generate_security_code(unsigned long *code);
int read_user_input(char *input, size_t size);
int compare_codes(unsigned long code1, unsigned long code2);
int log_access(unsigned long code);
void unlock_door(int door);
void lock_doors(void);
void signal_handler(int sig);
int setup_gpio(void);
int cleanup_gpio(void);
int open_log_file(void);
int close_log_file(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Received signal %d, terminating...\n", sig);
    }
}

// Function to generate a random security code
int generate_security_code(unsigned long *code) {
    *code = (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
    return 0;
}

// Function to read user input
int read_user_input(char *input, size_t size) {
    if (fgets(input, size, stdin) == NULL) {
        fprintf(stderr, "Error reading input: %s\n", strerror(errno));
        return -1;
    }

    // Remove trailing newline character
    size_t len = strlen(input);
    if (len > 0 && input[len - 1] == '\n') {
        input[len - 1] = '\0';
    }

    return 0;
}

// Function to compare two security codes
int compare_codes(unsigned long code1, unsigned long code2) {
    return (code1 == code2) ? 0 : -1;
}

// Function to log access to the file
int log_access(unsigned long code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%lu\n", timestamp, code);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to unlock a door
void unlock_door(int door) {
    struct gpiod_line *line = (door == 0) ? line_a : line_b;
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", (door == 0) ? DOOR_A_PIN : DOOR_B_PIN, strerror(-ret));
    }
}

// Function to lock doors
void lock_doors(void) {
    int ret = gpiod_line_set_value(line_a, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", DOOR_A_PIN, strerror(-ret));
    }
    ret = gpiod_line_set_value(line_b, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", DOOR_B_PIN, strerror(-ret));
    }
}

// Function to set up GPIO pins
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return -1;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line_a);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "door_access";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(line_a, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_A_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        return -1;
    }

    ret = gpiod_line_request(line_b, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_B_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        return -1;
    }

    return 0;
}

// Function to clean up GPIO pins
int cleanup_gpio(void) {
    if (line_a) {
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_release(line_b);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

// Function to open the log file
int open_log_file(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to close the log file
int close_log_file(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    return 0;
}

int main(void) {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Set up GPIO pins
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open log file
    if (open_log_file() != 0) {
        fprintf(stderr, "Failed to open log file. Continuing without logging.\n");
    }

    printf("Welcome to the door access system.\n");

    while (!terminate) {
        // Generate security code
        unsigned long security_code;
        if (generate_security_code(&security_code) != 0) {
            fprintf(stderr, "Failed to generate security code.\n");
            continue; // Continue to the next iteration
        }

        // Print security code
        printf("Security code: %lu\n", security_code);

        // Read user input
        char user_input[10]; // Buffer to store user input
        if (read_user_input(user_input, sizeof(user_input)) != 0) {
            fprintf(stderr, "Failed to read user input.\n");
            continue; // Continue to the next iteration
        }

        // Compare codes
        int comparison_result = compare_codes(security_code, strtoul(user_input, NULL, 10));
        if (comparison_result == 0) {
            // Access granted
            printf("Access granted!\n");
            unlock_door(0); // Unlock Door A
            unlock_door(1); // Unlock Door B
            sleep(5);       // Keep doors unlocked for 5 seconds
            lock_doors();    // Lock doors
            if (log_access(security_code) != 0) {
                fprintf(stderr, "Failed to log access.\n");
            }
        } else {
            // Access denied
            printf("Access denied.\n");
        }
    }

    // Clean up resources
    lock_doors(); // Ensure doors are locked before exiting
    close_log_file(); // Close the log file
    cleanup_gpio(); // Release GPIO resources

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

