#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_CONVERSION_TIME 180 // ms
#define LOG_FILE "light_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
float convert_raw_to_lux(uint16_t raw_value);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
int read_bh1750(float *lux) {
    uint8_t config_mode = CONTINUOUS_HIGH_RES_MODE;
    uint8_t buffer[2];
    int result;

    // Write configuration mode to the sensor
    result = i2cWriteByteData(i2c_handle, 0x00, config_mode); // 0x00 is the register to write to
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (up to MAX_CONVERSION_TIME)
    gpioDelay(MAX_CONVERSION_TIME * 1000); // Convert ms to microseconds

    // Read two bytes of data from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 2); // 0x00 is the register to read from
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert raw data to lux value
    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    *lux = convert_raw_to_lux(raw_value);

    return 0;
}

// Convert raw sensor reading to lux value
float convert_raw_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Log data to file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(log_file);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

