#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_PIN 18
#define PWM_FREQUENCY 440 // Initial frequency (A4)
#define PORT 12345
#define BUFFER_SIZE 256
#define LOG_FILE "frequency_log.txt"
#define AUTH_SECRET "MySecretKey"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_data(unsigned short *touch_data);
int authenticate_command(const char *command);
void play_tone(int frequency);
void stop_tone();
void log_frequency(int frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        perror("Error: Soft reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrode sensitivity and release thresholds
    if (i2cWriteByteData(i2c_handle, 0x41, 0x0A) < 0) return -1; // Touch threshold
    if (i2cWriteByteData(i2c_handle, 0x42, 0x0A) < 0) return -1; // Release threshold

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) return -1; // Set Electrode Configuration to enable all 12 electrodes

    // Start in run mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) return -1; // Enable all electrodes

    return 0;
}

// Read touch data from MPR121
int read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        perror("Error: Failed to read touch data");
        return -1;
    }
    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

// Authenticate command
int authenticate_command(const char *command) {
    if (strncmp(command, "MOTION_DETECTED:", 17) == 0) {
        // Extract the secret key from the command
        char *secret_key = strstr(command, "SECRET_KEY=");
        if (secret_key != NULL) {
            secret_key += strlen("SECRET_KEY=");
            // Compare the extracted secret key with the expected secret key
            if (strcmp(secret_key, AUTH_SECRET) == 0) {
                return 1; // Authentication successful
            } else {
                fprintf(stderr, "Error: Authentication failed - secret key mismatch\n");
                return 0;
            }
        } else {
            fprintf(stderr, "Error: Authentication failed - SECRET_KEY not found\n");
            return 0;
        }
    } else {
        fprintf(stderr, "Error: Authentication failed - invalid command format\n");
        return 0;
    }
}

// Play tone using hardware PWM
void play_tone(int frequency) {
    gpioSetPWMfrequency(GPIO_PIN, frequency);
    gpioPWM(GPIO_PIN, 128); // 50% duty cycle
}

// Stop the tone
void stop_tone() {
    gpioPWM(GPIO_PIN, 0); // 0% duty cycle
}

// Log frequency to file
void log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Frequency: %d Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    stop_tone();
    if (new_socket > 0) close(new_socket);
    if (server_fd > 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open I2C interface
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("Error: Socket creation failed");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error: Bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Error: Listen failed");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Main loop
    while (!terminate) {
        // Accept connection
        int addrlen = sizeof(address);
        new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            perror("Error: Accept failed");
            continue; // Continue listening
        }

        printf("Connection accepted\n");

        // Read command
        char buffer[BUFFER_SIZE] = {0};
        ssize_t valread = recv(new_socket, buffer, BUFFER_SIZE - 1, 0);
        if (valread < 0) {
            perror("Error: Receive failed");
            close(new_socket);
            continue; // Continue listening
        }

        buffer[valread] = '\0'; // Null-terminate the received data

        printf("Received command: %s\n", buffer);

        // Authenticate command
        if (authenticate_command(buffer)) {
            printf("Authentication successful\n");

            // Play tone
            play_tone(PWM_FREQUENCY);
            unsigned short touch_data;
            int frequency = PWM_FREQUENCY;
            while (!terminate) {
                if (read_touch_data(&touch_data) == 0) {
                    // Map touch data to frequency (example mapping)
                    for (int i = 0; i < 12; i++) {
                        if (touch_data & (1 << i)) {
                            // Calculate frequency based on electrode number and touch value
                            frequency = 440 * pow(2, (i / 4.0)); // Example frequency calculation
                            log_frequency(frequency);
                            break; // Play only the first touched electrode
                        }
                    }
                } else {
                    fprintf(stderr, "Error reading touch data, stopping tone.\n");
                    break;
                }
                gpioDelay(20); // Sample every 20ms
            }

            stop_tone();
        } else {
            fprintf(stderr, "Authentication failed\n");
        }

        close(new_socket);
        printf("Connection closed\n");
    }

    cleanup();
    return 0;
}

