#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_MAG_OUT_X_L_M 0x08
#define LSM303_MAG_OUT_X_H_M 0x09
#define LSM303_MAG_OUT_Y_L_M 0x0A
#define LSM303_MAG_OUT_Y_H_M 0x0B
#define LSM303_MAG_OUT_Z_L_M 0x0C
#define LSM303_MAG_OUT_Z_H_M 0x0D
#define LSM303_CTRL_REG1_M 0x20

// LED GPIO pin (BCM numbering)
#define LED_PIN 17

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int initialize_i2c();
magnetometer_data_t read_magnetometer_data();
float calculate_z_axis_magnitude(magnetometer_data_t data);
void set_led_brightness(float magnitude);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }

    // Configure magnetometer for continuous measurement mode
    if (i2cWriteByteData(i2c_handle, LSM303_CTRL_REG1_M, 0x00) < 0) {
        log_error("Failed to configure magnetometer");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM303_MAG_OUT_X_L_M, buffer, 6) != 6) {
        log_error("Failed to read magnetometer data");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to calculate Z-axis magnitude
float calculate_z_axis_magnitude(magnetometer_data_t data) {
    return (float)data.z;
}

// Function to set LED brightness using hardware PWM
void set_led_brightness(float magnitude) {
    // Map magnitude to PWM duty cycle (0-1000000)
    int duty_cycle = (int)(magnitude * 10000); // Scale magnitude to 0-10000
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;

    gpioPWM(LED_PIN, duty_cycle);
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
    perror(message); // Also print to stderr
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

