#include <time.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Configuration values
#define HMC5883L_CONFIG_A_VALUE 0x70  // 8 samples averaged, 15 Hz, normal measurement
#define HMC5883L_CONFIG_B_VALUE 0x20  // Gain = 1.3 Ga
#define HMC5883L_MODE_CONTINUOUS 0x00 // Continuous measurement mode

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Hard-iron offset buffer
int16_t hard_iron_offsets[100];
int offset_index = 0;

// Function prototypes
int initialize_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z);
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, int16_t *offset_x, int16_t *offset_y, int16_t *offset_z);
void print_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Configure register A
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, HMC5883L_CONFIG_A_VALUE) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, HMC5883L_CONFIG_B_VALUE) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, HMC5883L_MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to update hard-iron offsets
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z) {
    hard_iron_offsets[offset_index] = x;
    hard_iron_offsets[(offset_index + 1) % 100] = y;
    hard_iron_offsets[(offset_index + 2) % 100] = z;
    offset_index++;
}

// Function to apply hard-iron offsets
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, int16_t *offset_x, int16_t *offset_y, int16_t *offset_z) {
    *offset_x = x - hard_iron_offsets[(offset_index - 99 + 100) % 100];
    *offset_y = y - hard_iron_offsets[(offset_index - 98 + 100) % 100];
    *offset_z = z - hard_iron_offsets[(offset_index - 97 + 100) % 100];
}

// Function to print data
void print_data(int16_t x, int16_t y, int16_t z) {
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    int16_t offset_x, offset_y, offset_z;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Update hard-iron offsets
            update_hard_iron_offsets(x, y, z);

            // Apply hard-iron offsets
            apply_hard_iron_offsets(x, y, z, &offset_x, &offset_y, &offset_z);

            // Print data
            print_data(offset_x, offset_y, offset_z);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

