#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// Interrupt pin
#define INT1_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Circular buffer structure
typedef struct {
    accelerometer_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t buffer;

// Function prototypes
int init_lsm303d();
accelerometer_data_t read_accelerometer_data();
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data);
void dump_buffer(circular_buffer_t *buffer);
void interrupt_handler();
void signal_handler(int signal);
void log_error(const char *message);

// Function to log errors with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Function to initialize the LSM303D accelerometer
int init_lsm303d() {
    // Verify device ID
    int device_id = wiringPiI2CReadReg8(i2c_fd, 0x0F); // Read WHO_AM_I register
    if (device_id != 0x33) {
        log_error("LSM303D not found or incorrect device ID");
        return -1;
    }

    // Configure accelerometer: 50 Hz data rate, +/- 2g full scale
    if (wiringPiI2CWriteReg8(i2c_fd, CTRL_REG1_A, 0x57) < 0) { // 0x57 = 01110111
        log_error("Failed to write to CTRL_REG1_A");
        return -1;
    }

    // Configure interrupt threshold
    if (wiringPiI2CWriteReg8(i2c_fd, 0x30, 0x0A) < 0) { // INT1_THS_RDY_A register
        log_error("Failed to write to INT1_THS_RDY_A");
        return -1;
    }
    if (wiringPiI2CWriteReg8(i2c_fd, 0x31, 0x00) < 0) { // INT1_DURATION_A register
        log_error("Failed to write to INT1_DURATION_A");
        return -1;
    }

    // Enable interrupt on INT1 pin
    pinMode(INT1_PIN, INPUT);
    pullUpDnControl(INT1_PIN, PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    int16_t x, y, z;

    x = wiringPiI2CReadReg8(i2c_fd, OUT_X_L_A) | (wiringPiI2CReadReg8(i2c_fd, OUT_X_H_A) << 8);
    y = wiringPiI2CReadReg8(i2c_fd, OUT_Y_L_A) | (wiringPiI2CReadReg8(i2c_fd, OUT_Y_H_A) << 8);
    z = wiringPiI2CReadReg8(i2c_fd, OUT_Z_L_A) | (wiringPiI2CReadReg8(i2c_fd, OUT_Z_H_A) << 8);

    data.x = x;
    data.y = y;
    data.z = z;

    return data;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to dump the contents of the circular buffer
void dump_buffer(circular_buffer_t *buffer) {
    printf("Timestamp: %ld\n", time(NULL));
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("X: %d, Y: %d, Z: %d\n", buffer->data[index].x, buffer->data[index].y, buffer->data[index].z);
    }
    printf("\n");
}

// Interrupt handler function
void interrupt_handler() {
    accelerometer_data_t data = read_accelerometer_data();
    add_to_buffer(&buffer, data);
    dump_buffer(&buffer);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Disable accelerometer
    wiringPiI2CWriteReg8(i2c_fd, CTRL_REG1_A, 0x00); // Power down

    // Close I2C file descriptor
    close(i2c_fd);

    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_fd = wiringPiI2CSetup(LSM303D_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() == -1) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    if (wiringPiISR(INT1_PIN, INT_EDGE_RISING, interrupt_handler) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("LSM303D monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        delay(10); // 10 ms delay
    }

    return 0;
}

