#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Global variable to track the current solenoid state
int current_solenoid = 0;

// Function to set the state of a solenoid
int set_solenoid(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio_pin, result);
        return -1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to switch between the two solenoids
void switch_solenoid() {
    // De-energize the current solenoid
    if (current_solenoid == 1) {
        if (set_solenoid(SOLENOID_1_PIN, 0) != 0) {
            fprintf(stderr, "Error de-energizing solenoid 1\n");
        }
    } else {
        if (set_solenoid(SOLENOID_2_PIN, 0) != 0) {
            fprintf(stderr, "Error de-energizing solenoid 2\n");
        }
    }

    // Energize the other solenoid
    if (current_solenoid == 1) {
        if (set_solenoid(SOLENOID_2_PIN, 1) != 0) {
            fprintf(stderr, "Error energizing solenoid 2\n");
        }
    } else {
        if (set_solenoid(SOLENOID_1_PIN, 1) != 0) {
            fprintf(stderr, "Error energizing solenoid 1\n");
        }
    }

    // Update the current solenoid state
    current_solenoid = 1 - current_solenoid;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // De-energize both solenoids
    set_solenoid(SOLENOID_1_PIN, 0);
    set_solenoid(SOLENOID_2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    // Set both solenoids to LOW initially
    set_solenoid(SOLENOID_1_PIN, 0);
    set_solenoid(SOLENOID_2_PIN, 0);

    // Install signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        switch_solenoid();
        gpioDelay(500000); // 500ms delay
    }

    return 0;
}

