#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART port names
#define UART1_PORT "/dev/serial0"
#define UART2_PORT "/dev/serial1"

// Define expected 6-digit code
const char *expected_code = "123456";

// Define timeout duration (5 seconds)
#define TIMEOUT_SECONDS 5

// Define timeout interval (milliseconds)
#define TIMEOUT_INTERVAL_MS 100

// Global variables for UART handles
int uart1_handle = -1;
int uart2_handle = -1;

// Function prototypes
int initialize_gpio();
int open_uart(const char *port, int baud);
int read_code(int uart_handle, char *code_buffer, int buffer_size);
int authenticate_code(const char *code, const char *expected_code);
int activate_locks(int lock1_gpio, int lock2_gpio, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Ensure locks are locked (LOW)
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    // Close UART ports
    if (uart1_handle != -1) {
        serClose(uart1_handle);
    }
    if (uart2_handle != -1) {
        serClose(uart2_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Ensure locks are initially locked (LOW)
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    return 0;
}

// Open UART port
int open_uart(const char *port, int baud) {
    int handle = serOpen(port, baud, 0); // 0 for default flags (8N1)
    if (handle < 0) {
        fprintf(stderr, "Failed to open UART port %s: %d\n", port, handle);
        return -1;
    }
    return handle;
}

// Read code from UART port with timeout
int read_code(int uart_handle, char *code_buffer, int buffer_size) {
    int i = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (i < buffer_size) {
        int c = serReadByte(uart_handle);
        if (c >= 0) {
            if (c >= '0' && c <= '9') {
                code_buffer[i++] = (char)c;
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                if (((current_time.tv_sec - start_time.tv_sec) * 1000000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000) >= TIMEOUT_SECONDS * 1000) {
                    return -1; // Timeout
                }
            } else {
                // Reset buffer on non-digit character
                i = 0;
                code_buffer[0] = '\0'; // Ensure null termination
                clock_gettime(CLOCK_MONOTONIC, &start_time);
            }
        } else {
            // Handle error or timeout from serReadByte
            return -1;
        }
    }
    code_buffer[buffer_size] = '\0'; // Null-terminate the string
    return 0;
}

// Authenticate code
int authenticate_code(const char *code, const char *expected_code) {
    // Use constant-time string comparison to avoid timing side-channel attacks
    int i = 0;
    while (expected_code[i] != '\0' && code[i] != '\0') {
        if (expected_code[i] != code[i]) {
            return 0; // Codes do not match
        }
        i++;
    }
    if (expected_code[i] != '\0' || code[i] != '\0') {
        return 0; // Codes do not match
    }
    return 1; // Codes match
}

// Activate locks for a specified duration
int activate_locks(int lock1_gpio, int lock2_gpio, int duration_ms) {
    gpioWrite(lock1_gpio, 1); // Activate lock 1
    gpioWrite(lock2_gpio, 1); // Activate lock 2
    gpioDelay(duration_ms);    // Wait for the specified duration
    gpioWrite(lock1_gpio, 0); // Deactivate lock 1
    gpioWrite(lock2_gpio, 0); // Deactivate lock 2
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open UART ports
    uart1_handle = open_uart(UART1_PORT, 9600);
    if (uart1_handle < 0) {
        gpioTerminate();
        return 1;
    }

    uart2_handle = open_uart(UART2_PORT, 9600);
    if (uart2_handle < 0) {
        serClose(uart1_handle);
        gpioTerminate();
        return 1;
    }

    char code1[7]; // Buffer to store code from UART1
    char code2[7]; // Buffer to store code from UART2

    // Main loop
    while (1) {
        // Read code from UART1
        if (read_code(uart1_handle, code1, 6) == 0) {
            // Read code from UART2
            if (read_code(uart2_handle, code2, 6) == 0) {
                // Authenticate codes
                if (authenticate_code(code1, expected_code) && authenticate_code(code2, expected_code)) {
                    // Codes match and are correct
                    printf("Authentication successful!\n");
                    // Activate locks
                    activate_locks(LOCK1_GPIO, LOCK2_GPIO, 2000); // Activate for 2 seconds
                } else {
                    // Codes do not match or are incorrect
                    fprintf(stderr, "Authentication failed. Expected code: %s\n", expected_code);
                }
            }
        }

        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    serClose(uart1_handle);
    serClose(uart2_handle);
    gpioTerminate();

    return 0;
}

