#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 200
#define FAILSAFE_TIMEOUT_S 10
#define RELAY_ON_TIME_S 1

// Global variables
static volatile int running = 1;
static time_t last_motion_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to relay pin");
        return -1;
    }
    return 0;
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
    closelog();
}

int main() {
    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("Motion detector started");

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) * 1000 >= DEBOUNCE_DELAY_MS) {
                log_event("Motion detected!");
                if (control_relay(1) == 0) {
                    log_event("Relay activated");
                    sleep(RELAY_ON_TIME_S);
                    if (control_relay(0) == 0) {
                        log_event("Relay deactivated");
                    } else {
                        syslog(LOG_ERR, "Failed to deactivate relay");
                    }
                } else {
                    syslog(LOG_ERR, "Failed to activate relay");
                }

                last_motion_time = now;
            }
        } else {
            // Check for failsafe timeout
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) > FAILSAFE_TIMEOUT_S) {
                log_event("Failsafe triggered: No motion for too long!");
                if (control_relay(0) == 0) {
                    log_event("Relay deactivated due to failsafe");
                } else {
                    syslog(LOG_ERR, "Failed to deactivate relay due to failsafe");
                }
                log_event("Shutting down...");
                cleanup();
                exit(1);
            }
        }

        gpioDelay(50); // Poll every 50ms
    }

    return 0;
}

