#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the duration for which each relay is activated (in seconds)
#define RELAY_ACTIVATION_DURATION 300

// Define the duration for the pause between relay activations (in seconds)
#define PAUSE_DURATION 60

// Define the timer interval (in seconds)
#define TIMER_INTERVAL 60

// Global variables
volatile sig_atomic_t program_running = 1;
int current_relay = 1;

// Function prototypes
void activate_relay(int gpio);
void deactivate_relay(int gpio);
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);

// Function to activate a relay
void activate_relay(int gpio) {
    if (gpioWrite(gpio, 0) != 0) {
        syslog(LOG_ERR, "Failed to activate relay on GPIO %d", gpio);
    } else {
        syslog(LOG_INFO, "Activated relay on GPIO %d", gpio);
    }
}

// Function to deactivate a relay
void deactivate_relay(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", gpio);
    } else {
        syslog(LOG_INFO, "Deactivated relay on GPIO %d", gpio);
    }
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(LOG_INFO, "%s - Timer event: Relay %d", timestamp, current_relay);

    // Activate the current relay
    activate_relay((current_relay == 1) ? RELAY1_GPIO : ((current_relay == 2) ? RELAY2_GPIO : ((current_relay == 3) ? RELAY3_GPIO : RELAY4_GPIO)));

    // Wait for the activation duration
    gpioDelay(RELAY_ACTIVATION_DURATION * 1000000); // Convert seconds to microseconds

    // Deactivate the current relay
    deactivate_relay((current_relay == 1) ? RELAY1_GPIO : ((current_relay == 2) ? RELAY2_GPIO : ((current_relay == 3) ? RELAY3_GPIO : RELAY4_GPIO)));

    // Wait for the pause duration
    gpioDelay(PAUSE_DURATION * 1000000); // Convert seconds to microseconds

    // Increment the current relay number
    current_relay++;

    // Reset to the first relay after the fourth
    if (current_relay > 4) {
        current_relay = 1;
    }
}

// Signal handler function
void signal_handler(int signal) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(LOG_INFO, "%s - Signal received, shutting down...", timestamp);

    // Deactivate all relays
    deactivate_relay(RELAY1_GPIO);
    deactivate_relay(RELAY2_GPIO);
    deactivate_relay(RELAY3_GPIO);
    deactivate_relay(RELAY4_GPIO);

    // Stop the timer
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Remove the timer

    // Terminate the pigpio library
    gpioTerminate();

    // Close syslog
    closelog();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    deactivate_relay(RELAY1_GPIO);
    deactivate_relay(RELAY2_GPIO);
    deactivate_relay(RELAY3_GPIO);
    deactivate_relay(RELAY4_GPIO);

    // Set up the timer
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL * 1000, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set up timer");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        sleep(1); // Sleep for 1 second to reduce CPU usage
    }

    // The program should not reach here due to the signal handler
    return 0;
}

