    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Wake up the MPU6050
    uint8_t wake_up = 0x00;
    if (write(i2c_fd, &wake_up, 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        close(i2c_fd);
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    uint8_t config = 0x00; // 0x00 for +/- 2g
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Error writing to ACCEL_CONFIG register");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize memory mapping
int init_mmap() {
    struct sysinfo mem_info;
    if (sysinfo(&mem_info) == -1) {
        perror("sysinfo");
        return -1;
    }

    if (mem_fd = open("/dev/mem", O_RDWR | O_SYNC) < 0) {
        perror("Error opening /dev/mem");
        return -1;
    }

    buffer = (accel_data_t *)mmap(NULL, BUFFER_SIZE * sizeof(accel_data_t), PROT_READ | PROT_WRITE, MAP_SHARED, mem_fd, 0x3C000000); // Assuming MPU6050 is at 0x3C000000

    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(mem_fd);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the MPU6050
accel_data_t read_accel_data() {
    accel_data_t data;
    uint8_t buffer[6];

    // Read X, Y, and Z acceleration data
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading acceleration data");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to store data in the circular buffer
void store_data(accel_data_t data) {
    buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get the latest data from the circular buffer
accel_data_t get_latest_data() {
    int latest_index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer[latest_index];
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (buffer != NULL) {
        munmap(buffer, BUFFER_SIZE * sizeof(accel_data_t));
    }
    if (mem_fd != -1) {
        close(mem_fd);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c(MPU6050_ADDR) < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize Memory Mapping
    if (init_mmap() < 0) {
        fprintf(stderr, "Memory mapping initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Create /sys/kernel/mpu6050_accel/latest file
    if (mkfifo("/sys/kernel/mpu6050_accel/latest", 0666) == -1) {
        if (errno != EEXIST) {
            perror("Error creating fifo");
            cleanup();
            return 1;
        }
    }

    // Open /sys/kernel/mpu6050_accel/latest for writing
    FILE *fp = fopen("/sys/kernel/mpu6050_accel/latest", "w");
    if (fp == NULL) {
        perror("Error opening fifo for writing");
        cleanup();
        return 1;
    }

    // POSIX Timer Setup (using nanosleep for simplicity)
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10ms (100Hz)

    // Main loop
    while (running) {
        accel_data_t data = read_accel_data();
        store_data(data);
        fprintf(fp, "%d,%d,%d\n", data.x, data.y, data.z);
        fflush(fp);
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    fclose(fp);
    cleanup();
    return 0;
}

