#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 18
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

// Define prime-number intervals in seconds
#define RELAY1_INTERVAL 2
#define RELAY2_INTERVAL 3
#define RELAY3_INTERVAL 5
#define RELAY4_INTERVAL 7

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to initialize a GPIO pin for output
int initialize_gpio(int gpio) {
    if (gpioSetMode(gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", gpio);
        return -1;
    }
    return 0;
}

// Function to turn a relay on
int relay_on(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to turn a relay off
int relay_off(int gpio) {
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to toggle a relay on for a specified interval
int toggle_relay(int gpio, int interval) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (program_running) {
        if (relay_on(gpio) != 0) return -1;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - start.tv_sec) + (now.tv_nsec - start.tv_nsec) / 1e9;

        if (elapsed >= interval) {
            if (relay_off(gpio) != 0) return -1;
            break;
        }
        gpioDelay(100); // Small delay to prevent busy-waiting
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(RELAY1_GPIO) != 0 ||
        initialize_gpio(RELAY2_GPIO) != 0 ||
        initialize_gpio(RELAY3_GPIO) != 0 ||
        initialize_gpio(RELAY4_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (toggle_relay(RELAY1_GPIO, RELAY1_INTERVAL) != 0) break;
        if (toggle_relay(RELAY2_GPIO, RELAY2_INTERVAL) != 0) break;
        if (toggle_relay(RELAY3_GPIO, RELAY3_INTERVAL) != 0) break;
        if (toggle_relay(RELAY4_GPIO, RELAY4_INTERVAL) != 0) break;
    }

    // Ensure all relays are off before exiting
    relay_off(RELAY1_GPIO);
    relay_off(RELAY2_GPIO);
    relay_off(RELAY3_GPIO);
    relay_off(RELAY4_GPIO);

    // Terminate pigpio library
    gpioTerminate();

    printf("Relay control program terminated.\n");
    return 0;
}

