#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 500

// Define relay activation time (in milliseconds)
#define RELAY_ACTIVATION_TIME 3000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_activation_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int log_event();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the relay
int activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn relay on
    gpioDelay(RELAY_ACTIVATION_TIME);
    gpioWrite(RELAY_PIN, 0); // Turn relay off
    return 0;
}

// Function to log the event to a file
int log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Sound event detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Function to cleanup GPIO and close the log file
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 0) { // Sound detected (LOW signal)
            unsigned long current_time = gpioTick();

            // Debounce check
            if (current_time - last_activation_time > DEBOUNCE_TIME * 1000) {
                printf("Sound event detected!\n");
                log_event();
                activate_relay();
                last_activation_time = current_time;
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    cleanup();
    return 0;
}

