#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_mpu6050();
gyro_data_t read_gyro_data();
double calculate_angular_velocity(gyro_data_t data);
void add_to_buffer(gyro_data_t data);
double get_angular_velocity_magnitude();
void callback_function(double angular_velocity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buf[0] << 8) | buf[1]);
    data.y = (int16_t)((buf[2] << 8) | buf[3]);
    data.z = (int16_t)((buf[4] << 8) | buf[5]);

    return data;
}

// Calculate angular velocity magnitude
double calculate_angular_velocity(gyro_data_t data) {
    double x = (double)data.x;
    double y = (double)data.y;
    double z = (double)data.z;
    return sqrt(x * x + y * y + z * z) / 131.0; // Convert to degrees/second
}

// Add data to circular buffer
void add_to_buffer(gyro_data_t data) {
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Get angular velocity magnitude from the last sample in the buffer
double get_angular_velocity_magnitude() {
    gyro_data_t last_sample = gyro_buffer[(buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE];
    return calculate_angular_velocity(last_sample);
}

// Callback function
void callback_function(double angular_velocity) {
    printf("Angular velocity exceeded threshold: %.2f deg/s\n", angular_velocity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_data_t gyro_data = read_gyro_data();

        // Add data to circular buffer
        add_to_buffer(gyro_data);

        // Calculate angular velocity
        double angular_velocity = calculate_angular_velocity(gyro_data);

        // Check if angular velocity exceeds threshold
        if (angular_velocity > ANGULAR_VELOCITY_THRESHOLD) {
            callback_function(angular_velocity);
        }

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

