#include <pigpio.h>

// Define constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_COMMAND_LENGTH 9
#define CO2_RESPONSE_LENGTH 9
#define TIMEOUT_MS 1000
#define SAMPLE_INTERVAL_S 5
#define GPIO_TXD 14
#define GPIO_RXD 15

// Global variables
int uart_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold CO2 data
typedef struct {
    int ppm;
    int error;
} co2_data_t;

// Function prototypes
int initialize_uart();
int send_co2_command();
int read_co2_response(unsigned char *response);
int validate_checksum(unsigned char *response);
int parse_co2_data(unsigned char *response, co2_data_t *data);
int log_co2_data(co2_data_t data);
int log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Send CO2 command
int send_co2_command() {
    unsigned char command[CO2_COMMAND_LENGTH] = {0x22, 0x4C, 0x06, 0x2D, 0x01, 0x03, 0x00, 0x01, 0x38};
    int bytes_written = serWrite(uart_handle, (char *)command, CO2_COMMAND_LENGTH);
    if (bytes_written != CO2_COMMAND_LENGTH) {
        fprintf(stderr, "Error writing to UART: %d\n", bytes_written);
        return -1;
    }
    return 0;
}

// Read CO2 response
int read_co2_response(unsigned char *response) {
    int bytes_read = serRead(uart_handle, (char *)response, CO2_RESPONSE_LENGTH);
    if (bytes_read != CO2_RESPONSE_LENGTH) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate checksum
int validate_checksum(unsigned char *response) {
    unsigned short checksum = (response[8] << 8) | response[9];
    unsigned short calculated_checksum = 0;
    for (int i = 0; i < 8; i++) {
        calculated_checksum += response[i];
    }
    return (checksum == calculated_checksum);
}

// Parse CO2 data
int parse_co2_data(unsigned char *response, co2_data_t *data) {
    data->ppm = (response[3] << 8) | response[4];
    data->error = 0;
    return 0;
}

// Log CO2 data to file
int log_co2_data(co2_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_us = (ts.tv_sec * 1000000) + ts.tv_nsec / 1000;

    char json_string[256];
    snprintf(json_string, sizeof(json_string), "{\"timestamp\":%ld,\"ppm\":%d,\"error\":%d}\n", timestamp_us, data.ppm, data.error);

    if (fprintf(log_file, "%s", json_string) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    printf("%s", json_string); // Simulate remote API call
    return 0;
}

// Log error to file
int log_error(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_us = (ts.tv_sec * 1000000) + ts.tv_nsec / 1000;

    if (fprintf(error_log_file, "%ld: %s\n", timestamp_us, message) < 0) {
        fprintf(stderr, "Error writing to error log file\n");
        return -1;
    }
    fflush(error_log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen("co2_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening co2_log.json\n");
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen("co2_error.log", "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error opening co2_error.log\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        log_error("UART initialization failed");
        fclose(log_file);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char response[CO2_RESPONSE_LENGTH];
    co2_data_t co2_data;

    // Main loop
    while (!terminate) {
        // Send CO2 command
        if (send_co2_command() != 0) {
            log_error("Failed to send CO2 command");
            continue;
        }

        // Wait for response
        int timeout_counter = 0;
        while (timeout_counter < TIMEOUT_MS) {
            if (serDataAvailable(uart_handle) >= CO2_RESPONSE_LENGTH) {
                break;
            }
            gpioDelay(1); // Wait 1 ms
            timeout_counter++;
        }

        if (timeout_counter >= TIMEOUT_MS) {
            log_error("Timeout waiting for response");
            continue;
        }

        // Read CO2 response
        if (read_co2_response(response) != 0) {
            log_error("Failed to read CO2 response");
            continue;
        }

        // Validate checksum
        if (!validate_checksum(response)) {
            log_error("Checksum validation failed");
            continue;
        }

        // Parse CO2 data
        if (parse_co2_data(response, &co2_data) != 0) {
            log_error("Failed to parse CO2 data");
            continue;
        }

        // Log CO2 data
        if (log_co2_data(co2_data) != 0) {
            log_error("Failed to log CO2 data");
        }

        // Wait for next sample
        sleep(SAMPLE_INTERVAL_S);
    }

    // Clean up
    serClose(uart_handle);
    fclose(log_file);
    fclose(error_log_file);
    gpioTerminate();

    return 0;
}

