#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_REG_A 0x00
#define CONFIG_REG_B 0x01
#define MODE_REG 0x02
#define DATA_X_MSB 0x03
#define DATA_X_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define DATA_Y_MSB 0x07
#define DATA_Y_LSB 0x08
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_hmc5883l();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void apply_hard_iron_compensation(int16_t x, int16_t y, float *compensated_x, float *compensated_y);
float calculate_heading(float compensated_x, float compensated_y);
void add_to_circular_buffer(CircularBuffer *cb, float value);
float get_latest_reading(CircularBuffer *cb);
void control_gpio(float heading);
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the HMC5883L magnetometer
int init_hmc5883l() {
    // Configuration register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, CONFIG_REG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configuration register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, CONFIG_REG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Mode register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Apply hard-iron compensation
void apply_hard_iron_compensation(int16_t x, int16_t y, float *compensated_x, float *compensated_y) {
    *compensated_x = (float)x - 100.0;
    *compensated_y = (float)y + 50.0;
}

// Calculate heading in degrees
float calculate_heading(float compensated_x, float compensated_y) {
    float heading = atan2(compensated_y, compensated_x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Add a value to the circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the latest reading from the circular buffer
float get_latest_reading(CircularBuffer *cb) {
    if (cb->count > 0) {
        int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
        return cb->buffer[index];
    } else {
        return 0.0; // Return 0 if the buffer is empty
    }
}

// Control GPIO based on heading deviation
void control_gpio(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);
    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer heading_buffer;
    init_circular_buffer(&heading_buffer);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float compensated_x, compensated_y;
    float heading;
    float latest_heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Apply hard-iron compensation
            apply_hard_iron_compensation(x, y, &compensated_x, &compensated_y);

            // Calculate heading
            heading = calculate_heading(compensated_x, compensated_y);

            // Add heading to circular buffer
            add_to_circular_buffer(&heading_buffer, heading);

            // Get latest heading from buffer
            latest_heading = get_latest_reading(&heading_buffer);

            // Control GPIO
            control_gpio(latest_heading);

            // Print heading (for debugging)
            printf("Heading: %.2f, GPIO: %d\n", latest_heading, gpioRead(GPIO_PIN));
        } else {
            fprintf(stderr, "Error reading magnetometer, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low before exiting
    gpioTerminate();

    return 0;
}

