#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Define GPIO pins for RGB relays (BCM numbering)
#define RED_PIN   17
#define GREEN_PIN 27
#define BLUE_PIN  22

// Define BH1750 I2C address
#define BH1750_ADDR 0x23

// Define BH1750 command for continuous high-resolution mode
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
float read_lux();
void control_relays(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(BH1750_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (wiringPiI2CWrite(i2c_fd, BH1750_CONTINUOUS_HIGH_RES_MODE) == -1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    int raw_value = wiringPiI2CReadReg16(i2c_fd, 0x00); // Dummy register address
    if (raw_value == -1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1.0;
    }

    // BH1750 returns big-endian data, so swap bytes
    raw_value = (raw_value >> 8) | (raw_value << 8);

    return (float)raw_value / 1.2;
}

// Control RGB relays based on lux value
void control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < 50) {
        red_state = 1;
    } else if (lux < 150) {
        green_state = 1;
    } else if (lux < 300) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    digitalWrite(RED_PIN, red_state);
    digitalWrite(GREEN_PIN, green_state);
    digitalWrite(BLUE_PIN, blue_state);
}

// Log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off all relays
    digitalWrite(RED_PIN, LOW);
    digitalWrite(GREEN_PIN, LOW);
    digitalWrite(BLUE_PIN, LOW);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close I2C file descriptor
    // No explicit close function in wiringPiI2C, but setting to -1 indicates it's no longer in use.
    i2c_fd = -1; // Mark as closed

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as output
    pinMode(RED_PIN, OUTPUT);
    pinMode(GREEN_PIN, OUTPUT);
    pinMode(BLUE_PIN, OUTPUT);

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Lighting control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read lux value
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value. Retrying in 1 second.\n");
            delay(1000);
            continue;
        }

        // Control relays
        control_relays(lux);

        // Log data
        int red_state = digitalRead(RED_PIN);
        int green_state = digitalRead(GREEN_PIN);
        int blue_state = digitalRead(BLUE_PIN);
        log_data(lux, red_state, green_state, blue_state);

        // Wait for 1 second
        delay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

