#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Motor A GPIOs
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIOs
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Proportional gain
#define KP 5

// Distance range (cm)
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to set motor direction and speed
void set_motor_speed(int motor_a_in1, int motor_a_in2, int motor_b_in3, int motor_b_in4, int duty_cycle) {
    gpioWrite(motor_a_in1, 1);
    gpioWrite(motor_a_in2, duty_cycle > 127 ? 1 : 0);
    gpioWrite(motor_b_in3, 1);
    gpioWrite(motor_b_in4, duty_cycle > 127 ? 1 : 0);
}

// Function to stop the motors
void stop_motors(int motor_a_in1, int motor_a_in2, int motor_b_in3, int motor_b_in4) {
    gpioWrite(motor_a_in1, 0);
    gpioWrite(motor_a_in2, 0);
    gpioWrite(motor_b_in3, 0);
    gpioWrite(motor_b_in4, 0);
}

// Function to calculate PWM duty cycle based on distance
int calculate_duty_cycle(int distance) {
    int duty_cycle = 0;

    if (distance < 50) {
        // Forward direction
        duty_cycle = (int)(((float)(distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 255);
    } else {
        // Backward direction
        duty_cycle = (int)(((float)(distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 255);
        if (duty_cycle > 255) duty_cycle = 255;
        duty_cycle = 255 - duty_cycle; // Invert for backward direction
    }

    return duty_cycle;
}

int main(int argc, char *argv[]) {
    int motor_a_distance, motor_b_distance;
    int duty_cycle_a, duty_cycle_b;

    // Check command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <motor_a_distance> <motor_b_distance>\n", argv[0]);
        return 1;
    }

    // Parse distance arguments
    motor_a_distance = atoi(argv[1]);
    motor_b_distance = atoi(argv[2]);

    // Validate distance values
    if (motor_a_distance < MIN_DISTANCE || motor_a_distance > MAX_DISTANCE ||
        motor_b_distance < MIN_DISTANCE || motor_b_distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance values must be between %d and %d cm\n", MIN_DISTANCE, MAX_DISTANCE);
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_IN2, 255);
    gpioSetPWMrange(MOTOR_B_IN4, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (!terminate) {
        // Calculate duty cycles
        duty_cycle_a = calculate_duty_cycle(motor_a_distance);
        duty_cycle_b = calculate_duty_cycle(motor_b_distance);

        // Set motor speeds
        set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, duty_cycle_a);

        // Print current state
        printf("Motor A Distance: %d cm, Duty Cycle: %d\n", motor_a_distance, duty_cycle_a);
        printf("Motor B Distance: %d cm, Duty Cycle: %d\n", motor_b_distance, duty_cycle_b);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Stop motors and cleanup
    stop_motors(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4);
    gpioTerminate();

    return 0;
}

