#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define LOG_FILE "solar_tracker.log"
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *pitch, float *roll);
int set_servo_angle(float angle);
int log_data(float pitch, float roll, int servo_position);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// I2C initialization
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Wake up the MPU6050
    char data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;
    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read raw data from MPU6050
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[14];
    if (read(i2c_fd, buffer, 14) != 14) {
        perror("Error reading from I2C device");
        return -1;
    }

    *accel_x = (buffer[0] << 8) | buffer[1];
    *accel_y = (buffer[2] << 8) | buffer[3];
    *accel_z = (buffer[4] << 8) | buffer[5];
    *gyro_x = (buffer[8] << 8) | buffer[9];
    *gyro_y = (buffer[10] << 8) | buffer[11];
    *gyro_z = (buffer[12] << 8) | buffer[13];

    return 0;
}

// Process data and calculate pitch and roll
void process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *pitch, float *roll) {
    float ax = (float)accel_x;
    float ay = (float)accel_y;
    float az = (float)accel_z;

    *roll = atan2(ay, az) * 180 / M_PI;
    *pitch = atan2(-ax, sqrt(ay * ay + az * az)) * 180 / M_PI;
}

// Set servo angle using PWM
int set_servo_angle(float angle) {
    // Map angle (0-180) to PWM duty cycle (0-1000000)
    int duty_cycle = (int)(angle / 180.0 * 1000000.0);

    // Open PWM channel
    int pwm_fd = open("/sys/class/pwm/pwmchip2/pwm0", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Error opening PWM channel");
        return -1;
    }

    // Write duty cycle to PWM channel
    char duty_cycle_str[20];
    snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", duty_cycle);
    if (write(pwm_fd, duty_cycle_str, strlen(duty_cycle_str)) != strlen(duty_cycle_str)) {
        perror("Error writing to PWM channel");
        close(pwm_fd);
        return -1;
    }

    close(pwm_fd);
    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int servo_position) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_position);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_position;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Process data
        process_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, &pitch, &roll);

        // Set servo angle
        if (set_servo_angle(pitch) < 0) {
            fprintf(stderr, "Error setting servo angle. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }
        servo_position = (int)(pitch / 180.0 * 1000000.0); // Store duty cycle value

        // Log data
        if (log_data(pitch, roll, servo_position) < 0) {
            fprintf(stderr, "Error logging data. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

