#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration (seconds)
#define FADE_DURATION 1800

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to hold the schedule data
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state; // 0 = off, 1 = on
} ScheduleEntry;

// Global variables
FILE *schedule_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_schedule_file(ScheduleEntry *schedule, int *schedule_size);
int parse_schedule_line(const char *line, ScheduleEntry *entry);
int set_relay_state(int relay_number, int state);
int fade_relay(int relay_number, int target_state);
void handle_signal(int signal);
void cleanup();

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to read the schedule file
int read_schedule_file(ScheduleEntry *schedule, int *schedule_size) {
    char line[256];
    *schedule_size = 0;

    while (fgets(line, sizeof(line), schedule_file) != NULL) {
        (*schedule_size)++;
        ScheduleEntry *new_schedule = realloc(schedule, sizeof(ScheduleEntry) * (*schedule_size));
        if (new_schedule == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return 1;
        }
        schedule = new_schedule;
    }

    rewind(schedule_file); // Reset file pointer to the beginning
    return 0;
}

// Function to parse a schedule line
int parse_schedule_line(const char *line, ScheduleEntry *entry) {
    char *token;
    token = strtok(line, ";");
    if (token == NULL) return 1;
    entry->hour = atoi(token);
    token = strtok(NULL, ";");
    if (token == NULL) return 1;
    entry->minute = atoi(token);
    token = strtok(NULL, ";");
    if (token == NULL) return 1;
    entry->second = atoi(token);
    token = strtok(NULL, ";");
    if (token == NULL) return 1;
    entry->relay_number = atoi(token);
    token = strtok(NULL, ";");
    if (token == NULL) return 1;
    entry->state = atoi(token);

    return 0;
}

// Function to set the state of a relay
int set_relay_state(int relay_number, int state) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return 1;
    }

    if (state == 1) {
        gpioWrite(pin, 1); // Turn on the relay (HIGH)
    } else {
        gpioWrite(pin, 0); // Turn off the relay (LOW)
    }
    return 0;
}

// Function to fade the relay state
int fade_relay(int relay_number, int target_state) {
    int pin;
