#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_FREQUENCY 200.0   // Minimum frequency (Hz)
#define MAX_FREQUENCY 2000.0  // Maximum frequency (Hz)
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MIN_DISTANCE 2.0      // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0    // Maximum measurable distance (cm)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long read_echo_pulse();
float calculate_distance(long pulse_duration);
int map_distance_to_frequency(float distance);
void set_buzzer_frequency(int frequency);
void cleanup_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioPWM(PWM_PIN, 0);       // Ensure buzzer is off initially

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Read the echo pulse duration
long read_echo_pulse() {
    long start_tick, end_tick, pulse_duration;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;
    if (pulse_duration < 0) {
        // Handle tick rollover
        pulse_duration += 0xFFFFFFFF; // Add maximum value to get correct duration
    }

    return pulse_duration;
}

// Calculate distance in centimeters
float calculate_distance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Map distance to frequency
int map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return -1; // Indicate error
    }
    if (distance > MAX_DISTANCE) {
        return -1; // Indicate error
    }

    // Linear mapping
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    return (int)frequency;
}

// Set buzzer frequency using PWM
void set_buzzer_frequency(int frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Frequency out of range: %d\n", frequency);
        return;
    }

    // Calculate PWM duty cycle (assuming 1000 Hz PWM frequency)
    int period_us = 1000000 / frequency; // Period in microseconds
    int duty_cycle_us = period_us / 2;    // 50% duty cycle

    gpioPWM(PWM_PIN, duty_cycle_us); // Set PWM duty cycle
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioPWM(PWM_PIN, 0); // Silence the buzzer
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Read the echo pulse
        long pulse_duration = read_echo_pulse();

        if (pulse_duration < 0) {
            fprintf(stderr, "Error reading echo pulse\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate the distance
        float distance = calculate_distance(pulse_duration);

        if (distance < 0) {
            fprintf(stderr, "Error calculating distance\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Map the distance to a frequency
        int frequency = map_distance_to_frequency(distance);

        if (frequency < 0) {
            fprintf(stderr, "Error mapping distance to frequency\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Set the buzzer frequency
        set_buzzer_frequency(frequency);

        // Delay to avoid excessive CPU usage
        gpioDelay(20000); // 20ms delay
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    printf("Theremin stopped.\n");

    return 0;
}

