// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the RGB LED color using PWM
void set_rgb_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a color based on proximity value
void generate_color(float proximity) {
    // Use a sine wave to map proximity value to RGB values
    float red   = 255 * (1 - proximity) * 0.5 + 255 * proximity * 0.5 * sin(2 * M_PI * proximity);
    float green = 255 * (1 - proximity) * 0.5 + 255 * proximity * 0.5 * sin(2 * M_PI * proximity + 2 * M_PI / 3);
    float blue  = 255 * (1 - proximity) * 0.5 + 255 * proximity * 0.5 * sin(2 * M_PI * proximity + 4 * M_PI / 3);

    // Clamp RGB values to the range 0-255
    red   = fmax(0, fmin(255, red));
    green = fmax(0, fmin(255, green));
    blue  = fmax(0, fmin(255, blue));

    // Set the RGB LED color
    set_rgb_color((int)red, (int)green, (int)blue);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

