#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47
#define GYRO_CONFIG  0x1B

// Sensitivity scale factor for +/- 250 degrees/sec range
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    double x;
    double y;
    double z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set gyroscope range to +/- 250 degrees/sec
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
int read_raw_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw data to degrees per second
gyro_data_t convert_to_dps(int16_t x, int16_t y, int16_t z) {
    gyro_data_t dps;

    dps.x = (double)x / GYRO_SCALE;
    dps.y = (double)y / GYRO_SCALE;
    dps.z = (double)z / GYRO_SCALE;

    return dps;
}

// Function to log data to file
int log_data(double timestamp, double x, double y, double z) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    gyro_data_t dps;
    struct timespec ts;

    while (!terminate) {
        // Read raw gyroscope data
        if (read_raw_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            dps = convert_to_dps(raw_x, raw_y, raw_z);

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

                // Log data
                if (log_data(timestamp, dps.x, dps.y, dps.z) != 0) {
                    fprintf(stderr, "Error: Could not log data\n");
                }
            } else {
                fprintf(stderr, "Error: Could not get timestamp\n");
            }
        } else {
            fprintf(stderr, "Error: Could not read gyro data in main loop\n");
        }

        gpioDelay(100); // Sample every 100 ms
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

