#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define melody structure
typedef struct {
    int frequency;
    int duration;
} Note;

// Define melody
const Note melody[] = {
    {440, 250},  // A4, 250ms
    {494, 250},  // B4, 250ms
    {523, 250},  // C5, 250ms
    {587, 250},  // D5, 250ms
    {659, 250},  // E5, 250ms
    {698, 250},  // F5, 250ms
    {784, 250},  // G5, 250ms
    {880, 250}   // A5, 250ms
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile int button_pressed = 0;
volatile int melody_playing = 0;
int gpio_initialized = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Button ISR
void button_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) { // Button pressed (active-low)
        if (current_tick - last_tick > DEBOUNCE_TIME * 1000) { // Debounce
            button_pressed = 1;
            last_tick = current_tick;
        }
    }
}

// Play melody function
void play_melody() {
    if (!melody_playing) {
        melody_playing = 1;
        printf("Playing melody...\n");
        for (int i = 0; i < melody_length; i++) {
            gpioPWM(BUZZER_GPIO, 128); // 50% duty cycle
            gpioSetPWMfrequency(BUZZER_GPIO, melody[i].frequency);
            gpioDelay(melody[i].duration * 1000); // Convert ms to us
        }
        gpioPWM(BUZZER_GPIO, 0); // Stop PWM after melody
        melody_playing = 0;
        printf("Melody finished.\n");
    } else {
        stop_melody();
    }
}

// Stop melody function
void stop_melody() {
    gpioPWM(BUZZER_GPIO, 0); // Stop PWM
    melody_playing = 0;
    printf("Melody stopped.\n");
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_GPIO, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpio_initialized = 1;

    // Set GPIO modes
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(BUZZER_GPIO, 1000); // 1 kHz

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(BUZZER_GPIO, 255);

    // Set initial PWM duty cycle to 0
    gpioPWM(BUZZER_GPIO, 0);

    // Register ISR for button press
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            button_pressed = 0;
            play_melody();
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

