#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT 1000

// Structure to hold the last WINDOW_SIZE events
typedef struct {
    int events[WINDOW_SIZE];
    int head;
    int count;
} EventQueue;

// Global variables
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;
EventQueue event_queue;

// Function prototypes
int initialize_gpio();
int read_sensor();
void handle_edge(int edge);
void enqueue_event(int event);
int check_earthquake();
void log_event(int event);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Initialize the event queue
void init_event_queue() {
    event_queue.head = 0;
    event_queue.count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        event_queue.events[i] = 0;
    }
}

// Enqueue a new event into the circular buffer
void enqueue_event(int event) {
    event_queue.events[event_queue.head] = event;
    event_queue.head = (event_queue.head + 1) % WINDOW_SIZE;
    if (event_queue.count < WINDOW_SIZE) {
        event_queue.count++;
    }
}

// Check if an earthquake has occurred
int check_earthquake() {
    int high_count = 0;
    for (int i = 0; i < event_queue.count; i++) {
        if (event_queue.events[i] == 1) {
            high_count++;
        }
    }
    return (high_count >= 3);
}

// Log an event to the file
void log_event(int event) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp.\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s %d\n", timestamp, event) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        } else {
            fflush(log_file); // Ensure data is written to disk
        }
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
    free(timestamp);
}

// Get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    if (strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
