void init_event_queue() {
    event_queue.head = 0;
    event_queue.count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        event_queue.events[i] = 0;
    }
}

// Enqueue a new event into the circular buffer
void enqueue_event(int event) {
    event_queue.events[event_queue.head] = event;
    event_queue.head = (event_queue.head + 1) % WINDOW_SIZE;
    if (event_queue.count < WINDOW_SIZE) {
        event_queue.count++;
    }
