#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDRESS 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_REGISTER_MAG_OUT_X_L_M 0x08
#define LSM303_REGISTER_MAG_OUT_X_H_M 0x09
#define LSM303_REGISTER_MAG_OUT_Z_L_M 0x0A
#define LSM303_REGISTER_MAG_OUT_Z_H_M 0x0B
#define LSM303_REGISTER_MAG_OUT_Y_L_M 0x0B
#define LSM303_REGISTER_MAG_OUT_Y_H_M 0x0C

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
void calibrate_magnetometer_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_heading(float calibrated_x, float calibrated_y);
const char *determine_compass_direction(float heading);
int log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDRESS, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, LSM303_REGISTER_MAG_OUT_X_L_M, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *z = (int16_t)((buffer[3] << 8) | buffer[2]);
    *y = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate magnetometer data
void calibrate_magnetometer_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)raw_x - X_OFFSET;
    *calibrated_y = (float)raw_y - Y_OFFSET;
    *calibrated_z = (float)raw_z - Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(float calibrated_x, float calibrated_y) {
    float heading = atan2(calibrated_y, calibrated_x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Determine compass direction
const char *determine_compass_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 67.5) {
        return "NE";
    } else if (heading >= 67.5 && heading < 112.5) {
        return "E";
    } else if (heading >= 112.5 && heading < 157.5) {
        return "SE";
    } else if (heading >= 157.5 && heading < 202.5) {
        return "S";
    } else if (heading >= 202.5 && heading < 247.5) {
        return "SW";
    } else if (heading >= 247.5 && heading < 292.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Log data to file
int log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to end for appending

    int16_t raw_x, raw_y, raw_z;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;
    const char *direction;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate magnetometer data
            calibrate_magnetometer_data(raw_x, raw_y, raw_z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Determine compass direction
            direction = determine_compass_direction(heading);

            // Log data
            log_data(calibrated_x, calibrated_y, calibrated_z, heading);

            // Print data to console
            printf("Direction: %s, Heading: %.2f degrees\n", direction, heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

