#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int last_touch_time = 0;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static FILE *log_file = NULL;
static int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce(int current_time);
int toggle_relay(int current_state);
int log_relay_state(int new_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Ensure relay is OFF on exit
    if (relay_state == 1) {
        gpioWrite(RELAY_PIN, 0);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    if (pigpio_initialized) {
        gpioTerminate();
    }

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    return 0;
}

// Read touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounce function
int debounce(int current_time) {
    return (current_time - last_touch_time) > DEBOUNCE_TIME;
}

// Toggle relay state
int toggle_relay(int current_state) {
    int new_state = !current_state;
    gpioWrite(RELAY_PIN, new_state);
    return new_state;
}

// Log relay state to file
int log_relay_state(int new_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        log_file = fopen("relay_log.json", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
    }

    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", buf, new_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (1) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            int current_time = time(NULL);
            if (debounce(current_time)) {
                relay_state = toggle_relay(relay_state);
                log_relay_state(relay_state);
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                last_touch_time = current_time;
            }
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    return 0;
}

