#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void activate_relay(int relay_pin, int duration_seconds);
void log_event(int relay_number, int moisture_level);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold relay pins
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} RelayPins;

RelayPins relays = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (running) {
        // Read the moisture sensor value
        int moisture_level = read_moisture_sensor();

        // Check if the moisture level is below the threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            // Activate each relay sequentially
            for (int i = 1; i <= 4; i++) {
                // Activate the relay
                activate_relay(relays["relay" + i], 5);

                // Log the event
                log_event(i, moisture_level);

                // Wait for 1 second
                gpioDelay(1000); // 1000 milliseconds = 1 second
            }
        }

        // Wait for 10 seconds
        gpioDelay(10000); // 10000 milliseconds = 10 seconds
    }

    // Cleanup and exit
    cleanup_gpio();
    fclose(log_file);
    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the moisture sensor value (simulated using rand())
int read_moisture_sensor() {
    return rand() % 101; // Returns a value between 0 and 100
}

// Function to activate a relay for a specified duration
void activate_relay(int relay_pin, int duration_seconds) {
    // Set the GPIO pin low to activate the relay
    gpioWrite(relay_pin, 0);

    // Wait for the specified duration
    gpioDelay(duration_seconds * 1000); // Convert seconds to milliseconds

    // Set the GPIO pin high to deactivate the relay
    gpioWrite(relay_pin, 1);
}

// Function to log an event to the log file
void log_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp as ISO 8601
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write the log entry to the file
    fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file); // Flush the buffer to ensure the data is written to the file
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Set all GPIO pins high to deactivate relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Terminate the pigpio library
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

