#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture levels
#define MOISTURE_LEVELS 5
const int moisture_levels[] = {20, 40, 60, 80, 100};

// Define pulse widths for valve servo
#define VALVE_OPEN_PULSE_WIDTH 1500
#define VALVE_CLOSE_PULSE_WIDTH 500

// Define pulse widths for nozzle servo
const int nozzle_pulse_widths[] = {500, 1000, 1500, 2000, 2500};

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to set servo pulse width with retry
int set_servo_pulse_width(int gpio, int pulse_width) {
    int retries = 0;
    int result;

    while (retries < 3) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo pulse width for GPIO %d: %d. Retry %d\n", gpio, result, retries + 1);
            retries++;
            gpioDelay(100 * (1 << retries)); // Exponential backoff
        }
    }
    fprintf(stderr, "Failed to set servo pulse width for GPIO %d after multiple retries.\n", gpio);
    return -1; // Failure
}

// Function to open the valve
int open_valve() {
    return set_servo_pulse_width(VALVE_SERVO_PIN, VALVE_OPEN_PULSE_WIDTH);
}

// Function to close the valve
int close_valve() {
    return set_servo_pulse_width(VALVE_SERVO_PIN, VALVE_CLOSE_PULSE_WIDTH);
}

// Function to sweep the nozzle
int sweep_nozzle(int pulse_widths[], int num_positions) {
    for (int i = 0; i < num_positions; i++) {
        if (set_servo_pulse_width(NOZZLE_SERVO_PIN, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error setting nozzle pulse width to %d\n", pulse_widths[i]);
            return -1;
        }
        gpioDelay(2000); // Wait 2 seconds
    }
    return 0;
}

// Function to hold the spray
int hold_spray() {
    gpioDelay(5000); // Wait 5 seconds
    return 0;
}

// Function to water the plant
int water_plant(int moisture_level) {
    if (moisture_level < 50) {
        printf("Moisture level is below 50, watering...\n");

        if (open_valve() != 0) {
            fprintf(stderr, "Failed to open valve, aborting watering cycle.\n");
            return -1;
        }

        if (sweep_nozzle(nozzle_pulse_widths, MOISTURE_LEVELS) != 0) {
            fprintf(stderr, "Failed to sweep nozzle, aborting watering cycle.\n");
            close_valve();
            return -1;
        }

        if (hold_spray() != 0) {
            fprintf(stderr, "Failed to hold spray, aborting watering cycle.\n");
            close_valve();
            return -1;
        }

        if (close_valve() != 0) {
            fprintf(stderr, "Warning: Failed to close valve.\n");
        }

        printf("Watering complete.\n");
    } else {
        printf("Moisture level is 50 or above, skipping watering.\n");
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        for (int i = 0; i < MOISTURE_LEVELS; i++) {
            if (water_plant(moisture_levels[i]) != 0) {
                fprintf(stderr, "Watering cycle failed.\n");
                break; // Exit the loop if watering fails
            }
            gpioDelay(5000); // Wait 5 seconds
        }
    }

    // Stop servos and terminate pigpio
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

