        if (read_gyro_data(&gyro_data) == 0) {
            // Log data
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Error reading or logging data. Retrying...\n");
        }

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

