#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms
#define SPEED_OF_SOUND 34300 // cm/s
#define TRIGGER_PULSE_US 10
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Function prototypes
double measure_distance();
void log_distance(double distance);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Function to measure distance using the HC-SR04 sensor
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for the echo pin to go high with timeout
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    // Wait for the echo pin to go low with timeout
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    double distance = (double)diff_tick * 34300.0 / 2000000.0; // Speed of sound in cm/us

    return distance;
}

// Function to log the distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("distance_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return;
        }
    }

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(log_file, "%s, -1\n", timestamp);
        fflush(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance >= 0) {
            log_distance(distance);
        } else {
            log_distance(-1.0);
        }

        gpioDelay(60000); // Wait 60ms
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

