#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // No specific initialization needed for this example, as the sensor
    // is assumed to be configured for continuous ranging mode.
    // However, in a real application, you would need to write specific
    // initialization commands to the sensor.
    return 0; // Return 0 for success, -1 for failure
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    char cmd[1] = {0x00}; // Command to trigger a single measurement
    char data[2]; // Buffer to store the distance data
    int result;

    // Write command to trigger measurement
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Delay to allow measurement to complete (adjust as needed)
    gpioDelay(10000); // 10ms

    // Read distance data
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Convert data to distance in centimeters
    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Control relay based on distance
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1); // Set GPIO HIGH
    } else {
        gpioWrite(GPIO_RELAY, 0); // Set GPIO LOW
    }
}

int main() {
    int distance;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
