#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the server IP address and port
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Define the watering cycle duration (in seconds)
#define WATERING_CYCLE_DURATION 86400 // 24 hours

// Define the watering duration for each relay (in seconds)
#define WATERING_DURATION 5

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Global variables
static volatile int running = 1;
static int socket_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void activate_relay(int relay_pin, int duration_seconds);
void deactivate_relay(int relay_pin);
void log_message(const char *message);
void send_log_to_server(const char *log_message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set all relays to HIGH (inactive) at startup
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Activate a relay for a specified duration
void activate_relay(int relay_pin, int duration_seconds) {
    gpioWrite(relay_pin, 0); // Set relay to LOW (active)
    gpioDelay(duration_seconds * 1000000); // Delay for the specified duration (in microseconds)
    gpioWrite(relay_pin, 1); // Set relay to HIGH (inactive)
}

// Deactivate a relay
void deactivate_relay(int relay_pin) {
    gpioWrite(relay_pin, 1); // Set relay to HIGH (inactive)
}

// Log a message to the log file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
}

// Send a log message to the server
void send_log_to_server(const char *log_message) {
    if (socket_fd == -1) {
        fprintf(stderr, "Socket not initialized\n");
        return;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("inet_pton failed");
        return;
    }

    if (sendto(socket_fd, log_message, strlen(log_message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("sendto failed");
    }
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Close the socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Create UDP socket
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("Socket creation failed");
        cleanup();
        return 1;
    }

    // Main loop
    time_t start_time = time(NULL);
    while (running) {
        time_t current_time = time(NULL);
        if (difftime(current_time, start_time) >= WATERING_CYCLE_DURATION) {
            start_time = current_time;

            // Log the start of the watering cycle
            log_message("Starting watering cycle");

            // Activate each relay in turn
            activate_relay(RELAY1_PIN, WATERING_DURATION);
            activate_relay(RELAY2_PIN, WATERING_DURATION);
            activate_relay(RELAY3_PIN, WATERING_DURATION);
            activate_relay(RELAY4_PIN, WATERING_DURATION);

            // Log the completion of the watering cycle
            log_message("Watering cycle complete");
        }

        // Send log to server
        char log_buffer[256];
        if (fgets(log_buffer, sizeof(log_buffer), log_file) != NULL) {
            send_log_to_server(log_buffer);
        }

        sleep(60); // Check every 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

