#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIOCHIP 0
#define CS_GPIOLINE 8 // GPIO8, BCM
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s for +/- 250 deg/s range
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_RATE_MS 10

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void cleanup(int fd, struct gpiod_chip *chip, struct gpiod_line *line, FILE *fp);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function with retry
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    int retries = RETRY_COUNT;
    int delay_ms = RETRY_DELAY_MS;

    while (retries > 0) {
        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx_buf,
            .rx_buf = (unsigned long)rx_buf,
            .len = len,
            .speed_hz = SPI_SPEED,
            .delay_usecs = 0,
            .bits_per_word = SPI_BITS_PER_WORD,
        };

        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return 0; // Success
        } else {
            perror("SPI transfer failed");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[7] = {0x6B, 0x01, 0x6B, 0x02, 0x6B, 0x03, 0x6B, 0x04};
    uint8_t rx_buf[7];

    if (spi_transfer(fd, tx_buf, rx_buf, 7) != 0) {
        return -1;
    }

    *x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    *y = (int16_t)((rx_buf[3] << 8) | rx_buf[4]);
    *z = (int16_t)((rx_buf[5] << 8) | rx_buf[6]);

    return 0;
}

// Function to log data to CSV file
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    char timestamp[64];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(int fd, struct gpiod_chip *chip, struct gpiod_line *line, FILE *fp) {
    if (fd != -1) {
        close(fd);
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (fp != NULL) {
        fclose(fp);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO for chip select
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup(spi_fd, NULL, NULL, NULL);
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIOLINE);
    if (!cs_line) {
        perror("Error getting GPIO line");
        cleanup(spi_fd, gpio_chip, NULL, NULL);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "gyro_cs", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup(spi_fd, gpio_chip, cs_line, NULL);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup(spi_fd, gpio_chip, cs_line, NULL);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,x_rate,y_rate,z_rate\n");
    }

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(spi_fd, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data.\n");
        }

        usleep(SAMPLE_RATE_MS * 1000); // Sample rate
    }

