#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 4000000 // 3.9 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define LED_PIN 17
#define BUFFER_SIZE 64
#define THRESHOLD 200.0 // deg/s

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Structure for gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    struct timespec timestamp;
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t gyro_buffer;

// Function prototypes
int init_spi();
void close_spi();
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
int check_threshold(gyro_data_t data);
void blink_led(int pin, int duration_ms);
void signal_handler(int signal);
void print_buffer(circular_buffer_t buffer);

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Close SPI
void close_spi() {
    spiClose(spi_handle);
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char tx[7] = {0x3B, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    char rx[7];

    if (spiXfer(spi_handle, tx, rx, 7) != 0) {
        fprintf(stderr, "Error reading SPI data\n");
        return -1;
    }

    data->x = (rx[1] << 8) | rx[0];
    data->y = (rx[3] << 8) | rx[2];
    data->z = (rx[5] << 8) | rx[4];

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    clock_gettime(CLOCK_REALTIME, &buffer->timestamp);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if any axis exceeds the threshold
int check_threshold(gyro_data_t data) {
    if (abs(data.x) > THRESHOLD || abs(data.y) > THRESHOLD || abs(data.z) > THRESHOLD) {
        return 1;
    }
    return 0;
}

// Blink LED
void blink_led(int pin, int duration_ms) {
    gpioWrite(pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(pin, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay for specified duration
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Print the contents of the circular buffer as CSV
void print_buffer(circular_buffer_t buffer) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer.count; i++) {
        int index = (buffer.head - buffer.count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld.%09ld,%d,%d,%d\n", buffer.timestamp.tv_sec, buffer.timestamp.tv_nsec, buffer.data[index].x, buffer.data[index].y, buffer.data[index].z);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    gyro_data_t gyro_data;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Check for threshold exceedance
            if (check_threshold(gyro_data)) {
                blink_led(LED_PIN, 500);
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Delay for 10ms (100Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Print the contents of the circular buffer
    print_buffer(gyro_buffer);

    // Close SPI
    close_spi();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

