#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define GPIO_LED 17
#define PROXIMITY_THRESHOLD 100
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Si1145 Registers (Example - adjust based on datasheet)
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x24

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int *ambient_light, int *proximity);
int log_data(int ambient_light, int proximity);
int control_led(int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(int *ambient_light, int *proximity) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, REG_ALS_VIS_DATA0);
        if (result >= 0) {
            *ambient_light = result;
        } else {
            fprintf(stderr, "Error reading ambient light (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        result = i2cReadWordData(i2c_handle, REG_PS1_DATA0);
        if (result >= 0) {
            *proximity = result;
        } else {
            fprintf(stderr, "Error reading proximity (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Log data to file
int log_data(int ambient_light, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,AmbientLight:%d,Proximity:%d\n", timestamp, ambient_light, proximity);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Control LED based on proximity
int control_led(int proximity) {
    if (proximity > PROXIMITY_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
    return 0;
}

int main() {
    int ambient_light, proximity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Biometric sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&ambient_light, &proximity) == 0) {
            log_data(ambient_light, proximity);
            control_led(proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    printf("Biometric sensor data logging stopped.\n");

    return 0;
}

