#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define GPIO pin for chip enable (CE0)
#define CE_PIN 8

// Define ADXRS290 register addresses
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int spi_read_register(int spi_handle, uint8_t reg_addr, uint8_t *data);
int spi_write_register(int spi_handle, uint8_t reg_addr, uint8_t data);
int read_gyro_data(int spi_handle, gyro_data_t *data);
int log_data(FILE *fp, struct timespec ts, gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read a register from the ADXRS290
int spi_read_register(int spi_handle, uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer: register address (MSB first) OR'd with the read bit
    tx_buf[0] = reg_addr | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00; // Dummy byte

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Extract the received data (second byte)
    *data = rx_buf[1];

    return 0;
}

// Function to write a register to the ADXRS290
int spi_write_register(int spi_handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer: register address (MSB first) AND'd with the write bit, data
    tx_buf[0] = reg_addr & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data;

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data (X and Y axis rates)
int read_gyro_data(int spi_handle, gyro_data_t *data) {
    uint8_t x_rate_msb, x_rate_lsb, y_rate_msb, y_rate_lsb;

    if (spi_read_register(spi_handle, ADXRS290_REG_X_RATE, &x_rate_msb) != 0) {
        fprintf(stderr, "Failed to read X rate MSB\n");
        return -1;
    }
    if (spi_read_register(spi_handle, ADXRS290_REG_X_RATE + 1, &x_rate_lsb) != 0) {
        fprintf(stderr, "Failed to read X rate LSB\n");
        return -1;
    }
    if (spi_read_register(spi_handle, ADXRS290_REG_Y_RATE, &y_rate_msb) != 0) {
        fprintf(stderr, "Failed to read Y rate MSB\n");
        return -1;
    }
    if (spi_read_register(spi_handle, ADXRS290_REG_Y_RATE + 1, &y_rate_lsb) != 0) {
        fprintf(stderr, "Failed to read Y rate LSB\n");
        return -1;
    }

    // Combine MSB and LSB to form 16-bit signed integers
    data->x_rate = (int16_t)((x_rate_msb << 8) | x_rate_lsb);
    data->y_rate = (int16_t)((y_rate_msb << 8) | y_rate_lsb);

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, struct timespec ts, gyro_data_t data) {
    if (fprintf(fp, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, data.x_rate, data.y_rate) < 0) {
        fprintf(stderr, "Error writing to file\n");
