#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION_MS 2000
#define SEISMIC_WINDOW_MS 500
#define DEBOUNCE_DELAY_MS 10

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    unsigned long last_alert_time;
} SensorState;

SensorState sensor_state = {0, 0, 0};

// Function prototypes
int initialize_gpio();
int open_log_file();
void log_event();
void alert_callback(int gpio, int level, uint32_t tick, void *user_data);
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to open the log file
int open_log_file() {
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Function to log a seismic event
void log_event() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s - Seismic event detected!\n", buf);
    fflush(log_file); // Ensure the log is written immediately
}

// Callback function for the alert pin
void alert_callback(int gpio, int level, uint32_t tick, void *user_data) {
    unsigned long current_time = gpioTick();

    if (level == 1) { // Rising edge (alert starts)
        sensor_state.last_alert_time = current_time;
    } else if (level == 0) { // Falling edge (alert ends)
        // Do nothing, just handle the rising edge
    }
}

// Callback function for the tilt sensors
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor1_value = gpioRead(SENSOR_1_PIN);
    int sensor2_value = gpioRead(SENSOR_2_PIN);

    if (sensor1_value == 1 && sensor2_value == 1) {
        unsigned long now = gpioTick();
        if (sensor_state.sensor1_state == 0 && sensor_state.sensor2_state == 0) {
            // Both sensors just went HIGH
            if (now - sensor_state.last_alert_time >= SEISMIC_WINDOW_MS * 1000) {
                gpioWrite(ALERT_PIN, 1); // Set alert HIGH
                log_event(); // Log the event
                gpioDelay(ALERT_DURATION_MS); // Wait for alert duration
                gpioWrite(ALERT_PIN, 0); // Set alert LOW
                sensor_state.last_alert_time = now;
            }
        }
        sensor_state.sensor1_state = 1;
        sensor_state.sensor2_state = 1;
    } else {
        sensor_state.sensor1_state = 0;
        sensor_state.sensor2_state = 0;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is LOW
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        cleanup();
        return 1;
    }

    // Register callbacks
    gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL);
    gpioSetAlertFuncEx(ALERT_PIN, alert_callback, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

