    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
static volatile int running = 1;
static circular_buffer_t gyro_buffer;
static int spi_handle;

// Function prototypes
int init_gpio();
int init_spi();
void close_spi();
void init_circular_buffer(circular_buffer_t *cb);
int add_to_circular_buffer(circular_buffer_t *cb, struct timespec ts, float x_rate, float y_rate);
int read_gyro_data(float *x_rate, float *y_rate);
void check_threshold(float x_rate, float y_rate);
void signal_handler(int signal);
void cleanup();

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn LED off initially

    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Close SPI
void close_spi() {
    spiClose(spi_handle);
}

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

// Add data to circular buffer
int add_to_circular_buffer(circular_buffer_t *cb, struct timespec ts, float x_rate, float y_rate) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head].timestamp = ts;
    cb->buffer[cb->head].x_rate = x_rate;
    cb->buffer[cb->head].y_rate = y_rate;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x_rate, float *y_rate) {
    char tx_buf[3];
    char rx_buf[3];
    int16_t raw_x, raw_y;

    // Set MSB for read operation
    tx_buf[0] = (REG_XGYRO_OUT | 0x80); // Read X Gyro
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed for X gyro\n");
        return -1;
    }

    raw_x = (rx_buf[1] << 8) | rx_buf[2];
    *x_rate = (float)raw_x * GYRO_SENSITIVITY;

    // Set MSB for read operation
    tx_buf[0] = (REG_YGYRO_OUT | 0x80); // Read Y Gyro
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed for Y gyro\n");
        return -1;
    }

    raw_y = (rx_buf[1] << 8) | rx_buf[2];
    *y_rate = (float)raw_y * GYRO_SENSITIVITY;

    return 0;
}

// Check threshold and control LED
void check_threshold(float x_rate, float y_rate) {
    static int led_on = 0;

    if (fabs(x_rate) > THRESHOLD || fabs(y_rate) > THRESHOLD) {
        if (!led_on) {
            gpioWrite(LED_PIN, 1); // Turn LED on
            led_on = 1;
        }
    } else {
        if (led_on) {
            gpioWrite(LED_PIN, 0); // Turn LED off
            led_on = 0;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    close_spi();
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
}

int main() {
    struct timespec ts;
    float x_rate, y_rate;

    // Initialize
    if (init_gpio() != 0) {
        return 1;
    }

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    init_circular_buffer(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_circular_buffer(&gyro_buffer, ts, x_rate, y_rate);
            check_threshold(x_rate, y_rate);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

