#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to store the total duration
int total_duration = 0;

// Function prototypes
int validate_duration(int duration);
void fade_lamp(int gpio, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all lamps
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to validate the duration
int validate_duration(int duration) {
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Invalid duration. Duration must be between 1 and 3600 seconds.\n");
        return 1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to fade a lamp
void fade_lamp(int gpio, int duration) {
    int i;
    int duty_cycle;

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration);

    for (i = PWM_RANGE; i >= 0; i--) {
        duty_cycle = i;
        gpioPWM(gpio, duty_cycle);
        usleep(duration * 1000000 / PWM_RANGE); // Calculate sleep time based on duration
    }

    printf("Lamp on GPIO %d faded to off.\n", gpio);
}

int main(int argc, char *argv[]) {
    int duration;

    // Check for command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    // Parse the duration from the command line
    duration = atoi(argv[1]);

    // Validate the duration
    if (validate_duration(duration)) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop: fade lamps sequentially
    fade_lamp(LAMP1_GPIO, duration);
    fade_lamp(LAMP2_GPIO, duration);
    fade_lamp(LAMP3_GPIO, duration);

    printf("Sunset simulation complete.\n");

    // Terminate pigpio (this might not be reached if a signal is caught)
    gpioTerminate();

    return 0;
}

