#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the traffic lights
#define RED1 17
#define RED2 22
#define GREEN 23
#define YELLOW 24

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error setting GPIO %d to state %d\n", gpio, state);
        return -1;
    }
    return 0;
}

// Function to run the traffic light sequence
void run_traffic_light() {
    // Red for 10 seconds
    printf("Red 1, Red 2, Green, Yellow: LOW, LOW, HIGH, HIGH\n");
    if (set_gpio_state(RED1, 0) != 0 || set_gpio_state(RED2, 0) != 0 || set_gpio_state(GREEN, 1) != 0 || set_gpio_state(YELLOW, 1) != 0) return;
    gpioDelay(10000000); // 10 seconds

    // Red + Yellow for 2 seconds
    printf("Red 1, Red 2, Green, Yellow: LOW, LOW, HIGH, LOW\n");
    if (set_gpio_state(RED1, 0) != 0 || set_gpio_state(RED2, 0) != 0 || set_gpio_state(GREEN, 1) != 0 || set_gpio_state(YELLOW, 0) != 0) return;
    gpioDelay(2000000); // 2 seconds

    // Green for 10 seconds
    printf("Red 1, Red 2, Green, Yellow: HIGH, HIGH, LOW, HIGH\n");
    if (set_gpio_state(RED1, 1) != 0 || set_gpio_state(RED2, 1) != 0 || set_gpio_state(GREEN, 0) != 0 || set_gpio_state(YELLOW, 1) != 0) return;
    gpioDelay(10000000); // 10 seconds

    // Yellow for 3 seconds
    printf("Red 1, Red 2, Green, Yellow: HIGH, HIGH, HIGH, LOW\n");
    if (set_gpio_state(RED1, 1) != 0 || set_gpio_state(RED2, 1) != 0 || set_gpio_state(GREEN, 0) != 0 || set_gpio_state(YELLOW, 0) != 0) return;
    gpioDelay(3000000); // 3 seconds
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RED1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RED2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RED2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GREEN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(YELLOW, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", YELLOW);
        gpioTerminate();
        return 1;
    }

    // Set initial states (all HIGH, inactive)
    if (set_gpio_state(RED1, 1) != 0 || set_gpio_state(RED2, 1) != 0 || set_gpio_state(GREEN, 1) != 0 || set_gpio_state(YELLOW, 1) != 0) {
        gpioTerminate();
        return 1;
    }

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to run the traffic light sequence indefinitely
    while (!terminate) {
        run_traffic_light();
    }

    // Cleanly release GPIO resources before exiting
    printf("Cleaning up GPIO resources...\n");
    if (set_gpio_state(RED1, 1) != 0 || set_gpio_state(RED2, 1) != 0 || set_gpio_state(GREEN, 1) != 0 || set_gpio_state(YELLOW, 1) != 0) {
        fprintf(stderr, "Error setting GPIO to initial state during cleanup\n");
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

