#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define MPR121_I2C_ADDR 0x5A
#define RELAY_PIN 17 // BCM GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define POLLING_DELAY_MS 10

// Global variables
int i2c_fd;
FILE *log_file;
bool relay_state = false;
time_t last_touch_time = 0;

// Function prototypes
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void relay_control(int pin, bool state);
void log_error(const char *message);
void signal_handler(int signal);

// Function to initialize the MPR121
int mpr121_init(int fd) {
    // Stop mode
    if (wiringPiI2CWriteReg8(fd, 0x80, 0x63) < 0) {
        log_error("Failed to set MPR121 to stop mode");
        return -1;
    }
    delay(1); // Small delay after stop mode

    // Electrode configuration (enable all 12 electrodes)
    if (wiringPiI2CWriteReg8(fd, 0x5E, 0x3F) < 0) {
        log_error("Failed to configure electrode sensitivity");
        return -1;
    }

    // Set touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(fd, 0x41 + 2 * i, 40) < 0) { // Touch threshold
            log_error("Failed to set touch threshold");
            return -1;
        }
        if (wiringPiI2CWriteReg8(fd, 0x42 + 2 * i, 20) < 0) { // Release threshold
            log_error("Failed to set release threshold");
            return -1;
        }
    }

    // Start mode (enable all electrodes)
    if (wiringPiI2CWriteReg8(fd, 0x80, 0x10) < 0) {
        log_error("Failed to set MPR121 to start mode");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int fd) {
    int touch_status = wiringPiI2CReadReg8(fd, 0x00);
    if (touch_status < 0) {
        log_error("Failed to read touch status");
        return -1;
    }
    return touch_status;
}

// Function to control the relay
void relay_control(int pin, bool state) {
    digitalWrite(pin, state ? HIGH : LOW);
    relay_state = state;
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    relay_control(RELAY_PIN, LOW); // Turn off the relay
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed!\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file!\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_I2C_ADDR);
    if (i2c_fd == -1) {
        log_error("Failed to initialize I2C");
        fclose(log_file);
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) == -1) {
        log_error("MPR121 initialization failed");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    relay_control(RELAY_PIN, LOW); // Initialize relay to OFF

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status < 0) {
            log_error("Failed to read touch status, retrying...");
            delay(100); // Wait before retrying
            continue;
        }

        if (touch_status & 0x01) { // Check if electrode 0 is touched
            time_t now = time(NULL);
            if (difftime(now, last_touch_time) * 1000 >= DEBOUNCE_DELAY_MS) {
                relay_control(RELAY_PIN, !relay_state); // Toggle relay state
                last_touch_time = now;
            }
        }

        delay(POLLING_DELAY_MS);
    }

    return 0;
}

