int log_dispense_event(int solenoid_pin, int duration_ms) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Write log entry
    fprintf(fp, "%s, %d, %d\n", timestamp, solenoid_pin, duration_ms);

    // Close log file
    fclose(fp);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Dispense solenoid 1
        if (dispense_solenoid(SOLENOID_1_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Error dispensing solenoid 1\n");
        } else {
            if (log_dispense_event(SOLENOID_1_PIN, DISPENSE_DURATION_MS) != 0) {
