#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO4 as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", TOUCH_SENSOR_PIN);
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to toggle the relay state
int toggle_relay() {
    int current_relay_state = gpioRead(RELAY_PIN);
    if (current_relay_state < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", RELAY_PIN);
        return -1; // Indicate error
    }

    // Toggle the relay state
    if (current_relay_state == 0) {
        if (gpioWrite(RELAY_PIN, 1) != 0) {
            fprintf(stderr, "Failed to write to GPIO%d\n", RELAY_PIN);
            return -1; // Indicate error
        }
    } else {
        if (gpioWrite(RELAY_PIN, 0) != 0) {
            fprintf(stderr, "Failed to write to GPIO%d\n", RELAY_PIN);
            return -1; // Indicate error
        }
    }

    return 0;
}

// Function to perform debouncing
void debounce() {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();
        if (touch_detected < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting\n");
            break; // Exit loop on error
        }

        if (touch_detected == 1) {
            printf("Touch detected!\n");
            if (toggle_relay() != 0) {
                fprintf(stderr, "Error toggling relay, exiting\n");
                break; // Exit loop on error
            }
            debounce(); // Debounce the input
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup GPIO resources before exiting
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

