#include <wiringPiSPI.h>
#include <alsa/asoundlib.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Configuration
#define DEFAULT_SAMPLE_RATE 8000
#define DEFAULT_PERIOD_SIZE 1024
#define DEFAULT_SENSITIVITY 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_DHT22_PIN 4
#define DEFAULT_MOTION_SENSOR_PIN 22
#define DEFAULT_LED_RED_PIN 17
#define DEFAULT_LED_GREEN_PIN 18
#define DEFAULT_LED_BLUE_PIN 27
#define DEFAULT_MOTION_LED_PIN 23
#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_SPI_SPEED 1000000 // 1 MHz
#define DEFAULT_DHT22_RETRY_COUNT 3

// Global variables
static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle = NULL;
static int spi_channel = DEFAULT_SPI_CHANNEL;
static int spi_speed = DEFAULT_SPI_SPEED;
static float sensitivity = DEFAULT_SENSITIVITY;
static char *server_ip = NULL;
static int server_port = DEFAULT_SERVER_PORT;
static int dht22_pin = DEFAULT_DHT22_PIN;
static int motion_sensor_pin = DEFAULT_MOTION_SENSOR_PIN;
static int led_red_pin = DEFAULT_LED_RED_PIN;
static int led_green_pin = DEFAULT_LED_GREEN_PIN;
static int led_blue_pin = DEFAULT_LED_BLUE_PIN;
static int motion_led_pin = DEFAULT_MOTION_LED_PIN;
static int dht22_retry_count = DEFAULT_DHT22_RETRY_COUNT;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle, int sample_rate, int period_size);
int init_gpio(int led_red_pin, int led_green_pin, int led_blue_pin, int motion_led_pin);
int init_spi(int spi_channel, int spi_speed);
DHT22Data read_dht22(int pin);
int read_motion_sensor(int pin);
int send_data(float temperature, float humidity, int motion_detected);
void set_led_color(int red, int green, int blue);
void signal_handler(int sig);
void cleanup();
void log_message(const char *message);
void log_error(const char *message);

// ALSA-related functions (behind ALSA_AVAILABLE macro)
#ifdef ALSA_AVAILABLE
int init_alsa(snd_pcm_t **pcm_handle, int sample_rate, int period_size) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        log_error("Error opening PCM device");
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        log_error("Error setting HW params");
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        log_error("Error setting access");
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        log_error("Error setting format");
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, 1)) < 0) {
        log_error("Error setting channels");
        return -1;
    }

    unsigned int rate = sample_rate;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        log_error("Error setting rate");
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, period_size, 0)) < 0) {
        log_error("Error setting period size");
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        log_error("Error setting HW params");
        return -1;
    }

    if ((err = snd_pcm_prepare(*pcm_handle)) < 0) {
        log_error("Error preparing PCM device");
        return -1;
    }

    return 0;
}
#endif

// GPIO-related functions
int init_gpio(int led_red_pin, int led_green_pin, int led_blue_pin, int motion_led_pin) {
    if (wiringPiSetupGpio() == -1) {
        log_error("Error initializing wiringPi");
        return -1;
    }

    pinMode(led_red_pin, OUTPUT);
    pinMode(led_green_pin, OUTPUT);
    pinMode(led_blue_pin, OUTPUT);
    pinMode(motion_led_pin, OUTPUT);

    return 0;
}

// SPI-related functions
int init_spi(int spi_channel, int spi_speed) {
    if (wiringPiSPISetup(spi_channel, spi_speed) == -1) {
        log_error("Error initializing SPI");
        return -1;
    }
    return 0;
}

// DHT22-related functions
DHT22Data read_dht22(int pin) {
    DHT22Data data = {0.0, 0.0};
    int data_bits[40] = {0};
    int i, j;

    // Send start signal
    pinMode(pin, OUTPUT);
    digitalWrite(pin, LOW);
    delay(1); // > 1ms
    digitalWrite(pin, HIGH);
    delayMicroseconds(30); // 20-40us
    pinMode(pin, INPUT);
    pullUpDnControl(pin, PUD_UP);
    delayMicroseconds(40); // Wait for response

    // Read data
    for (i = 0; i < 40; i++) {
        // Wait for low
        int count = 0;
        while (digitalRead(pin) == LOW) {
            count++;
            delayMicroseconds(1); // Check every microsecond
            if (count > 100) {
                log_error("DHT22 timeout waiting for low");
                return data; // Return default values on timeout
            }
        }

        // Measure high time
        count = 0;
        while (digitalRead(pin) == HIGH) {
            count++;
            delayMicroseconds(1); // Check every microsecond
            if (count > 100) {
                log_error("DHT22 timeout waiting for high");
                return data; // Return default values on timeout
            }
        }

        // Determine bit value (0 if < 40us, 1 if > 40us)
        data_bits[i] = (count > 40) ? 1 : 0;
    }

    // Convert data bits to bytes
    int data_bytes[5] = {0};
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            data_bytes[i] <<= 1;
            data_bytes[i] |= data_bits[i * 8 + j];
        }
    }

    // Verify checksum
    if (data_bytes[4] != ((data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) & 0xFF)) {
        log_error("DHT22 checksum error");
        return data; // Return default values on checksum error
    }

    // Convert data
    data.humidity = (float)(((data_bytes[0] << 8) | data_bytes[1])) / 10.0;
    data.temperature = (float)(((data_bytes[2] & 0x7F) << 8) | data_bytes[3]) / 10.0;
    if (data_bytes[2] & 0x80) {
