#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Integration time (154ms)
#define INTEGRATION_TIME 0x0F

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable the sensor (power on and enable RGBC)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ENABLE: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, INTEGRATION_TIME) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ATIME: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    unsigned char buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error reading color data: %s\n", strerror(errno));
        data.clear = 0;
        data.red = 0;
        data.green = 0;
        data.blue = 0;
        return data;
    }

    // Combine the bytes to form 16-bit values
    data.clear = (buffer[1] << 8) | buffer[0];
    data.red = (buffer[3] << 8) | buffer[2];
    data.green = (buffer[5] << 8) | buffer[4];
    data.blue = (buffer[7] << 8) | buffer[6];

    return data;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%ld,%s,%u,%u,%u,%u\n", now, timestamp, data.clear, data.red, data.green, data.blue);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to clean up resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open the CSV file for writing
    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write the header row
    fprintf(fp, "Unix Epoch Timestamp,Unix Epoch Timestamp (ISO 8601),Clear,Red,Green,Blue\n");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(500000); // 500ms delay
    }

    // Clean up and exit
    cleanup();
    return 0;
}

