#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Function to set the duty cycle for all relays
void set_duty_cycle(int duty_cycle) {
    gpioWrite(RELAY1_PIN, duty_cycle > 0 ? 0 : 1); // Active-low relay
    gpioWrite(RELAY2_PIN, duty_cycle > 0 ? 0 : 1);
    gpioWrite(RELAY3_PIN, duty_cycle > 0 ? 0 : 1);
    gpioWrite(RELAY4_PIN, duty_cycle > 0 ? 0 : 1);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Sunrise phase (1 hour)
    printf("Starting sunrise phase...\n");
    for (int i = 0; i <= 100; ++i) {
        set_duty_cycle(i);
        gpioDelay(60000); // 60 seconds
    }

    // Daytime phase (6 hours)
    printf("Starting daytime phase...\n");
    for (int i = 100; i >= 0; --i) {
        set_duty_cycle(i);
        gpioDelay(3600000); // 1 hour
    }

    // Sunset phase (1 hour)
    printf("Starting sunset phase...\n");
    for (int i = 0; i <= 100; ++i) {
        set_duty_cycle(100 - i);
        gpioDelay(60000); // 60 seconds
    }

    // Nighttime phase (14.4 hours)
    printf("Starting nighttime phase...\n");
    for (int i = 0; i < 864000; i += 360000) { // 14.4 hours * 60 minutes/hour = 864000 seconds
        set_duty_cycle(0);
        gpioDelay(3600000); // 1 hour
    }

    // Turn off all relays before exiting
    printf("Turning off all relays...\n");
    set_duty_cycle(0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

