#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define SENSOR_3_GPIO 27

// Define the log file path
#define LOG_FILE "/home/pi/logs/motion_log.txt"

// Define the video directory
#define VIDEO_DIR "/home/pi/videos/"

// Debounce interval in milliseconds
#define DEBOUNCE_INTERVAL 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int debounce(int gpio_pin, int last_trigger_time);
int capture_video();
int log_motion_event();
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;

        // Close the log file if it's open
        if (log_file != NULL) {
            fclose(log_file);
            printf("Log file closed.\n");
        }

        // Terminate the pigpio library
        gpioTerminate();
        printf("pigpio terminated.\n");

        exit(0);
    }
}

// Function to initialize the pigpio library and set GPIO pins as inputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_3_GPIO, PI_INPUT);

    return 0;
}

// Function to read the digital value from a specified GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to debounce the sensor input
int debounce(int gpio_pin, int last_trigger_time) {
    int current_value = read_sensor(gpio_pin);
    int current_time = time(NULL);

    if (current_value == 0) { // Active-low sensor
        if (current_time - last_trigger_time >= DEBOUNCE_INTERVAL / 1000) {
            return 1; // Valid trigger
        }
    }

    return 0; // No valid trigger
}

// Function to capture a video using raspivid
int capture_video() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];
    char command[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), VIDEO_DIR "%Y%m%d_%H%M%S.h264", timeinfo);
    snprintf(command, sizeof(command), "raspivid -o %s", filename);

    printf("Executing command: %s\n", command);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspivid command\n");
        return 1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d\n", WEXITSTATUS(status));
        return 1;
    }

    printf("Video captured: %s\n", filename);
    return 0;
}

// Function to log a motion event to the log file
int log_motion_event() {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        free(timestamp);
        return 1;
    }

    fprintf(log_file, "%s Motion detected\n", timestamp);
    fclose(log_file);
    free(timestamp);

    printf("Motion event logged: %s\n", timestamp);
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    int last_trigger_time_1 = 0;
    int last_trigger_time_2 = 0;
    int last_trigger_time_3 = 0;

    while (running) {
        // Read sensor 1
        if (read_sensor(SENSOR_1_GPIO) == 0) {
            if (debounce(SENSOR_1_GPIO, last_trigger_time_1)) {
                printf("Motion detected by sensor 1\n");
                if (capture_video() == 0 && log_motion_event() == 0) {
                    last_trigger_time_1 = time(NULL);
                }
            }
        }

        // Read sensor 2
        if (read_sensor(SENSOR_2_GPIO) == 0) {
            if (debounce(SENSOR_2_GPIO, last_trigger_time_2)) {
                printf("Motion detected by sensor 2\n");
                if (capture_video() == 0 && log_motion_event() == 0) {
                    last_trigger_time_2 = time(NULL);
                }
            }
        }

        // Read sensor 3
        if (read_sensor(SENSOR_3_GPIO) == 0) {
            if (debounce(SENSOR_3_GPIO, last_trigger_time_3)) {
                printf("Motion detected by sensor 3\n");
                if (capture_video() == 0 && log_motion_event() == 0) {
                    last_trigger_time_3 = time(NULL);
                }
            }
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

