void control_relays(int moisture_level) {
    int relay1_state = 1; // Default to OFF
    int relay2_state = 1; // Default to OFF
    int relay3_state = 1; // Default to OFF
    int relay4_state = 1; // Default to OFF

    if (moisture_level < 30) {
        relay1_state = 0; // Activate relay 1
