    while (running) {
        // Read moisture sensor
        int moisture_level = read_moisture_sensor();

        // Control relays
        control_relays(moisture_level);

        // Log data
        if (log_data(moisture_level, gpioRead(RELAY1_PIN), gpioRead(RELAY2_PIN), gpioRead(RELAY3_PIN), gpioRead(RELAY4_PIN)) != 0) {
            fprintf(stderr, "Error logging data!\n");
