#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION 0.5f
#define ALARM_GPIO 27
#define ALARM_DURATION 5f

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_adxl345();
accelerometer_data_t read_acceleration();
int detect_freefall(accelerometer_data_t data);
int trigger_alarm();
int log_freefall(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
    exit(0);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// ADXL345 configuration function
int configure_adxl345() {
    // Set data format: full resolution, +/- 2g range
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Failed to write to DATA_FORMAT register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
accelerometer_data_t read_acceleration() {
    accelerometer_data_t data;
    char raw_data[6];

    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
        data.x = 0.0f;
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    // Combine high and low bytes, convert to g-force units
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    data.x = (float)x / 256.0f; // Assuming +/- 2g range and 10-bit resolution
    data.y = (float)y / 256.0f;
    data.z = (float)z / 256.0f;

    return data;
}

// Function to detect freefall
int detect_freefall(accelerometer_data_t data) {
    return (fabs(data.x) < FREEFALL_THRESHOLD &&
            fabs(data.y) < FREEFALL_THRESHOLD &&
            fabs(data.z) < FREEFALL_THRESHOLD);
}

// Function to trigger the alarm
int trigger_alarm() {
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    gpioDelay(ALARM_DURATION * 1000000); // Delay for 5 seconds
    gpioWrite(ALARM_GPIO, 0); // Set GPIO low
    return 0;
}

// Function to log freefall event
int log_freefall(accelerometer_data_t data) {
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure ADXL345
    if (configure_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("ADXL345 freefall detection started. Press Ctrl+C to exit.\n");

    time_t start_time, current_time;
    int freefall_count = 0;

    while (!terminate) {
        accelerometer_data_t data = read_acceleration();

        if (detect_freefall(data)) {
            freefall_count++;
            if (freefall_count >= (int)(FREEFALL_DURATION * 10)) { // Check for 0.5 seconds (10 * 100ms)
                printf("Freefall detected!\n");
                trigger_alarm();
                log_freefall(data);
                freefall_count = 0; // Reset counter after logging
            }
        } else {
            freefall_count = 0; // Reset counter if not in freefall
        }

        gpioDelay(100000); // Delay for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();

    return 0;
}

