#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10  // microseconds
#define TIMEOUT_DURATION 100       // milliseconds
#define MAX_PULSE_WIDTH 23200      // microseconds (4 meters)
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile int pulse_width = 0;
static volatile int echo_received = 0;
static volatile int timeout_occurred = 0;
static pthread_mutex_t mutex;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void timeout_callback();
void log_distance(double distance);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for rising edge of the echo pulse
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_width = tick;
        echo_received = 1;
    }
}

// Callback function for falling edge of the echo pulse
void timeout_callback() {
    timeout_occurred = 1;
}

// Function to log the distance to a file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (ts.tv_sec * 1000000000) + (ts.tv_nsec);

    if (log_file != NULL) {
        fprintf(log_file, "%ld,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    // Cancel callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    // Set up interrupt handlers
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for ECHO_PIN\n");
        cleanup();
        return 1;
    }

    // Set up timeout callback
    gpioSetTimerFuncEx(0, TIMEOUT_DURATION, timeout_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();

        // Wait for echo or timeout
        while (!echo_received && !timeout_occurred) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (timeout_occurred) {
            fprintf(stderr, "Timeout occurred. No echo received.\n");
            timeout_occurred = 0; // Reset timeout flag
        } else {
            // Calculate distance
            double distance = (double)(pulse_width - gpioTick()) / 2.0 / 1000000.0 * 34300.0; // cm

            // Validate distance
            if (distance > 0 && distance < MAX_PULSE_WIDTH / 1000.0) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
            }
        }

        echo_received = 0; // Reset echo received flag
        timeout_occurred = 0; // Reset timeout flag
        gpioDelay(200); // Wait 200ms before next trigger
    }

    cleanup();
    return 0;
}

