#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

// Default values for free-fall and impact thresholds
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f

// GPIO pin for the buzzer
#define BUZZER_PIN 17

// Global variables
int i2c_handle;
float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
float impact_threshold = DEFAULT_IMPACT_THRESHOLD;
bool running = true;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void activate_buzzer();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0); // Bus 1, address 0x18, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the LIS3DH accelerometer
int init_lis3dh() {
    // Enable all axes and set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L | 0x80, buffer, 6) == 6) {
            // Combine high and low bytes for each axis
            int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

            // Convert raw values to g units (assuming +/- 2g full-scale)
            *x = (float)x_raw / 16384.0f;
            *y = (float)y_raw / 16384.0f;
            *z = (float)z_raw / 16384.0f;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1; // Failure
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to activate the buzzer for 1 second
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(1000000);       // Wait for 1 second (1000000 microseconds)
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "f:i:")) != -1) {
        switch (opt) {
            case 'f':
                freefall_threshold = atof(optarg);
                break;
            case 'i':
                impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-f freefall_threshold] [-i impact_threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    printf("Monitoring acceleration... Press Ctrl+C to exit.\n");

    while (running) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > impact_threshold) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        gpioDelay(10000); // Delay 10 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

