#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH Registers
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Default I2C address
#define DEFAULT_I2C_ADDRESS 0x18

// Default threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int address);
int configure_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
void log_high_acceleration(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// LIS3DH configuration function
int configure_lis3dh() {
    // CTRL_REG1: 0x77 (ODR = 100Hz, Enable all axes)
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: 0x88 (FS = +/-2g, High Resolution)
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Acceleration reading function
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0; *y = 0; *z = 0;
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Acceleration conversion function
float convert_to_g(int16_t raw_value) {
    // Assuming +/- 2g range and 12-bit left-justified
    return (float)raw_value / 2048.0f; // 2^11 = 2048
}

// High acceleration logging function
void log_high_acceleration(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address != 0x18 && i2c_address != 0x19) {
                    fprintf(stderr, "Invalid I2C address. Must be 0x18 or 0x19.\n");
                    return 0;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 0;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 0;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 0;
    }

    // Configure LIS3DH
    if (configure_lis3dh() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Convert to g
            float x_g = convert_to_g(x);
            float y_g = convert_to_g(y);
            float z_g = convert_to_g(z);

            // Check for high acceleration
            if (x_g > threshold || y_g > threshold || z_g > threshold) {
                log_high_acceleration(x, y, z);
                printf("High acceleration detected! Shutting down...\n");
                break;
            }
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    // Shutdown
    printf("Shutting down...\n");
    system("sudo shutdown -h now");

    return 0;
}

