#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Global variables
SensorReadings sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;
int running = 1; // Flag to control the main loop

// Function prototypes
int read_sensor(int gpio_pin);
void update_circular_buffer(int left, int center, int right);
void check_line_status(int center_sensor_value);
void turn_left();
void turn_right();
void stop();
void alert();
void signal_handler(int signal);

// Function to read sensor value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to update the circular buffer with new sensor readings
void update_circular_buffer(int left, int center, int right) {
    sensor_buffer[buffer_index].left = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check the line status and control the robot
void check_line_status(int center_sensor_value) {
    static int alert_count = 0;

    if (center_sensor_value == 1) {
        alert_count++;
        if (alert_count >= 5) {
            alert();
            alert_count = 0; // Reset the count after alerting
        }
    } else {
        alert_count = 0; // Reset the count if line is detected
    }

    if (center_sensor_value == 0) {
