#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define SI7210_I2C_ADDR 0x40
#define MAGNETIC_FIELD_REG 0x01
#define RELAY_PIN 17 // BCM GPIO 17
#define THRESHOLD_MT 5.0
#define RETRY_COUNT 50
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_magnetic_field();
float convert_to_millitesla(int raw_value);
void control_relay(int state);
void log_event(const char *event_type, int raw_value, float mT, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Close I2C connection
    if (i2c_fd != -1) {
        close(i2c_fd);
        printf("I2C connection closed.\n");
    }

    // Deactivate relay
    control_relay(0);
    printf("Relay deactivated.\n");

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    exit(0);
}

// I2C initialization function
int initialize_i2c() {
    i2c_fd = wiringPiI2CSetup(SI7210_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    printf("I2C initialized successfully.\n");
    return 0;
}

// Function to read magnetic field data from Si7210
int read_magnetic_field() {
    int raw_value = -1;
    int retry = 0;

    while (retry < RETRY_COUNT) {
        raw_value = wiringPiI2CReadReg16(i2c_fd, MAGNETIC_FIELD_REG);
        if (raw_value != -1) {
            return raw_value;
        } else {
            fprintf(stderr, "Error reading magnetic field data (attempt %d): %s\n", retry + 1, strerror(errno));
            log_event("ERROR", -1, -1.0, -1); // Log the error
            delay(RETRY_DELAY_MS);
            retry++;
        }
    }

    fprintf(stderr, "Timeout reading magnetic field data after %d attempts.\n", RETRY_COUNT);
    log_event("TIMEOUT", -1, -1.0, -1); // Log the timeout
    return -1; // Indicate failure
}

// Function to convert raw sensor reading to milliteslas
float convert_to_millitesla(int raw_value) {
    // Assuming a linear relationship between raw value and mT
    // This conversion factor needs to be calibrated for your specific sensor
    // and environment.
    float mT_per_unit = 0.01; // Example: 0.01 mT per unit
    return (float)raw_value * mT_per_unit;
}

// Function to control the relay
void control_relay(int state) {
    digitalWrite(RELAY_PIN, state);
    printf("Relay set to %d\n", state);
}

// Function to log events to file
void log_event(const char *event_type, int raw_value, float mT, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - %s: Raw = %d, mT = %.2f, Relay = %d\n",
            timestamp, event_type, raw_value, mT, relay_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() == -1) {
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    control_relay(0); // Ensure relay is initially off

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int raw_value = read_magnetic_field();
        if (raw_value != -1) {
            float mT = convert_to_millitesla(raw_value);
            int relay_state = digitalRead(RELAY_PIN);

            log_event("READ", raw_value, mT, relay_state);

            if (mT > THRESHOLD_MT) {
                control_relay(1); // Activate relay
                log_event("TRIGGER", raw_value, mT, 1);
            } else {
                control_relay(0); // Deactivate relay
                log_event("RELEASE", raw_value, mT, 0);
            }
        }

        delay(SAMPLE_INTERVAL_MS);
    }

    return 0;
}

