        perror("listen");
        close(fd);
        return -1;
    }
    return fd;
}

// Function to handle client connection
void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t valread;

    while (program_running) {
        valread = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
        if (valread > 0) {
            buffer[valread] = '\0';
            // Remove trailing whitespace
            while (valread > 0 && buffer[valread - 1] == ' ') {
                buffer[valread - 1] = '\0';
                valread--;
            }

            if (strcasecmp(buffer, "ON") == 0) {
                gpioWrite(GPIO_PIN, 1);
                log_event("Relay ON");
            } else if (strcasecmp(buffer, "OFF") == 0) {
                gpioWrite(GPIO_PIN, 0);
                log_event("Relay OFF");
            } else {
                log_event("Invalid command");
            }
        } else if (valread == 0) {
            printf("Client disconnected\n");
            break;
        } else {
            perror("recv failed");
            break;
        }
    }
    close(client_fd);
}

// Function to log events
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received: %d. Shutting down...\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (server_fd != -1) {
        close(server_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize GPIO
    if (setup_gpio() != 0) {
        log_event("GPIO setup failed");
        cleanup();
        return 1;
    }
    log_event("GPIO setup successful");

    // Initialize socket
    server_fd = setup_socket();
    if (server_fd == -1) {
        log_event("Socket setup failed");
        cleanup();
        return 1;
    }
    log_event("Socket setup successful");

    printf("Server listening on port %d\n", PORT);

    while (program_running) {
        struct sockaddr_in client_address;
        int client_fd;
        socklen_t client_len = sizeof(client_address);

        if ((client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len)) < 0) {
            perror("accept failed");
            log_event("Accept failed");
            break;
        }
        printf("Client connected\n");
        handle_client(client_fd);
    }

    cleanup();
    return 0;
}

