#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_RELAY 18
#define FLOW_THRESHOLD 5.0f
#define POLLING_INTERVAL_MS 100

// Global variables
static volatile int keepRunning = 1;
static int fd1 = -1; // File descriptor for sensor 1
static int fd2 = -1; // File descriptor for sensor 2

// Function prototypes
int init_i2c(int address);
int start_measurement(int fd);
int read_sensor_data(int fd, uint8_t *data);
int validate_crc(uint8_t data[], int len);
float calculate_flow_rate(uint8_t data[], int len);
int control_relay(int state);
int log_flow_rate(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        keepRunning = 0;
    }
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C for address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return fd;
}

// Start measurement on the sensor
int start_measurement(int fd) {
    uint8_t cmd[2] = {0x36, 0x08}; // Start measurement command
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Error writing start measurement command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    int bytes_read = read(fd, data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %s (read %d bytes)\n", strerror(errno), bytes_read);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// Calculate flow rate (ml/min) from raw data
float calculate_flow_rate(uint8_t data[], int len) {
    // Assuming the first two bytes represent the flow rate
    int16_t raw_flow = (data[0] << 8) | data[1];
    return (float)raw_flow / 120.0f; // Scaling factor from datasheet
}

// Control the safety relay (GPIO 18)
int control_relay(int state) {
    digitalWrite(GPIO_RELAY, state);
    return 0;
}

// Log flow rates to file
int log_flow_rate(float flow1, float flow2) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03d", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
    return 0;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C for both sensors
    fd1 = init_i2c(SENSOR1_ADDR);
    if (fd1 == -1) {
        return 1;
    }

    fd2 = init_i2c(SENSOR2_ADDR);
    if (fd2 == -1) {
        return 1;
    }

    // Start measurement on both sensors
    if (start_measurement(fd1) == -1 || start_measurement(fd2) == -1) {
        return 1;
    }

    // Configure GPIO 18 as output
    pinMode(GPIO_RELAY, OUTPUT);
    control_relay(LOW); // Initialize relay to OFF state

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t sensor1_data[3];
    uint8_t sensor2_data[3];

    // Main loop
    while (keepRunning) {
        // Read sensor data
        if (read_sensor_data(fd1, sensor1_data) == -1 || read_sensor_data(fd2, sensor2_data) == -1) {
            // Error already logged in read_sensor_data
            delay(POLLING_INTERVAL_MS);
            continue;
        }

        // Validate CRC
        if (validate_crc(sensor1_data, 3) == -1 || validate_crc(sensor2_data, 3) == -1) {
            delay(POLLING_INTERVAL_MS);
            continue;
        }

        // Calculate flow rates
        float flow1 = calculate_flow_rate(sensor1_data, 3);
        float flow2 = calculate_flow_rate(sensor2_data, 3);

        // Log flow rates
        if (log_flow_rate(flow1, flow2) == -1) {
            // Error already logged in log_flow_rate
        }

        // Control relay based on flow rates
        if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD) {
            control_relay(HIGH); // Energize relay
        } else {
            control_relay(LOW);  // De-energize relay
        }

        delay(POLLING_INTERVAL_MS);
    }

    // Cleanup
    control_relay(LOW); // Ensure relay is OFF on exit
    if (fd1 != -1) close(fd1);
    if (fd2 != -1) close(fd2);

    printf("Exiting cleanly.\n");
    return 0;
}

