#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Define debounce count
#define DEBOUNCE_COUNT 3

// Global variables
static volatile int running = 1;
static int debounce_count = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int start);
void signal_handler(int signal);
void log_event(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    log_event(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Logging function
void log_event(int priority, const char *message) {
    syslog(priority, message);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    log_event(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Control motor
int control_motor(int start) {
    if (start) {
        gpioWrite(MOTOR_ENA_PIN, 1);
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        log_event(LOG_INFO, "Motor started");
        return 0;
    } else {
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        log_event(LOG_INFO, "Motor stopped");
        return 0;
    }
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        closelog();
        return 1;
    }

    log_event(LOG_INFO, "Rain sensor monitoring started");

    int rain_detected = 0;
    int last_rain_state = 1; // Assume dry initially

    while (running) {
        int sensor_value = read_rain_sensor();

        if (sensor_value == 0 && last_rain_state == 1) {
            // Rain detected (low signal)
            rain_detected = 1;
            debounce_count++;
            if (debounce_count >= DEBOUNCE_COUNT) {
                log_event(LOG_INFO, "Rain detected, closing window");
                if (control_motor(1)) {
                    log_event(LOG_ERR, "Failed to start motor");
                }
                usleep(MOTOR_RUN_TIME * 1000000); // Sleep for motor run time
                if (control_motor(0)) {
                    log_event(LOG_ERR, "Failed to stop motor");
                }
                debounce_count = 0; // Reset debounce counter
            }
        } else if (sensor_value == 1 && last_rain_state == 0) {
            // Rain stopped (high signal)
            rain_detected = 0;
            debounce_count = 0; // Reset debounce counter
        }

        last_rain_state = sensor_value;
        usleep(200000); // Poll every 200ms
    }

    // Cleanup
    control_motor(0); // Stop motor
    gpioTerminate(); // Terminate pigpio
    log_event(LOG_INFO, "Rain sensor monitoring stopped");
    closelog(); // Close syslog

    return 0;
}

