#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_PIN 4
#define LED_PIN 17

// Define constants
#define LED_ON_TIME 60 // seconds
#define POLLING_INTERVAL 100 // milliseconds

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, double duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Control LED state
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Log event to file
int log_event(const char *event_type, double duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec start, end;
    double elapsed;

    clock_gettime(CLOCK_REALTIME, &start);

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (fprintf(log_file, "%s %s %.2f\n", timestamp, event_type, duration) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file

    clock_gettime(CLOCK_REALTIME, &end);
    elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        control_led(0);
        gpioTerminate();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_pir_sensor() == 1) {
            printf("Motion detected!\n");
            if (control_led(1) != 0) {
                fprintf(stderr, "Error controlling LED\n");
                running = 0; // Exit loop on error
                break;
            }

            log_event("Motion Detected", 0.0);

            gpioDelay(LED_ON_TIME * 1000); // Wait for LED_ON_TIME seconds

            if (control_led(0) != 0) {
                fprintf(stderr, "Error controlling LED\n");
                running = 0; // Exit loop on error
                break;
            }

            log_event("LED Off", (double)LED_ON_TIME);
        }

        gpioDelay(POLLING_INTERVAL); // Polling interval
    }

    // Cleanup
    control_led(0); // Ensure LED is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio

    printf("Motion detection system stopped.\n");

    return 0;
}

