#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Define constants
#define MPR121_I2C_ADDR 0x5A
#define RELAY_PIN 17 // BCM GPIO17
#define DEBOUNCE_DELAY_MS 200

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTERING 0x2C
#define MPR121_ELECTRODE_FILTERING 0x2D
#define MPR121_ELECTRODE_TOUCHTH_0 0x41
#define MPR121_ELECTRODE_RELEASETH_0 0x42
#define MPR121_FFE 0x5B
#define MPR121_SFE 0x5C
#define MPR121_CDE 0x5D
#define MPR121_AUTOCONFIG 0x5F
#define MPR121_ELECTRODE_COUNT 0x5B

// Global variables
static int i2c_fd;
static volatile bool running = true;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void relay_on();
void relay_off();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
    relay_off(); // Ensure relay is off on exit
    exit(0);
}

// Initialize the MPR121 sensor
int mpr121_init() {
    int retries = 3;
    while (retries > 0) {
        // Soft reset
        if (wiringPiI2CWriteReg8(i2c_fd, 0x80, 0x63) < 0) {
            fprintf(stderr, "Error: Failed to reset MPR121. Retrying...\n");
            retries--;
            delay(100); // Wait before retrying
            continue;
        }
        delay(100); // Wait for reset to complete

        // Configure baseline filtering
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_BASELINE_FILTERING, 0x0A) < 0) {
            fprintf(stderr, "Error: Failed to configure MHD. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_BASELINE_FILTERING + 1, 0x05) < 0) {
            fprintf(stderr, "Error: Failed to configure NHD. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_BASELINE_FILTERING + 2, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to configure NCL. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_BASELINE_FILTERING + 3, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to configure FDL. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }

        // Configure electrode filtering
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ELECTRODE_FILTERING, 0x0A) < 0) {
            fprintf(stderr, "Error: Failed to configure MHD. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ELECTRODE_FILTERING + 1, 0x05) < 0) {
            fprintf(stderr, "Error: Failed to configure NHD. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ELECTRODE_FILTERING + 2, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to configure NCL. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ELECTRODE_FILTERING + 3, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to configure FDL. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }

        // Set debounce
        if (wiringPiI2CWriteReg8(i2c_fd, 0x5D, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to set debounce. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }

        // Configure FFE, SFE, CDE
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_FFE, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to configure FFE. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_SFE, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to configure SFE. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_CDE, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to configure CDE. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }

        // Enable autoconfig
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_AUTOCONFIG, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to enable autoconfig. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }

        // Enable electrodes
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ELECTRODE_CONFIG, 0x0F) < 0) {
            fprintf(stderr, "Error: Failed to enable electrodes. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }

        printf("MPR121 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to initialize MPR121 after multiple retries.\n");
    return -1; // Failure
}

// Read the touch status from the MPR121
int mpr121_read_touch_status() {
