// Initialize the MPR121 sensor
int mpr121_init() {
    int retries = 3;
    while (retries > 0) {
        // Soft reset
        if (wiringPiI2CWriteReg8(i2c_fd, 0x80, 0x63) < 0) {
            fprintf(stderr, "Error: Failed to reset MPR121. Retrying...\n");
            retries--;
            delay(100); // Wait before retrying
            continue;
        }
        delay(100); // Wait for reset to complete

        // Configure baseline filtering
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_BASELINE_FILTERING, 0x0A) < 0) {
            fprintf(stderr, "Error: Failed to configure MHD. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_BASELINE_FILTERING + 1, 0x05) < 0) {
