            retries--;
            delay(100);
            continue;
        }

        // Configure FFE, SFE, CDE
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_FFE, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to configure FFE. Retrying...\n");
            retries--;
            delay(100);
            continue;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, MPR121_SFE, 0x01) < 0) {
            fprintf(stderr, "Error: Failed to configure SFE. Retrying...\n");
