#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <stdarg.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_SERVO 17
#define GPIO_PIR 4
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000
#define PWM_DUTYCYCLE 1000 // 50% duty cycle

int server_fd, new_socket;

// Function to log messages to syslog and a file
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // syslog
    vsyslog(priority, format, args);

    // File logging
    FILE *fp = fopen("security.log", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: ", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
        vfprintf(fp, format, args);
        fclose(fp);
    } else {
        syslog(LOG_ERR, "Error opening security.log for writing.");
    }
    va_end(args);
}

// Function to handle errors and log them
void handle_error(const char *message, ...) {
    va_list args;
    va_start(args, message);
    char log_message_buffer[256];
    vsnprintf(log_message_buffer, sizeof(log_message_buffer), message, args);
    log_message(LOG_ERR, "%s", log_message_buffer);
    va_end(args);
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }

    // Calculate pulse width (1000us - 2000us for 0-180 degrees)
    int pulse_width = 1000 + (int)((float)angle / 180.0 * 1000.0);

    gpioPWM(GPIO_SERVO, pulse_width);
    log_message(LOG_INFO, "Servo angle set to %d degrees (pulse width: %d)", angle, pulse_width);
    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    int pir_value = gpioRead(GPIO_PIR);
    log_message(LOG_INFO, "PIR sensor value: %d", pir_value);
    return pir_value;
}

// Function to handle client commands
void handle_client_command(int client_socket) {
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        handle_error("Error receiving data from client");
        close(client_socket);
        return;
    }

    char command[256];
    strncpy(command, buffer, sizeof(command) - 1);
    command[sizeof(command) - 1] = '\0'; // Ensure null termination

    log_message(LOG_INFO, "Received command: %s", command);

    if (strncmp(command, "SERVO:", 6) == 0) {
        int angle;
        if (sscanf(command, "SERVO:%d", &angle) == 1) {
            if (set_servo_angle(angle) != 0) {
                const char *error_message = "Failed to set servo angle";
                send(client_socket, error_message, strlen(error_message), 0);
                log_message(LOG_ERR, "%s", error_message);
            }
        } else {
            const char *error_message = "Invalid servo command format";
            send(client_socket, error_message, strlen(error_message), 0);
            log_message(LOG_ERR, "%s", error_message);
        }
    } else if (strcmp(command, "PIR") == 0) {
        int pir_value = read_pir_sensor();
        char response[10];
        snprintf(response, sizeof(response), "PIR:%d", pir_value);
        send(client_socket, response, strlen(response), 0);
    } else {
        const char *error_message = "Unknown command";
        send(client_socket, error_message, strlen(error_message), 0);
        log_message(LOG_WARNING, "%s", error_message);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received: %d. Shutting down...", signum);
    gpioPWM(GPIO_SERVO, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    close(new_socket);
    close(server_fd);
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        handle_error("pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_SERVO, PI_OUTPUT);
    gpioSetMode(GPIO_PIR, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIR, PI_PUD_DOWN); // Optional: Pull-down resistor

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_SERVO, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_SERVO, PWM_RANGE);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        handle_error("Socket creation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        handle_error("Socket bind failed");
        close(server_fd);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        handle_error("Socket listen failed");
        close(server_fd);
        gpioTerminate();
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Security server listening on port %d", PORT);

    // Accept connections and handle them
    while (1) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t *)&client_address_len);
        if (new_socket < 0) {
            handle_error("Socket accept failed");
            continue; // Continue listening for other connections
        }

        log_message(LOG_INFO, "Connection accepted from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client_command(new_socket);
        close(new_socket);
    }

    // The following lines will never be reached due to the infinite loop.
    close(server_fd);
    gpioTerminate();
    closelog();
    return 0;
}

