    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light controller started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_bh1750(&lux) == 0) {
                log_data(lux);

                if (lux < LUX_THRESHOLD) {
                    control_relay(1); // Activate relay
                } else {
                    control_relay(0); // Deactivate relay
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Sensor read failed, retrying... (%d/%d)\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(100); // Small delay before retrying
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor after %d retries. Check connection.\n", RETRY_COUNT);
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for the next sample
    }

    cleanup();
    return 0;
}

