#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static int duration = DEFAULT_DURATION;
static int tare_offset = 0;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, int tare_offset);
void control_solenoid(double weight, double threshold, int duration);
void signal_handler(int signal);
void cleanup();
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Received signal, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioSetMode(HX711_DOUT, PI_INPUT); // Set DOUT to input
    gpioSetMode(HX711_SCK, PI_INPUT); // Set SCK to input
    gpioSetMode(SOLENOID_PIN, PI_INPUT); // Set solenoid pin to input
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog
}

// Function to read raw data from HX711
int read_hx711() {
    int i;
    int data = 0;

    // Wait for DOUT to go LOW
    int timeout = 100; // Timeout after 100 attempts
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout == 0) {
        log_message(LOG_ERR, "HX711 DOUT timeout");
        return -1; // Indicate error
    }

    // Clock out 24 bits MSB-first
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // One extra clock pulse to select Channel A gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer (two's complement)
    if (data & 0x800000) {
        data |= 0xFF000000; // Sign extend
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value, int tare_offset) {
    return (double)(raw_value - tare_offset) * scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight, double threshold, int duration) {
    if (weight > threshold) {
        log_message(LOG_INFO, "Weight exceeds threshold, activating solenoid lock.");
        gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
        gpioDelay(duration); // Wait for specified duration
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
        log_message(LOG_INFO, "Solenoid lock deactivated.");
    }
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main(int argc, char *argv[]) {
    int opt;
    int num_readings = 5; // Number of readings to average per cycle

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale_factor] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    log_message(LOG_INFO, "Taring load cell...");
    int tare_sum = 0;
    for (int i = 0; i < 10; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during tare, exiting.");
            cleanup();
            return 1;
        }
        tare_sum += raw_value;
        gpioDelay(50); // Small delay between readings
    }
    tare_offset = tare_sum / 10;
    log_message(LOG_INFO, "Tare complete. Offset: %d", tare_offset);

    // Main loop
    while (running) {
        double weight_sum = 0.0;
        for (int i = 0; i < num_readings; i++) {
            int raw_value = read_hx711();
            if (raw_value == -1) {
                log_message(LOG_ERR, "Error reading HX711, exiting.");
                cleanup();
                return 1;
            }
            weight_sum += raw_value;
            gpioDelay(10); // Small delay between readings
        }
        double average_weight = calculate_weight(weight_sum / num_readings, tare_offset);
        char weight_str[50];
        snprintf(weight_str, sizeof(weight_str), "Average weight: %.2f grams", average_weight);
        log_message(LOG_INFO, weight_str);

        control_solenoid(average_weight, threshold, duration);
        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

