#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define KEEP_ALIVE 60

struct mosquitto *mosq = NULL;

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF
    log_message(LOG_INFO, "GPIO initialized");
    return 0;
}

// Function to set relay state
void set_relay_state(const char *state) {
    if (strcmp(state, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1);
        log_message(LOG_INFO, "Relay turned ON");
    } else if (strcmp(state, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0);
        log_message(LOG_INFO, "Relay turned OFF");
    } else {
        log_message(LOG_ERR, "Invalid relay state received");
    }
}

// MQTT message callback function
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        set_relay_state((char *)message->payload);
    } else {
        log_message(LOG_ERR, "Empty payload received");
    }
}

// MQTT connect callback function
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT connected");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_message(LOG_ERR, "MQTT connection error");
    }
}

// MQTT disconnect callback function
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message(LOG_WARNING, "MQTT disconnected unexpectedly");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, KEEP_ALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        sleep(1); // Keep the program running
    }

    return 0;
}

