#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PWM frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Encoder ticks per revolution
#define TICKS_PER_REVOLUTION 64

// Target RPM
#define TARGET_RPM 50

// PI controller parameters
#define Kp 0.5
#define Ki 0.1

// Stall detection timeout (seconds)
#define STALL_TIMEOUT 2

// Global variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile int encoder_a_stalled = 0;
volatile int encoder_b_stalled = 0;
volatile unsigned long last_encoder_a_tick = 0;
volatile unsigned long last_encoder_b_tick = 0;

// Mutexes for atomic operations
pthread_mutex_t encoder_a_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder_b_mutex = PTHREAD_MUTEX_INITIALIZER;

// PI controller state
double integral_a = 0;
double integral_b = 0;
double last_error_a = 0;
double last_error_b = 0;

// Structure to hold motor data
typedef struct {
    int pwm_pin;
    int dir_pin;
    volatile int *ticks;
    volatile int *stalled;
    unsigned long *last_tick;
    pthread_mutex_t *mutex;
    double *integral;
    double *last_error;
    int encoder_a_pin;
    int encoder_b_pin;
} MotorData;

// Global motor data
MotorData motor_a_data = {MOTOR_A_PWM, MOTOR_A_DIR, &encoder_a_ticks, &encoder_a_stalled, &last_encoder_a_tick, &encoder_a_mutex, &integral_a, &last_error_a, ENCODER_A_A, ENCODER_A_B};
MotorData motor_b_data = {MOTOR_B_PWM, MOTOR_B_DIR, &encoder_b_ticks, &encoder_b_stalled, &last_encoder_b_tick, &encoder_b_mutex, &integral_b, &last_error_b, ENCODER_B_A, ENCODER_B_B};

// Function prototypes
void *encoder_a_isr(void *arg);
void *encoder_b_isr(void *arg);
void set_motor_speed(int motor_data, int speed);
double calculate_rpm(volatile int *ticks);
double calculate_pwm(double rpm, double *integral, double *last_error);
void check_stall(volatile int *ticks, unsigned long *last_tick, int *stalled);
void signal_handler(int signal);

// Encoder A ISR
void *encoder_a_isr(void *arg) {
    int a_val = gpioRead(motor_a_data.encoder_a_pin);
    int b_val = gpioRead(motor_a_data.encoder_b_pin);

    if (a_val != b_val) {
        pthread_mutex_lock(&motor_a_data.mutex);
        encoder_a_ticks++;
        if (encoder_a_ticks >= TICKS_PER_REVOLUTION) {
            encoder_a_ticks = 0;
        }
        pthread_mutex_unlock(&motor_a_data.mutex);
    }

    unsigned long now = gpioTick();
    if (now - *motor_a_data.last_tick > 1000000) { // 1ms
        *motor_a_data.last_tick = now;
        check_stall(&encoder_a_ticks, motor_a_data.last_tick, motor_a_data.stalled);
    }

    return NULL;
}

// Encoder B ISR
void *encoder_b_isr(void *arg) {
    int a_val = gpioRead(motor_b_data.encoder_a_pin);
    int b_val = gpioRead(motor_b_data.encoder_b_pin);

    if (a_val != b_val) {
        pthread_mutex_lock(&motor_b_data.mutex);
        encoder_b_ticks++;
        if (encoder_b_ticks >= TICKS_PER_REVOLUTION) {
            encoder_b_ticks = 0;
        }
        pthread_mutex_unlock(&motor_b_data.mutex);
    }

    unsigned long now = gpioTick();
    if (now - *motor_b_data.last_tick > 1000000) { // 1ms
        *motor_b_data.last_tick = now;
        check_stall(&encoder_b_ticks, motor_b_data.last_tick, motor_b_data.stalled);
    }

    return NULL;
}

// Set motor speed
void set_motor_speed(int motor_data, int speed) {
    if (speed > 0) {
        gpioWrite(motor_data.dir_pin, 1); // Forward
        gpioPWM(motor_data.pwm_pin, speed);
    } else if (speed < 0) {
        gpioWrite(motor_data.dir_pin, 0); // Backward
        gpioPWM(motor_data.pwm_pin, -speed);
    } else {
        gpioWrite(motor_data.dir_pin, 0); // Stop
        gpioPWM(motor_data.pwm_pin, 0);
    }
}

// Calculate RPM
double calculate_rpm(volatile int *ticks) {
    static int last_ticks = 0;
    int current_ticks = *ticks;
    double time_diff;
    double rpm;

    pthread_mutex_lock(&encoder_a_mutex);
    int diff = current_ticks - last_ticks;
    if (diff < 0) {
        diff += TICKS_PER_REVOLUTION; // Handle wrap-around
    }
    rpm = (double)diff * 60.0 / TICKS_PER_REVOLUTION;
    pthread_mutex_unlock(&encoder_a_mutex);

    last_ticks = current_ticks;
    return rpm;
}

// Calculate PWM duty cycle using PI controller
double calculate_pwm(double rpm, double *integral, double *last_error) {
    double error = TARGET_RPM - rpm;

    *integral += error;
    if (*integral > 255) *integral = 255;
    if (*integral < 0) *integral = 0;

    double output = Kp * error + Ki * (*integral);

    if (output > 255) output = 255;
    if (output < 0) output = 0;

    *last_error = error;
    return output;
}

// Check for stall
void check_stall(volatile int *ticks, unsigned long *last_tick, int *stalled) {
    static unsigned long stall_start_time = 0;
    static int stall_detected = 0;

    if (*ticks == 0) {
        if (!stall_detected) {
            stall_start_time = gpioTick() / 1000; // Get seconds
            stall_detected = 1;
        }
        if (gpioTick() / 1000 - stall_start_time > STALL_TIMEOUT) {
            if (!(*stalled)) {
                printf("Warning: Motor A stalled!\n");
                *stalled = 1;
            }
        }
    } else {
        stall_detected = 0;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Stopping motors and exiting.\n");

    // Stop motors
    set_motor_speed(motor_a_data, 0);
    set_motor_speed(motor_b_data, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_PWM, 255);
    gpioSetPWMrange(MOTOR_B_PWM, 255);

    // Register ISRs
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Calculate RPM
        double rpm_a = calculate_rpm(&encoder_a_ticks);
        double rpm_b = calculate_rpm(&encoder_b_ticks);

        // Calculate PWM duty cycles
        double pwm_a = calculate_pwm(rpm_a, &integral_a, &last_error_a);
        double pwm_b = calculate_pwm(rpm_b, &integral_b, &last_error_b);

        // Set motor speeds
        set_motor_speed(motor_a_data, (int)pwm_a);
        set_motor_speed(motor_b_data, (int)pwm_b);

        // Print motor data
        printf("Motor A: RPM = %.2f, PWM = %.2f\n", rpm_a, pwm_a);
        printf("Motor B: RPM = %.2f, PWM = %.2f\n", rpm_b, pwm_b);

        // Sleep for 100ms
        gpioDelay(100000); // 100ms
    }

    return 0;
}

