    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_PWM, 255);
    gpioSetPWMrange(MOTOR_B_PWM, 255);

    // Register ISRs
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Calculate RPM
        double rpm_a = calculate_rpm(&encoder_a_ticks);
        double rpm_b = calculate_rpm(&encoder_b_ticks);

        // Calculate PWM duty cycles
        double pwm_a = calculate_pwm(rpm_a, &integral_a, &last_error_a);
        double pwm_b = calculate_pwm(rpm_b, &integral_b, &last_error_b);

        // Set motor speeds
        set_motor_speed(motor_a_data, (int)pwm_a);
        set_motor_speed(motor_b_data, (int)pwm_b);

        // Print motor data
        printf("Motor A: RPM = %.2f, PWM = %.2f\n", rpm_a, pwm_a);
        printf("Motor B: RPM = %.2f, PWM = %.2f\n", rpm_b, pwm_b);

        // Sleep for 100ms
        gpioDelay(100000); // 100ms
    }

    return 0;
}

