#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_RELAY 17
#define LUX_DUSK 50
#define LUX_DAWN 200
#define POLL_INTERVAL_SEC 5
#define POLL_INTERVAL_MS 0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int retries = 0;

    // Send mode command
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing mode command: %d\n", i2c_handle);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200000); // 200ms

    while (retries < MAX_RETRIES) {
        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            unsigned int raw_value = (buf[0] << 8) | buf[1];
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Sensor non-response after %d retries.\n", MAX_RETRIES);
    return -1; // Sensor non-response
}

// Control the relay (ON/OFF)
int control_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", GPIO_RELAY);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Turn off relay
    gpioTerminate();
}

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Chicken Coop Light Controller started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read light level
        if (read_bh1750(&lux) == 0) {
            // Control relay based on light level and hysteresis
            if (lux < LUX_DUSK && relay_state == 0) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    log_data(lux, relay_state);
                }
            } else if (lux > LUX_DAWN && relay_state == 1) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    log_data(lux, relay_state);
                }
            } else {
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Error reading light level. Retrying...\n");
            log_data(-1.0, relay_state); // Log error
        }

        // Wait before next poll
        gpioDelay(POLL_INTERVAL_SEC * 1000000 + POLL_INTERVAL_MS * 1000); // microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

