#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
void toggle_relay(int current_state);
void log_relay_state(int new_state);
void debounce_delay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        // Turn off the relay
        gpioWrite(RELAY_PIN, 0);
        // Terminate the pigpio library
        gpioTerminate();
        exit(0);
    }
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay(int current_state) {
    int new_state = !current_state;
    gpioWrite(RELAY_PIN, new_state);
    log_relay_state(new_state);
}

// Function to log the relay state with a timestamp
void log_relay_state(int new_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is now %s\n", timestamp, new_state ? "ON" : "OFF");
}

// Function to implement a delay using pigpio
void debounce_delay() {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the touch sensor
        int touch_detected = read_touch_sensor();

        // Check if a touch is detected and the relay is currently OFF
        if (touch_detected && !relay_state) {
            // Toggle the relay state
            toggle_relay(relay_state);
            // Debounce delay
            debounce_delay();
        }

        // Check if the touch is released and the relay is currently ON
        if (!touch_detected && relay_state) {
            // Turn the relay OFF
            gpioWrite(RELAY_PIN, 0);
            relay_state = 0;
            log_relay_state(relay_state);
        }

        // Sleep for 10 milliseconds
        gpioDelay(10000); // 10 milliseconds
    }

    // The program should never reach here, but it's good practice to include gpioTerminate()
    gpioTerminate();
    return 0;
}

