#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD 5.0
#define LPM_HYSTERESIS 4.5
#define DEBOUNCE_TIME_US 1000000 // 1 second in microseconds

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
int solenoid_state = 1; // 1 = open, 0 = closed

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
float calculate_lpm(int pulse_count, float time_elapsed);
void control_solenoid(float lpm);
void log_data(float lpm, int solenoid_state);
void signal_handler(int signal);

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate LPM
float calculate_lpm(int pulse_count, float time_elapsed) {
    return (float)pulse_count / PULSES_PER_LITER / (time_elapsed / 60.0);
}

// Function to control the solenoid valve
void control_solenoid(float lpm) {
    if (lpm > LPM_THRESHOLD && solenoid_state == 1) {
        gpioWrite(SOLENOID_GPIO, 0); // Close the valve
        solenoid_state = 0;
        log_data(lpm, solenoid_state);
    } else if (lpm < LPM_HYSTERESIS && solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1); // Open the valve
        solenoid_state = 1;
        log_data(lpm, solenoid_state);
    }
}

// Function to log data to a file
void log_data(float lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "Open" : "Closed");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Signal received, shutting down...\n", timestamp);
    fflush(log_file);

    gpioWrite(SOLENOID_GPIO, 1); // Open the valve
    solenoid_state = 1;

    if (log_file != NULL) {
        fclose(log_file);
    }

    pthread_mutex_destroy(&pulse_mutex);

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Set pull-up/down resistor (optional, depending on sensor wiring)
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIME_US, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    time_t last_log_time = time(NULL);
    int last_pulse_count = 0;

    // Main loop
    while (1) {
        time_t current_time = time(NULL);
        float time_elapsed = difftime(current_time, last_log_time);

        // Calculate LPM
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next second
        pthread_mutex_unlock(&pulse_mutex);

        float lpm = calculate_lpm(current_pulse_count - last_pulse_count, time_elapsed);

        // Control solenoid
        control_solenoid(lpm);

        // Log data every second
        if (current_time - last_log_time >= 1) {
            log_data(lpm, solenoid_state);
            last_log_time = current_time;
            last_pulse_count = current_pulse_count;
        }

        gpioDelay(1000); // Check every 1 ms
    }

    return 0;
}

