#define DEFAULT_STABILIZATION_TIME 1
#define DEFAULT_SERVO_PULSE_WIDTH 1500
#define DEFAULT_TARGET_WEIGHT 100.0
#define DEFAULT_API_CALL_DELAY 5
#define DEFAULT_API_CALL_ATTEMPTS 3
#define DEFAULT_API_CALL_BACKOFF 2
#define LOG_FILE "dispensing_log.json"

// GPIO pins
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18

// Global variables
static volatile int running = 1;
static int socket_desc;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static int timeout = DEFAULT_TIMEOUT;
static int stabilization_time = DEFAULT_STABILIZATION_TIME;
static int servo_pulse_width = DEFAULT_SERVO_PULSE_WIDTH;
static double target_weight = DEFAULT_TARGET_WEIGHT;
static int api_call_delay = DEFAULT_API_CALL_DELAY;
static int api_call_attempts = DEFAULT_API_CALL_ATTEMPTS;
static int api_call_backoff = DEFAULT_API_CALL_BACKOFF;
static int api_call_active = 0;
static time_t api_call_start_time;
static int api_call_remaining_attempts = DEFAULT_API_CALL_ATTEMPTS;
static int api_call_backoff_factor = 1; // Exponential backoff factor

// Function prototypes
int read_config();
int read_hx711();
double calibrate_weight(int raw_value);
int dispense(double target_weight);
int api_call_control(int pulse_width);
int log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
int setup_socket();
void cleanup();

// HX711 read function with timeout
int read_hx711() {
    int data = 0;
    int timeout_count = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_count < timeout) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
    }

    if (timeout_count >= timeout) {
        log_event(0.0, 0.0, "HX711 timeout");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // 1 us clock pulse
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // 1 us clock pulse
    }

    // Apply the 25th clock pulse to set the gain to 128
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Calibrate weight function
double calibrate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Dispense function
int dispense(double target_weight) {
    int raw_value;
    double actual_weight;
    int servo_position = 0;
    int servo_step = 10; // Increment/decrement servo position in steps
    int servo_direction = 1; // 1 for increment, -1 for decrement
    time_t start_time = time(NULL);
    double elapsed_time;

    // Move servo to initial position
    while (servo_position < servo_pulse_width && running) {
        gpioServo(SERVO_PIN, servo_position);
        gpioDelay(10); // Small delay to allow servo to move
        servo_position += servo_step;
        gpioDelay(10);
    }

    // Dispense
    while (running && (time(NULL) - start_time) < stabilization_time) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            log_event(target_weight, 0.0, "HX711 read error during dispensing");
            return -1;
        }
        actual_weight = calibrate_weight(raw_value);
        elapsed_time = time(NULL) - start_time;
        if (actual_weight > target_weight) {
            // Stop dispensing if target weight is reached
            break;
        }
        gpioServo(SERVO_PIN, servo_position + (int)((target_weight - actual_weight) / (stabilization_time * 0.1))); // Adjust servo speed
        gpioDelay(10);
    }

    // Move servo to stop position
    while (servo_position > 0 && running) {
        gpioServo(SERVO_PIN, servo_position);
        gpioDelay(10);
        servo_position -= servo_step;
        gpioDelay(10);
    }

    // Read final weight
    raw_value = read_hx711();
    if (raw_value == -1) {
        log_event(target_weight, 0.0, "HX711 read error after dispensing");
        return -1;
    }
    actual_weight = calibrate_weight(raw_value);

    return (int)actual_weight;
}

// API call control function
int api_call_control(int pulse_width) {
    if (api_call_active) {
        // Check if delay has passed
        if (time(NULL) - api_call_start_time >= api_call_delay) {
            api_call_remaining_attempts--;
            if (api_call_remaining_attempts <= 0) {
                api_call_active = 0;
                log_event(target_weight, 0.0, "API call cancelled due to max attempts");
                return -1;
            }
            api_call_start_time = time(NULL);
            api_call_backoff_factor = 1; // Reset backoff factor
            api_call_backoff = DEFAULT_API_CALL_BACKOFF; // Reset backoff delay
        } else {
            // Calculate remaining delay
            double remaining_delay = api_call_delay - (time(NULL) - api_call_start_time);
            if (remaining_delay > 0) {
                gpioDelay((int)remaining_delay * 1000); // Delay in milliseconds
            }
            api_call_backoff_factor *= api_call_backoff; // Exponential backoff
            api_call_backoff = DEFAULT_API_CALL_BACKOFF * api_call_backoff_factor;
            api_call_remaining_attempts--;
            if (api_call_remaining_attempts <= 0) {
                api_call_active = 0;
                log_event(target_weight, 0.0, "API call cancelled due to max attempts");
                return -1;
            }
        }
    }

    if (api_call_active) {
        gpioServo(SERVO_PIN, pulse_width);
        gpioDelay(10);
        gpioServo(SERVO_PIN, 0); // Stop servo
        api_call_active = 0;
        log_event(target_weight, 0.0, "API call completed");
        return 0;
    }

    api_call_active = 1;
    api_call_start_time = time(NULL);
    gpioServo(SERVO_PIN, pulse_width);
    gpioDelay(10);
    log_event(target_weight, 0.0, "API call initiated");
    return 1;
}

// Log event function
int log_event(double target_weight, double actual_weight, const char *error_message) {
    json_t *root, *event;
    json_t *target_weight_json, *actual_weight_json, *error_message_json;
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    root = json_object();
    event = json_object();

    json_object_set_new(event, "timestamp", json_string(timestamp));
    json_object_set_new(event, "target_weight", json_real(target_weight));
    json_object_set_new(event, "actual_weight", json_real(actual_weight));
    json_object_set_new(event, "error_message", json_string(error_message));

    json_object_set_new(root, "event", event);

    if (json_dump_file(root, LOG_FILE, JSON_INDENT(4)) != 0) {
        fprintf(stderr, "Error writing to log file: %s\n", LOG_FILE);
        json_decref(root);
        return -1;
    }

    json_decref(root);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Setup socket function
int setup_socket() {
    struct sockaddr_in server_addr;

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        perror("Could not create socket");
        return -1;
    }

    // Prepare the sockaddr_in structure
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(12345);

    // Bind
    if (bind(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        return -1;
    }

    // Listen
    listen(socket_desc, 3);

    printf("Listening on port 12345...\n");
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate(); // Terminate pigpio
    if (socket_desc > 0) {
        close(socket_desc); // Close socket
    }
}

int main() {
    int client_sock, c;
    struct sockaddr_in client_addr;
    char client_ip[INET_ADDRSTRLEN];
    char buffer[256];
    double raw_weight, calibrated_weight;
    int servo_pulse_width_map;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration
    if (read_config() != 0) {
        fprintf(stderr, "Failed to read config file, using defaults\n");
    }

    // Setup socket
    if (setup_socket() != 0) {
        fprintf(stderr, "Failed to setup socket\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Accept and setup socket
        c = accept(socket_desc, (struct sockaddr *)&client_addr, sizeof(client_addr));
        if (c < 0) {
            perror("Accept failed");
            continue; // Continue listening
        }

        inet_ntop(AF_INET, &(client_addr.sin_addr), client_ip, INET_ADDRSTRLEN);
        printf("Connection accepted from %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        // Receive data
        memset(buffer, 0, sizeof(buffer));
        if (recv(c, buffer, sizeof(buffer) - 1, 0) < 0) {
            perror("Receive failed");
            close(c);
            continue; // Continue listening
        }

        printf("Received: %s\n", buffer);

        // Parse JSON
        json_error_t error;
        json_t *root = json_loads(buffer, 0, &error);
        if (!root) {
            fprintf(stderr, "Error parsing JSON: %s\n", error.text);
            log_event(target_weight, 0.0, "Failed to parse JSON");
            close(c);
            continue; // Continue listening
        }

        json_t *target_weight_json = json_object_get(root, "target_weight");
        if (!json_is_real(target_weight_json)) {
            fprintf(stderr, "target_weight is not a real number\n");
            log_event(target_weight, 0.0, "Invalid target weight in JSON");
            json_decref(root);
            close(c);
            continue; // Continue listening
        }
        target_weight = json_real_value(target_weight_json);

        // Dispense
        int dispensing_attempts = 0;
        int dispensing_success = 0;
        while (dispensing_attempts < 3 && !dispensing_success && running) {
            int raw_weight_int = read_hx711();
            if (raw_weight_int == -1) {
                log_event(target_weight, 0.0, "HX711 read error before dispensing");
                dispensing_attempts++;
                gpioDelay(1000); // Wait before retrying
                continue;
            }

            raw_weight = calibrate_weight(raw_weight_int);
            if (raw_weight < 0) {
                log_event(target_weight, 0.0, "Calibration failed");
                dispensing_attempts++;
                gpioDelay(1000); // Wait before retrying
                continue;
            }

