            if (dispense_result != -1) {
                // Read actual weight after dispensing
                int actual_weight_int = read_hx711();
                if (actual_weight_int == -1) {
                    log_event(target_weight, 0.0, "HX711 read error after dispensing");
                    dispensing_attempts++;
                    gpioDelay(1000); // Wait before retrying
                    continue;
                }

                calibrated_weight = calibrate_weight(actual_weight_int);
                if (calibrated_weight < 0) {
                    log_event(target_weight, 0.0, "Calibration failed");
                    dispensing_attempts++;
                    gpioDelay(1000); // Wait before retrying
                    continue;
                }

                log_event(target_weight, calibrated_weight, "Dispensing successful");
                dispensing_success = 1;
            } else {
                log_event(target_weight, 0.0, "Dispensing failed");
                dispensing_attempts++;
                gpioDelay(1000); // Wait before retrying
            }
        }

        if (!dispensing_success) {
            log_event(target_weight, 0.0, "Dispensing failed after multiple attempts");
        }

        // Map target weight to servo pulse width
        servo_pulse_width_map = (int)((target_weight / 1000.0) * 2000.0); // Assuming max weight of 1000g
        if (servo_pulse_width_map < 1000) {
            servo_pulse_width_map = 1000;
        } else if (servo_pulse_width_map > 2000) {
            servo_pulse_width_map = 2000;
        }

        // Control API call
        if (api_call_active) {
            // Check if delay has passed
            if (time(NULL) - api_call_start_time >= api_call_delay) {
                api_call_active = 0;
                log_event(target_weight, 0.0, "API call cancelled due to delay");
            }
        } else {
            api_call_active = api_call_control(servo_pulse_width_map);
        }

        // Send response
        char response[256];
        snprintf(response, sizeof(response), "Target Weight: %.2f, Actual Weight: %.2f, API Call: %d", target_weight, calibrated_weight, api_call_active);
        send(c, response, strlen(response), 0);
        printf("Sent response: %s\n", response);

        // Free JSON
        json_decref(root);

        // Close connection
        close(c);
    }

    // Cleanup
    cleanup();

    return 0;
}

// Read configuration function
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file: %s\n", CONFIG_FILE);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') {
            continue;
        }

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            // Trim whitespace
            while (*key == ' ') key++;
            while (*value == ' ') value++;

            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "timeout") == 0) {
                timeout = atoi(value);
            } else if (strcmp(key, "stabilization_time") == 0) {
                stabilization_time = atoi(value);
            } else if (strcmp(key, "servo_pulse_width") == 0) {
                servo_pulse_width = atoi(value);
            } else if (strcmp(key, "api_call_delay") == 0) {
                api_call_delay = atoi(value);
            } else if (strcmp(key, "api_call_attempts") == 0) {
                api_call_attempts = atoi(value);
            } else if (strcmp(key, "api_call_backoff") == 0) {
                api_call_backoff = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

