#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17

static volatile int running = 1;
static int debounce_interval = 50; // Default debounce interval in milliseconds

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioWrite(RELAY_PIN, 0); // Turn relay OFF
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            char *endptr;
            long debounce_value = strtol(argv[i + 1], &endptr, 10);
            if (*endptr == '\0' && debounce_value > 0) {
                debounce_interval = (int)debounce_value;
                printf("Using debounce interval: %d ms\n", debounce_interval);
                i++; // Skip the value
            } else {
                fprintf(stderr, "Error: Invalid debounce interval. Using default (%d ms).\n", debounce_interval);
            }
        } else {
            fprintf(stderr, "Usage: %s [-d debounce_interval_ms]\n", argv[0]);
            return 1; // Indicate error
        }
    }
    return 0; // Indicate success
}

// Function to get current timestamp as a string
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log relay state changes
void log_relay_state(int state) {
    char timestamp[20];
    get_timestamp(timestamp);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    int last_touch_state = 0; // Store the last touch sensor state
    int current_touch_state = 0; // Store the current touch sensor state

    printf("Monitoring touch sensor on GPIO %d. Relay on GPIO %d. Debounce interval: %d ms. Press Ctrl+C to exit.\n", TOUCH_PIN, RELAY_PIN, debounce_interval);

    while (running) {
        current_touch_state = gpioRead(TOUCH_PIN);

        if (current_touch_state != last_touch_state) {
            gpioDelay(debounce_interval * 1000); // Debounce
            current_touch_state = gpioRead(TOUCH_PIN); // Re-read after debounce

            if (current_touch_state != last_touch_state) {
                if (current_touch_state == 1) { // Rising edge detected
                    int relay_state = !gpioRead(RELAY_PIN); // Toggle relay state
                    gpioWrite(RELAY_PIN, relay_state);
                    log_relay_state(relay_state);
                }
                last_touch_state = current_touch_state;
            }
        }
        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_PIN, 0); // Turn relay OFF
    gpioTerminate(); // Release pigpio resources

    return 0;
}

