#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL_S 5

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    int log_file_open;
} program_state_t;

program_state_t state = {0, 0};

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(long long pulse_count, double time_elapsed);
void log_rpm(double rpm);
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();

// Callback function for rising edge detection
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;
    uint32_t diff = current_tick - last_tick;

    if (diff > DEBOUNCE_MS * 1000) { // Debounce
        pulse_count++;
        last_tick = current_tick;
    }
}

// Function to calculate RPM
double calculate_rpm(long long pulse_count, double time_elapsed) {
    return (double)pulse_count / time_elapsed * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm) {
