#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME 2 // seconds
#define DEBOUNCE_DELAY 50 // milliseconds
#define CONTINUOUS_HIGH_THRESHOLD 10 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t relay_locked = 0;
time_t last_touch_time = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void toggle_relay();
void handle_signal(int signal);
void cleanup();

// Signal handler function
void handle_signal(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially OFF
    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to RELAY_PIN\n");
        return 1;
    }
    return 0;
}

// Function to toggle the relay state
void toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    int new_state = !current_state;
    if (control_relay(new_state) != 0) {
        fprintf(stderr, "Failed to toggle relay\n");
    }
}

// Function to cleanup GPIO resources
void cleanup() {
    printf("Cleaning up GPIO resources...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    time_t last_toggle_time = 0;
    int relay_state = 0; // 0 = OFF, 1 = ON

    while (program_running) {
        int touch_value = read_touch_sensor();

        if (touch_value == 1) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_touch_time) >= DEBOUNCE_DELAY / 1000.0) {
                toggle_relay();
                last_toggle_time = current_time;
                relay_state = !relay_state; // Update relay state
                if (control_relay(relay_state) != 0) {
                    fprintf(stderr, "Failed to control relay\n");
                }
                last_touch_time = current_time;
            }
        } else {
            last_touch_time = 0; // Reset touch time if released
        }

        if (relay_state == 1) {
            last_touch_time = time(NULL);
        }

        if (difftime(time(NULL), last_touch_time) > CONTINUOUS_HIGH_THRESHOLD) {
            printf("Sensor continuously HIGH for %d seconds. Locking relay.\n", CONTINUOUS_HIGH_THRESHOLD);
            relay_locked = 1;
            control_relay(0); // Turn off relay
        } else if (relay_locked && relay_state == 0) {
            relay_locked = 0;
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

