#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define target flow rate
double target_flow_rate = 0.0;

// Define Kp value
double Kp = 1.0;

// Global variables
volatile int pulse_count = 0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
void set_valve_enable(int enable);
void set_valve_pwm(int duty_cycle);
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate();
double calculate_pwm_duty_cycle(double flow_rate);
void log_data(double flow_rate, int duty_cycle);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, 255); // Set PWM range to 0-255

    // Set initial valve enable state
    set_valve_enable(1);

    // Register interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for flow sensor\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to set valve enable pin
void set_valve_enable(int enable) {
    gpioWrite(VALVE_ENABLE_PIN, enable);
}

// Function to set valve PWM duty cycle
void set_valve_pwm(int duty_cycle) {
    gpioPWM(VALVE_PWM_PIN, duty_cycle);
}

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    pulse_count++;
}

// Function to calculate flow rate (L/min)
double calculate_flow_rate() {
    // Discharge the interrupt-driven pulse counter
    pulse_count = 0;
    gpioDelay(100); // Wait 100ms

    // Calculate flow rate (L/min) - Assuming 7.5 pulses per liter
    return (double)pulse_count / 7.5;
}

// Function to calculate PWM duty cycle
double calculate_pwm_duty_cycle(double flow_rate) {
    double error = target_flow_rate - flow_rate;
    double duty_cycle = Kp * error;

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to log data to CSV file
void log_data(double flow_rate, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    long timestamp_ms = (t->tm_sec * 1000) + (t->tm_msec);

    fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;

    // Stop PWM
    set_valve_pwm(0);

    // Disable valve
    set_valve_enable(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
                return 1;
        }
    }

    // Validate target flow rate
    if (target_flow_rate <= 0) {
        fprintf(stderr, "Error: Target flow rate must be greater than 0\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (running) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate();

        // Calculate PWM duty cycle
        double duty_cycle = calculate_pwm_duty_cycle(flow_rate);

        // Set valve PWM
        set_valve_pwm((int)duty_cycle);

        // Log data
        log_data(flow_rate, (int)duty_cycle);

        // Sleep for 100ms
        gpioDelay(100);
    }

    return 0;
}

