    set_valve_enable(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
                return 1;
        }
    }

    // Validate target flow rate
    if (target_flow_rate <= 0) {
        fprintf(stderr, "Error: Target flow rate must be greater than 0\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (running) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate();

        // Calculate PWM duty cycle
        double duty_cycle = calculate_pwm_duty_cycle(flow_rate);

        // Set valve PWM
        set_valve_pwm((int)duty_cycle);

        // Log data
        log_data(flow_rate, (int)duty_cycle);

        // Sleep for 100ms
        gpioDelay(100);
    }

    return 0;
}

