void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close SPI interface
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Engage locks
    engage_locks();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read RFID tag
int read_rfid_tag() {
    unsigned char tx_buf[1] = {0x00}; // Dummy data for SPI transfer
    unsigned char rx_buf[11]; // Increased size to handle potential errors
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 11);
    if (result != 11) {
        log_event("SPI Read Error", "Failed to read SPI data");
        return -1; // Indicate error
    }

    // Check for no tag present (all zeros)
    if (rx_buf[0] == 0x00 && rx_buf[1] == 0x00 && rx_buf[2] == 0x00 && rx_buf[3] == 0x00 && rx_buf[4] == 0x00 && rx_buf[5] == 0x00 && rx_buf[6] == 0x00 && rx_buf[7] == 0x00 && rx_buf[8] == 0x00 && rx_buf[9] == 0x00 && rx_buf[10] == 0x00) {
        log_event("No Tag", "No RFID tag present");
        return 0; // Indicate no tag
    }

    // Create a string from the received bytes
    char *tag = (char *)malloc(VALID_TAG_LENGTH + 1); // Allocate memory for the tag
    if (tag == NULL) {
        log_event("Memory Allocation Error", "Failed to allocate memory for tag");
        return -1; // Indicate memory allocation error
    }
    memcpy(tag, rx_buf, VALID_TAG_LENGTH);
    tag[VALID_TAG_LENGTH] = '\0'; // Null-terminate the string

