    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_2_GPIO, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Open SPI interface
    spi_handle = spiOpen(RFID_SPI_CHANNEL, RFID_SPI_SPEED, RFID_SPI_MODE);
    if (spi_handle < 0) {
        log_event("SPI Open Error", "Failed to open SPI interface");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System Started", "Door access control system started");

    // Main loop
    while (!terminate) {
        int rfid_result = read_rfid_tag();
        if (rfid_result == 1) {
            log_event("RFID Read", "Valid RFID tag read");
            if (button_pressed()) {
                log_event("Button Pressed", "Button pressed after valid RFID read");
                disengage_locks();
                gpioDelay(5000); // Keep locks disengaged for 5 seconds
                engage_locks();
            }
        } else if (rfid_result == 0) {
            // No tag present
        } else {
            // Error reading RFID
        }
        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    engage_locks();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

