#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

// MCP3008 SPI channel
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// PID parameters
#define TARGET_SPEED 60.0 // RPM
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME 0.1 // 100 ms

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
double motor1_speed = 0.0;
double motor2_speed = 0.0;
double p1 = 0.0, i1 = 0.0, d1 = 0.0;
double p2 = 0.0, i2 = 0.0, d2 = 0.0;
FILE *log_file = NULL;
bool running = true;

// Mutexes for encoder access
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void motor1_forward(int speed);
void motor1_backward(int speed);
void motor1_stop();
void motor2_forward(int speed);
void motor2_backward(int speed);
void motor2_stop();
int read_encoder1();
int read_encoder2();
double calculate_rpm(int encoder_count);
double pid_control(double target_speed, double current_speed, double *p, double *i, double *d, double dt);
void log_data(double motor1_speed, double motor2_speed, double p1, double i1, double d1, double p2, double i2, double d2);
void encoder1_interrupt();
void encoder2_interrupt();
void *encoder1_monitor(void *arg);
void *encoder2_monitor(void *arg);
void signal_handler(int signal);

// Motor control functions
void motor1_forward(int speed) {
    digitalWrite(MOTOR1_ENA, HIGH);
    pwmWrite(MOTOR1_ENA, speed);
    digitalWrite(MOTOR1_IN1, HIGH);
    digitalWrite(MOTOR1_IN2, LOW);
}

void motor1_backward(int speed) {
    digitalWrite(MOTOR1_ENA, HIGH);
    pwmWrite(MOTOR1_ENA, speed);
    digitalWrite(MOTOR1_IN1, LOW);
    digitalWrite(MOTOR1_IN2, HIGH);
}

void motor1_stop() {
    digitalWrite(MOTOR1_ENA, LOW);
    digitalWrite(MOTOR1_IN1, LOW);
    digitalWrite(MOTOR1_IN2, LOW);
}

void motor2_forward(int speed) {
    digitalWrite(MOTOR2_ENB, HIGH);
    pwmWrite(MOTOR2_ENB, speed);
    digitalWrite(MOTOR2_IN3, HIGH);
    digitalWrite(MOTOR2_IN4, LOW);
}

void motor2_backward(int speed) {
    digitalWrite(MOTOR2_ENB, HIGH);
    pwmWrite(MOTOR2_ENB, speed);
    digitalWrite(MOTOR2_IN3, LOW);
    digitalWrite(MOTOR2_IN4, HIGH);
}

void motor2_stop() {
    digitalWrite(MOTOR2_ENB, LOW);
    digitalWrite(MOTOR2_IN3, LOW);
    digitalWrite(MOTOR2_IN4, LOW);
}

// Encoder reading functions
int read_encoder1() {
    int a_value = digitalRead(ENCODER1_A);
    int b_value = digitalRead(ENCODER1_B);

    if (a_value == LOW) {
        if (b_value == HIGH) {
            pthread_mutex_lock(&encoder1_mutex);
            encoder1_count++;
            pthread_mutex_unlock(&encoder1_mutex);
        } else {
            pthread_mutex_lock(&encoder1_mutex);
            encoder1_count--;
            pthread_mutex_unlock(&encoder1_mutex);
        }
    } else {
        // Do nothing, A is high, no change
    }
    return 0;
}

int read_encoder2() {
    int a_value = digitalRead(ENCODER2_A);
    int b_value = digitalRead(ENCODER2_B);

    if (a_value == LOW) {
        if (b_value == HIGH) {
            pthread_mutex_lock(&encoder2_mutex);
            encoder2_count++;
            pthread_mutex_unlock(&encoder2_mutex);
        } else {
            pthread_mutex_lock(&encoder2_mutex);
            encoder2_count--;
            pthread_mutex_unlock(&encoder2_mutex);
        }
    } else {
        // Do nothing, A is high, no change
    }
    return 0;
}

// RPM calculation function
double calculate_rpm(int encoder_count) {
    // Assuming 360 ticks per revolution
    return (double)encoder_count * 60.0 / SAMPLE_TIME;
}

// PID control function
double pid_control(double target_speed, double current_speed, double *p, double *i, double *d, double dt) {
    double error = target_speed - current_speed;
    *p = KP * error;
    *i += KI * error * dt;
    *d = KD * (error - (*p + *i)) / dt;
    return (*p + *i + *d);
}

// Logging function
void log_data(double motor1_speed, double motor2_speed, double p1, double i1, double d1, double p2, double i2, double d2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_speed, motor2_speed, p1, i1, d1, p2, i2, d2);
    fflush(log_file);
}

// Interrupt service routines
void encoder1_interrupt() {
    read_encoder1();
}

void encoder2_interrupt() {
    read_encoder2();
}

// Encoder monitoring threads
void *encoder1_monitor(void *arg) {
    while (running) {
        read_encoder1();
        delay(1); // Small delay to avoid busy-waiting
    }
    return NULL;
}

void *encoder2_monitor(void *arg) {
    while (running) {
        read_encoder2();
        delay(1); // Small delay to avoid busy-waiting
    }
    return NULL;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = false;

    motor1_stop();
    motor2_stop();

    // Release GPIO lines
    pinMode(MOTOR1_ENA, INPUT); // Set to input to release the pin
    pinMode(MOTOR1_IN1, INPUT);
    pinMode(MOTOR1_IN2, INPUT);
    pinMode(MOTOR2_ENB, INPUT);
    pinMode(MOTOR2_IN3, INPUT);
    pinMode(MOTOR2_IN4, INPUT);
    pinMode(ENCODER1_A, INPUT);
    pinMode(ENCODER1_B, INPUT);
    pinMode(ENCODER2_A, INPUT);
    pinMode(ENCODER2_B, INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

