#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(int touch_detected);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x05) < 0) { // Set ELEPROX_CFG to 0x05
        fprintf(stderr, "Error: Failed to write ELEPROX_CFG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x05) < 0) { // Set ELEPROX_CFG to 0x05
        fprintf(stderr, "Error: Failed to write ELEPROX_CFG\n");
        return -1;
    }

    // Set touch and release thresholds for each electrode
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x0F) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x0A) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set ELE_EN to 0x0C
        fprintf(stderr, "Error: Failed to write ELE_EN\n");
        return -1;
    }

    // Enter Run Mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Set MHD_R, NHD_R, NCL_R, FDL_R to 0x01
        fprintf(stderr, "Error: Failed to write MHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) { // Set MHD_R, NHD_R, NCL_R, FDL_R to 0x01
        fprintf(stderr, "Error: Failed to write MHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) { // Set MHD_R, NHD_R, NCL_R, FDL_R to 0x01
        fprintf(stderr, "Error: Failed to write MHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set ELE_EN to 0x0C
        fprintf(stderr, "Error: Failed to write ELE_EN\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to control the relay
void control_relay(int touch_detected) {
    int current_state = gpioRead(RELAY_GPIO);
    int new_state = (touch_detected) ? 1 : 0;

    if (new_state != current_state) {
        gpioWrite(RELAY_GPIO, new_state);
        log_relay_state(new_state);
    }
}

// Function to log relay state to file
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Relay is %s\n", timestamp, (state == 1) ? "ON" : "OFF");
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status;
    int last_relay_state = 0; // Store the last relay state

    // Main loop
    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            control_relay((touch_status > 0) ? 1 : 0);
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

