// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(unsigned short *touch_status);
void relay_toggle();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode\n");
        return -1;
    }

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE0_TL + 2 * i, 0x0F) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE0_TH + 2 * i, 0x05) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    if (i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCL_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set FDL_R\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_MHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHD_F\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHD_F\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCHF, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCH_F\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDLF, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set FDL_F\n");
        return -1;
    }

    // Configure electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODERESISTANCE, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }

    // Configure electrode configuration
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to set ECR\n");
        return -1;
    }

    // Switch to run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(unsigned short *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to toggle the relay
void relay_toggle() {
    int current_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_state);
    printf("Relay toggled to state: %d\n", !current_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned short touch_status;

    // Main loop
    while (!terminate) {
        // Read touch status
        if (mpr121_read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            if (touch_status > 0) {
                relay_toggle();
            }
        }

        // Delay
        gpioDelay(100);
    }

    // Close I2C interface
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

