#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_S 2
#define POLLING_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
int log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int last_motion_time;
} ProgramState;

ProgramState state = {0};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read PIR sensor
        int motion_detected = read_pir_sensor();

        // Check for motion and rate limit
        if (motion_detected) {
            time_t current_time = time(NULL);
            if (difftime(current_time, state.last_motion_time) >= RATE_LIMIT_DURATION_S) {
                // Log motion event
                log_event("Motion Detected");

                // Activate relay
                control_relay(1);

                // Deactivate relay
                control_relay(0);

                // Log unlock event
                log_event("Door Unlocked");

                // Update last motion time
                state.last_motion_time = current_time;
            } else {
                // Log rate-limited event
                log_event("Rate Limited");
            }
        }

        // Delay for polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR sensor pin as input with pull-down resistor
    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Control relay state
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

// Log event to file
int log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup resources
void cleanup() {
    // Deactivate relay
    control_relay(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

