#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the number of steps in the pattern
#define NUM_STEPS 10

// Define the maximum duration of a step (in milliseconds)
#define MAX_DURATION 200

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to generate a random duty cycle value
int generate_duty_cycle()
{
    return rand() % 256;
}

// Function to generate a random duration value
int generate_duration()
{
    return (rand() % 151) + 50; // 50-200ms
}

// Function to generate a random step in the pattern
void generate_step(int *duty_cycle1, int *duty_cycle2, int *duration)
{
    *duty_cycle1 = generate_duty_cycle();
    *duty_cycle2 = generate_duty_cycle();
    *duration = generate_duration();
}

// Function to set the PWM duty cycle for a motor
int set_motor_pwm(int gpio_pin, int duty_cycle)
{
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to delay for a specified duration
void delay(int milliseconds)
{
    gpioDelay(milliseconds * 1000); // pigpioDelay takes microseconds
}

// Function to play a single step of the pattern
void play_step(int duty_cycle1, int duty_cycle2, int duration)
{
    if (set_motor_pwm(MOTOR1_PIN, duty_cycle1) != 0) return;
    if (set_motor_pwm(MOTOR2_PIN, duty_cycle2) != 0) return;

    delay(duration);

    if (set_motor_pwm(MOTOR1_PIN, 0) != 0) return;
    if (set_motor_pwm(MOTOR2_PIN, 0) != 0) return;
}

// Function to generate a random pattern
void generate_pattern(int *pattern, int num_steps)
{
    for (int i = 0; i < num_steps; i++) {
        generate_step(&pattern[i * 3], &pattern[i * 3 + 1], &pattern[i * 3 + 2]);
    }
}

// Function to play a pattern
void play_pattern(int *pattern, int num_steps)
{
    for (int i = 0; i < num_steps; i++) {
        play_step(pattern[i * 3], pattern[i * 3 + 1], pattern[i * 3 + 2]);
    }
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins to output mode
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handling for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Allocate memory for the pattern
    int *pattern = (int *)malloc(NUM_STEPS * 3 * sizeof(int));
    if (pattern == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        gpioTerminate();
        return 1;
    }

    // Generate a random pattern
    generate_pattern(pattern, NUM_STEPS);

    // Main loop to generate and play patterns indefinitely
    while (!terminate) {
        play_pattern(pattern, NUM_STEPS);
    }

    // Clean up and terminate the pigpio library
    free(pattern);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

