#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Default calibration values
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0

// Weight threshold in kg
#define WEIGHT_THRESHOLD 10.0

// Number of calibration readings
#define NUM_CALIBRATION_READINGS 100

// Timeout duration in seconds
#define TIMEOUT_DURATION 0.5

// Global variables
static volatile int running = 1;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static double offset = DEFAULT_OFFSET;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double calibrate_hx711();
double calculate_weight(int raw_value, double scale_factor, double offset);
void control_solenoid(double weight, double threshold);
void log_data(int raw_value, double weight);
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout_counter = 0;

    // Wait for the data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
        if (timeout_counter > (int)(TIMEOUT_DURATION * 1000000)) { // Timeout after 0.5 seconds
            fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the HX711
double calibrate_hx711() {
    double sum = 0.0;
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Calibration failed due to timeout.\n");
            return -1.0; // Indicate calibration failure
        }
        sum += raw_value;
        gpioDelay(1); // Small delay between readings
    }
    return sum / NUM_CALIBRATION_READINGS;
}

// Function to calculate weight
double calculate_weight(int raw_value, double scale_factor, double offset) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid
void control_solenoid(double weight, double threshold) {
    if (weight > threshold) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
    }
}

// Function to log data to file
void log_data(int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Raw: %d, Weight: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_value, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen("calibration.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration.txt. Using default values.\n");
        return;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%lf %lf", &scale_factor, &offset) != 2) {
            fprintf(stderr, "Warning: Invalid calibration data in calibration.txt. Using default values.\n");
            fclose(fp);
            return;
        }
    } else {
        fprintf(stderr, "Warning: calibration.txt is empty. Using default values.\n");
        fclose(fp);
        return;
    }

    fclose(fp);
}

// Function to save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen("calibration.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration.txt for writing.\n");
        return;
    }

    fprintf(fp, "%.6lf %.6lf\n", scale_factor, offset);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration_data();

    // Calibrate HX711
    offset = calibrate_hx711();
    if (offset < 0) {
        fprintf(stderr, "Error: HX711 calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open weight_log.txt for writing.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value, scale_factor, offset);
            control_solenoid(weight, WEIGHT_THRESHOLD);
            log_data(raw_value, weight);
        } else {
            fprintf(stderr, "Error: Failed to read from HX711. Skipping this iteration.\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Save calibration data
    save_calibration_data();

    // Close log file
    fclose(log_file);

    // Release GPIO resources
    gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid on exit
    gpioTerminate();

    printf("Weight monitoring stopped.\n");

    return 0;
}

