#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150

// Define debounce parameters
#define NUM_READINGS 5
#define DEBOUNCE_DELAY_MS 50

// Define motor run time
#define MOTOR_RUN_TIME_S 5

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction, int speed);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, stopping motor and exiting...");
    control_motor(0, 0); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int readings[NUM_READINGS];
    int low_count = 0;

    // Take multiple readings and debounce
    for (int i = 0; i < NUM_READINGS; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        if (readings[i] == PI_BAD_GPIO) {
            log_event("Error reading rain sensor");
            return -1; // Indicate error
        }
        if (readings[i] == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Determine if it's raining based on the majority of readings
    return (low_count >= NUM_READINGS / 2) ? 0 : 1; // 0 = rain, 1 = dry
}

// Function to control the DC motor
void control_motor(int direction, int speed) {
    if (direction == 1) { // Close the window
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, speed);
        log_event("Closing window");
    } else if (direction == 0) { // Stop the motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Stopping motor");
    } else {
        log_event("Invalid motor direction");
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    char log_message[256];
    snprintf(log_message, sizeof(log_message)-1, "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);

    // Open syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Window control program started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == 0) {
            log_event("Rain detected");
            control_motor(1, PWM_DUTY_CYCLE); // Close the window
            gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Run motor for 5 seconds
            control_motor(0, 0); // Stop the motor
            log_event("Window closed");
            gpioDelay(60 * 1000000); // Wait 60 seconds before next check
        } else if (rain_detected == 1) {
            //log_event("No rain detected"); //Commented out to reduce log spam
        } else {
            log_event("Error reading rain sensor, skipping check");
        }

        gpioDelay(60 * 1000000); // Check every 60 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motor(0, 0); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog

    return 0;
}

