// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define TIMEOUT_MS 100
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_ACTIVATE_TIME 5 // seconds

// Global variables
static volatile int running = 1;
static double calibration_factor = 0.0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_hx711();
double convert_to_kg(int raw_value);
void activate_solenoid();
void log_security_event(double weight);
void signal_handler(int signal);
int read_calibration_factor();
int save_calibration_factor(double factor);
int open_log_file();
int close_log_file();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Unlock the solenoid
    gpioWrite(SOLENOID_PIN, 0);

    // Close the log file
    close_log_file();

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Ensure solenoid is initially unlocked
    gpioWrite(SOLENOID_PIN, 0);

    return 0;
}

// Read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0); // Ensure clock is low

    // Wait for data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_MS * 1000) {
        gpioDelay(1); // 1 us delay
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Convert raw value to kilograms
double convert_to_kg(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Activate the solenoid for a specified time
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    gpioDelay(SOLENOID_ACTIVATE_TIME * 1000); // Delay for 5 seconds
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
}

// Log security event to file
void log_security_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Read calibration factor from file
int read_calibration_factor() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for reading.\n");
        return 1;
    }

    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error: Could not read calibration factor from file.\n");
        fclose(fp);
        return 1;
    }

    fclose(fp);
    return 0;
}

// Save calibration factor to file
int save_calibration_factor(double factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return 1;
    }

    if (fprintf(fp, "%lf", factor) < 0) {
        fprintf(stderr, "Error: Could not write calibration factor to file.\n");
        fclose(fp);
        return 1;
    }

    fclose(fp);
    return 0;
}

// Open the security log file
int open_log_file() {
    log_file = fopen(SECURITY_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open security log file for appending.\n");
        return 1;
    }
    return 0;
}

// Close the security log file
int close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
        return 0;
    }
    return 1;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Read calibration factor from file
    if (read_calibration_factor() != 0) {
        // Prompt user to enter calibration factor
        double user_factor;
        printf("Enter calibration factor: ");
        if (scanf("%lf", &user_factor) != 1) {
            fprintf(stderr, "Error: Invalid input.\n");
            gpioTerminate();
            return 1;
        }

        // Save calibration factor to file
        if (save_calibration_factor(user_factor) != 0) {
            gpioTerminate();
            return 1;
        }

        calibration_factor = user_factor;
    }

    // Open the security log file
    if (open_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_kg(raw_value);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight threshold exceeded! Activating solenoid.\n");
                activate_solenoid();
                log_security_event(weight);
            }
        } else {
            fprintf(stderr, "Error reading HX711, retrying...\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Close the log file
    close_log_file();

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

