        // Delay to avoid excessive CPU usage
        gpioDelay(100 * 1000); // 100ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(BUZZER_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

