#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <wiringPi.h>

#define VALVE_PIN 18 // BCM GPIO18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600
#define MIN_DURATION 1

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, shutting down...\n", signal);
}

// Function to read the watering duration from the configuration file
int read_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    // Remove trailing newline character
    line[strcspn(line, "\n")] = 0;

    char *token = strtok(line, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid format in file %s\n", filename);
        fclose(fp);
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing value in file %s\n", filename);
        fclose(fp);
        return -1;
    }

    long duration = strtol(token, NULL, 10);
    if (duration < MIN_DURATION || duration > MAX_DURATION) {
        fprintf(stderr, "Error: Duration out of range (%ld seconds) in file %s\n", duration, filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return (int)duration;
}

// Function to control the solenoid valve
void control_valve(int pin, int duration) {
    time_t start_time = time(NULL);

    printf("Turning valve ON for %d seconds\n", duration);
    digitalWrite(pin, HIGH); // Activate the valve
    fflush(stdout);

    while (time(NULL) - start_time < duration) {
        if (!program_running) {
            printf("Turning valve OFF due to shutdown signal\n");
            digitalWrite(pin, LOW); // Deactivate the valve
            fflush(stdout);
            return;
        }
        delay(100); // Small delay to prevent busy-waiting
    }

    printf("Turning valve OFF\n");
    digitalWrite(pin, LOW); // Deactivate the valve
    fflush(stdout);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set the valve pin as an output
    pinMode(VALVE_PIN, OUTPUT);
    digitalWrite(VALVE_PIN, LOW); // Ensure valve is initially off

    // Main loop
    while (program_running) {
        int duration = read_duration(CONFIG_FILE);
        if (duration == -1) {
            fprintf(stderr, "Error reading duration from %s, retrying in 60 seconds...\n", CONFIG_FILE);
            sleep(60);
            continue;
        }

        control_valve(VALVE_PIN, duration);
        sleep(60); // Wait 60 seconds before checking the config file again
    }

    // Ensure valve is off before exiting
    digitalWrite(VALVE_PIN, LOW);

    printf("Program exiting cleanly.\n");
    return 0;
}

