#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_PWM 22
#define LEFT_MOTOR_DIR 23
#define RIGHT_MOTOR_PWM 24
#define RIGHT_MOTOR_DIR 25

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define base speed
#define BASE_SPEED 150

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
void set_motor_speed(int left_speed, int right_speed);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting.\n", signal);
    running = 0;
    set_motor_speed(0, 0); // Stop motors
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set sensor pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Set motor control pins as outputs
    gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, PWM_FREQUENCY);

    return 0;
}

// Read sensor value
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Set motor speeds
void set_motor_speed(int left_speed, int right_speed) {
    // Limit speeds to 0-255
    if (left_speed < 0) left_speed = 0;
    if (left_speed > 255) left_speed = 255;
    if (right_speed < 0) right_speed = 0;
    if (right_speed > 255) right_speed = 255;

    // Set motor directions (forward)
    gpioWrite(LEFT_MOTOR_DIR, 1);
    gpioWrite(RIGHT_MOTOR_DIR, 1);

    // Set PWM duty cycles
    gpioPWM(LEFT_MOTOR_PWM, left_speed);
    gpioPWM(RIGHT_MOTOR_PWM, right_speed);
}

// Log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
