#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int gpio_pin;
    float lux_threshold;
    int measurement_delay_ms;
    char *log_file;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
int read_bh1750(float *lux) {
    char config[1] = {0x10}; // Continuous high resolution mode
    int result;

    result = i2cWriteDevice(i2c_handle, config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

    char buffer[2];
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control the relay
int control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%lld,%.2f,%d\n", timestamp_ms, lux, relay_state);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Turn off relay
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Grow lamp control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1); // Turn on relay
                relay_state = 1;
                log_data(lux, relay_state);
                printf("Grow lamp ON\n");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0); // Turn off relay
                relay_state = 0;
                log_data(lux, relay_state);
                printf("Grow lamp OFF\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        gpioDelay(100); // Check every 100ms
    }

    cleanup();
    return 0;
}

