#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths (microseconds)
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000

// Define safe pulse width range (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d us). Must be between %d and %d us.\n", pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1; // Indicate failure
    }

    gpioServo(gpio, pulse_width);
    return 0; // Indicate success
}

// Function to read the lock button state
int read_lock_button(int gpio) {
    return (gpioRead(gpio) == 0) ? 1 : 0; // Active-low logic
}

// Function to read the unlock button state
int read_unlock_button(int gpio) {
    return (gpioRead(gpio) == 0) ? 1 : 0; // Active-low logic
}

// Function to debounce the button press
void debounce(int gpio) {
    gpioDelay(100); // 100ms delay
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (read_lock_button(LOCK_BUTTON_PIN)) {
            printf("Lock button pressed. Setting servo to lock position.\n");
            if (set_servo_pulse_width(SERVO_PIN, LOCK_PULSE_WIDTH) == 0) {
                gpioDelay(500); // Keep lock position for 500ms
                set_servo_pulse_width(SERVO_PIN, 1500); // Set to neutral position
            }
            debounce(LOCK_BUTTON_PIN);
        }

        // Check for unlock button press
        if (read_unlock_button(UNLOCK_BUTTON_PIN)) {
            printf("Unlock button pressed. Setting servo to unlock position.\n");
            if (set_servo_pulse_width(SERVO_PIN, UNLOCK_PULSE_WIDTH) == 0) {
                gpioDelay(500); // Keep unlock position for 500ms
                set_servo_pulse_width(SERVO_PIN, 1500); // Set to neutral position
            }
            debounce(UNLOCK_BUTTON_PIN);
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Clean up and exit
    set_servo_pulse_width(SERVO_PIN, 1500); // Set to neutral position before exiting
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

