#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the duration for which each motor is activated (in milliseconds)
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    program_running = 0;
}

// Function to activate a vibration motor for a specified duration
int activate_motor(int gpio_pin, int duration_ms) {
    int result;

    // Set the GPIO pin as an output
    result = gpioSetMode(gpio_pin, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %d\n", gpio_pin, result);
        return -1;
    }

    // Activate the motor by setting the GPIO pin HIGH
    result = gpioWrite(gpio_pin, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio_pin, result);
        return -1;
    }

    // Wait for the specified duration
    gpioDelay(duration_ms * 1000); // pigpioDelay takes microseconds

    // Deactivate the motor by setting the GPIO pin LOW
    result = gpioWrite(gpio_pin, 0);
