#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <zmq.h>

// Constants
#define GPIO_SOUND_SENSOR 17
#define GPIO_ALARM_LED 27
#define SOUND_THRESHOLD 0 // Active-low sensor
#define ALARM_DURATION 1000 // milliseconds
#define ZMQ_PORT 5555
#define ZMQ_TOPIC "SOUND_ALERTS"
#define ZMQ_SERVER_ADDRESS "tcp://*:5555"
#define ZMQ_CLIENT_ADDRESS "tcp://localhost:5555"

// Global variables
static volatile int running = 1;
static void *zmq_context = NULL;
static void *zmq_pub_socket = NULL; // For sound sensor mode
static void *zmq_sub_socket = NULL; // For alarm node mode
static int gpio_initialized = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_zmq(void **context, void **socket);
int publish_message(void *socket, const char *topic, const char *message);
int subscribe_message(void *socket, const char *topic, char *message, int message_size);
void cleanup_gpio();
void cleanup_zmq(void *context, void *pub_socket, void *sub_socket);
void log_message(const char *message);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    log_message("Signal received, shutting down...");
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    gpio_initialized = 1;

    gpioSetMode(GPIO_SOUND_SENSOR, PI_INPUT);
    gpioSetMode(GPIO_ALARM_LED, PI_OUTPUT);
    gpioWrite(GPIO_ALARM_LED, 0); // Ensure LED is off initially

    return 0;
}

// Initialize ZeroMQ
int initialize_zmq(void **context, void **socket) {
    *context = zmq_ctx_new();
    if (!*context) {
        log_message("Failed to create ZeroMQ context");
        return -1;
    }

    *socket = zmq_socket(*context, ZMQ_PUB); // For sound sensor mode
    if (!*socket) {
        log_message("Failed to create ZeroMQ socket (PUB)");
        zmq_ctx_destroy(*context);
        return -1;
    }

    int rc = zmq_bind(*socket, ZMQ_SERVER_ADDRESS);
    if (rc != 0) {
        log_message("Failed to bind ZeroMQ socket");
        zmq_close(*socket);
        zmq_ctx_destroy(*context);
        return -1;
    }

    // For alarm node mode
    void *sub_socket = zmq_socket(*context, ZMQ_SUB);
    if (!sub_socket) {
        log_message("Failed to create ZeroMQ socket (SUB)");
        zmq_close(*socket);
        zmq_ctx_destroy(*context);
        return -1;
    }

    int rc2 = zmq_connect(sub_socket, ZMQ_CLIENT_ADDRESS);
    if (rc2 != 0) {
        log_message("Failed to connect ZeroMQ socket");
        zmq_close(*socket);
        zmq_close(sub_socket);
        zmq_ctx_destroy(*context);
        return -1;
    }

    zmq_setsockopt(sub_socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));

    return 0;
}

// Publish message
int publish_message(void *socket, const char *topic, const char *message) {
    zmq_msg_t zmsg;
    zmq_msg_init_size(&zmsg, strlen(topic) + strlen(message) + 2); // Topic + message + null terminator + delimiter
    memcpy(zmq_msg_data(&zmsg), topic, strlen(topic));
    memcpy(zmq_msg_data(&zmsg) + strlen(topic), message, strlen(message));

    int rc = zmq_msg_send(&zmsg, socket, 0);
    zmq_msg_close(&zmsg);

    if (rc == -1) {
        log_message("Failed to send message");
        return -1;
    }

    return 0;
}

// Subscribe message
int subscribe_message(void *socket, const char *topic, char *message, int message_size) {
    zmq_msg_t zmsg;
    zmq_msg_init(&zmsg);

    int rc = zmq_msg_recv(&zmsg, socket, 0);

    if (rc == -1) {
        log_message("Failed to receive message");
        zmq_msg_close(&zmsg);
        return -1;
    }

    // Check if the message starts with the topic
    char *msg_data = zmq_msg_data(&zmsg);
    size_t msg_size = zmq_msg_size(&zmsg);
    if (msg_size < strlen(topic) || strncmp(msg_data, topic, strlen(topic)) != 0) {
        zmq_msg_close(&zmsg);
        return -1; // Not a message for this topic
    }

    // Extract the actual message (after the topic and null terminator)
    size_t message_offset = strlen(topic) + 1; // +1 for null terminator
    if (msg_size < message_offset + 1) {
        zmq_msg_close(&zmsg);
        return -1; // Message too short
    }

    strncpy(message, msg_data + message_offset, message_size - 1);
    message[message_size - 1] = '\0'; // Ensure null termination

    zmq_msg_close(&zmsg);
    return 0;
}

// Log message with timestamp
void log_message(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld: %s\n", tmbuf, tv.tv_usec, message);
    printf("%s", buf);
}

// Cleanup GPIO
void cleanup_gpio() {
    if (gpio_initialized) {
        gpioWrite(GPIO_ALARM_LED, 0); // Turn off LED
        gpioTerminate();
    }
}

// Cleanup ZeroMQ
void cleanup_zmq(void *context, void *pub_socket, void *sub_socket) {
    if (pub_socket) zmq_close(pub_socket);
    if (sub_socket) zmq_close(sub_socket);
    if (context) zmq_ctx_destroy(context);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    const char *mode = argv[1];

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (initialize_zmq(&zmq_context, &zmq_pub_socket) != 0) {
        cleanup_gpio();
        return 1;
    }

    char message[256];

    if (strcmp(mode, "sound_sensor") == 0) {
        log_message("Starting sound sensor mode...");

        while (running) {
            int sound_detected = gpioRead(GPIO_SOUND_SENSOR);

            if (sound_detected == SOUND_THRESHOLD) {
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char timestamp[80];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

                snprintf(message, sizeof(message), "%s: Sound detected!", timestamp);
                if (publish_message(zmq_pub_socket, ZMQ_TOPIC, message) != 0) {
                    running = 0; // Stop on error
                    break;
                }
                log_message(message);
            }
            gpioDelay(10000); // 10ms delay
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        log_message("Starting alarm node mode...");

        while (running) {
            if (subscribe_message(zmq_sub_socket, ZMQ_TOPIC, message, sizeof(message)) == 0) {
                log_message(message);
                gpioWrite(GPIO_ALARM_LED, 1); // Turn on LED
                gpioDelay(ALARM_DURATION);      // Wait for alarm duration
                gpioWrite(GPIO_ALARM_LED, 0); // Turn off LED
            }
            gpioDelay(100); // Check every 100ms
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        cleanup_gpio();
        cleanup_zmq(zmq_context, zmq_pub_socket, zmq_sub_socket);
        return 1;
    }

    // Cleanup
    log_message("Cleaning up...");
    cleanup_gpio();
    cleanup_zmq(zmq_context, zmq_pub_socket, zmq_sub_socket);

    return 0;
}

