#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>
#include <time.h>

// Configuration
#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100 // Maximum number of pulses to store

// NEC Protocol Constants (in microseconds)
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_CHECKSUM_BITS 16

// Global variables
static volatile int pulse_count = 0;
static volatile uint32_t pulse_widths[MAX_PULSES];
static volatile int last_tick = 0;
static volatile int nec_frame_ready = 0;
static struct mosquitto *mosq = NULL;
static int running = 1;

// Function prototypes
void signal_handler(int signal);
void gpio_callback(int gpio, int level, uint32_t tick);
int decode_nec(uint32_t *pulse_widths, int pulse_count, uint32_t *address, uint32_t *command, uint32_t *inverted_address, uint32_t *inverted_command);
int validate_nec(uint32_t address, uint32_t command, uint32_t inverted_address, uint32_t inverted_command);
int calculate_nec_checksum(uint32_t address, uint32_t command);
int publish_mqtt(const char *json_payload);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// GPIO callback function
void gpio_callback(int gpio, int level, uint32_t tick) {
    int pulse_width;

    if (level != PI_TIMEOUT) {
        pulse_width = tick - last_tick;
        last_tick = tick;

        if (pulse_count < MAX_PULSES) {
            pulse_widths[pulse_count++] = pulse_width;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
        }
    }

    if (level == PI_TIMEOUT) {
        nec_frame_ready = 1;
    }
}

// NEC decoding function
int decode_nec(uint32_t *pulse_widths, int pulse_count, uint32_t *address, uint32_t *command, uint32_t *inverted_address, uint32_t *inverted_command) {
    if (pulse_count < 68) {
        syslog(LOG_ERR, "Too few pulses received (%d)", pulse_count);
        return -1;
    }

    // Check for start bit
    if (pulse_widths[0] < NEC_HDR_MARK - 200 || pulse_widths[0] > NEC_HDR_MARK + 200 ||
        pulse_widths[1] < NEC_HDR_SPACE - 200 || pulse_widths[1] > NEC_HDR_SPACE + 200) {
        syslog(LOG_ERR, "Invalid start bit");
        return -1;
    }

    uint32_t decoded_address = 0;
    uint32_t decoded_command = 0;
    uint32_t decoded_inverted_address = 0;
    uint32_t decoded_inverted_command = 0;

    // Decode address (8 bits)
    for (int i = 2; i < 10; i++) {
        if (pulse_widths[2 * i] < NEC_BIT_MARK - 50 || pulse_widths[2 * i] > NEC_BIT_MARK + 50) {
            syslog(LOG_ERR, "Invalid bit mark");
            return -1;
        }

        if (pulse_widths[2 * i + 1] > NEC_ONE_SPACE - 200 && pulse_widths[2 * i + 1] < NEC_ONE_SPACE + 200) {
            decoded_address = (decoded_address << 1) | 1;
        } else if (pulse_widths[2 * i + 1] > NEC_ZERO_SPACE - 200 && pulse_widths[2 * i + 1] < NEC_ZERO_SPACE + 200) {
            decoded_address = (decoded_address << 1) | 0;
        } else {
            syslog(LOG_ERR, "Invalid bit space");
            return -1;
        }
    }

    // Decode command (8 bits)
    for (int i = 10; i < 18; i++) {
        if (pulse_widths[2 * i] < NEC_BIT_MARK - 50 || pulse_widths[2 * i] > NEC_BIT_MARK + 50) {
            syslog(LOG_ERR, "Invalid bit mark");
            return -1;
        }

        if (pulse_widths[2 * i + 1] > NEC_ONE_SPACE - 200 && pulse_widths[2 * i + 1] < NEC_ONE_SPACE + 200) {
