}

// Function to initialize I2C device
int init_i2c(int address) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", address, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read lux value from BH1750FVI sensor
float read_lux(int fd) {
    unsigned char buf[2];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, "\x10", 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        usleep(180000); // Wait 180ms for conversion

        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        unsigned int raw_value = (buf[0] << 8) | buf[1];
        return (float)raw_value / 1.2;
    }

    fprintf(stderr, "Failed to read lux value after multiple retries.\n");
    return NAN;
}

// Function to format sensor data into a string
void format_sensor_data(int sensor_id, float lux, char *buffer, size_t buffer_size) {
    snprintf(buffer, buffer_size, "%d,%.1f", sensor_id, lux);
}

// Function to send UDP multicast packet
int send_udp_packet(const char *data) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Set TTL for multicast
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting TTL: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    addr.sin_port = htons(UDP_MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C devices
    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = init_i2c(sensor_addresses[i]);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to initialize I2C device at address 0x%02x\n", sensor_addresses[i]);
            // Continue to the next sensor, but exit if all fail
            if (i == NUM_SENSORS - 1) {
                fprintf(stderr, "Failed to initialize all I2C devices. Exiting.\n");
                // Close any open file descriptors
                for (int j = 0; j < i; j++) {
                    close(i2c_fds[j]);
                }
                return 1;
            }
        }
    }

    // Main loop
    while (!terminate) {
        float lux_values[NUM_SENSORS];
        char data_buffer[256]; // Buffer to hold formatted data
        int data_len = 0;       // Current length of data in the buffer

        // Read lux values from each sensor
        for (int i = 0; i < NUM_SENSORS; i++) {
            lux_values[i] = read_lux(i2c_fds[i]);
            if (isnan(lux_values[i])) {
                fprintf(stderr, "Error reading from sensor %d\n", i + 1);
            } else {
                // Format sensor data and append to buffer
                format_sensor_data(i + 1, lux_values[i], data_buffer + data_len, sizeof(data_buffer));
                data_len += strlen(data_buffer + data_len) + 1; // +1 for the comma
                if (data_len >= sizeof(data_buffer)) {
                    fprintf(stderr, "Data buffer overflow!\n");
                    data_len = 0; // Reset buffer to avoid sending garbage
                    break;        // Exit the loop to prevent further overflows
                }
                if (i < NUM_SENSORS - 1) {
                    data_len++; // Add comma for the next sensor
                }
            }
        }

        // Send UDP packet
        if (data_len > 0) {
            if (send_udp_packet(data_buffer) != 0) {
                fprintf(stderr, "Failed to send UDP packet.\n");
            }
        }

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    // Close I2C devices
    for (int i = 0; i < NUM_SENSORS; i++) {
        close(i2c_fds[i]);
    }

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

