#define SLPM_SCALE 0.01
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
