void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

// Initialize I2C bus
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, AWM7300V_ADDR, 0);
