        gpioTerminate();
        return 1;
    }

    unsigned char sensor_data[2];
    unsigned int raw_flow;
    float flow_rate;

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Mask and convert flow value
            raw_flow = mask_flow_value(sensor_data);
            flow_rate = convert_to_slpm(raw_flow);

            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
