#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define AS7341_ADDR 0x39
#define ENABLE_REG 0x80
#define CFG6_REG 0x8F
#define SP_EN_REG 0x81
#define F1_DATA_REG 0x94
#define LUX_SCALE 0.1 // Example scale factor, adjust as needed

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_spectral_data(uint16_t *data);
float calculate_lux(uint16_t *data);
int log_data(uint16_t *data, float lux);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
    float lux;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;
    uint16_t spectral_data[10];

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read spectral data
        if (read_spectral_data(spectral_data) == 0) {
            // Calculate lux
            sensor_data.lux = calculate_lux(spectral_data);

            // Log the data
            if (log_data(spectral_data, sensor_data.lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read spectral data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AS7341_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Initialize the AS7341 sensor
int init_sensor() {
    // Verify sensor ID (optional)
    int sensor_id = i2cReadByteData(i2c_handle, 0x73);
    if (sensor_id < 0) {
        fprintf(stderr, "Failed to read sensor ID: %s\n", strerror(errno));
        return 1;
    }
    if (sensor_id != 0x73) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return 1;
    }

    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, ENABLE_REG, 0x03) < 0) {
        fprintf(stderr, "Failed to enable sensor: %s\n", strerror(errno));
        return 1;
    }

    // Configure SMUX (example: enable F1-F8, Clear, NIR)
    if (i2cWriteByteData(i2c_handle, CFG6_REG, 0x03) < 0) {
        fprintf(stderr, "Failed to configure SMUX: %s\n", strerror(errno));
        return 1;
    }

    // Enable spectral measurement
    if (i2cWriteByteData(i2c_handle, SP_EN_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to enable spectral measurement: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

// Read spectral data from the sensor
int read_spectral_data(uint16_t *data) {
    for (int i = 0; i < 10; i++) {
        int result = i2cReadWordData(i2c_handle, F1_DATA_REG + (i * 2));
        if (result < 0) {
            fprintf(stderr, "Failed to read spectral data channel %d: %s\n", i, strerror(errno));
            return 1;
        }
        data[i] = (uint16_t)result;
    }
    return 0;
}

// Calculate lux from spectral data (simplified approximation)
float calculate_lux(uint16_t *data) {
    // This is a placeholder.  A real implementation would use a more complex formula
    // based on the AS7341 datasheet and calibration data.
    // This example just sums the values of the first 5 channels.
    float sum = 0.0;
    for (int i = 0; i < 5; i++) {
        sum += (float)data[i];
    }
    return sum * LUX_SCALE;
}

// Log data to a CSV file
int log_data(uint16_t *data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp,
            data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7], data[8], data[9], lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

