#define DEFAULT_SAMPLING_INTERVAL 1.0
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define I2C_BUS 1

// Global variables
static int i2c_handle = -1;
static FILE *csv_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int i2c_address);
int read_sensor_data(int i2c_handle, sensor_data_t *data);
int write_data_to_csv(FILE *csv_file, long timestamp, int16_t x, int16_t y, int16_t z);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c(int i2c_address) {
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, 0x28, (char *)data, 6); // Read X, Y, Z
        if (result == 6) {
            // Success
            return 0;
        } else {
            log_error("I2C read failed, retrying...");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    log_error("I2C read failed after multiple retries");
    return -1;
}

// Function to write data to CSV file
int write_data_to_csv(FILE *csv_file, long timestamp, int16_t x, int16_t y, int16_t z) {
    if (fprintf(csv_file, "%ld,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        log_error("Failed to write data to CSV file");
        return -1;
    }
    return 0;
}

// Function to log errors
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_file != NULL) {
        if (fprintf(error_file, "%s: %s\n", timestamp, message) < 0) {
            perror("Failed to write to error log");
            return -1;
        }
        fflush(error_file);
    } else {
        perror("Error log file not opened");
        return -1;
    }
    return 0;
}

