    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    double sampling_interval = DEFAULT_SAMPLING_INTERVAL;
    char *output_filename = DEFAULT_OUTPUT_FILENAME;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = strtod(optarg, NULL);
                if (sampling_interval <= 0) {
                    fprintf(stderr, "Invalid sampling interval. Using default value.\n");
                    sampling_interval = DEFAULT_SAMPLING_INTERVAL;
                }
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f output_filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        perror("Failed to open error log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(output_filename, "a");
    if (csv_file == NULL) {
        log_error("Failed to open CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
    }
    rewind(csv_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    struct timespec ts;
    long timestamp_ms;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

                // Write data to CSV file
                if (write_data_to_csv(csv_file, timestamp_ms, sensor_data.x, sensor_data.y, sensor_data.z) != 0) {
                    terminate = 1; // Stop if CSV write fails
                }
            } else {
                log_error("Failed to get timestamp");
                terminate = 1; // Stop if timestamp fails
            }
        } else {
            terminate = 1; // Stop if sensor read fails
        }

        // Wait for the next sample
        gpioDelay((int)(sampling_interval * 1000000)); // Delay in microseconds
    }

    cleanup();
    printf("Data acquisition stopped.\n");
    return 0;
}

