#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <stdint.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

// Global variables
int i2c_fd = -1;
int sockfd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_bh1750();
int send_udp_multicast(float lux_value);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Initialize I2C interface
int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read ambient light from BH1750 sensor
float read_bh1750() {
    uint8_t buf[2];
    int ret;

    // Send measurement mode command
    buf[0] = CONTINUOUS_HIGH_RES_MODE;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        perror("Error writing to I2C device");
        return -1.0f;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("Error reading from I2C device");
        return -1.0f;
    }

    // Convert big-endian data to 16-bit integer
    uint16_t raw_value = (buf[0] << 8) | buf[1];

    // Convert to lux value
    float lux = (float)raw_value / 1.2f;

    return lux;
}

// Send lux value via UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    char buffer[32];

    // Create socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Set TTL
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Format lux value as string
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    // Send data
    if (sendto(sockfd, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending data");
        close(sockfd);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (sockfd != -1) {
        close(sockfd);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Retrying in 1 second.\n");
        sleep(1);
        if (init_i2c() < 0) {
            fprintf(stderr, "I2C initialization failed again. Exiting.\n");
            return 1;
        }
    }

    printf("BH1750 light sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux = read_bh1750();
        if (lux >= 0.0f) {
            if (send_udp_multicast(lux) < 0) {
                fprintf(stderr, "UDP multicast failed. Retrying in 1 second.\n");
            }
        } else {
            fprintf(stderr, "Failed to read light sensor. Retrying in 1 second.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

