#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <syslog.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define MAX_LINE_LENGTH 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
char *line_buffer = NULL;
size_t buffer_size = 0;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
}

// Function to initialize the UART
int init_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("Error opening UART");
        syslog(LOG_ERR, "Error opening UART: %s", strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting UART attributes");
        syslog(LOG_ERR, "Error getting UART attributes: %s", strerror(errno));
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, no hardware control
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 second timeout

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting UART attributes");
        syslog(LOG_ERR, "Error setting UART attributes: %s", strerror(errno));
        close(uart_fd);
        return -1;
    }

    return 0;
}

// Function to read data from the UART with timeout
int read_uart(char *buffer, size_t max_len) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(uart_fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select() error");
        syslog(LOG_ERR, "select() error: %s", strerror(errno));
        return -1;
    } else if (retval) {
        ssize_t bytes_read = read(uart_fd, buffer, max_len - 1);
        if (bytes_read == -1) {
            perror("read() error");
            syslog(LOG_ERR, "read() error: %s", strerror(errno));
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    } else {
        return 0; // Timeout
    }
}

// Function to parse the data and extract timestamp and range
int parse_data(const char *data, long *timestamp, float *range) {
    char *line = strdup(data);
    if (line == NULL) {
        perror("strdup() error");
        syslog(LOG_ERR, "strdup() error: %s", strerror(errno));
        return -1;
    }

    char *token;
    char *rest = line;

    // Get timestamp
    token = strtok_r(rest, ",", &rest);
    if (token == NULL) {
        syslog(LOG_ERR, "Invalid data format: missing timestamp");
        free(line);
        return -1;
    }
    *timestamp = strtol(token, NULL, 10);
    if (*timestamp == 0 && errno == ERANGE) {
        syslog(LOG_ERR, "Timestamp out of range");
        free(line);
        return -1;
    }

    // Get range
    token = strtok_r(rest, "\n", &rest);
    if (token == NULL) {
        syslog(LOG_ERR, "Invalid data format: missing range");
        free(line);
        return -1;
    }
    *range = strtof(token, NULL);

    free(line);
    return 0;
}

// Function to format the data and print it to stdout
void format_output(long timestamp, float range) {
    time_t rawtime = timestamp;
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&rawtime);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
    syslog(LOG_INFO, "Timestamp: %s, Range: %.2f meters", timestamp_str, range);
}

// Function to free the line buffer
void free_line_buffer() {
    if (line_buffer != NULL) {
        free(line_buffer);
        line_buffer = NULL;
        buffer_size = 0;
    }
}

int main() {
    openlog("radar_data_processor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Initialize UART
    if (init_uart() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Allocate initial line buffer
    line_buffer = malloc(MAX_LINE_LENGTH);
    if (line_buffer == NULL) {
        perror("malloc() error");
        syslog(LOG_ERR, "malloc() error: %s", strerror(errno));
        close(uart_fd);
        gpioTerminate();
        closelog();
        return 1;
    }
    buffer_size = MAX_LINE_LENGTH;

    syslog(LOG_INFO, "Radar data processor started");

    while (program_running) {
        ssize_t bytes_read = read_uart(line_buffer, buffer_size);

        if (bytes_read > 0) {
            // Accumulate data in the line buffer
            size_t current_len = strlen(line_buffer);
            size_t new_len = current_len + bytes_read;
            if (new_len >= buffer_size) {
                // Buffer overflow, process the data and reallocate
                process_data(line_buffer, current_len);
                free_line_buffer();
                line_buffer = malloc(MAX_LINE_LENGTH);
                if (line_buffer == NULL) {
                    perror("malloc() error");
                    syslog(LOG_ERR, "malloc() error: %s", strerror(errno));
                    program_running = 0; // Exit on memory allocation failure
                    break;
                }
                buffer_size = MAX_LINE_LENGTH;
                line_buffer[0] = '\0'; // Initialize the buffer after reallocation
            } else {
                line_buffer[new_len] = '\0'; // Null-terminate the buffer
            }
        } else if (bytes_read < 0) {
            // Error reading from UART, exit the loop
            program_running = 0;
            break;
        } else {
            // Timeout occurred, process the data
            process_data(line_buffer, strlen(line_buffer));
            free_line_buffer();
            line_buffer = malloc(MAX_LINE_LENGTH);
            if (line_buffer == NULL) {
                perror("malloc() error");
                syslog(LOG_ERR, "malloc() error: %s", strerror(errno));
                program_running = 0; // Exit on memory allocation failure
                break;
            }
            buffer_size = MAX_LINE_LENGTH;
            line_buffer[0] = '\0'; // Initialize the buffer after reallocation
        }
    }

    // Cleanup
    free_line_buffer();
    close(uart_fd);
    gpioTerminate();
    closelog();

    syslog(LOG_INFO, "Radar data processor stopped");

    return 0;
}

void process_data(const char *data, size_t data_len) {
    long timestamp;
    float range;

    if (data_len > 0 && data[data_len - 1] == '\n') {
        data[data_len - 1] = '\0'; // Null-terminate the string
        if (parse_data(data, &timestamp, &range) == 0) {
            format_output(timestamp, range);
        } else {
            syslog(LOG_ERR, "Failed to parse data: %s", data);
        }
    }
}

