#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable for UART handle
int uart_handle = -1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int check_obstacle();
int send_uart_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close UART port if open
    if (uart_handle != -1) {
        gpioSerialReadClose(uart_handle);
    }

    // Terminate pigpio library
    gpioTerminate();

    // Exit the program
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", LEFT_SENSOR_PIN);
        return -1;
    }
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", MIDDLE_SENSOR_PIN);
        return -1;
    }
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", RIGHT_SENSOR_PIN);
        return -1;
    }
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to check for obstacle
int check_obstacle() {
    int left = read_sensor(LEFT_SENSOR_PIN);
    int middle = read_sensor(MIDDLE_SENSOR_PIN);
    int right = read_sensor(RIGHT_SENSOR_PIN);

    if (left == 0 || middle == 0 || right == 0) {
        return 0; // Obstacle detected
    } else {
        return 1; // No obstacle
    }
}

// Function to send UART message
int send_uart_message(const char *message) {
    if (uart_handle == -1) {
        fprintf(stderr, "UART not initialized\n");
        return -1;
    }

    int bytes_written = gpioSerialWrite(uart_handle, message, strlen(message));
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to UART: %d\n", bytes_written);
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open UART port
    uart_handle = gpioSerialReadOpen(UART_DEVICE, BAUD_RATE, 8); // 8N1
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log sensor states to console
        printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);

        // Check for emergency stop condition
        if (check_obstacle() == 0) {
            // Send emergency stop message over UART
            if (send_uart_message("EMERGENCY STOP!\n") != 0) {
                fprintf(stderr, "Failed to send emergency stop message\n");
            }
        }

        // Delay for 100ms (10Hz)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // This point should not be reached due to the signal handler
    return 0;
}

